def accumulate(binop, seq, initial=no_default):
    seq = iter(seq)
    if initial == no_default:
        try:
            result = next(seq)
        except StopIteration:
            return
    else:
        result = initial
    yield result
    for elem in seq:
        result = binop(result, elem)
        yield result

def groupby(key, seq):
    if not callable(key):
        key = getter(key)
    d = collections.defaultdict(lambda : [].append)
    for item in seq:
        d[key(item)](item)
    rv = {}
    for (k, v) in d.items():
        rv[k] = v.__self__
    return rv

def merge_sorted(*seqs, **kwargs):
    if len(seqs) == 0:
        return iter([])
    elif len(seqs) == 1:
        return iter(seqs[0])
    key = kwargs.get('key', None)
    if key is None:
        return _merge_sorted_binary(seqs)
    else:
        return _merge_sorted_binary_key(seqs, key)

def _merge_sorted_binary(seqs):
    mid = len(seqs) // 2
    L1 = seqs[:mid]
    if len(L1) == 1:
        seq1 = iter(L1[0])
    else:
        seq1 = _merge_sorted_binary(L1)
    L2 = seqs[mid:]
    if len(L2) == 1:
        seq2 = iter(L2[0])
    else:
        seq2 = _merge_sorted_binary(L2)
    try:
        val2 = next(seq2)
    except StopIteration:
        yield from seq1
        return
    for val1 in seq1:
        if val2 < val1:
            yield val2
            for val2 in seq2:
                if val2 < val1:
                    yield val2
                else:
                    yield val1
                    break
            else:
                break
        else:
            yield val1
    else:
        yield val2
        yield from seq2
        return
    yield val1
    yield from seq1

def _merge_sorted_binary_key(seqs, key):
    mid = len(seqs) // 2
    L1 = seqs[:mid]
    if len(L1) == 1:
        seq1 = iter(L1[0])
    else:
        seq1 = _merge_sorted_binary_key(L1, key)
    L2 = seqs[mid:]
    if len(L2) == 1:
        seq2 = iter(L2[0])
    else:
        seq2 = _merge_sorted_binary_key(L2, key)
    try:
        val2 = next(seq2)
    except StopIteration:
        yield from seq1
        return
    key2 = key(val2)
    for val1 in seq1:
        key1 = key(val1)
        if key2 < key1:
            yield val2
            for val2 in seq2:
                key2 = key(val2)
                if key2 < key1:
                    yield val2
                else:
                    yield val1
                    break
            else:
                break
        else:
            yield val1
    else:
        yield val2
        yield from seq2
        return
    yield val1
    yield from seq1

def interleave(seqs):
    iters = itertools.cycle(map(iter, seqs))
    while True:
        try:
            for itr in iters:
                yield next(itr)
            return
        except StopIteration:
            predicate = partial(operator.is_not, itr)
            iters = itertools.cycle(itertools.takewhile(predicate, iters))

def unique(seq, key=None):
    seen = set()
    seen_add = seen.add
    if key is None:
        for item in seq:
            if item not in seen:
                seen_add(item)
                yield item
    else:
        for item in seq:
            val = key(item)
            if val not in seen:
                seen_add(val)
                yield item

def isiterable(x):
    try:
        iter(x)
        return True
    except TypeError:
        return False

def isdistinct(seq):
    if iter(seq) is seq:
        seen = set()
        seen_add = seen.add
        for item in seq:
            if item in seen:
                return False
            seen_add(item)
        return True
    else:
        return len(seq) == len(set(seq))

def tail(n, seq):
    try:
        return seq[-n:]
    except (TypeError, KeyError):
        return tuple(collections.deque(seq, n))

def second(seq):
    seq = iter(seq)
    next(seq)
    return next(seq)

def nth(n, seq):
    if isinstance(seq, (tuple, list, Sequence)):
        return seq[n]
    else:
        return next(itertools.islice(seq, n, None))

def _get(ind, seq, default):
    try:
        return seq[ind]
    except (KeyError, IndexError):
        return default

def get(ind, seq, default=no_default):
    try:
        return seq[ind]
    except TypeError:
        if isinstance(ind, list):
            if default == no_default:
                if len(ind) > 1:
                    return operator.itemgetter(*ind)(seq)
                elif ind:
                    return (seq[ind[0]],)
                else:
                    return ()
            else:
                return tuple((_get(i, seq, default) for i in ind))
        elif default != no_default:
            return default
        else:
            raise
    except (KeyError, IndexError):
        if default == no_default:
            raise
        else:
            return default

def interpose(el, seq):
    inposed = concat(zip(itertools.repeat(el), seq))
    try:
        next(inposed)
    except StopIteration:
        return iter([])
    return inposed

def frequencies(seq):
    d = collections.defaultdict(int)
    for item in seq:
        d[item] += 1
    return dict(d)

def reduceby(key, binop, seq, init=no_default):
    is_no_default = init == no_default
    if not is_no_default and (not callable(init)):
        _init = init
        init = lambda : _init
    if not callable(key):
        key = getter(key)
    d = {}
    for item in seq:
        k = key(item)
        if k not in d:
            if is_no_default:
                d[k] = item
                continue
            else:
                d[k] = init()
        d[k] = binop(d[k], item)
    return d

def iterate(func, x):
    while True:
        yield x
        x = func(x)

def partition(n, seq, pad=no_pad):
    args = [iter(seq)] * n
    if pad is no_pad:
        return zip(*args)
    else:
        return zip_longest(*args, fillvalue=pad)

def partition_all(n, seq):
    args = [iter(seq)] * n
    it = zip_longest(*args, fillvalue=no_pad)
    try:
        prev = next(it)
    except StopIteration:
        return
    for item in it:
        yield prev
        prev = item
    if prev[-1] is no_pad:
        try:
            end = len(seq) % n
            if prev[end - 1] is no_pad or prev[end] is not no_pad:
                raise LookupError('The sequence passed to `parition_all` has invalid length')
            yield prev[:end]
        except TypeError:
            (lo, hi) = (0, n)
            while lo < hi:
                mid = (lo + hi) // 2
                if prev[mid] is no_pad:
                    hi = mid
                else:
                    lo = mid + 1
            yield prev[:lo]
    else:
        yield prev

def count(seq):
    if hasattr(seq, '__len__'):
        return len(seq)
    return sum((1 for i in seq))

def pluck(ind, seqs, default=no_default):
    if default == no_default:
        get = getter(ind)
        return map(get, seqs)
    elif isinstance(ind, list):
        return (tuple((_get(item, seq, default) for item in ind)) for seq in seqs)
    return (_get(ind, seq, default) for seq in seqs)

def getter(index):
    if isinstance(index, list):
        if len(index) == 1:
            index = index[0]
            return lambda x: (x[index],)
        elif index:
            return operator.itemgetter(*index)
        else:
            return lambda x: ()
    else:
        return operator.itemgetter(index)

def join(leftkey, leftseq, rightkey, rightseq, left_default=no_default, right_default=no_default):
    if not callable(leftkey):
        leftkey = getter(leftkey)
    if not callable(rightkey):
        rightkey = getter(rightkey)
    d = groupby(leftkey, leftseq)
    if left_default == no_default and right_default == no_default:
        for item in rightseq:
            key = rightkey(item)
            if key in d:
                for left_match in d[key]:
                    yield (left_match, item)
    elif left_default != no_default and right_default == no_default:
        for item in rightseq:
            key = rightkey(item)
            if key in d:
                for left_match in d[key]:
                    yield (left_match, item)
            else:
                yield (left_default, item)
    elif right_default != no_default:
        seen_keys = set()
        seen = seen_keys.add
        if left_default == no_default:
            for item in rightseq:
                key = rightkey(item)
                seen(key)
                if key in d:
                    for left_match in d[key]:
                        yield (left_match, item)
        else:
            for item in rightseq:
                key = rightkey(item)
                seen(key)
                if key in d:
                    for left_match in d[key]:
                        yield (left_match, item)
                else:
                    yield (left_default, item)
        for (key, matches) in d.items():
            if key not in seen_keys:
                for match in matches:
                    yield (match, right_default)

def diff(*seqs, **kwargs):
    N = len(seqs)
    if N == 1 and isinstance(seqs[0], list):
        seqs = seqs[0]
        N = len(seqs)
    if N < 2:
        raise TypeError('Too few sequences given (min 2 required)')
    default = kwargs.get('default', no_default)
    if default == no_default:
        iters = zip(*seqs)
    else:
        iters = zip_longest(*seqs, fillvalue=default)
    key = kwargs.get('key', None)
    if key is None:
        for items in iters:
            if items.count(items[0]) != N:
                yield items
    else:
        for items in iters:
            vals = tuple(map(key, items))
            if vals.count(vals[0]) != N:
                yield items

def topk(k, seq, key=None):
    if key is not None and (not callable(key)):
        key = getter(key)
    return tuple(heapq.nlargest(k, seq, key=key))

def peek(seq):
    iterator = iter(seq)
    item = next(iterator)
    return (item, itertools.chain((item,), iterator))

def peekn(n, seq):
    iterator = iter(seq)
    peeked = tuple(take(n, iterator))
    return (peeked, itertools.chain(iter(peeked), iterator))

def random_sample(prob, seq, random_state=None):
    if not hasattr(random_state, 'random'):
        from random import Random
        random_state = Random(random_state)
    return filter(lambda _: random_state.random() < prob, seq)

def _get_factory(f, kwargs):
    factory = kwargs.pop('factory', dict)
    if kwargs:
        raise TypeError("{}() got an unexpected keyword argument '{}'".format(f.__name__, kwargs.popitem()[0]))
    return factory

def merge(*dicts, **kwargs):
    if len(dicts) == 1 and (not isinstance(dicts[0], Mapping)):
        dicts = dicts[0]
    factory = _get_factory(merge, kwargs)
    rv = factory()
    for d in dicts:
        rv.update(d)
    return rv

def merge_with(func, *dicts, **kwargs):
    if len(dicts) == 1 and (not isinstance(dicts[0], Mapping)):
        dicts = dicts[0]
    factory = _get_factory(merge_with, kwargs)
    values = collections.defaultdict(lambda : [].append)
    for d in dicts:
        for (k, v) in d.items():
            values[k](v)
    result = factory()
    for (k, v) in values.items():
        result[k] = func(v.__self__)
    return result

def valfilter(predicate, d, factory=dict):
    rv = factory()
    for (k, v) in d.items():
        if predicate(v):
            rv[k] = v
    return rv

def keyfilter(predicate, d, factory=dict):
    rv = factory()
    for (k, v) in d.items():
        if predicate(k):
            rv[k] = v
    return rv

def itemfilter(predicate, d, factory=dict):
    rv = factory()
    for item in d.items():
        if predicate(item):
            (k, v) = item
            rv[k] = v
    return rv

def dissoc(d, *keys, **kwargs):
    factory = _get_factory(dissoc, kwargs)
    d2 = factory()
    if len(keys) < len(d) * 0.6:
        d2.update(d)
        for key in keys:
            if key in d2:
                del d2[key]
    else:
        remaining = set(d)
        remaining.difference_update(keys)
        for k in remaining:
            d2[k] = d[k]
    return d2

def update_in(d, keys, func, default=None, factory=dict):
    ks = iter(keys)
    k = next(ks)
    rv = inner = factory()
    rv.update(d)
    for key in ks:
        if k in d:
            d = d[k]
            dtemp = factory()
            dtemp.update(d)
        else:
            d = dtemp = factory()
        inner[k] = inner = dtemp
        k = key
    if k in d:
        inner[k] = func(d[k])
    else:
        inner[k] = func(default)
    return rv

def get_in(keys, coll, default=None, no_default=False):
    try:
        return reduce(operator.getitem, keys, coll)
    except (KeyError, IndexError, TypeError):
        if no_default:
            raise
        return default

def apply(*func_and_args, **kwargs):
    if not func_and_args:
        raise TypeError('func argument is required')
    (func, args) = (func_and_args[0], func_and_args[1:])
    return func(*args, **kwargs)

def thread_first(val, *forms):

    def evalform_front(val, form):
        if callable(form):
            return form(val)
        if isinstance(form, tuple):
            (func, args) = (form[0], form[1:])
            args = (val,) + args
            return func(*args)
    return reduce(evalform_front, forms, val)

def thread_last(val, *forms):

    def evalform_back(val, form):
        if callable(form):
            return form(val)
        if isinstance(form, tuple):
            (func, args) = (form[0], form[1:])
            args = args + (val,)
            return func(*args)
    return reduce(evalform_back, forms, val)

def instanceproperty(fget=None, fset=None, fdel=None, doc=None, classval=None):
    if fget is None:
        return partial(instanceproperty, fset=fset, fdel=fdel, doc=doc, classval=classval)
    return InstanceProperty(fget=fget, fset=fset, fdel=fdel, doc=doc, classval=classval)

def _restore_curry(cls, func, args, kwargs, userdict, is_decorated):
    if isinstance(func, str):
        (modname, qualname) = func.rsplit(':', 1)
        obj = import_module(modname)
        for attr in qualname.split('.'):
            obj = getattr(obj, attr)
        if is_decorated:
            return obj
        func = obj.func
    obj = cls(func, *args, **kwargs or {})
    obj.__dict__.update(userdict)
    return obj

def memoize(func, cache=None, key=None):
    if cache is None:
        cache = {}
    try:
        may_have_kwargs = has_keywords(func) is not False
        is_unary = is_arity(1, func)
    except TypeError:
        may_have_kwargs = True
        is_unary = False
    if key is None:
        if is_unary:

            def key(args, kwargs):
                return args[0]
        elif may_have_kwargs:

            def key(args, kwargs):
                return (args or None, frozenset(kwargs.items()) if kwargs else None)
        else:

            def key(args, kwargs):
                return args

    def memof(*args, **kwargs):
        k = key(args, kwargs)
        try:
            return cache[k]
        except TypeError:
            raise TypeError('Arguments to memoized function must be hashable')
        except KeyError:
            cache[k] = result = func(*args, **kwargs)
            return result
    try:
        memof.__name__ = func.__name__
    except AttributeError:
        pass
    memof.__doc__ = func.__doc__
    memof.__wrapped__ = func
    return memof

def compose(*funcs):
    if not funcs:
        return identity
    if len(funcs) == 1:
        return funcs[0]
    else:
        return Compose(funcs)

def pipe(data, *funcs):
    for func in funcs:
        data = func(data)
    return data

def do(func, x):
    func(x)
    return x

def _check_sigspec(sigspec, func, builtin_func, *builtin_args):
    if sigspec is None:
        try:
            sigspec = inspect.signature(func)
        except (ValueError, TypeError) as e:
            sigspec = e
    if isinstance(sigspec, ValueError):
        return (None, builtin_func(*builtin_args))
    elif not isinstance(sigspec, inspect.Signature):
        if func in _sigs.signatures and (hasattr(func, '__signature__') and hasattr(func.__signature__, '__get__')):
            val = builtin_func(*builtin_args)
            return (None, val)
        return (None, False)
    return (sigspec, None)

def num_required_args(func, sigspec=None):
    (sigspec, rv) = _check_sigspec(sigspec, func, _sigs._num_required_args, func)
    if sigspec is None:
        return rv
    return sum((1 for p in sigspec.parameters.values() if p.default is p.empty and p.kind in (p.POSITIONAL_OR_KEYWORD, p.POSITIONAL_ONLY)))

def has_varargs(func, sigspec=None):
    (sigspec, rv) = _check_sigspec(sigspec, func, _sigs._has_varargs, func)
    if sigspec is None:
        return rv
    return any((p.kind == p.VAR_POSITIONAL for p in sigspec.parameters.values()))

def has_keywords(func, sigspec=None):
    (sigspec, rv) = _check_sigspec(sigspec, func, _sigs._has_keywords, func)
    if sigspec is None:
        return rv
    return any((p.default is not p.empty or p.kind in (p.KEYWORD_ONLY, p.VAR_KEYWORD) for p in sigspec.parameters.values()))

def is_valid_args(func, args, kwargs, sigspec=None):
    (sigspec, rv) = _check_sigspec(sigspec, func, _sigs._is_valid_args, func, args, kwargs)
    if sigspec is None:
        return rv
    try:
        sigspec.bind(*args, **kwargs)
    except TypeError:
        return False
    return True

def is_partial_args(func, args, kwargs, sigspec=None):
    (sigspec, rv) = _check_sigspec(sigspec, func, _sigs._is_partial_args, func, args, kwargs)
    if sigspec is None:
        return rv
    try:
        sigspec.bind_partial(*args, **kwargs)
    except TypeError:
        return False
    return True

def is_arity(n, func, sigspec=None):
    (sigspec, rv) = _check_sigspec(sigspec, func, _sigs._is_arity, n, func)
    if sigspec is None:
        return rv
    num = num_required_args(func, sigspec)
    if num is not None:
        num = num == n
        if not num:
            return False
    varargs = has_varargs(func, sigspec)
    if varargs:
        return False
    keywords = has_keywords(func, sigspec)
    if keywords:
        return False
    if num is None or varargs is None or keywords is None:
        return None
    return True

def raises(err, lamda):
    try:
        lamda()
        return False
    except err:
        return True

def countby(key, seq):
    if not callable(key):
        key = getter(key)
    return frequencies(map(key, seq))

def get_exclude_keywords(num_pos_only, sigspec):
    if num_pos_only == 0:
        return ()
    has_kwargs = any((x.kind == x.VAR_KEYWORD for x in sigspec.parameters.values()))
    if not has_kwargs:
        return ()
    pos_args = list(sigspec.parameters.values())[:num_pos_only]
    return tuple((x.name for x in pos_args))

def signature_or_spec(func):
    try:
        return inspect.signature(func)
    except (ValueError, TypeError):
        return None

def expand_sig(sig):
    if isinstance(sig, tuple):
        if len(sig) == 3:
            (num_pos_only, func, keyword_only) = sig
            assert isinstance(sig[-1], tuple)
        else:
            (num_pos_only, func) = sig
            keyword_only = ()
        sigspec = signature_or_spec(func)
    else:
        func = sig
        sigspec = signature_or_spec(func)
        num_pos_only = num_pos_args(sigspec)
        keyword_only = ()
    keyword_exclude = get_exclude_keywords(num_pos_only, sigspec)
    return (num_pos_only, func, keyword_only + keyword_exclude, sigspec)

def create_signature_registry(module_info=module_info, signatures=signatures):
    for (module, info) in module_info.items():
        if isinstance(module, str):
            module = import_module(module)
        for (name, sigs) in info.items():
            if hasattr(module, name):
                new_sigs = tuple((expand_sig(sig) for sig in sigs))
                signatures[getattr(module, name)] = new_sigs

def check_valid(sig, args, kwargs):
    (num_pos_only, func, keyword_exclude, sigspec) = sig
    if len(args) < num_pos_only:
        return False
    if keyword_exclude:
        kwargs = dict(kwargs)
        for item in keyword_exclude:
            kwargs.pop(item, None)
    try:
        func(*args, **kwargs)
        return True
    except TypeError:
        return False

def _is_valid_args(func, args, kwargs):
    if func not in signatures:
        return None
    sigs = signatures[func]
    return any((check_valid(sig, args, kwargs) for sig in sigs))

def check_partial(sig, args, kwargs):
    (num_pos_only, func, keyword_exclude, sigspec) = sig
    if len(args) < num_pos_only:
        pad = (None,) * (num_pos_only - len(args))
        args = args + pad
    if keyword_exclude:
        kwargs = dict(kwargs)
        for item in keyword_exclude:
            kwargs.pop(item, None)
    return is_partial_args(func, args, kwargs, sigspec)

def _is_partial_args(func, args, kwargs):
    if func not in signatures:
        return None
    sigs = signatures[func]
    return any((check_partial(sig, args, kwargs) for sig in sigs))

def check_arity(n, sig):
    (num_pos_only, func, keyword_exclude, sigspec) = sig
    if keyword_exclude or num_pos_only > n:
        return False
    return is_arity(n, func, sigspec)

def _is_arity(n, func):
    if func not in signatures:
        return None
    sigs = signatures[func]
    checks = [check_arity(n, sig) for sig in sigs]
    if all(checks):
        return True
    elif any(checks):
        return None
    return False

def check_varargs(sig):
    (num_pos_only, func, keyword_exclude, sigspec) = sig
    return has_varargs(func, sigspec)

def _has_varargs(func):
    if func not in signatures:
        return None
    sigs = signatures[func]
    checks = [check_varargs(sig) for sig in sigs]
    if all(checks):
        return True
    elif any(checks):
        return None
    return False

def check_keywords(sig):
    (num_pos_only, func, keyword_exclude, sigspec) = sig
    if keyword_exclude:
        return True
    return has_keywords(func, sigspec)

def _has_keywords(func):
    if func not in signatures:
        return None
    sigs = signatures[func]
    checks = [check_keywords(sig) for sig in sigs]
    if all(checks):
        return True
    elif any(checks):
        return None
    return False

def check_required_args(sig):
    (num_pos_only, func, keyword_exclude, sigspec) = sig
    return num_required_args(func, sigspec)

def _num_required_args(func):
    if func not in signatures:
        return None
    sigs = signatures[func]
    vals = [check_required_args(sig) for sig in sigs]
    val = vals[0]
    if all((x == val for x in vals)):
        return val
    return None

