def test_unzip():

    def _to_lists(seq, n=10):

        def initial(s):
            return list(take(n, s))
        return initial(map(initial, seq))

    def _assert_initial_matches(a, b, n=10):
        assert list(take(n, a)) == list(take(n, b))
    assert _to_lists(unzip([('a', 1), ('b', 2), ('c', 3)])) == [['a', 'b', 'c'], [1, 2, 3]]
    (a, b, c) = unzip(zip(count(1), repeat(0), repeat(1)))
    _assert_initial_matches(a, count(1))
    _assert_initial_matches(b, repeat(0))
    _assert_initial_matches(c, repeat(1))
    assert list(unzip(zip([]))) == []

def test_fold():
    assert fold(add, range(10), 0) == reduce(add, range(10), 0)
    with Pool() as pool:
        assert fold(add, range(10), 0, map=pool.map) == reduce(add, range(10), 0)
    assert fold(add, range(10), 0, chunksize=2) == reduce(add, range(10), 0)
    assert fold(add, range(10)) == fold(add, range(10), 0)

    def setadd(s, item):
        s = s.copy()
        s.add(item)
        return s
    assert fold(setadd, [1, 2, 3], set()) == {1, 2, 3}
    assert fold(setadd, [1, 2, 3], set(), chunksize=2, combine=set.union) == {1, 2, 3}
    assert fold(add, range(10), default=no_default2) == fold(add, range(10))

def fib(n):
    (a, b) = (0, 1)
    for i in range(n):
        (a, b) = (b, a + b)
    return a

def fib(n):
    if n == 0 or n == 1:
        return n
    else:
        return fib(n - 1) + fib(n - 2)

def bfs(graph: list[list[int]], source: int, sink: int, parent: list[int]) -> bool:
    visited = [False] * len(graph)
    queue = [source]
    visited[source] = True
    while queue:
        node = queue.pop(0)
        for neighbor in range(len(graph[node])):
            if visited[neighbor] is False and graph[node][neighbor] > 0:
                queue.append(neighbor)
                visited[neighbor] = True
                parent[neighbor] = node
    return visited[sink]

def mincut(graph: list[list[int]], source: int, sink: int) -> list[tuple[int, int]]:
    residual = [row[:] for row in graph]
    parent = [-1] * len(residual)
    res = []
    while bfs(residual, source, sink, parent):
        path_flow = max((max(row) for row in residual))
        s = sink
        while s != source:
            path_flow = min(path_flow, residual[parent[s]][s])
            s = parent[s]
        v = sink
        while v != source:
            u = parent[v]
            residual[u][v] -= path_flow
            residual[v][u] += path_flow
            v = parent[v]
    for i in range(len(graph)):
        for j in range(len(graph[0])):
            if graph[i][j] > 0 and residual[i][j] == 0:
                res.append((i, j))
    return res

def breadth_first_search(graph: list, source: int, sink: int, parents: list) -> bool:
    num_nodes = len(graph)
    visited = [False] * num_nodes
    queue = []
    queue.append(source)
    visited[source] = True
    while queue:
        current_node = queue.pop(0)
        if current_node == sink:
            return True
        for (neighbor, capacity) in enumerate(graph[current_node]):
            if not visited[neighbor] and capacity > 0:
                visited[neighbor] = True
                parents[neighbor] = current_node
                queue.append(neighbor)
    return visited[sink]

def binary_search(a_list: list[int], item: int) -> bool:
    if len(a_list) == 0:
        return False
    midpoint = len(a_list) // 2
    if a_list[midpoint] == item:
        return True
    if item < a_list[midpoint]:
        return binary_search(a_list[:midpoint], item)
    else:
        return binary_search(a_list[midpoint + 1:], item)

def bisect_left(sorted_collection: list[int], item: int, lo: int=0, hi: int=-1) -> int:
    if hi < 0:
        hi = len(sorted_collection)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if sorted_collection[mid] < item:
            lo = mid + 1
        else:
            hi = mid
    return lo

def bisect_right(sorted_collection: list[int], item: int, lo: int=0, hi: int=-1) -> int:
    if hi < 0:
        hi = len(sorted_collection)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if sorted_collection[mid] <= item:
            lo = mid + 1
        else:
            hi = mid
    return lo

def binary_search(sorted_collection: list[int], item: int) -> int:
    if any((a > b for (a, b) in pairwise(sorted_collection))):
        raise ValueError('sorted_collection must be sorted in ascending order')
    left = 0
    right = len(sorted_collection) - 1
    result = -1
    while left <= right:
        midpoint = left + (right - left) // 2
        current_item = sorted_collection[midpoint]
        if current_item == item:
            result = midpoint
            right = midpoint - 1
        elif item < current_item:
            right = midpoint - 1
        else:
            left = midpoint + 1
    return result

def binary_search_std_lib(sorted_collection: list[int], item: int) -> int:
    if list(sorted_collection) != sorted(sorted_collection):
        raise ValueError('sorted_collection must be sorted in ascending order')
    index = bisect.bisect_left(sorted_collection, item)
    if index != len(sorted_collection) and sorted_collection[index] == item:
        return index
    return -1

def binary_search_with_duplicates(sorted_collection: list[int], item: int) -> list[int]:
    if list(sorted_collection) != sorted(sorted_collection):
        raise ValueError('sorted_collection must be sorted in ascending order')

    def lower_bound(sorted_collection: list[int], item: int) -> int:
        left = 0
        right = len(sorted_collection)
        while left < right:
            midpoint = left + (right - left) // 2
            current_item = sorted_collection[midpoint]
            if current_item < item:
                left = midpoint + 1
            else:
                right = midpoint
        return left

    def upper_bound(sorted_collection: list[int], item: int) -> int:
        left = 0
        right = len(sorted_collection)
        while left < right:
            midpoint = left + (right - left) // 2
            current_item = sorted_collection[midpoint]
            if current_item <= item:
                left = midpoint + 1
            else:
                right = midpoint
        return left
    left = lower_bound(sorted_collection, item)
    right = upper_bound(sorted_collection, item)
    if left == len(sorted_collection) or sorted_collection[left] != item:
        return []
    return list(range(left, right))

def binary_search_by_recursion(sorted_collection: list[int], item: int, left: int=0, right: int=-1) -> int:
    if right < 0:
        right = len(sorted_collection) - 1
    if list(sorted_collection) != sorted(sorted_collection):
        raise ValueError('sorted_collection must be sorted in ascending order')

    def _binary_search_recursive(left_idx: int, right_idx: int) -> int:
        if right_idx < left_idx:
            return -1
        midpoint = left_idx + (right_idx - left_idx) // 2
        current_item = sorted_collection[midpoint]
        if current_item == item:
            leftmost = _binary_search_recursive(left_idx, midpoint - 1)
            return leftmost if leftmost != -1 else midpoint
        elif item < current_item:
            return _binary_search_recursive(left_idx, midpoint - 1)
        else:
            return _binary_search_recursive(midpoint + 1, right_idx)
    return _binary_search_recursive(left, right)

def exponential_search(sorted_collection: list[int], item: int) -> int:
    if list(sorted_collection) != sorted(sorted_collection):
        raise ValueError('sorted_collection must be sorted in ascending order')
    bound = 1
    while bound < len(sorted_collection) and sorted_collection[bound] < item:
        bound *= 2
    left = bound // 2
    right = min(bound, len(sorted_collection) - 1)
    last_result = binary_search_by_recursion(sorted_collection=sorted_collection, item=item, left=left, right=right)
    if last_result is None:
        return -1
    return last_result

def double_linear_search(array: list[int], search_item: int) -> int:
    (start_ind, end_ind) = (0, len(array) - 1)
    while start_ind <= end_ind:
        if array[start_ind] == search_item:
            return start_ind
        elif array[end_ind] == search_item:
            return end_ind
        else:
            start_ind += 1
            end_ind -= 1
    return -1

def sentinel_linear_search(sequence, target):
    sequence.append(target)
    index = 0
    while sequence[index] != target:
        index += 1
    sequence.pop()
    if index == len(sequence):
        return None
    return index

def binary_search_by_recursion(sorted_collection: list[int], item: int, left: int=0, right: int | None=None) -> int:
    if list(sorted_collection) != sorted(sorted_collection):
        raise ValueError('sorted_collection must be sorted in ascending order')
    if right is None:
        right = len(sorted_collection) - 1

    def _search(left: int, right: int) -> int:
        if right < left:
            return -1
        midpoint = left + (right - left) // 2
        if sorted_collection[midpoint] == item:
            return midpoint
        elif sorted_collection[midpoint] > item:
            return _search(left, midpoint - 1)
        else:
            return _search(midpoint + 1, right)
    return _search(left, right)

def exponential_search(sorted_collection: list[int], item: int) -> int:
    if list(sorted_collection) != sorted(sorted_collection):
        raise ValueError('sorted_collection must be sorted in ascending order')
    if not sorted_collection:
        return -1
    if sorted_collection[0] == item:
        return 0
    bound = 1
    while bound < len(sorted_collection) and sorted_collection[bound] < item:
        bound *= 2
    left = bound // 2
    right = min(bound, len(sorted_collection) - 1)
    return binary_search_by_recursion(sorted_collection, item, left, right)

def _partition(data: list, pivot) -> tuple:
    (less, equal, greater) = ([], [], [])
    for element in data:
        if element < pivot:
            less.append(element)
        elif element > pivot:
            greater.append(element)
        else:
            equal.append(element)
    return (less, equal, greater)

def quick_select(items: list, index: int):
    if index >= len(items) or index < 0:
        return None
    pivot = items[random.randint(0, len(items) - 1)]
    count = 0
    (smaller, equal, larger) = _partition(items, pivot)
    count = len(equal)
    m = len(smaller)
    if m <= index < m + count:
        return pivot
    elif m > index:
        return quick_select(smaller, index)
    else:
        return quick_select(larger, index - (m + count))

def median(items: list):
    (mid, rem) = divmod(len(items), 2)
    if rem != 0:
        return quick_select(items=items, index=mid)
    else:
        low_mid = quick_select(items=items, index=mid - 1)
        high_mid = quick_select(items=items, index=mid)
        return (low_mid + high_mid) / 2

def lin_search(left: int, right: int, array: list[int], target: int) -> int:
    for i in range(left, right):
        if array[i] == target:
            return i
    return -1

def ite_ternary_search(array: list[int], target: int) -> int:
    left = 0
    right = len(array)
    while left <= right:
        if right - left < precision:
            return lin_search(left, right, array, target)
        one_third = left + (right - left) // 3
        two_third = right - (right - left) // 3
        if array[one_third] == target:
            return one_third
        elif array[two_third] == target:
            return two_third
        elif target < array[one_third]:
            right = one_third
        elif array[two_third] < target:
            left = two_third + 1
        else:
            left = one_third + 1
            right = two_third
    return -1

def rec_ternary_search(left: int, right: int, array: list[int], target: int) -> int:
    if left < right:
        if right - left < precision:
            return lin_search(left, right, array, target)
        one_third = left + (right - left) // 3
        two_third = right - (right - left) // 3
        if array[one_third] == target:
            return one_third
        elif array[two_third] == target:
            return two_third
        elif target < array[one_third]:
            return rec_ternary_search(left, one_third, array, target)
        elif array[two_third] < target:
            return rec_ternary_search(two_third + 1, right, array, target)
        else:
            return rec_ternary_search(one_third + 1, two_third, array, target)
    else:
        return -1

