def pre_order_iter(node: TreeNode) -> None:
    if not isinstance(node, TreeNode) or not node:
        return
    stack: list[TreeNode] = []
    n = node
    while n or stack:
        while n:
            print(n.data, end=',')
            stack.append(n)
            n = n.left
        n = stack.pop()
        n = n.right

def in_order_iter(node: TreeNode) -> None:
    if not isinstance(node, TreeNode) or not node:
        return
    stack: list[TreeNode] = []
    n = node
    while n or stack:
        while n:
            stack.append(n)
            n = n.left
        n = stack.pop()
        print(n.data, end=',')
        n = n.right

def post_order_iter(node: TreeNode) -> None:
    if not isinstance(node, TreeNode) or not node:
        return
    (stack1, stack2) = ([], [])
    n = node
    stack1.append(n)
    while stack1:
        n = stack1.pop()
        if n.left:
            stack1.append(n.left)
        if n.right:
            stack1.append(n.right)
        stack2.append(n)
    while stack2:
        print(stack2.pop().data, end=',')

def prompt(s: str='', width=50, char='*') -> str:
    if not s:
        return '\n' + width * char
    (left, extra) = divmod(width - len(s) - 2, 2)
    return f'{left * char} {s} {(left + extra) * char}'

def linear_search(sequence: list, target: int) -> int:
    for (index, item) in enumerate(sequence):
        if item == target:
            return index
    return -1

def rec_linear_search(sequence: list, low: int, high: int, target: int) -> int:
    if not (0 <= high < len(sequence) and 0 <= low < len(sequence)):
        raise ValueError('Invalid upper or lower bound!')
    if high < low:
        return -1
    if sequence[low] == target:
        return low
    if sequence[high] == target:
        return high
    return rec_linear_search(sequence, low + 1, high - 1, target)

def generate_neighbours(path):
    dict_of_neighbours = {}
    with open(path) as f:
        for line in f:
            if line.split()[0] not in dict_of_neighbours:
                _list = []
                _list.append([line.split()[1], line.split()[2]])
                dict_of_neighbours[line.split()[0]] = _list
            else:
                dict_of_neighbours[line.split()[0]].append([line.split()[1], line.split()[2]])
            if line.split()[1] not in dict_of_neighbours:
                _list = []
                _list.append([line.split()[0], line.split()[2]])
                dict_of_neighbours[line.split()[1]] = _list
            else:
                dict_of_neighbours[line.split()[1]].append([line.split()[0], line.split()[2]])
    return dict_of_neighbours

def find_neighborhood(solution, dict_of_neighbours):
    neighborhood_of_solution = []
    for n in solution[1:-1]:
        idx1 = solution.index(n)
        for kn in solution[1:-1]:
            idx2 = solution.index(kn)
            if n == kn:
                continue
            _tmp = copy.deepcopy(solution)
            _tmp[idx1] = kn
            _tmp[idx2] = n
            distance = 0
            for k in _tmp[:-1]:
                next_node = _tmp[_tmp.index(k) + 1]
                for i in dict_of_neighbours[k]:
                    if i[0] == next_node:
                        distance = distance + int(i[1])
            _tmp.append(distance)
            if _tmp not in neighborhood_of_solution:
                neighborhood_of_solution.append(_tmp)
    index_of_last_item_in_the_list = len(neighborhood_of_solution[0]) - 1
    neighborhood_of_solution.sort(key=lambda x: x[index_of_last_item_in_the_list])
    return neighborhood_of_solution

def interpolation_search(sorted_collection: list[int], item: int) -> int | None:
    left = 0
    right = len(sorted_collection) - 1
    while left <= right:
        if sorted_collection[left] == sorted_collection[right]:
            if sorted_collection[left] == item:
                return left
            return None
        point = left + (item - sorted_collection[left]) * (right - left) // (sorted_collection[right] - sorted_collection[left])
        if point < 0 or point >= len(sorted_collection):
            return None
        current_item = sorted_collection[point]
        if current_item == item:
            return point
        if point < left:
            right = left
            left = point
        elif point > right:
            left = right
            right = point
        elif item < current_item:
            right = point - 1
        else:
            left = point + 1
    return None

def interpolation_search_by_recursion(sorted_collection: list[int], item: int, left: int=0, right: int | None=None) -> int | None:
    if right is None:
        right = len(sorted_collection) - 1
    if left > right:
        return None
    if sorted_collection[left] == sorted_collection[right]:
        return left if sorted_collection[left] == item else None
    point = left + (item - sorted_collection[left]) * (right - left) // (sorted_collection[right] - sorted_collection[left])
    if point < 0 or point >= len(sorted_collection):
        return None
    if sorted_collection[point] == item:
        return point
    if point < left:
        return interpolation_search_by_recursion(sorted_collection, item, point, left)
    if point > right:
        return interpolation_search_by_recursion(sorted_collection, item, right, left)
    if sorted_collection[point] > item:
        return interpolation_search_by_recursion(sorted_collection, item, left, point - 1)
    return interpolation_search_by_recursion(sorted_collection, item, point + 1, right)

def median_of_five(arr: list) -> int:
    arr = sorted(arr)
    return arr[len(arr) // 2]

def median_of_medians(arr: list) -> int:
    if len(arr) <= 5:
        return median_of_five(arr)
    medians = []
    i = 0
    while i < len(arr):
        if i + 4 <= len(arr):
            medians.append(median_of_five(arr[i:].copy()))
        else:
            medians.append(median_of_five(arr[i:i + 5].copy()))
        i += 5
    return median_of_medians(medians)

def quick_select(arr: list, target: int) -> int:
    if target > len(arr):
        return -1
    x = median_of_medians(arr)
    left = []
    right = []
    check = False
    for i in range(len(arr)):
        if arr[i] < x:
            left.append(arr[i])
        elif arr[i] > x:
            right.append(arr[i])
        elif arr[i] == x and (not check):
            check = True
        else:
            right.append(arr[i])
    rank_x = len(left) + 1
    if rank_x == target:
        answer = x
    elif rank_x > target:
        answer = quick_select(left, target)
    elif rank_x < target:
        answer = quick_select(right, target - rank_x)
    return answer

def make_set(x: Node) -> None:
    x.rank = 0
    x.parent = x

def union_set(x: Node, y: Node) -> None:
    (x, y) = (find_set(x), find_set(y))
    if x == y:
        return
    elif x.rank > y.rank:
        y.parent = x
    else:
        x.parent = y
        if x.rank == y.rank:
            y.rank += 1

def find_set(x: Node) -> Node:
    if x != x.parent:
        x.parent = find_set(x.parent)
    return x.parent

def find_python_set(node: Node) -> set:
