def next_greatest_element_slow(arr: list[float]) -> list[float]:
    result = []
    arr_size = len(arr)
    for i in range(arr_size):
        next_element: float = -1
        for j in range(i + 1, arr_size):
            if arr[i] < arr[j]:
                next_element = arr[j]
                break
        result.append(next_element)
    return result

def next_greatest_element_fast(arr: list[float]) -> list[float]:
    result = []
    for (i, outer) in enumerate(arr):
        next_item: float = -1
        for inner in arr[i + 1:]:
            if outer < inner:
                next_item = inner
                break
        result.append(next_item)
    return result

def next_greatest_element(arr: list[float]) -> list[float]:
    arr_size = len(arr)
    stack: list[float] = []
    result: list[float] = [-1] * arr_size
    for index in reversed(range(arr_size)):
        if stack:
            while stack[-1] <= arr[index]:
                stack.pop()
                if not stack:
                    break
        if stack:
            result[index] = stack[-1]
        stack.append(arr[index])
    return result

def evaluate(expression) -> float:
    stack = []
    for c in expression.split()[::-1]:
        if is_operand(c):
            stack.append(int(c))
        else:
            o1 = stack.pop()
            o2 = stack.pop()
            stack.append(operators[c](o1, o2))
    return stack.pop()

def evaluate_recursive(expression: list[str]) -> float:
    op = expression.pop(0)
    if is_operand(op):
        return int(op)
    operation = operators[op]
    a = evaluate_recursive(expression)
    b = evaluate_recursive(expression)
    return operation(a, b)

def dijkstras_two_stack_algorithm(equation: str) -> int:
    operators = {'*': op.mul, '/': op.truediv, '+': op.add, '-': op.sub}
    operand_stack: Stack[int] = Stack()
    operator_stack: Stack[str] = Stack()
    for i in equation:
        if i.isdigit():
            operand_stack.push(int(i))
        elif i in operators:
            operator_stack.push(i)
        elif i == ')':
            opr = operator_stack.peek()
            operator_stack.pop()
            num1 = operand_stack.peek()
            operand_stack.pop()
            num2 = operand_stack.peek()
            operand_stack.pop()
            total = operators[opr](num2, num1)
            operand_stack.push(total)
    return operand_stack.peek()

def find_kth_next_greater_element(array: list[int | float], kth_ord: int) -> list[int | float | None]:
    if not isinstance(kth_ord, int) or kth_ord < 1:
        raise ValueError('kth_ord must be a positive integer.')
    kth_next_greater_elements: list[int | float | None] = [None] * len(array)
    if kth_ord >= len(array):
        return kth_next_greater_elements
    stacks: list[list[tuple[int | float, int]]] = [[] for _ in range(kth_ord + 1)]
    for (idx, element) in enumerate(array):
        while stacks[kth_ord] and stacks[kth_ord][-1][0] < element:
            (_, prev_idx) = stacks[kth_ord].pop()
            kth_next_greater_elements[prev_idx] = element
        for stack_ord in range(kth_ord - 1, 0, -1):
            while stacks[stack_ord] and stacks[stack_ord][-1][0] < element:
                stacks[0].append(stacks[stack_ord].pop())
            while stacks[0]:
                stacks[stack_ord + 1].append(stacks[0].pop())
        unvisited_elements_count = len(array) - 1 - idx
        if unvisited_elements_count >= kth_ord:
            stacks[1].append((element, idx))
    return kth_next_greater_elements

def balanced_parentheses(parentheses: str) -> bool:
    stack: Stack[str] = Stack()
    bracket_pairs = {'(': ')', '[': ']', '{': '}'}
    for bracket in parentheses:
        if bracket in bracket_pairs:
            stack.push(bracket)
        elif bracket in (')', ']', '}') and (stack.is_empty() or bracket_pairs[stack.pop()] != bracket):
            return False
    return stack.is_empty()

