def postfix_to_infix(postfix_expression: str) -> str:
    if postfix_expression is None or postfix_expression == '':
        raise ValueError('Invalid postfix expression.')
    stack = []
    for item in postfix_expression:
        if item not in ['+', '-', '*', '/', '^']:
            stack.append(item)
        else:
            operand_2 = stack.pop()
            operand_1 = stack.pop()
            infix_expression = '(' + operand_1 + item + operand_2 + ')'
            stack.append(infix_expression)
    return stack.pop()

def infix_to_postfix(expression_str: str) -> str:
    if not balanced_parentheses(expression_str):
        raise ValueError('Mismatched parentheses')
    stack: Stack[str] = Stack()
    postfix = []
    for char in expression_str:
        if char.isalpha() or char.isdigit():
            postfix.append(char)
        elif char == '(':
            stack.push(char)
        elif char == ')':
            while not stack.is_empty() and stack.peek() != '(':
                postfix.append(stack.pop())
            stack.pop()
        else:
            while True:
                if stack.is_empty():
                    stack.push(char)
                    break
                char_precedence = precedence(char)
                tos_precedence = precedence(stack.peek())
                if char_precedence > tos_precedence:
                    stack.push(char)
                    break
                if char_precedence < tos_precedence:
                    postfix.append(stack.pop())
                    continue
                if associativity(char) == 'RL':
                    stack.push(char)
                    break
                postfix.append(stack.pop())
    while not stack.is_empty():
        postfix.append(stack.pop())
    return ' '.join(postfix)

def lexical_order(max_number: int) -> Iterator[int]:
    stack = [1]
    while stack:
        num = stack.pop()
        if num > max_number:
            continue
        yield num
        if num % 10 != 9:
            stack.append(num + 1)
        stack.append(num * 10)

def parse_token(token: str | float) -> float | str:
    if token in OPERATORS:
        return token
    try:
        return float(token)
    except ValueError:
        msg = f'{token} is neither a number nor a valid operator'
        raise ValueError(msg)

def evaluate(post_fix: list[str], verbose: bool=False) -> float:
    if not post_fix:
        return 0
    valid_expression = [parse_token(token) for token in post_fix]
    if verbose:
        print('Symbol'.center(8), 'Action'.center(12), 'Stack', sep=' | ')
        print('-' * (30 + len(post_fix)))
    stack = []
    for x in valid_expression:
        if x not in OPERATORS:
            stack.append(x)
            if verbose:
                print(f'{x}'.rjust(8), f'push({x})'.ljust(12), stack, sep=' | ')
            continue
        if x in UNARY_OP_SYMBOLS and len(stack) < 2:
            b = stack.pop()
            if x == '-':
                b *= -1
            stack.append(b)
            if verbose:
                print(''.rjust(8), f'pop({b})'.ljust(12), stack, sep=' | ')
                print(str(x).rjust(8), f'push({x}{b})'.ljust(12), stack, sep=' | ')
            continue
        b = stack.pop()
        if verbose:
            print(''.rjust(8), f'pop({b})'.ljust(12), stack, sep=' | ')
        a = stack.pop()
        if verbose:
            print(''.rjust(8), f'pop({a})'.ljust(12), stack, sep=' | ')
        stack.append(OPERATORS[x](a, b))
        if verbose:
            print(f'{x}'.rjust(8), f'push({a}{x}{b})'.ljust(12), stack, sep=' | ')
    if len(stack) != 1:
        raise ArithmeticError('Input is not a valid postfix expression')
    return float(stack[0])

