def get_middle(head: Node | None) -> Node | None:
    if head is None or head.next is None:
        return None
    slow: Node | None = head
    fast: Node | None = head.next
    while fast is not None and fast.next is not None:
        if slow is None:
            return None
        slow = slow.next
        fast = fast.next.next
    return slow

def merge(left: Node | None, right: Node | None) -> Node | None:
    if left is None:
        return right
    if right is None:
        return left
    if left <= right:
        result = left
        result.next = merge(left.next, right)
    else:
        result = right
        result.next = merge(left, right.next)
    return result

def merge_sort_linked_list(head: Node | None) -> Node | None:
    if head is None or head.next is None:
        return head
    middle = get_middle(head)
    if middle is None or middle.next is None:
        return head
    next_to_middle = middle.next
    middle.next = None
    left = merge_sort_linked_list(head)
    right = merge_sort_linked_list(next_to_middle)
    return merge(left, right)

def is_palindrome(head: ListNode | None) -> bool:
    if not head:
        return True
    fast: ListNode | None = head.next_node
    slow: ListNode | None = head
    while fast and fast.next_node:
        fast = fast.next_node.next_node
        slow = slow.next_node if slow else None
    if slow:
        second = slow.next_node
        slow.next_node = None
    node: ListNode | None = None
    while second:
        nxt = second.next_node
        second.next_node = node
        node = second
        second = nxt
    while node and head:
        if node.val != head.val:
            return False
        node = node.next_node
        head = head.next_node
    return True

def is_palindrome_stack(head: ListNode | None) -> bool:
    if not head or not head.next_node:
        return True
    slow: ListNode | None = head
    fast: ListNode | None = head
    while fast and fast.next_node:
        fast = fast.next_node.next_node
        slow = slow.next_node if slow else None
    if slow:
        stack = [slow.val]
        while slow.next_node:
            slow = slow.next_node
            stack.append(slow.val)
        cur: ListNode | None = head
        while stack and cur:
            if stack.pop() != cur.val:
                return False
            cur = cur.next_node
    return True

def is_palindrome_dict(head: ListNode | None) -> bool:
    if not head or not head.next_node:
        return True
    d: dict[int, list[int]] = {}
    pos = 0
    while head:
        if head.val in d:
            d[head.val].append(pos)
        else:
            d[head.val] = [pos]
        head = head.next_node
        pos += 1
    checksum = pos - 1
    middle = 0
    for v in d.values():
        if len(v) % 2 != 0:
            middle += 1
        else:
            for (step, i) in enumerate(range(len(v))):
                if v[i] + v[len(v) - 1 - step] != checksum:
                    return False
        if middle > 1:
            return False
    return True

