def find_median_sorted_arrays(nums1: list[int], nums2: list[int]) -> float:
    if not nums1 and (not nums2):
        raise ValueError('Both input arrays are empty.')
    merged = sorted(nums1 + nums2)
    total = len(merged)
    if total % 2 == 1:
        return float(merged[total // 2])
    middle1 = merged[total // 2 - 1]
    middle2 = merged[total // 2]
    return (float(middle1) + float(middle2)) / 2.0

def partition(arr: list[int], low: int, high: int) -> int:
    pivot = arr[high]
    i = low - 1
    for j in range(low, high):
        if arr[j] >= pivot:
            i += 1
            (arr[i], arr[j]) = (arr[j], arr[i])
    (arr[i + 1], arr[high]) = (arr[high], arr[i + 1])
    return i + 1

def kth_largest_element(arr: list[int], position: int) -> int:
    if not arr:
        return -1
    if not isinstance(position, int):
        raise ValueError('The position should be an integer')
    if not 1 <= position <= len(arr):
        raise ValueError("Invalid value of 'position'")
    (low, high) = (0, len(arr) - 1)
    while low <= high:
        if low > len(arr) - 1 or high < 0:
            return -1
        pivot_index = partition(arr, low, high)
        if pivot_index == position - 1:
            return arr[pivot_index]
        elif pivot_index > position - 1:
            high = pivot_index - 1
        else:
            low = pivot_index + 1
    return -1

def build_sparse_table(number_list: list[int]) -> list[list[int]]:
    if not number_list:
        raise ValueError('empty number list not allowed')
    length = len(number_list)
    row = int(log2(length)) + 1
    sparse_table = [[0 for i in range(length)] for j in range(row)]
    for (i, value) in enumerate(number_list):
        sparse_table[0][i] = value
    j = 1
    while 1 << j <= length:
        i = 0
        while i + (1 << j) - 1 < length:
            sparse_table[j][i] = min(sparse_table[j - 1][i + (1 << j - 1)], sparse_table[j - 1][i])
            i += 1
        j += 1
    return sparse_table

def query(sparse_table: list[list[int]], left_bound: int, right_bound: int) -> int:
    if left_bound < 0 or right_bound >= len(sparse_table[0]):
        raise IndexError('list index out of range')
    j = int(log2(right_bound - left_bound + 1))
    return min(sparse_table[j][right_bound - (1 << j) + 1], sparse_table[j][left_bound])

def set_matrix_zeroes(matrix: list[list[int]]) -> None:
    rows = len(matrix)
    cols = len(matrix[0])
    col0 = 1
    for i in range(rows):
        if matrix[i][0] == 0:
            col0 = 0
        for j in range(1, cols):
            if matrix[i][j] == 0:
                matrix[i][0] = 0
                matrix[0][j] = 0
    for i in range(1, rows):
        for j in range(1, cols):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
    if matrix[0][0] == 0:
        for j in range(cols):
            matrix[0][j] = 0
    if col0 == 0:
        for i in range(rows):
            matrix[i][0] = 0

def merge_sorted_arrays(nums1: list[int], nums2: list[int]) -> list[int]:
    for nums in (nums1, nums2):
        if list(nums) != sorted(nums):
            msg = f'nums = {nums!r} is not sorted'
            raise ValueError(msg)
    if not nums1:
        return nums2
    if not nums2:
        return nums1
    (i, j) = (0, 0)
    merged = []
    while i < len(nums1) and j < len(nums2):
        if nums1[i] <= nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1
    merged.extend(nums1[i:])
    merged.extend(nums2[j:])
    return merged

def find_triplets_with_0_sum_hashing(arr: list[int]) -> list[list[int]]:
    target_sum = 0
    output_arr = []
    for (index, item) in enumerate(arr[:-2]):
        set_initialize = set()
        current_sum = target_sum - item
        for other_item in arr[index + 1:]:
            required_value = current_sum - other_item
            if required_value in set_initialize:
                combination_array = sorted([item, other_item, required_value])
                if combination_array not in output_arr:
                    output_arr.append(combination_array)
            set_initialize.add(other_item)
    return output_arr

def find_triplets_with_0_sum_two_pointers(nums: list[int]) -> list[list[int]]:
    nums.sort()
    result = []
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        (left, right) = (i + 1, n - 1)
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                result.append([nums[i], nums[left], nums[right]])
                left += 1
                right -= 1
                while left < right and nums[left] == nums[left - 1]:
                    left += 1
                while left < right and nums[right] == nums[right + 1]:
                    right -= 1
            elif total < 0:
                left += 1
            else:
                right -= 1
    return result

def permute_recursive(nums: list[int]) -> list[list[int]]:
    result: list[list[int]] = []
    if len(nums) == 0:
        return [[]]
    for _ in range(len(nums)):
        n = nums.pop(0)
        permutations = permute_recursive(nums.copy())
        for perm in permutations:
            perm.append(n)
        result.extend(permutations)
        nums.append(n)
    return result

def permute_backtrack(nums: list[int]) -> list[list[int]]:

    def backtrack(start: int) -> None:
        if start == len(nums) - 1:
            output.append(nums[:])
        else:
            for i in range(start, len(nums)):
                (nums[start], nums[i]) = (nums[i], nums[start])
                backtrack(start + 1)
                (nums[start], nums[i]) = (nums[i], nums[start])
    output: list[list[int]] = []
    backtrack(0)
    return output

def rotate_array(arr: list[int], steps: int) -> list[int]:
    n = len(arr)
    if n == 0:
        return arr
    steps = steps % n
    if steps < 0:
        steps += n

    def reverse(start: int, end: int) -> None:
        while start < end:
            (arr[start], arr[end]) = (arr[end], arr[start])
            start += 1
            end -= 1
    reverse(0, n - 1)
    reverse(0, steps - 1)
    reverse(steps, n - 1)
    return arr

def equilibrium_index(arr: list[int]) -> int:
    total_sum = sum(arr)
    left_sum = 0
    for (i, value) in enumerate(arr):
        total_sum -= value
        if left_sum == total_sum:
            return i
        left_sum += value
    return -1

def index_2d_array_in_1d(array: list[list[int]], index: int) -> int:
    rows = len(array)
    cols = len(array[0])
    if rows == 0 or cols == 0:
        raise ValueError('no items in array')
    if index < 0 or index >= rows * cols:
        raise ValueError('index out of range')
    return array[index // cols][index % cols]

def product_sum(arr: list[int | list], depth: int) -> int:
    total_sum = 0
    for ele in arr:
        total_sum += product_sum(ele, depth + 1) if isinstance(ele, list) else ele
    return total_sum * depth

def product_sum_iterative(arr: list[int | list]) -> int:
    queue = [(arr, 1, 1)]
    product_sum = 0
    while queue:
        (queue_front_list, depth, multiplication_factor) = queue.pop(0)
        for element in queue_front_list:
            if isinstance(element, list):
                queue.append((element, depth + 1, multiplication_factor * (depth + 1)))
            else:
                product_sum += element * multiplication_factor
    return product_sum

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []
    for interval in intervals:
        msg = f'Each interval must have exactly 2 integers, got {interval}'
        if len(interval) != 2:
            raise ValueError(msg)
    sorted_intervals = sorted(intervals, key=lambda interval: interval[0])
    merged: list[list[int]] = [sorted_intervals[0][:]]
    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            last[1] = max(last[1], current[1])
        else:
            merged.append(current[:])
    return merged

def max_sliding_window(arr: list[float], window_size: int) -> list[float]:
    max_val = []
    mono_queue: deque = deque()
    for i in range(len(arr)):
        if mono_queue and i - mono_queue[0] >= window_size:
            mono_queue.popleft()
        while mono_queue and arr[i] >= arr[mono_queue[-1]]:
            mono_queue.pop()
        mono_queue.append(i)
        if i >= window_size - 1:
            max_val.append(arr[mono_queue[0]])
    return max_val

def sdbm(plain_text: str) -> int:
    hash_value = 0
    for plain_chr in plain_text:
        hash_value = ord(plain_chr) + (hash_value << 6) + (hash_value << 16) - hash_value
    return hash_value

def _generate_crc32_table() -> list[int]:
    polynomial = 3988292384
    table = []
    for i in range(256):
        crc = i
        for _ in range(8):
            if crc & 1:
                crc = crc >> 1 ^ polynomial
            else:
                crc >>= 1
        table.append(crc)
    return table

def crc32(data: bytes) -> int:
    if not isinstance(data, bytes):
        msg = f'data must be bytes, not {type(data).__name__}'
        raise TypeError(msg)
    crc = 4294967295
    for byte in data:
        table_index = (crc ^ byte) & 255
        crc = crc >> 8 ^ CRC32_TABLE[table_index]
    return crc ^ 4294967295

