def z_function(input_str: str) -> list[int]:
    z_result = [0 for i in range(len(input_str))]
    (left_pointer, right_pointer) = (0, 0)
    for i in range(1, len(input_str)):
        if i <= right_pointer:
            min_edge = min(right_pointer - i + 1, z_result[i - left_pointer])
            z_result[i] = min_edge
        while go_next(i, z_result, input_str):
            z_result[i] += 1
        if i + z_result[i] - 1 > right_pointer:
            (left_pointer, right_pointer) = (i, i + z_result[i] - 1)
    return z_result

def find_pattern(pattern: str, input_str: str) -> int:
    pattern_length = len(pattern)
    z_result = z_function(pattern + input_str)
    return sum((value >= pattern_length for value in z_result[pattern_length:]))

def min_window(search_str: str, target_letters: str) -> str:
    target_count = len(target_letters)
    search_len = len(search_str)
    if search_len < target_count:
        return ''
    char_dict = {}
    for ch in target_letters:
        if ch not in char_dict:
            char_dict[ch] = 1
        else:
            char_dict[ch] += 1
    window_start = 0
    window_end = 0
    exists = False
    min_window_len = search_len + 1
    while window_end < search_len:
        while target_count > 0 and window_end < search_len:
            cur = search_str[window_end]
            if cur in char_dict:
                char_dict[cur] -= 1
                if char_dict[cur] >= 0:
                    target_count -= 1
            window_end += 1
        temp = window_end - window_start
        if target_count == 0 and temp < min_window_len:
            min_window = [window_start, window_end]
            exists = True
            min_window_len = temp
        while target_count == 0 and window_start < window_end:
            cur = search_str[window_start]
            window_start += 1
            if cur in char_dict:
                char_dict[cur] += 1
                if char_dict[cur] > 0:
                    break
        temp = window_end - window_start + 1
        if temp < min_window_len and target_count == 0:
            min_window = [window_start - 1, window_end]
            min_window_len = temp
        target_count = 1
    if exists:
        return search_str[min_window[0]:min_window[1]]
    else:
        return ''

def damerau_levenshtein_distance(first_string: str, second_string: str) -> int:
    dp_matrix = [[0] * (len(second_string) + 1) for _ in range(len(first_string) + 1)]
    for i in range(len(first_string) + 1):
        dp_matrix[i][0] = i
    for j in range(len(second_string) + 1):
        dp_matrix[0][j] = j
    for (i, first_char) in enumerate(first_string, start=1):
        for (j, second_char) in enumerate(second_string, start=1):
            cost = int(first_char != second_char)
            dp_matrix[i][j] = min(dp_matrix[i - 1][j] + 1, dp_matrix[i][j - 1] + 1, dp_matrix[i - 1][j - 1] + cost)
            if i > 1 and j > 1 and (first_string[i - 1] == second_string[j - 2]) and (first_string[i - 2] == second_string[j - 1]):
                dp_matrix[i][j] = min(dp_matrix[i][j], dp_matrix[i - 2][j - 2] + cost)
    return dp_matrix[-1][-1]

def is_palindrome(s: str) -> bool:
    start_i = 0
    end_i = len(s) - 1
    while start_i < end_i:
        if s[start_i] == s[end_i]:
            start_i += 1
            end_i -= 1
        else:
            return False
    return True

def is_palindrome_traversal(s: str) -> bool:
    end = len(s) // 2
    n = len(s)
    return all((s[i] == s[n - i - 1] for i in range(end)))

def is_palindrome_recursive(s: str) -> bool:
    if len(s) <= 1:
        return True
    if s[0] == s[len(s) - 1]:
        return is_palindrome_recursive(s[1:-1])
    else:
        return False

def is_palindrome_ignore_case_and_spaces(s: str) -> bool:
