        current_state = state_machine[current_state][char_type]
    return current_state in valid_final_states

def text_justification(word: str, max_width: int) -> list:
    words = word.split()

    def justify(line: list, width: int, max_width: int) -> str:
        overall_spaces_count = max_width - width
        words_count = len(line)
        if len(line) == 1:
            return line[0] + ' ' * overall_spaces_count
        else:
            spaces_to_insert_between_words = words_count - 1
            num_spaces_between_words_list = spaces_to_insert_between_words * [overall_spaces_count // spaces_to_insert_between_words]
            spaces_count_in_locations = overall_spaces_count % spaces_to_insert_between_words
            for i in range(spaces_count_in_locations):
                num_spaces_between_words_list[i] += 1
            aligned_words_list = []
            for i in range(spaces_to_insert_between_words):
                aligned_words_list.append(line[i])
                aligned_words_list.append(num_spaces_between_words_list[i] * ' ')
            aligned_words_list.append(line[-1])
            return ''.join(aligned_words_list)
    answer = []
    line: list[str] = []
    width = 0
    for inner_word in words:
        if width + len(inner_word) + len(line) <= max_width:
            line.append(inner_word)
            width += len(inner_word)
        else:
            answer.append(justify(line, width, max_width))
            (line, width) = ([inner_word], len(inner_word))
    remaining_spaces = max_width - width - len(line)
    answer.append(' '.join(line) + (remaining_spaces + 1) * ' ')
    return answer

def jaro_winkler(str1: str, str2: str) -> float:

    def get_matched_characters(_str1: str, _str2: str) -> str:
        matched = []
        character_positions: defaultdict[str, deque[int]] = defaultdict(deque)
        for (index, char) in enumerate(_str2):
            character_positions[char].append(index)
        limit = min(len(_str1), len(_str2)) // 2
        for (i, char) in enumerate(_str1):
            positions = character_positions.get(char)
            if not positions:
                continue
            left = int(max(0, i - limit))
            right = int(min(i + limit + 1, len(_str2)))
            while positions and positions[0] < left:
                positions.popleft()
            if positions and positions[0] < right:
                matched.append(char)
                positions.popleft()
        return ''.join(matched)
    matching_1 = get_matched_characters(str1, str2)
    matching_2 = get_matched_characters(str2, str1)
    match_count = len(matching_1)
    transpositions = len([(c1, c2) for (c1, c2) in zip(matching_1, matching_2) if c1 != c2]) // 2
    if not match_count:
        jaro = 0.0
    else:
        jaro = 1 / 3 * (match_count / len(str1) + match_count / len(str2) + (match_count - transpositions) / match_count)
    prefix_len = 0
    for (c1, c2) in zip(str1[:4], str2[:4]):
        if c1 == c2:
            prefix_len += 1
        else:
            break
    return jaro + 0.1 * prefix_len * (1 - jaro)

