def join(separator: str, separated: list[str]) -> str:
    for word_or_phrase in separated:
        if not isinstance(word_or_phrase, str):
            raise Exception('join() accepts only strings')
    joined: str = ''
    '\n    The last element of the list is not followed by the separator.\n    So, we need to iterate through the list and join each element\n    with the separator except the last element.\n    '
    last_index: int = len(separated) - 1
    '\n    Iterate through the list and join each element with the separator.\n    Except the last element, all other elements are followed by the separator.\n    '
    for word_or_phrase in separated[:last_index]:
        joined += word_or_phrase + separator
    if separated != []:
        joined += separated[last_index]
    return joined

