def match_pattern(input_string: str, pattern: str) -> bool:
    len_string = len(input_string) + 1
    len_pattern = len(pattern) + 1
    dp = [[0 for i in range(len_pattern)] for j in range(len_string)]
    dp[0][0] = 1
    for i in range(1, len_string):
        dp[i][0] = 0
    for j in range(1, len_pattern):
        dp[0][j] = dp[0][j - 2] if pattern[j - 1] == '*' else 0
    for i in range(1, len_string):
        for j in range(1, len_pattern):
            if input_string[i - 1] == pattern[j - 1] or pattern[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[j - 1] == '*':
                if dp[i][j - 2] == 1:
                    dp[i][j] = 1
                elif pattern[j - 2] in (input_string[i - 1], '.'):
                    dp[i][j] = dp[i - 1][j]
                else:
                    dp[i][j] = 0
            else:
                dp[i][j] = 0
    return bool(dp[-1][-1])

def split(string: str, separator: str=' ') -> list:
    split_words = []
    separator_length = len(separator)
    if separator_length == 0:
        return [string]
    last_index = 0
    index = 0
    while index < len(string):
        if string[index:index + separator_length] == separator:
            split_words.append(string[last_index:index])
            last_index = index + separator_length
            index += separator_length
        else:
            index += 1
    split_words.append(string[last_index:])
    return split_words

