def get_set_bits_count_using_lookup_table(number: int) -> int:
    _lookup_table = [bin(i).count('1') for i in range(256)]
    if number < 0:
        raise ValueError('the value of input must not be negative')
    return _lookup_table[number & 255] + _lookup_table[number >> 8 & 255] + _lookup_table[number >> 16 & 255] + _lookup_table[number >> 24 & 255]

def gray_code(bit_count: int) -> list[int]:
    if bit_count < 0:
        raise ValueError('The given input must be positive')
    sequence = gray_code_sequence_string(bit_count)
    return [int(code, 2) for code in sequence]

def gray_code_sequence_string(bit_count: int) -> list[str]:
    if bit_count == 0:
        return ['0']
    if bit_count == 1:
        return ['0', '1']
    seq_len = 1 << bit_count
    smaller_sequence = gray_code_sequence_string(bit_count - 1)
    sequence: list[str] = []
    for i in range(seq_len // 2):
        generated_no = '0' + smaller_sequence[i]
        sequence.append(generated_no)
    for i in reversed(range(seq_len // 2)):
        generated_no = '1' + smaller_sequence[i]
        sequence.append(generated_no)
    return sequence

