        return []
    is_prime = [True] * (max_number // 2)
    for i in range(3, isqrt(max_number - 1) + 1, 2):
        if is_prime[i // 2]:
            is_prime[i ** 2 // 2::i] = [False] * len(range(i ** 2 // 2, max_number // 2, i))
    return [2] + [2 * i + 1 for i in range(1, max_number // 2) if is_prime[i]]

