def attention_mechanism(query: np.ndarray, key: np.ndarray, value: np.ndarray, mask: np.ndarray | None=None) -> tuple[np.ndarray, np.ndarray]:
    d_k = query.shape[-1]
    scores = query @ key.T / np.sqrt(d_k)
    if mask is not None:
        scores = np.where(mask, scores, -1000000000.0)
    exp_scores = np.exp(scores - np.max(scores, axis=-1, keepdims=True))
    attention_weights = exp_scores / np.sum(exp_scores, axis=-1, keepdims=True)
    output = attention_weights @ value
    return (output, attention_weights)

def layer_norm(embeddings: np.ndarray, epsilon: float=1e-06) -> np.ndarray:
    mean = embeddings.mean(axis=-1, keepdims=True)
    std = embeddings.std(axis=-1, keepdims=True)
    return (embeddings - mean) / (std + epsilon)

def mean_threshold(image: Image.Image) -> Image.Image:
    (height, width) = image.size
    mean = 0
    pixels = image.load()
    for i in range(width):
        for j in range(height):
            pixel = pixels[j, i]
            mean += pixel
    mean //= width * height
    for j in range(width):
        for i in range(height):
            pixels[i, j] = 255 if pixels[i, j] > mean else 0
    return image

def segment_image(image: np.ndarray, thresholds: list[int]) -> np.ndarray:
