def gram_matrix(mat: np.ndarray) -> np.ndarray:
    (color, height, width) = mat.shape
    vec = mat.reshape(color, height * width)
    gram = vec @ vec.T
    return gram / (color * height * width)

def gram_loss(input_features: np.ndarray, reference_features: np.ndarray) -> np.float64:
    input_gram = gram_matrix(input_features)
    reference_gram = gram_matrix(reference_features)
    return np.sum(np.square(input_gram - reference_gram)).astype(np.float64)

def straight_line_depreciation(useful_years: int, purchase_value: float, residual_value: float=0.0) -> list[float]:
    if not isinstance(useful_years, int):
        raise TypeError('Useful years must be an integer')
    if useful_years < 1:
        raise ValueError('Useful years cannot be less than 1')
    if not isinstance(purchase_value, (float, int)):
        raise TypeError('Purchase value must be numeric')
    if not isinstance(residual_value, (float, int)):
        raise TypeError('Residual value must be numeric')
    if purchase_value < 0.0:
        raise ValueError('Purchase value cannot be less than zero')
    if purchase_value < residual_value:
        raise ValueError('Purchase value cannot be less than residual value')
    depreciable_cost = purchase_value - residual_value
    annual_depreciation_expense = depreciable_cost / useful_years
    list_of_depreciation_expenses = []
    accumulated_depreciation_expense = 0.0
    for period in range(useful_years):
        if period != useful_years - 1:
            accumulated_depreciation_expense += annual_depreciation_expense
            list_of_depreciation_expenses.append(annual_depreciation_expense)
        else:
            depreciation_expense_in_end_year = depreciable_cost - accumulated_depreciation_expense
            list_of_depreciation_expenses.append(depreciation_expense_in_end_year)
    return list_of_depreciation_expenses

def calculate_weights(degree: float, length: int) -> list[float]:
    weights = [1.0]
    for k in range(1, length):
        weights.append(-1 * weights[-1] * (degree - k + 1) / k)
    return weights

def fracdiff_fixedwindow(price_series: Sequence[float], degree: float, window_size: int) -> list[float]:
    if window_size > len(price_series):
        raise ValueError('window_size cannot exceed the length of price_series')
    weights = calculate_weights(degree=degree, length=window_size)
    frac_diff_series = [nan] * window_size
    for i in range(window_size, len(price_series)):
        frac_diff_series.append(sum((weights[j] * price_series[i - j] for j in range(window_size))))
    return frac_diff_series

def simple_moving_average(data: Sequence[float], window_size: int) -> list[float | None]:
    if window_size < 1:
        raise ValueError('Window size must be a positive integer')
    sma: list[float | None] = []
    for i in range(len(data)):
        if i < window_size - 1:
            sma.append(None)
        else:
            window = data[i - window_size + 1:i + 1]
            sma_value = sum(window) / window_size
            sma.append(sma_value)
    return sma

def kelly_criterion(win_probability: float, win_loss_ratio: float) -> float:
    if win_probability <= 0 or win_probability >= 1:
        raise ValueError('win_probability must be between 0 and 1 (exclusive)')
    if win_loss_ratio <= 0:
        raise ValueError('win_loss_ratio must be > 0')
    loss_probability = 1 - win_probability
    kelly_fraction = (win_probability * win_loss_ratio - loss_probability) / win_loss_ratio
    return kelly_fraction

def kelly_criterion_extended(win_probability: float, win_amount: float, loss_amount: float) -> float:
    if win_probability <= 0 or win_probability >= 1:
        raise ValueError('win_probability must be between 0 and 1 (exclusive)')
    if win_amount <= 0:
        raise ValueError('win_amount must be > 0')
    if loss_amount <= 0:
        raise ValueError('loss_amount must be > 0')
    loss_probability = 1 - win_probability
    win_loss_ratio = win_amount / loss_amount
    kelly_fraction = (win_probability * win_loss_ratio - loss_probability) / win_loss_ratio
    return kelly_fraction

def fractional_kelly(win_probability: float, win_loss_ratio: float, fraction: float=0.5) -> float:
    if fraction <= 0 or fraction > 1:
        raise ValueError('fraction must be between 0 and 1 (exclusive for 0, inclusive for 1)')
    full_kelly = kelly_criterion(win_probability, win_loss_ratio)
    return fraction * full_kelly

def present_value(discount_rate: float, cash_flows: list[float]) -> float:
    if discount_rate < 0:
        raise ValueError('Discount rate cannot be negative')
    if not cash_flows:
        raise ValueError('Cash flows list cannot be empty')
    present_value = sum((cash_flow / (1 + discount_rate) ** i for (i, cash_flow) in enumerate(cash_flows)))
    return round(present_value, ndigits=2)

def sharpe_ratio(returns: list[float], risk_free_rate: float=0.0) -> float:
    if not returns:
        raise ValueError('returns list must not be empty')
    if len(returns) < 2:
        raise ValueError('returns list must contain at least 2 values')
    mean_return = sum(returns) / len(returns)
    excess_return = mean_return - risk_free_rate
    variance = sum(((r - mean_return) ** 2 for r in returns)) / (len(returns) - 1)
    std_dev = variance ** 0.5
    if std_dev == 0:
        return float('inf') if excess_return > 0 else 0.0
    return excess_return / std_dev

def annualized_sharpe_ratio(returns: list[float], risk_free_rate: float=0.0, periods_per_year: int=252) -> float:
    if periods_per_year <= 0:
        raise ValueError('periods_per_year must be > 0')
    periodic_sharpe = sharpe_ratio(returns, risk_free_rate)
    if periodic_sharpe == float('inf'):
        return float('inf')
    return periodic_sharpe * periods_per_year ** 0.5

def expected_shortfall(returns: Sequence[float], confidence_level: float=0.95) -> float:
    if not returns:
        raise ValueError('returns must not be empty')
    if not all((isfinite(value) for value in returns)):
        raise ValueError('returns must contain only finite numbers')
    if not 0 < confidence_level < 1:
        raise ValueError('confidence_level must be strictly between 0 and 1')
    sorted_returns = sorted(returns)
    threshold = _linear_interpolated_quantile(sorted_returns, 1 - confidence_level)
    tail = [value for value in sorted_returns if value <= threshold]
    return -sum(tail) / len(tail)

def simple_interest(principal: float, daily_interest_rate: float, days_between_payments: float) -> float:
    if days_between_payments <= 0:
        raise ValueError('days_between_payments must be > 0')
    if daily_interest_rate < 0:
        raise ValueError('daily_interest_rate must be >= 0')
    if principal <= 0:
        raise ValueError('principal must be > 0')
    return principal * daily_interest_rate * days_between_payments

def compound_interest(principal: float, nominal_annual_interest_rate_percentage: float, number_of_compounding_periods: float) -> float:
    if number_of_compounding_periods <= 0:
        raise ValueError('number_of_compounding_periods must be > 0')
    if nominal_annual_interest_rate_percentage < 0:
        raise ValueError('nominal_annual_interest_rate_percentage must be >= 0')
    if principal <= 0:
        raise ValueError('principal must be > 0')
    return principal * ((1 + nominal_annual_interest_rate_percentage) ** number_of_compounding_periods - 1)

def apr_interest(principal: float, nominal_annual_percentage_rate: float, number_of_years: float) -> float:
    if number_of_years <= 0:
        raise ValueError('number_of_years must be > 0')
    if nominal_annual_percentage_rate < 0:
        raise ValueError('nominal_annual_percentage_rate must be >= 0')
    if principal <= 0:
        raise ValueError('principal must be > 0')
    return compound_interest(principal, nominal_annual_percentage_rate / 365, number_of_years * 365)

def value_at_risk(returns: Sequence[float], confidence_level: float=0.95) -> float:
    if not returns:
        raise ValueError('returns must not be empty')
    if not all((isfinite(value) for value in returns)):
        raise ValueError('returns must contain only finite numbers')
    if not 0 < confidence_level < 1:
        raise ValueError('confidence_level must be strictly between 0 and 1')
    sorted_returns = sorted(returns)
    threshold = _linear_interpolated_quantile(sorted_returns, 1 - confidence_level)
    return -threshold

def exponential_moving_average(stock_prices: Iterator[float], window_size: int) -> Iterator[float]:
    if window_size <= 0:
        raise ValueError('window_size must be > 0')
    alpha = 2 / (1 + window_size)
    moving_average = 0.0
    for (i, stock_price) in enumerate(stock_prices):
        if i == 0 or window_size == 1:
            moving_average = stock_price
        elif i <= window_size:
            moving_average = (moving_average + stock_price) * 0.5
        else:
            moving_average = alpha * stock_price + (1 - alpha) * moving_average
        yield moving_average

def macaulay_duration(face_value: float, coupon_rate: float, periods: int, yield_rate: float) -> float:
    if face_value <= 0:
        raise ValueError('face_value must be > 0')
    if coupon_rate < 0:
        raise ValueError('coupon_rate must be >= 0')
    if periods < 1:
        raise ValueError('periods must be > 0')
    if yield_rate <= 0:
        raise ValueError('yield_rate must be > 0')
    total_present_value: float = 0.0
    total_time_weighted_value: float = 0.0
    for period in range(1, periods + 1):
        cash_flow: float = face_value * coupon_rate + (face_value if period == periods else 0)
        time_weighted_value: float = period * cash_flow / pow(1 + yield_rate, period)
        total_time_weighted_value += time_weighted_value
        present_value: float = cash_flow / pow(1 + yield_rate, period)
        total_present_value += present_value
    return total_time_weighted_value / total_present_value

def equated_monthly_installments(principal: float, rate_per_annum: float, years_to_repay: int) -> float:
    if principal <= 0:
        raise Exception('Principal borrowed must be > 0')
    if rate_per_annum < 0:
        raise Exception('Rate of interest must be >= 0')
    if years_to_repay <= 0 or not isinstance(years_to_repay, int):
        raise Exception('Years to repay must be an integer > 0')
    rate_per_month = rate_per_annum / 12
    number_of_payments = years_to_repay * 12
    return principal * rate_per_month * (1 + rate_per_month) ** number_of_payments / ((1 + rate_per_month) ** number_of_payments - 1)

def weighted_interval_scheduling(intervals: list[Interval]) -> tuple[float, list[Interval]]:
    if not intervals:
        return (0.0, [])
    sorted_intervals = sorted(intervals, key=lambda item: item.end)
    n = len(sorted_intervals)
    end_times = [item.end for item in sorted_intervals]
    predecessors: list[int] = [0] * n
    for j in range(n):
        idx = bisect_right(end_times, sorted_intervals[j].start)
        predecessors[j] = idx
    dp: list[float] = [0.0] * (n + 1)
    for j in range(1, n + 1):
        incl_weight = sorted_intervals[j - 1].weight + dp[predecessors[j - 1]]
        excl_weight = dp[j - 1]
        dp[j] = max(incl_weight, excl_weight)
    selected: list[Interval] = []
    curr = n
    while curr > 0:
        incl_weight = sorted_intervals[curr - 1].weight + dp[predecessors[curr - 1]]
        if incl_weight > dp[curr - 1]:
            selected.append(sorted_intervals[curr - 1])
            curr = predecessors[curr - 1]
        else:
            curr -= 1
    selected.reverse()
    return (dp[n], selected)

def calculate_waiting_times(duration_times: list[int]) -> list[int]:
    waiting_times = [0] * len(duration_times)
    for i in range(1, len(duration_times)):
        waiting_times[i] = duration_times[i - 1] + waiting_times[i - 1]
    return waiting_times

def max_tasks(tasks_info: list[tuple[int, int]]) -> list[int]:
    tasks = sorted((Task(task_id, deadline, reward) for (task_id, (deadline, reward)) in enumerate(tasks_info)), key=attrgetter('reward'), reverse=True)
    return [task.task_id for (i, task) in enumerate(tasks, start=1) if task.deadline >= i]

def calculate_waiting_times(burst_times: list[int]) -> list[int]:
    quantum = 2
    rem_burst_times = list(burst_times)
    waiting_times = [0] * len(burst_times)
    t = 0
    while True:
        done = True
        for (i, burst_time) in enumerate(burst_times):
            if rem_burst_times[i] > 0:
                done = False
                if rem_burst_times[i] > quantum:
                    t += quantum
                    rem_burst_times[i] -= quantum
                else:
                    t += rem_burst_times[i]
                    waiting_times[i] = t - burst_time
                    rem_burst_times[i] = 0
        if done is True:
            return waiting_times

def calculate_waiting_time(process_name: list, turn_around_time: list, burst_time: list, no_of_process: int) -> list:
    waiting_time = [0] * no_of_process
    for i in range(no_of_process):
        waiting_time[i] = turn_around_time[i] - burst_time[i]
    return waiting_time

def calculate_waitingtime(arrival_time: list[int], burst_time: list[int], no_of_processes: int) -> list[int]:
    waiting_time = [0] * no_of_processes
    remaining_time = [0] * no_of_processes
    for i in range(no_of_processes):
        remaining_time[i] = burst_time[i]
    ready_process: list[int] = []
    completed = 0
    total_time = 0
    while completed != no_of_processes:
        ready_process = []
        target_process = -1
        for i in range(no_of_processes):
            if arrival_time[i] <= total_time and remaining_time[i] > 0:
                ready_process.append(i)
        if len(ready_process) > 0:
            target_process = ready_process[0]
            for i in ready_process:
                if remaining_time[i] < remaining_time[target_process]:
                    target_process = i
            total_time += burst_time[target_process]
            completed += 1
            remaining_time[target_process] = 0
            waiting_time[target_process] = total_time - arrival_time[target_process] - burst_time[target_process]
        else:
            total_time += 1
    return waiting_time

def calculate_turnaroundtime(burst_time: list[int], no_of_processes: int, waiting_time: list[int]) -> list[int]:
    turn_around_time = [0] * no_of_processes
    for i in range(no_of_processes):
        turn_around_time[i] = burst_time[i] + waiting_time[i]
    return turn_around_time

def calculate_turnaroundtime(burst_time: list[int], no_of_processes: int, waiting_time: list[int]) -> list[int]:
    turn_around_time = [0] * no_of_processes
    for i in range(no_of_processes):
        turn_around_time[i] = burst_time[i] + waiting_time[i]
    return turn_around_time

def evaluate(item: str, main_target: str) -> tuple[str, float]:
    score = len([g for (position, g) in enumerate(item) if g == main_target[position]])
    return (item, float(score))

def crossover(parent_1: str, parent_2: str) -> tuple[str, str]:
    random_slice = random.randint(0, len(parent_1) - 1)
    child_1 = parent_1[:random_slice] + parent_2[random_slice:]
    child_2 = parent_2[:random_slice] + parent_1[random_slice:]
    return (child_1, child_2)

def mutate(child: str, genes: list[str]) -> str:
    child_list = list(child)
    if random.uniform(0, 1) < MUTATION_PROBABILITY:
        child_list[random.randint(0, len(child)) - 1] = random.choice(genes)
    return ''.join(child_list)

def basic(target: str, genes: list[str], debug: bool=True) -> tuple[int, int, str]:
    if N_POPULATION < N_SELECTED:
        msg = f'{N_POPULATION} must be bigger than {N_SELECTED}'
        raise ValueError(msg)
    not_in_genes_list = sorted({c for c in target if c not in genes})
    if not_in_genes_list:
        msg = f'{not_in_genes_list} is not in genes list, evolution cannot converge'
        raise ValueError(msg)
    population = []
    for _ in range(N_POPULATION):
        population.append(''.join([random.choice(genes) for i in range(len(target))]))
    (generation, total_population) = (0, 0)
    while True:
        generation += 1
        total_population += len(population)
        population_score = [evaluate(item, target) for item in population]
        population_score = sorted(population_score, key=lambda x: x[1], reverse=True)
        if population_score[0][0] == target:
            return (generation, total_population, population_score[0][0])
        if debug and generation % 10 == 0:
            print(f'\nGeneration: {generation}\nTotal Population:{total_population}\nBest score: {population_score[0][1]}\nBest string: {population_score[0][0]}')
        population_best = population[:int(N_POPULATION / 3)]
        population.clear()
        population.extend(population_best)
        population_score = [(item, score / len(target)) for (item, score) in population_score]
        for i in range(N_SELECTED):
            population.extend(select(population_score[int(i)], population_score, genes))
            if len(population) > N_POPULATION:
                break

def main(cities: dict[int, list[int]], population_size: int, iterations_num: int, crossover_probability: float, mutation_probability: float) -> tuple[list[int], float]:
    best_path: list[int] = []
    best_distance = float('inf')
    (chromosomes, cities_list) = init(cities, population_size)
    (fitness_matrix, best_path, best_distance) = fitness(cities, chromosomes, best_path, best_distance)
    for _ in range(iterations_num):
        '\n        Uncomment to choose another selection operator\n        Only one of the two selection operators can be uncommented at the same time.\n        '
        chromosomes = chose_rws(fitness_matrix, chromosomes, population_size)
        for x in range(int(population_size / 2)):
            (chromosomes[x], chromosomes[x + int(population_size / 2)]) = crossing(chromosomes[x], chromosomes[x + int(population_size / 2)], crossover_probability, cities_list)
        for x in range(population_size):
            chromosomes[x] = mutate(chromosomes[x], mutation_probability)
        (fitness_matrix, best_path, best_distance) = fitness(cities, chromosomes, best_path, best_distance)
    return (best_path, best_distance)

def fitness(cities: dict[int, list[int]], chromosomes: list[list[int]], best_path: list[int], best_distance: float) -> tuple[list[float], list[int], float]:
    fitness_matrix = []
    new_best_path = best_path
    new_best_distance = best_distance
    for chromosome in chromosomes:
        total_distance = 0.0
        for i in range(len(chromosome) - 1):
            total_distance += distance(cities[chromosome[i]], cities[chromosome[i + 1]])
        fitness_matrix.append(1 / total_distance)
        if total_distance < new_best_distance:
            new_best_path = chromosome
            new_best_distance = total_distance
    return (fitness_matrix, new_best_path, new_best_distance)

def chose_ts(fitness_matrix: list[float], chromosomes: list[list[int]], population_size: int) -> list[list[int]]:
    chromosomes_new = []
    for _ in range(population_size):
        x1 = random.randint(0, population_size - 1)
        x2 = random.randint(0, population_size - 1)
        if fitness_matrix[x1] >= fitness_matrix[x2]:
            chromosomes_new.append(chromosomes[x1])
        else:
            chromosomes_new.append(chromosomes[x2])
    return chromosomes_new

def chose_rws(fitness_matrix: list[float], chromosomes: list[list[int]], population_size: int) -> list[list[int]]:
    probabilitys = [0.0] * len(fitness_matrix)
    total_probability = 0.0
    for i in fitness_matrix:
        total_probability += i
    for i in range(len(fitness_matrix)):
        probabilitys[i] = fitness_matrix[i] / total_probability
    chromosomes_new = copy.deepcopy(chromosomes)
    for i in range(population_size):
        k = 0.0
        r = random.uniform(0, 1)
        for j in range(population_size):
            k = k + probabilitys[j]
            if r <= k:
                chromosomes_new[i] = chromosomes[j]
                break
    return chromosomes_new

def crossing(chromosome_a: list[int], chromosome_b: list[int], crossover_probability: float, cities_list: list[int]) -> tuple[list[int], list[int]]:
    new_chromosome_a = copy.deepcopy(chromosome_a)
    new_chromosome_b = copy.deepcopy(chromosome_b)
    if random.random() <= crossover_probability:
        crossover_segment = sorted([random.randint(0, len(new_chromosome_a) - 1), random.randint(0, len(new_chromosome_a) - 1)])
        for k in range(crossover_segment[1] - crossover_segment[0] + 1):
            (new_chromosome_a[crossover_segment[0] + k], new_chromosome_b[crossover_segment[0] + k]) = (new_chromosome_b[crossover_segment[0] + k], new_chromosome_a[crossover_segment[0] + k])
        for chromosome in [new_chromosome_a, new_chromosome_b]:
            unique_elements_set = set(chromosome)
            if len(unique_elements_set) != len(chromosome):
                for segment_index in range(crossover_segment[1] - crossover_segment[0] + 1):
                    target_index = 0
                    for chrom_index in range(1, len(chromosome) - 1):
                        if chrom_index == crossover_segment[0] + segment_index:
                            continue
                        if chromosome[chrom_index] == chromosome[crossover_segment[0] + segment_index]:
                            target_index = chrom_index
                            break
                    if target_index != 0:
                        cities_list_copy = copy.deepcopy(cities_list)
                        for t in chromosome:
                            try:
                                cities_list_copy.remove(t)
                            except ValueError:
                                continue
                        chromosome[target_index] = random.sample(cities_list_copy, 1)[0]
    return (new_chromosome_a, new_chromosome_b)

def mutate(chromosome: list[int], mutation_probability: float) -> list[int]:
    new_chromosome = copy.deepcopy(chromosome)
    if random.random() <= mutation_probability:
        mutate_location = [random.randint(1, len(new_chromosome) - 2), random.randint(1, len(new_chromosome) - 2)]
        (new_chromosome[mutate_location[0]], new_chromosome[mutate_location[1]]) = (new_chromosome[mutate_location[1]], new_chromosome[mutate_location[0]])
    return new_chromosome

def decimal_to_binary_iterative(num: int) -> str:
    if isinstance(num, float):
        raise TypeError("'float' object cannot be interpreted as an integer")
    if isinstance(num, str):
        raise TypeError("'str' object cannot be interpreted as an integer")
    if num == 0:
        return '0b0'
    negative = False
    if num < 0:
        negative = True
        num = -num
    binary: list[int] = []
    while num > 0:
        binary.insert(0, num % 2)
        num >>= 1
    if negative:
        return '-0b' + ''.join((str(e) for e in binary))
    return '0b' + ''.join((str(e) for e in binary))

def decimal_to_binary_recursive_helper(decimal: int) -> str:
    decimal = int(decimal)
    if decimal in (0, 1):
        return str(decimal)
    (div, mod) = divmod(decimal, 2)
    return decimal_to_binary_recursive_helper(div) + str(mod)

def decimal_to_binary_recursive(number: str) -> str:
    number = str(number).strip()
    if not number:
        raise ValueError('No input value was provided')
    negative = '-' if number.startswith('-') else ''
    number = number.lstrip('-')
    if not number.isnumeric():
        raise ValueError('Input value is not an integer')
    return f'{negative}0b{decimal_to_binary_recursive_helper(int(number))}'

def pressure_conversion(value: float, from_type: str, to_type: str) -> float:
    if from_type not in PRESSURE_CONVERSION:
        raise ValueError(f"Invalid 'from_type' value: {from_type!r}  Supported values are:\n" + ', '.join(PRESSURE_CONVERSION))
    if to_type not in PRESSURE_CONVERSION:
        raise ValueError(f"Invalid 'to_type' value: {to_type!r}.  Supported values are:\n" + ', '.join(PRESSURE_CONVERSION))
    return value * PRESSURE_CONVERSION[from_type].from_factor * PRESSURE_CONVERSION[to_type].to_factor

def convert_speed(speed: float, unit_from: str, unit_to: str) -> float:
    if unit_to not in speed_chart or unit_from not in speed_chart_inverse:
        msg = f"Incorrect 'from_type' or 'to_type' value: {unit_from!r}, {unit_to!r}\nValid values are: {', '.join(speed_chart_inverse)}"
        raise ValueError(msg)
    return round(speed * speed_chart[unit_from] * speed_chart_inverse[unit_to], 3)

def convert_si_prefix(known_amount: float, known_prefix: str | SIUnit, unknown_prefix: str | SIUnit) -> float:
    if isinstance(known_prefix, str):
        known_prefix = SIUnit[known_prefix.lower()]
    if isinstance(unknown_prefix, str):
        unknown_prefix = SIUnit[unknown_prefix.lower()]
    unknown_amount: float = known_amount * 10 ** (known_prefix.value - unknown_prefix.value)
    return unknown_amount

def convert_binary_prefix(known_amount: float, known_prefix: str | BinaryUnit, unknown_prefix: str | BinaryUnit) -> float:
    if isinstance(known_prefix, str):
        known_prefix = BinaryUnit[known_prefix.lower()]
    if isinstance(unknown_prefix, str):
        unknown_prefix = BinaryUnit[unknown_prefix.lower()]
    unknown_amount: float = known_amount * 2 ** ((known_prefix.value - unknown_prefix.value) * 10)
    return unknown_amount

def ipv4_to_decimal(ipv4_address: str) -> int:
    octets = [int(octet) for octet in ipv4_address.split('.')]
    if len(octets) != 4:
        raise ValueError('Invalid IPv4 address format')
    decimal_ipv4 = 0
    for octet in octets:
        if not 0 <= octet <= 255:
            raise ValueError(f'Invalid IPv4 octet {octet}')
        decimal_ipv4 = (decimal_ipv4 << 8) + int(octet)
    return decimal_ipv4

def decimal_to_ipv4(decimal_ipv4: int) -> str:
    if not 0 <= decimal_ipv4 <= 4294967295:
        raise ValueError('Invalid decimal IPv4 address')
    ip_parts = []
    for _ in range(4):
        ip_parts.append(str(decimal_ipv4 & 255))
        decimal_ipv4 >>= 8
    return '.'.join(reversed(ip_parts))

def binary_to_gray(binary_number: int) -> int:
    if not isinstance(binary_number, int):
        raise TypeError('Input must be an integer')
    if binary_number < 0:
        raise ValueError('Input must be a non-negative integer')
    return binary_number ^ binary_number >> 1

def gray_to_binary(gray_number: int) -> int:
    if not isinstance(gray_number, int):
        raise TypeError('Input must be an integer')
    if gray_number < 0:
        raise ValueError('Input must be a non-negative integer')
    binary_number = gray_number
    gray_number >>= 1
    while gray_number:
        binary_number ^= gray_number
        gray_number >>= 1
    return binary_number

def decimal_to_gray(decimal_number: int) -> str:
    if not isinstance(decimal_number, int):
        raise TypeError('Input must be an integer')
    if decimal_number < 0:
        raise ValueError('Input must be a non-negative integer')
    gray_code = binary_to_gray(decimal_number)
    return bin(gray_code)[2:]

def gray_to_decimal(gray_string: str) -> int:
    if not gray_string:
        raise ValueError('Input string cannot be empty')
    if not all((bit in '01' for bit in gray_string)):
        raise ValueError('Invalid binary string')
    gray_number = int(gray_string, 2)
    return gray_to_binary(gray_number)

def rectangular_to_polar(real: float, img: float) -> tuple[float, float]:
    mod = round(math.sqrt(real ** 2 + img ** 2), 2)
    ang = round(math.degrees(math.atan2(img, real)), 2)
    return (mod, ang)

def hex_to_decimal(hex_string: str) -> int:
    hex_string = hex_string.strip().lower()
    if not hex_string:
        raise ValueError('Empty string was passed to the function')
    is_negative = hex_string[0] == '-'
    if is_negative:
        hex_string = hex_string[1:]
    if not all((char in hex_table for char in hex_string)):
        raise ValueError('Non-hexadecimal value was passed to the function')
    decimal_number = 0
    for char in hex_string:
        decimal_number = 16 * decimal_number + hex_table[char]
    return -decimal_number if is_negative else decimal_number

def rgb_to_hsv(red: int, green: int, blue: int) -> list[float]:
    if red < 0 or red > 255:
        raise Exception('red should be between 0 and 255')
    if green < 0 or green > 255:
        raise Exception('green should be between 0 and 255')
    if blue < 0 or blue > 255:
        raise Exception('blue should be between 0 and 255')
    float_red = red / 255
    float_green = green / 255
    float_blue = blue / 255
    value = max(float_red, float_green, float_blue)
    chroma = value - min(float_red, float_green, float_blue)
    saturation = 0 if value == 0 else chroma / value
    if chroma == 0:
        hue = 0.0
    elif value == float_red:
        hue = 60 * (0 + (float_green - float_blue) / chroma)
    elif value == float_green:
        hue = 60 * (2 + (float_blue - float_red) / chroma)
    else:
        hue = 60 * (4 + (float_red - float_green) / chroma)
    hue = (hue + 360) % 360
    return [hue, saturation, value]

def energy_conversion(from_type: str, to_type: str, value: float) -> float:
    if to_type not in ENERGY_CONVERSION or from_type not in ENERGY_CONVERSION:
        msg = f"Incorrect 'from_type' or 'to_type' value: {from_type!r}, {to_type!r}\nValid values are: {', '.join(ENERGY_CONVERSION)}"
        raise ValueError(msg)
    return value * ENERGY_CONVERSION[from_type] / ENERGY_CONVERSION[to_type]

def hex_to_bin(hex_num: str) -> int:
    hex_num = hex_num.strip()
    if not hex_num:
        raise ValueError('No value was passed to the function')
    is_negative = hex_num[0] == '-'
    if is_negative:
        hex_num = hex_num[1:]
    try:
        int_num = int(hex_num, 16)
    except ValueError:
        raise ValueError('Invalid value was passed to the function')
    bin_str = ''
    while int_num > 0:
        bin_str = str(int_num % 2) + bin_str
        int_num >>= 1
    return int('-' + bin_str if is_negative else bin_str)

def rgb_to_cmyk(r_input: int, g_input: int, b_input: int) -> tuple[int, int, int, int]:
    if not isinstance(r_input, int) or not isinstance(g_input, int) or (not isinstance(b_input, int)):
        msg = f'Expected int, found {(type(r_input), type(g_input), type(b_input))}'
        raise ValueError(msg)
    if not 0 <= r_input < 256 or not 0 <= g_input < 256 or (not 0 <= b_input < 256):
        raise ValueError('Expected int of the range 0..255')
    r = r_input / 255
    g = g_input / 255
    b = b_input / 255
    k = 1 - max(r, g, b)
    if k == 1:
        return (0, 0, 0, 100)
    c = round(100 * (1 - r - k) / (1 - k))
    m = round(100 * (1 - g - k) / (1 - k))
    y = round(100 * (1 - b - k) / (1 - k))
    k = round(100 * k)
    return (c, m, y, k)

def add_si_prefix(value: float) -> str:
    prefixes = SIUnit.get_positive() if value > 0 else SIUnit.get_negative()
    for (name_prefix, value_prefix) in prefixes.items():
        numerical_part = value / 10 ** value_prefix
        if numerical_part > 1:
            return f'{numerical_part!s} {name_prefix}'
    return str(value)

def add_binary_prefix(value: float) -> str:
    for prefix in BinaryUnit:
        numerical_part = value / 2 ** prefix.value
        if numerical_part > 1:
            return f'{numerical_part!s} {prefix.name}'
    return str(value)

def weight_conversion(from_type: str, to_type: str, value: float) -> float:
    if to_type not in KILOGRAM_CHART or from_type not in WEIGHT_TYPE_CHART:
