        raise ValueError(msg)
    return value * KILOGRAM_CHART[to_type] * WEIGHT_TYPE_CHART[from_type]

def octal_to_binary(octal_number: str) -> str:
    if not octal_number:
        raise ValueError('Empty string was passed to the function')
    binary_number = ''
    octal_digits = '01234567'
    for digit in octal_number:
        if digit not in octal_digits:
            raise ValueError('Non-octal value was passed to the function')
        binary_digit = ''
        value = int(digit)
        for _ in range(3):
            binary_digit = str(value % 2) + binary_digit
            value //= 2
        binary_number += binary_digit
    return binary_number

def bin_to_octal(bin_string: str) -> str:
    if not all((char in '01' for char in bin_string)):
        raise ValueError('Non-binary value was passed to the function')
    if not bin_string:
        raise ValueError('Empty string was passed to the function')
    oct_string = ''
    while len(bin_string) % 3 != 0:
        bin_string = '0' + bin_string
    bin_string_in_3_list = [bin_string[index:index + 3] for index in range(len(bin_string)) if index % 3 == 0]
    for bin_group in bin_string_in_3_list:
        oct_val = 0
        for (index, val) in enumerate(bin_group):
            oct_val += int(2 ** (2 - index) * int(val))
        oct_string += str(oct_val)
    return oct_string

def decimal_to_negative_binary(number: int) -> int:
    if number == 0:
        return 0
    result_str = ''
    while number != 0:
        (number, remainder) = divmod(number, -2)
        if remainder < 0:
            (number, remainder) = (number + 1, remainder + 2)
        result_str = str(remainder) + result_str
    return int(result_str)

def hex_to_rgb(hex_color: str) -> str:
    hex_color = hex_color.lstrip('#')
    if not (len(hex_color) == 6 or len(hex_color) == 3):
        raise ValueError('Invalid hex color code')
    if len(hex_color) == 3:
        hex_color = ''.join([char * 2 for char in hex_color])
    red = int(hex_color[0:2], 16)
    green = int(hex_color[2:4], 16)
    blue = int(hex_color[4:6], 16)
    return f'rgb({red}, {green}, {blue})'

def base64_to_bin(base64_str: str) -> str:
    b64_str = str(base64_str).strip()
    if not b64_str:
        raise ValueError('Empty string was passed to the function')
    is_negative = b64_str[0] == '-'
    if is_negative:
        b64_str = b64_str[1:]
    bin_str = ''
    for (i, x) in enumerate(b64_str):
        if x not in B64_TO_BITS:
            exception_message = f'Invalid base64 string. Invalid char {x} at pos {i}'
            raise ValueError(exception_message)
        bin_str += B64_TO_BITS[x]
    if is_negative:
        bin_str = '-' + bin_str
    return bin_str

def oct_to_decimal(oct_string: str) -> int:
    oct_string = str(oct_string).strip()
    if not oct_string:
        raise ValueError('Empty string was passed to the function')
    is_negative = oct_string[0] == '-'
    if is_negative:
        oct_string = oct_string[1:]
    if not oct_string.isdigit() or not all((0 <= int(char) <= 7 for char in oct_string)):
        raise ValueError('Non-octal value was passed to the function')
    decimal_number = 0
    for char in oct_string:
        decimal_number = 8 * decimal_number + int(char)
    if is_negative:
        decimal_number = -decimal_number
    return decimal_number

def mass_to_moles(mass: float, molar_mass: float) -> float:
    if molar_mass <= 0:
        raise ValueError('Molar mass must be greater than zero.')
    if mass < 0:
        raise ValueError('Mass cannot be negative.')
    return round(float(mass / molar_mass), 2)

def moles_to_molecules(moles: float) -> float:
    if moles < 0:
        raise ValueError('Moles cannot be negative.')
    return float(f'{moles * 6.022e+23:.4e}')

def roman_to_int(roman: str) -> int:
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    place = 0
    while place < len(roman):
        if place + 1 < len(roman) and vals[roman[place]] < vals[roman[place + 1]]:
            total += vals[roman[place + 1]] - vals[roman[place]]
            place += 2
        else:
            total += vals[roman[place]]
            place += 1
    return total

def int_to_roman(number: int) -> str:
    if isinstance(number, bool) or not isinstance(number, int):
        msg = f'int_to_roman only accepts integers, got {type(number).__name__}'
        raise TypeError(msg)
    if not 1 <= number <= 3999:
        msg = f'int_to_roman only accepts integers in the range 1 to 3999, got {number}'
        raise ValueError(msg)
    result = []
    for (arabic, roman) in ROMAN:
        (factor, number) = divmod(number, arabic)
        result.append(roman * factor)
        if number == 0:
            break
    return ''.join(result)

def negative_binary_to_int(negative_binary: int) -> int:
    negative_binary_str = str(negative_binary)
    r = negative_binary_str[::-1]
    res = [int(r[c]) * (-2) ** c for c in range(len(r))]
    return sum(res)

def octal_to_hex(octal: str) -> str:
    if not isinstance(octal, str):
        raise TypeError('Expected a string as input')
    if octal.startswith('0o'):
        octal = octal[2:]
    if octal == '':
        raise ValueError('Empty string was passed to the function')
    if any((char not in '01234567' for char in octal)):
        raise ValueError('Not a Valid Octal Number')
    decimal = 0
    for char in octal:
        decimal <<= 3
        decimal |= int(char)
    hex_char = '0123456789ABCDEF'
    revhex = ''
    while decimal:
        revhex += hex_char[decimal & 15]
        decimal >>= 4
    return '0x' + revhex[::-1]

def volume_conversion(value: float, from_type: str, to_type: str) -> float:
    if from_type not in METRIC_CONVERSION:
