    if to_type not in METRIC_CONVERSION:
        raise ValueError(f"Invalid 'to_type' value: {to_type!r}.  Supported values are:\n" + ', '.join(METRIC_CONVERSION))
    return value * METRIC_CONVERSION[from_type].from_factor * METRIC_CONVERSION[to_type].to_factor

def bin_to_base64(bin_str: str) -> str:
    bin_str = str(bin_str).strip()
    if not bin_str:
        raise ValueError('Empty string was passed to the function')
    is_negative = bin_str[0] == '-'
    if is_negative:
        bin_str = bin_str[1:]
    if not all((char in '01' for char in bin_str)):
        raise ValueError('Non-binary value was passed to the function')
    bin_str = '0' * (6 * (divmod(len(bin_str), 6)[0] + 1) - len(bin_str)) + bin_str
    base64_str = ''
    while len(bin_str) > 0:
        base64_str += BITS_TO_B64[bin_str[:6]]
        bin_str = bin_str[6:]
    return '-' + base64_str if is_negative else base64_str

def binary_to_gray(binary: str) -> str:
    binary_int = int(binary, 2)
    gray_int = binary_int ^ binary_int >> 1
    gray_code = bin(gray_int)[2:]
    return gray_code.zfill(len(binary))

def convert_time(time_value: float, unit_from: str, unit_to: str) -> float:
