    if is_negative:
        bin_string = bin_string[1:]
    if not all((char in '01' for char in bin_string)):
        raise ValueError('Non-binary value was passed to the function')
    decimal_number = 0
    for char in bin_string:
        decimal_number = 2 * decimal_number + int(char)
    return -decimal_number if is_negative else decimal_number

def knapsack(capacity: int, weights: list[int], values: list[int], counter: int, allow_repetition=False) -> int:

    @lru_cache
    def knapsack_recur(capacity: int, counter: int) -> int:
        if counter == 0 or capacity == 0:
            return 0
        if weights[counter - 1] > capacity:
            return knapsack_recur(capacity, counter - 1)
        else:
            left_capacity = capacity - weights[counter - 1]
            new_value_included = values[counter - 1] + knapsack_recur(left_capacity, counter - 1 if not allow_repetition else counter)
            without_new_value = knapsack_recur(capacity, counter - 1)
            return max(new_value_included, without_new_value)
    return knapsack_recur(capacity, counter)

def knapsack(weights: list, values: list, number_of_items: int, max_weight: int, index: int) -> int:
    if index == number_of_items:
        return 0
    ans1 = 0
    ans2 = 0
    ans1 = knapsack(weights, values, number_of_items, max_weight, index + 1)
    if weights[index] <= max_weight:
        ans2 = values[index] + knapsack(weights, values, number_of_items, max_weight - weights[index], index + 1)
    return max(ans1, ans2)

def count_inversions_bf(arr: list[int]) -> int:
    num_inversions = 0
    n = len(arr)
    for i in range(n - 1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                num_inversions += 1
    return num_inversions

def count_inversions_recursive(arr: list[int]) -> tuple[list[int], int]:
    if len(arr) <= 1:
        return (arr, 0)
    mid = len(arr) // 2
    p = arr[0:mid]
    q = arr[mid:]
    (a, inversion_p) = count_inversions_recursive(p)
    (b, inversions_q) = count_inversions_recursive(q)
    (c, cross_inversions) = _count_cross_inversions(a, b)
    num_inversions = inversion_p + inversions_q + cross_inversions
    return (c, num_inversions)

def _count_cross_inversions(p: list[int], q: list[int]) -> tuple[list[int], int]:
    r = []
    i = j = num_inversion = 0
    while i < len(p) and j < len(q):
        if p[i] > q[j]:
            num_inversion += len(p) - i
            r.append(q[j])
            j += 1
        else:
            r.append(p[i])
            i += 1
    if i < len(p):
        r.extend(p[i:])
    else:
        r.extend(q[j:])
    return (r, num_inversion)

def max_subarray(arr: Sequence[float], low: int, high: int) -> tuple[int | None, int | None, float]:
    if not arr:
        return (None, None, 0)
    if low == high:
        return (low, high, arr[low])
    mid = (low + high) // 2
    (left_low, left_high, left_sum) = max_subarray(arr, low, mid)
    (right_low, right_high, right_sum) = max_subarray(arr, mid + 1, high)
    (cross_left, cross_right, cross_sum) = max_cross_sum(arr, low, mid, high)
    if left_sum >= right_sum and left_sum >= cross_sum:
        return (left_low, left_high, left_sum)
    elif right_sum >= left_sum and right_sum >= cross_sum:
        return (right_low, right_high, right_sum)
    return (cross_left, cross_right, cross_sum)

def max_cross_sum(arr: Sequence[float], low: int, mid: int, high: int) -> tuple[int, int, float]:
    (left_sum, max_left) = (float('-inf'), -1)
    (right_sum, max_right) = (float('-inf'), -1)
    summ: int | float = 0
    for i in range(mid, low - 1, -1):
        summ += arr[i]
        if summ > left_sum:
            left_sum = summ
            max_left = i
    summ = 0
    for i in range(mid + 1, high + 1):
        summ += arr[i]
        if summ > right_sum:
            right_sum = summ
            max_right = i
    return (max_left, max_right, left_sum + right_sum)

def time_max_subarray(input_size: int) -> float:
    arr = [randint(1, input_size) for _ in range(input_size)]
    start = time.time()
    max_subarray(arr, 0, input_size - 1)
    end = time.time()
    return end - start

def heaps(arr: list) -> list:
    if len(arr) <= 1:
        return [tuple(arr)]
    res = []

    def generate(k: int, arr: list) -> None:
        if k == 1:
            res.append(tuple(arr[:]))
            return
        generate(k - 1, arr)
        for i in range(k - 1):
            if k % 2 == 0:
                (arr[i], arr[k - 1]) = (arr[k - 1], arr[i])
            else:
                (arr[0], arr[k - 1]) = (arr[k - 1], arr[0])
            generate(k - 1, arr)
    generate(len(arr), arr)
    return res

def heaps(arr: list) -> list:
    if len(arr) <= 1:
        return [tuple(arr)]
    res = []

    def generate(n: int, arr: list) -> None:
        c = [0] * n
        res.append(tuple(arr))
        i = 0
        while i < n:
            if c[i] < i:
                if i % 2 == 0:
                    (arr[0], arr[i]) = (arr[i], arr[0])
                else:
                    (arr[c[i]], arr[i]) = (arr[i], arr[c[i]])
                res.append(tuple(arr))
                c[i] += 1
                i = 0
            else:
                c[i] = 0
                i += 1
    generate(len(arr), arr)
    return res

def max_difference(a: list[int]) -> tuple[int, int]:
    if len(a) == 1:
        return (a[0], a[0])
    else:
        first = a[:len(a) // 2]
        second = a[len(a) // 2:]
        (small1, big1) = max_difference(first)
        (small2, big2) = max_difference(second)
        min_first = min(first)
        max_second = max(second)
        if big2 - small2 > max_second - min_first and big2 - small2 > big1 - small1:
            return (small2, big2)
        elif big1 - small1 > max_second - min_first:
            return (small1, big1)
        else:
            return (min_first, max_second)

def peak(lst: list[int]) -> int:
    m = len(lst) // 2
    three = lst[m - 1:m + 2]
    if three[1] > three[0] and three[1] > three[2]:
        return three[1]
    elif three[0] < three[2]:
        if len(lst[:m]) == 2:
            m -= 1
        return peak(lst[m:])
    else:
        if len(lst[:m]) == 2:
            m += 1
        return peak(lst[:m])

def dis_between_closest_pair(points, points_counts, min_dis=float('inf')):
    for i in range(points_counts - 1):
        for j in range(i + 1, points_counts):
            current_dis = euclidean_distance_sqr(points[i], points[j])
            min_dis = min(min_dis, current_dis)
    return min_dis

def dis_between_closest_in_strip(points, points_counts, min_dis=float('inf')):
    for i in range(min(6, points_counts - 1), points_counts):
        for j in range(max(0, i - 6), i):
            current_dis = euclidean_distance_sqr(points[i], points[j])
            min_dis = min(min_dis, current_dis)
    return min_dis

def closest_pair_of_points_sqr(points_sorted_on_x, points_sorted_on_y, points_counts):
    if points_counts <= 3:
        return dis_between_closest_pair(points_sorted_on_x, points_counts)
    mid = points_counts // 2
    closest_in_left = closest_pair_of_points_sqr(points_sorted_on_x, points_sorted_on_y[:mid], mid)
    closest_in_right = closest_pair_of_points_sqr(points_sorted_on_y, points_sorted_on_y[mid:], points_counts - mid)
    closest_pair_dis = min(closest_in_left, closest_in_right)
    "\n    cross_strip contains the points, whose Xcoords are at a\n    distance(< closest_pair_dis) from mid's Xcoord\n    "
    cross_strip = []
    for point in points_sorted_on_x:
        if abs(point[0] - points_sorted_on_x[mid][0]) < closest_pair_dis:
            cross_strip.append(point)
    closest_in_strip = dis_between_closest_in_strip(cross_strip, len(cross_strip), closest_pair_dis)
    return min(closest_pair_dis, closest_in_strip)

def default_matrix_multiplication(a: list, b: list) -> list:
    if len(a) != 2 or len(a[0]) != 2 or len(b) != 2 or (len(b[0]) != 2):
        raise Exception('Matrices are not 2x2')
    new_matrix = [[a[0][0] * b[0][0] + a[0][1] * b[1][0], a[0][0] * b[0][1] + a[0][1] * b[1][1]], [a[1][0] * b[0][0] + a[1][1] * b[1][0], a[1][0] * b[0][1] + a[1][1] * b[1][1]]]
    return new_matrix

def split_matrix(a: list) -> tuple[list, list, list, list]:
    if len(a) % 2 != 0 or len(a[0]) % 2 != 0:
        raise Exception('Odd matrices are not supported!')

    def extract_submatrix(rows, cols):
        return [[a[i][j] for j in cols] for i in rows]
    mid = len(a) // 2
    (rows_top, rows_bot) = (range(mid), range(mid, len(a)))
    (cols_left, cols_right) = (range(mid), range(mid, len(a)))
    return (extract_submatrix(rows_top, cols_left), extract_submatrix(rows_top, cols_right), extract_submatrix(rows_bot, cols_left), extract_submatrix(rows_bot, cols_right))

def strassen(matrix1: list, matrix2: list) -> list:
    if matrix_dimensions(matrix1)[1] != matrix_dimensions(matrix2)[0]:
        msg = f'Unable to multiply these matrices, please check the dimensions.\nMatrix A: {matrix1}\nMatrix B: {matrix2}'
        raise Exception(msg)
    dimension1 = matrix_dimensions(matrix1)
    dimension2 = matrix_dimensions(matrix2)
    if dimension1[0] == dimension1[1] and dimension2[0] == dimension2[1]:
        return [matrix1, matrix2]
    maximum = max(*dimension1, *dimension2)
    maxim = int(math.pow(2, math.ceil(math.log2(maximum))))
    new_matrix1 = matrix1
    new_matrix2 = matrix2
    for i in range(maxim):
        if i < dimension1[0]:
            for _ in range(dimension1[1], maxim):
                new_matrix1[i].append(0)
        else:
            new_matrix1.append([0] * maxim)
        if i < dimension2[0]:
            for _ in range(dimension2[1], maxim):
                new_matrix2[i].append(0)
        else:
            new_matrix2.append([0] * maxim)
    final_matrix = actual_strassen(new_matrix1, new_matrix2)
    for i in range(maxim):
        if i < dimension1[0]:
            for _ in range(dimension2[1], maxim):
                final_matrix[i].pop()
        else:
            final_matrix.pop()
    return final_matrix

def partition(array: list, starting_index: int, ending_index: int) -> int:
    pivot = array[ending_index]
    i = starting_index - 1
    for j in range(starting_index, ending_index):
        if array[j] <= pivot:
            i += 1
            (array[i], array[j]) = (array[j], array[i])
    (array[i + 1], array[ending_index]) = (array[ending_index], array[i + 1])
    return i + 1

def randomized_partition(array: list, starting_index: int, ending_index: int) -> int:
    rand_idx = random.randint(starting_index, ending_index)
    (array[rand_idx], array[ending_index]) = (array[ending_index], array[rand_idx])
    return partition(array, starting_index, ending_index)

def selection_sort(array: list, starting_index: int, ending_index: int, smallest_element: int) -> list | None:
    if not array:
        return array
    if starting_index == ending_index:
        return array[starting_index]
    q = randomized_partition(array, starting_index, ending_index)
    k = q - starting_index + 1
    if smallest_element == k:
        return array[q]
    if smallest_element < k:
        return selection_sort(array, starting_index, q - 1, smallest_element)
    else:
        return selection_sort(array, q + 1, ending_index, smallest_element - k)

def kth_number(lst: list[int], k: int) -> int:
    pivot = random_pivot(lst)
    small = [e for e in lst if e < pivot]
    big = [e for e in lst if e > pivot]
    if len(small) == k - 1:
        return pivot
    elif len(small) < k - 1:
        return kth_number(big, k - len(small) - 1)
    else:
        return kth_number(small, k)

def merge_sort(array: list) -> list:
    if len(array) <= 1:
        return array
    middle = 0 + (len(array) - 0) // 2
    left_half = array[:middle]
    right_half = array[middle:]
    return merge(merge_sort(left_half), merge_sort(right_half))

def actual_power(a: int, b: int) -> int:
    if b == 0:
        return 1
    half = actual_power(a, b // 2)
    if b % 2 == 0:
        return half * half
    else:
        return a * half * half

def power(a: int, b: int) -> float:
    if b < 0:
        return 1 / actual_power(a, -b)
    return actual_power(a, b)

def _reactive_power_difference(frequency: float, voltage: float, real_power: float, current_power_factor: float, expected_power_factor: float) -> float:
    for power_factor in (current_power_factor, expected_power_factor):
        if not isinstance(power_factor, (int, float)) or not -1 <= power_factor <= 1:
            raise ValueError('power_factor must be a valid float value between -1 and 1.')
    if frequency == 0:
        raise ValueError('frequency is zero dc circuit')
    if voltage == 0:
        raise ValueError('voltage is zero no excitation')
    current_reactive_power = real_power / current_power_factor * math.sin(math.acos(current_power_factor))
    expected_reactive_power = real_power / expected_power_factor * math.sin(math.acos(expected_power_factor))
    return current_reactive_power - expected_reactive_power

def shunt_capacitor_power_factor_correction(voltage: float, frequency: float, real_power: float, current_power_factor: float, expected_power_factor: float) -> float:
    change_reactive_power = _reactive_power_difference(frequency, voltage, real_power, current_power_factor, expected_power_factor)
    return change_reactive_power / (2 * math.pi * frequency * voltage ** 2)

def shunt_inductor_power_factor_correction(voltage: float, frequency: float, real_power: float, current_power_factor: float, expected_power_factor: float) -> float:
    change_reactive_power = _reactive_power_difference(frequency, voltage, real_power, current_power_factor, expected_power_factor)
    if change_reactive_power == 0:
        raise ValueError('current and expected power factors are equal, no correction needed')
    return voltage ** 2 / (2 * math.pi * frequency * change_reactive_power)

def electric_power(voltage: float, current: float, power: float) -> tuple:
    if (voltage, current, power).count(0) != 1:
        raise ValueError('Exactly one argument must be 0')
    if power < 0:
        raise ValueError('Power cannot be negative in any electrical/electronics system')
    if voltage == 0:
        return Result('voltage', power / current)
    elif current == 0:
        return Result('current', power / voltage)
    elif power == 0:
        return Result('power', float(round(abs(voltage * current), 2)))
    else:
        raise AssertionError

def real_power(apparent_power: float, power_factor: float) -> float:
    if not isinstance(power_factor, (int, float)) or power_factor < -1 or power_factor > 1:
        raise ValueError('power_factor must be a valid float value between -1 and 1.')
    return apparent_power * power_factor

def reactive_power(apparent_power: float, power_factor: float) -> float:
    if not isinstance(power_factor, (int, float)) or power_factor < -1 or power_factor > 1:
        raise ValueError('power_factor must be a valid float value between -1 and 1.')
    return apparent_power * math.sqrt(1 - power_factor ** 2)

def electrical_impedance(resistance: float, reactance: float, impedance: float) -> dict[str, float]:
    if (resistance, reactance, impedance).count(0) != 1:
        raise ValueError('One and only one argument must be 0')
    if resistance == 0:
        return {'resistance': sqrt(pow(impedance, 2) - pow(reactance, 2))}
    elif reactance == 0:
        return {'reactance': sqrt(pow(impedance, 2) - pow(resistance, 2))}
    elif impedance == 0:
        return {'impedance': sqrt(pow(resistance, 2) + pow(reactance, 2))}
    else:
        raise ValueError('Exactly one argument must be 0')

def charging_inductor(source_voltage: float, resistance: float, inductance: float, time: float) -> float:
    if source_voltage <= 0:
        raise ValueError('Source voltage must be positive.')
    if resistance <= 0:
        raise ValueError('Resistance must be positive.')
    if inductance <= 0:
        raise ValueError('Inductance must be positive.')
    return round(source_voltage / resistance * (1 - exp(-time * resistance / inductance)), 3)

def ohms_law(voltage: float, current: float, resistance: float) -> dict[str, float]:
    if (voltage, current, resistance).count(0) != 1:
        raise ValueError('One and only one argument must be 0')
    if resistance < 0:
        raise ValueError('Resistance cannot be negative')
    if voltage == 0:
        return {'voltage': float(current * resistance)}
    elif current == 0:
        return {'current': voltage / resistance}
    elif resistance == 0:
        return {'resistance': voltage / current}
    else:
        raise ValueError('Exactly one argument must be 0')

def astable_frequency(resistance_1: float, resistance_2: float, capacitance: float) -> float:
    if resistance_1 <= 0 or resistance_2 <= 0 or capacitance <= 0:
        raise ValueError('All values must be positive')
    return 1.44 / ((resistance_1 + 2 * resistance_2) * capacitance) * 10 ** 6

def astable_duty_cycle(resistance_1: float, resistance_2: float) -> float:
    if resistance_1 <= 0 or resistance_2 <= 0:
        raise ValueError('All values must be positive')
    return (resistance_1 + resistance_2) / (resistance_1 + 2 * resistance_2) * 100

def wheatstone_solver(resistance_1: float, resistance_2: float, resistance_3: float) -> float:
    if resistance_1 <= 0 or resistance_2 <= 0 or resistance_3 <= 0:
        raise ValueError('All resistance values must be positive')
    return float(resistance_2 / resistance_1 * resistance_3)

def electric_conductivity(conductivity: float, electron_conc: float, mobility: float) -> tuple[str, float]:
    if (conductivity, electron_conc, mobility).count(0) != 1:
        raise ValueError('You cannot supply more or less than 2 values')
    if conductivity < 0:
        raise ValueError('Conductivity cannot be negative')
    if electron_conc < 0:
        raise ValueError('Electron concentration cannot be negative')
    if mobility < 0:
        raise ValueError('mobility cannot be negative')
    if conductivity == 0:
        return ('conductivity', mobility * electron_conc * ELECTRON_CHARGE)
    elif electron_conc == 0:
        return ('electron_conc', conductivity / (mobility * ELECTRON_CHARGE))
    else:
        return ('mobility', conductivity / (electron_conc * ELECTRON_CHARGE))

def max_load_current(rf: float, rs: float, rl: float, vm: float) -> tuple:
    if (rf, rs, rl).count(0) == 3:
        raise ValueError('At least one Resistance must be non-zero')
    if rf < 0 or rs < 0 or rl < 0:
        raise ValueError('Resistance cannot be negative')
    if vm == 0:
        return Result('max_load_current', vm / (rf + rs + rl))
    else:
        return Result('max_load_current', vm / (rf + rs + rl))

def max_current(vm: float, rl: float) -> tuple:
    if rl <= 0:
        raise ValueError('Resistance cannot be negative or equal to zero')
    return Result('Max_current_Im', vm / rl)

def couloumbs_law(force: float, charge1: float, charge2: float, distance: float) -> dict[str, float]:
    charge_product = abs(charge1 * charge2)
    if (force, charge1, charge2, distance).count(0) != 1:
        raise ValueError('One and only one argument must be 0')
    if distance < 0:
        raise ValueError('Distance cannot be negative')
    if force == 0:
        force = COULOMBS_CONSTANT * charge_product / distance ** 2
        return {'force': force}
    elif charge1 == 0:
        charge1 = abs(force) * distance ** 2 / (COULOMBS_CONSTANT * charge2)
        return {'charge1': charge1}
    elif charge2 == 0:
        charge2 = abs(force) * distance ** 2 / (COULOMBS_CONSTANT * charge1)
        return {'charge2': charge2}
    elif distance == 0:
        distance = (COULOMBS_CONSTANT * charge_product / abs(force)) ** 0.5
        return {'distance': distance}
    raise ValueError('Exactly one argument must be 0')

def builtin_voltage(donor_conc: float, acceptor_conc: float, intrinsic_conc: float) -> float:
    if donor_conc <= 0:
        raise ValueError('Donor concentration should be positive')
    if acceptor_conc <= 0:
        raise ValueError('Acceptor concentration should be positive')
    if intrinsic_conc <= 0:
        raise ValueError('Intrinsic concentration should be positive')
    if donor_conc <= intrinsic_conc:
        raise ValueError('Donor concentration should be greater than intrinsic concentration')
    if acceptor_conc <= intrinsic_conc:
        raise ValueError('Acceptor concentration should be greater than intrinsic concentration')
    return Boltzmann * T * log(donor_conc * acceptor_conc / intrinsic_conc ** 2) / physical_constants['electron volt'][0]

def carrier_concentration(electron_conc: float, hole_conc: float, intrinsic_conc: float) -> tuple:
    if (electron_conc, hole_conc, intrinsic_conc).count(0) != 1:
        raise ValueError('You cannot supply more or less than 2 values')
    if electron_conc < 0:
        raise ValueError('Electron concentration cannot be negative in a semiconductor')
    if hole_conc < 0:
        raise ValueError('Hole concentration cannot be negative in a semiconductor')
    if intrinsic_conc < 0:
        raise ValueError('Intrinsic concentration cannot be negative in a semiconductor')
    if electron_conc == 0:
        return ('electron_conc', intrinsic_conc ** 2 / hole_conc)
    elif hole_conc == 0:
        return ('hole_conc', intrinsic_conc ** 2 / electron_conc)
    elif intrinsic_conc == 0:
        return ('intrinsic_conc', (electron_conc * hole_conc) ** 0.5)
    else:
        return (-1, -1)

def get_significant_digits(colors: list) -> str:
    digit = ''
    for color in colors:
        if color not in significant_figures_color_values:
            msg = f'{color} is not a valid color for significant figure bands'
            raise ValueError(msg)
        digit = digit + str(significant_figures_color_values[color])
    return str(digit)

def get_multiplier(color: str) -> float:
    if color not in multiplier_color_values:
        msg = f'{color} is not a valid color for multiplier band'
        raise ValueError(msg)
    return multiplier_color_values[color]

def get_tolerance(color: str) -> float:
    if color not in tolerance_color_values:
        msg = f'{color} is not a valid color for tolerance band'
        raise ValueError(msg)
    return tolerance_color_values[color]

def get_temperature_coeffecient(color: str) -> int:
    if color not in temperature_coeffecient_color_values:
        msg = f'{color} is not a valid color for temperature coeffecient band'
        raise ValueError(msg)
    return temperature_coeffecient_color_values[color]

def get_band_type_count(total_number_of_bands: int, type_of_band: str) -> int:
    if total_number_of_bands not in band_types:
        msg = f'{total_number_of_bands} is not a valid number of bands'
        raise ValueError(msg)
    if type_of_band not in band_types[total_number_of_bands]:
        msg = f'{type_of_band} is not valid for a {total_number_of_bands} band resistor'
        raise ValueError(msg)
    return band_types[total_number_of_bands][type_of_band]

def check_validity(number_of_bands: int, colors: list) -> bool:
    if number_of_bands >= 3 and number_of_bands <= 6:
        if number_of_bands == len(colors):
            for color in colors:
                if color not in valid_colors:
                    msg = f'{color} is not a valid color'
                    raise ValueError(msg)
            return True
        else:
            msg = f'Expecting {number_of_bands} colors, provided {len(colors)} colors'
            raise ValueError(msg)
    else:
        msg = 'Invalid number of bands. Resistor bands must be 3 to 6'
        raise ValueError(msg)

def calculate_resistance(number_of_bands: int, color_code_list: list) -> dict:
    is_valid = check_validity(number_of_bands, color_code_list)
    if is_valid:
        number_of_significant_bands = get_band_type_count(number_of_bands, 'significant')
        significant_colors = color_code_list[:number_of_significant_bands]
        significant_digits = int(get_significant_digits(significant_colors))
        multiplier_color = color_code_list[number_of_significant_bands]
        multiplier = get_multiplier(multiplier_color)
        if number_of_bands == 3:
            tolerance_color = None
        else:
            tolerance_color = color_code_list[number_of_significant_bands + 1]
        tolerance = 20 if tolerance_color is None else get_tolerance(str(tolerance_color))
        if number_of_bands != 6:
            temperature_coeffecient_color = None
        else:
            temperature_coeffecient_color = color_code_list[number_of_significant_bands + 2]
        temperature_coeffecient = 0 if temperature_coeffecient_color is None else get_temperature_coeffecient(str(temperature_coeffecient_color))
        resisitance = significant_digits * multiplier
        if temperature_coeffecient == 0:
            answer = f'{resisitance}Ω ±{tolerance}% '
        else:
            answer = f'{resisitance}Ω ±{tolerance}% {temperature_coeffecient} ppm/K'
        return {'resistance': answer}
    else:
        raise ValueError('Input is invalid')

def resistor_parallel(resistors: list[float]) -> float:
    first_sum = 0.0
    for (index, resistor) in enumerate(resistors):
        if resistor <= 0:
            msg = f'Resistor at index {index} has a negative or zero value!'
            raise ValueError(msg)
        first_sum += 1 / float(resistor)
    return 1 / first_sum

def resistor_series(resistors: list[float]) -> float:
    sum_r = 0.0
    for (index, resistor) in enumerate(resistors):
        sum_r += resistor
        if resistor < 0:
            msg = f'Resistor at index {index} has a negative value!'
            raise ValueError(msg)
    return sum_r

def resonant_frequency(inductance: float, capacitance: float) -> tuple:
    if inductance <= 0:
        raise ValueError('Inductance cannot be 0 or negative')
    if capacitance <= 0:
        raise ValueError('Capacitance cannot be 0 or negative')
    return ('Resonant frequency', float(1 / (2 * pi * sqrt(inductance * capacitance))))

def max_load_current(rf: float, rs: float, rl: float, vm: float) -> tuple:
    if (rf, rs, rl).count(0) == 3:
        raise ValueError('At least one Resistance must be non-zero')
    if rf < 0 or rs < 0 or rl < 0:
        raise ValueError('Resistance cannot be negative')
    if vm == 0:
        return Result('max_load_current', vm / (rf + rs + rl))
    else:
        return Result('max_load_current', vm / (rf + rs + rl))

def max_current(vm: float, rl: float) -> tuple:
    if rl <= 0:
        raise ValueError('Resistance cannot be negative or equal to zero')
    return Result('Max_current_Im', vm / rl)

def charging_capacitor(source_voltage: float, resistance: float, capacitance: float, time_sec: float) -> float:
    if source_voltage <= 0:
        raise ValueError('Source voltage must be positive.')
    if resistance <= 0:
        raise ValueError('Resistance must be positive.')
    if capacitance <= 0:
        raise ValueError('Capacitance must be positive.')
    return round(source_voltage * (1 - exp(-time_sec / (resistance * capacitance))), 3)

def ind_reactance(inductance: float, frequency: float, reactance: float) -> dict[str, float]:
    if (inductance, frequency, reactance).count(0) != 1:
        raise ValueError('One and only one argument must be 0')
    if inductance < 0:
        raise ValueError('Inductance cannot be negative')
    if frequency < 0:
        raise ValueError('Frequency cannot be negative')
    if reactance < 0:
        raise ValueError('Inductive reactance cannot be negative')
    if inductance == 0:
        return {'inductance': reactance / (2 * pi * frequency)}
    elif frequency == 0:
        return {'frequency': reactance / (2 * pi * inductance)}
    elif reactance == 0:
        return {'reactance': 2 * pi * frequency * inductance}
    else:
        raise ValueError('Exactly one argument must be 0')

def capacitor_parallel(capacitors: list[float]) -> float:
    sum_c = 0.0
    for (index, capacitor) in enumerate(capacitors):
        if capacitor < 0:
            msg = f'Capacitor at index {index} has a negative value!'
            raise ValueError(msg)
        sum_c += capacitor
    return sum_c

def capacitor_series(capacitors: list[float]) -> float:
    first_sum = 0.0
    for (index, capacitor) in enumerate(capacitors):
        if capacitor <= 0:
            msg = f'Capacitor at index {index} has a negative or zero value!'
            raise ValueError(msg)
        first_sum += 1 / capacitor
    return 1 / first_sum

def rmsprop(params: list[float], gradients: list[float], learning_rate: float, rho: float=0.9, epsilon: float=1e-08, moving_avg: list[float] | None=None) -> list[float]:
    if len(params) != len(gradients):
        msg = f'params and gradients must have the same length, got {len(params)} and {len(gradients)}'
        raise ValueError(msg)
    if learning_rate <= 0:
        msg = f'learning_rate must be positive, got {learning_rate}'
        raise ValueError(msg)
    if not 0.0 <= rho < 1.0:
        msg = f'rho must be in [0, 1), got {rho}'
        raise ValueError(msg)
    if epsilon <= 0:
        msg = f'epsilon must be positive, got {epsilon}'
        raise ValueError(msg)
    if moving_avg is None:
        moving_avg = [0.0] * len(params)
    updated_params = []
    for (i, (param, grad)) in enumerate(zip(params, gradients)):
        moving_avg[i] = rho * moving_avg[i] + (1 - rho) * grad ** 2
        param = param - learning_rate / math.sqrt(moving_avg[i] + epsilon) * grad
        updated_params.append(param)
    return updated_params

def ols_regression(x_point: np.ndarray, y_point: np.ndarray) -> tuple:
    x_mean = np.mean(x_point)
    y_mean = np.mean(y_point)
    slope = np.sum((x_point - x_mean) * (y_point - y_mean)) / np.sum((x_point - x_mean) ** 2)
    intercept = y_mean - slope * x_mean
    return (intercept, slope)

def binary_cross_entropy(y_true: np.ndarray, y_pred: np.ndarray, epsilon: float=1e-15) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Input arrays must have the same length.')
    y_pred = np.clip(y_pred, epsilon, 1 - epsilon)
    bce_loss = -(y_true * np.log(y_pred) + (1 - y_true) * np.log(1 - y_pred))
    return np.mean(bce_loss)

def binary_focal_cross_entropy(y_true: np.ndarray, y_pred: np.ndarray, gamma: float=2.0, alpha: float=0.25, epsilon: float=1e-15) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Input arrays must have the same length.')
    y_pred = np.clip(y_pred, epsilon, 1 - epsilon)
    bcfe_loss = -(alpha * (1 - y_pred) ** gamma * y_true * np.log(y_pred) + (1 - alpha) * y_pred ** gamma * (1 - y_true) * np.log(1 - y_pred))
    return np.mean(bcfe_loss)

def categorical_cross_entropy(y_true: np.ndarray, y_pred: np.ndarray, epsilon: float=1e-15) -> float:
    if y_true.shape != y_pred.shape:
        raise ValueError('Input arrays must have the same shape.')
    if np.any((y_true != 0) & (y_true != 1)) or np.any(y_true.sum(axis=1) != 1):
        raise ValueError('y_true must be one-hot encoded.')
    if not np.all(np.isclose(np.sum(y_pred, axis=1), 1, rtol=epsilon, atol=epsilon)):
        raise ValueError('Predicted probabilities must sum to approximately 1.')
    y_pred = np.clip(y_pred, epsilon, 1)
    return -np.sum(y_true * np.log(y_pred))

def sparse_categorical_cross_entropy(y_true: np.ndarray, y_pred: np.ndarray, epsilon: float=1e-15) -> float:
    if np.any(y_true >= y_pred.shape[1]) or np.any(y_true < 0):
        raise ValueError('Class labels in y_true are out of range.')
    if not np.all(np.isclose(np.sum(y_pred, axis=1), 1, rtol=epsilon, atol=epsilon)):
        raise ValueError('Predicted probabilities must sum to approximately 1.')
    y_pred = np.clip(y_pred, epsilon, 1)
    log_preds = np.log(y_pred[np.arange(len(y_pred)), y_true])
    return -np.sum(log_preds)

def categorical_focal_cross_entropy(y_true: np.ndarray, y_pred: np.ndarray, alpha: np.ndarray | None=None, gamma: float=2.0, epsilon: float=1e-15) -> float:
    if y_true.shape != y_pred.shape:
        raise ValueError('Shape of y_true and y_pred must be the same.')
    if alpha is None:
        alpha = np.ones(y_true.shape[1])
    if np.any((y_true != 0) & (y_true != 1)) or np.any(y_true.sum(axis=1) != 1):
        raise ValueError('y_true must be one-hot encoded.')
    if len(alpha) != y_true.shape[1]:
        raise ValueError('Length of alpha must match the number of classes.')
    if not np.all(np.isclose(np.sum(y_pred, axis=1), 1, rtol=epsilon, atol=epsilon)):
        raise ValueError('Predicted probabilities must sum to approximately 1.')
    y_pred = np.clip(y_pred, epsilon, 1 - epsilon)
    cfce_loss = -np.sum(alpha * np.power(1 - y_pred, gamma) * y_true * np.log(y_pred), axis=1)
    return np.mean(cfce_loss)

def gaussian_negative_log_likelihood_loss(y_true: np.ndarray, expectation_pred: np.ndarray, var_pred: np.ndarray, eps: float=1e-06) -> float:
    if len(y_true) != len(expectation_pred) or len(y_true) != len(var_pred) or len(expectation_pred) != len(var_pred):
        raise ValueError('Input arrays must have the same length.')
    loss_var = 0.5 * np.log(np.maximum(var_pred, eps))
    loss_exp = 0.5 * (np.square(y_true - expectation_pred) / np.maximum(var_pred, eps))
    loss = loss_var + loss_exp
    return np.mean(loss)

def hinge_loss(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Length of predicted and actual array must be same.')
    if np.any((y_true != -1) & (y_true != 1)):
        raise ValueError('y_true can have values -1 or 1 only.')
    hinge_losses = np.maximum(0, 1.0 - y_true * y_pred)
    return np.mean(hinge_losses)

def huber_loss(y_true: np.ndarray, y_pred: np.ndarray, delta: float) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Input arrays must have the same length.')
    huber_mse = 0.5 * (y_true - y_pred) ** 2
    huber_mae = delta * (np.abs(y_true - y_pred) - 0.5 * delta)
    return np.where(np.abs(y_true - y_pred) <= delta, huber_mse, huber_mae).mean()

def mean_squared_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Input arrays must have the same length.')
    squared_errors = (y_true - y_pred) ** 2
    return np.mean(squared_errors)

def mean_absolute_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Input arrays must have the same length.')
    return np.mean(abs(y_true - y_pred))

def mean_squared_logarithmic_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Input arrays must have the same length.')
    squared_logarithmic_errors = (np.log1p(y_true) - np.log1p(y_pred)) ** 2
    return np.mean(squared_logarithmic_errors)

def mean_absolute_percentage_error(y_true: np.ndarray, y_pred: np.ndarray, epsilon: float=1e-15) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('The length of the two arrays should be the same.')
    y_true = np.where(y_true == 0, epsilon, y_true)
    absolute_percentage_diff = np.abs((y_true - y_pred) / y_true)
    return np.mean(absolute_percentage_diff)

def perplexity_loss(y_true: np.ndarray, y_pred: np.ndarray, epsilon: float=1e-07) -> float:
    vocab_size = y_pred.shape[2]
    if y_true.shape[0] != y_pred.shape[0]:
        raise ValueError('Batch size of y_true and y_pred must be equal.')
    if y_true.shape[1] != y_pred.shape[1]:
        raise ValueError('Sentence length of y_true and y_pred must be equal.')
    if np.max(y_true) > vocab_size:
        raise ValueError('Label value must not be greater than vocabulary size.')
    filter_matrix = np.array([[list(np.eye(vocab_size)[word]) for word in sentence] for sentence in y_true])
    true_class_pred = np.sum(y_pred * filter_matrix, axis=2).clip(epsilon, 1)
    perp_losses = np.exp(np.negative(np.mean(np.log(true_class_pred), axis=1)))
    return np.mean(perp_losses)

def smooth_l1_loss(y_true: np.ndarray, y_pred: np.ndarray, beta: float=1.0) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('The length of the two arrays should be the same.')
    diff = np.abs(y_true - y_pred)
    loss = np.where(diff < beta, 0.5 * diff ** 2 / beta, diff - 0.5 * beta)
    return np.mean(loss)

def kullback_leibler_divergence(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Input arrays must have the same length.')
    filter_array = y_true != 0
    y_true = y_true[filter_array]
    y_pred = y_pred[filter_array]
    kl_loss = y_true * np.log(y_true / y_pred)
    return np.sum(kl_loss)

def connectionist_temporal_classification_loss(y_true: np.ndarray, y_pred: np.ndarray, blank: int=0):
    if len(y_true) > len(y_pred):
        raise ValueError('y_true cannot be longer than y_pred.')
    if y_true.ndim != 1:
        raise ValueError('y_true should be an 1D array.')
    if y_pred.ndim != 2:
        raise ValueError('y_pred should be a 2D array.')
    if np.max(y_true) >= y_pred.shape[1]:
        raise ValueError('Class indices in y_true should be less than y_pred.shape[1].')
    log_probs = np.log(y_pred)
    input_len = log_probs.shape[0]
    target_len = len(y_true)
    target_len_extended = 2 * target_len + 1
    extended_targets = np.full(target_len_extended, blank)
    extended_targets[1::2] = y_true
    alpha = np.full((input_len, target_len_extended), -np.inf)
    alpha[0, 0] = log_probs[0, blank]
    if target_len_extended > 1:
        alpha[0, 1] = log_probs[0, extended_targets[1]]
    for t in range(1, input_len):
        for s in range(target_len_extended):
            current_label = extended_targets[s]
            alpha[t, s] = alpha[t - 1, s]
            if s > 0:
                alpha[t, s] = np.logaddexp(alpha[t, s], alpha[t - 1, s - 1])
            if s > 1 and current_label != extended_targets[s - 2]:
                alpha[t, s] = np.logaddexp(alpha[t, s], alpha[t - 1, s - 2])
            alpha[t, s] += log_probs[t, current_label]
    loss = -np.logaddexp(alpha[input_len - 1, target_len_extended - 1], alpha[input_len - 1, target_len_extended - 2])
    return loss

def symmetric_mean_absolute_percentage_error(y_true: np.ndarray, y_pred: np.ndarray, epsilon: float=1e-15) -> float:
    if len(y_true) != len(y_pred):
        raise ValueError('Input arrays must have the same length.')
    denominator = (np.abs(y_true) + np.abs(y_pred)) / 2.0
    denominator = np.where(denominator == 0, epsilon, denominator)
    smape_loss = np.abs(y_true - y_pred) / denominator
    return np.mean(smape_loss)

def create_tree(data_set: list, min_sup: int=1) -> tuple[TreeNode, dict]:
    header_table: dict = {}
    for trans in data_set:
        for item in trans:
            header_table[item] = header_table.get(item, [0, None])
            header_table[item][0] += 1
    for k in list(header_table):
        if header_table[k][0] < min_sup:
            del header_table[k]
    if not (freq_item_set := set(header_table)):
        return (TreeNode('Null Set', 1, None), {})
    for (key, value) in header_table.items():
        header_table[key] = [value, None]
    fp_tree = TreeNode('Null Set', 1, None)
    for tran_set in data_set:
        local_d = {item: header_table[item][0] for item in tran_set if item in freq_item_set}
        if local_d:
            sorted_items = sorted(local_d.items(), key=lambda item_info: item_info[1], reverse=True)
            ordered_items = [item[0] for item in sorted_items]
            update_tree(ordered_items, fp_tree, header_table, 1)
    return (fp_tree, header_table)

def update_tree(items: list, in_tree: TreeNode, header_table: dict, count: int) -> None:
    if items[0] in in_tree.children:
        in_tree.children[items[0]].inc(count)
    else:
        in_tree.children[items[0]] = TreeNode(items[0], count, in_tree)
        if header_table[items[0]][1] is None:
            header_table[items[0]][1] = in_tree.children[items[0]]
        else:
            update_header(header_table[items[0]][1], in_tree.children[items[0]])
    if len(items) > 1:
        update_tree(items[1:], in_tree.children[items[0]], header_table, count)

def update_header(node_to_test: TreeNode, target_node: TreeNode) -> TreeNode:
    while node_to_test.node_link is not None:
        node_to_test = node_to_test.node_link
    if node_to_test.node_link is None:
        node_to_test.node_link = target_node
    return node_to_test

def ascend_tree(leaf_node: TreeNode, prefix_path: list[str]) -> None:
    if leaf_node.parent is not None:
        prefix_path.append(leaf_node.name)
        ascend_tree(leaf_node.parent, prefix_path)

def find_prefix_path(base_pat: frozenset, tree_node: TreeNode | None) -> dict:
    cond_pats: dict = {}
    while tree_node is not None:
        prefix_path: list = []
        ascend_tree(tree_node, prefix_path)
        if len(prefix_path) > 1:
            cond_pats[frozenset(prefix_path[1:])] = tree_node.count
        tree_node = tree_node.node_link
    return cond_pats

