def similarity_search(dataset: np.ndarray, value_array: np.ndarray) -> list[list[list[float] | float]]:
    if dataset.ndim != value_array.ndim:
        msg = f"Wrong input data's dimensions... dataset : {dataset.ndim}, value_array : {value_array.ndim}"
        raise ValueError(msg)
    try:
        if dataset.shape[1] != value_array.shape[1]:
            msg = f"Wrong input data's shape... dataset : {dataset.shape[1]}, value_array : {value_array.shape[1]}"
            raise ValueError(msg)
    except IndexError:
        if dataset.ndim != value_array.ndim:
            raise TypeError('Wrong shape')
    if dataset.dtype != value_array.dtype:
        msg = f'Input data have different datatype... dataset : {dataset.dtype}, value_array : {value_array.dtype}'
        raise TypeError(msg)
    answer = []
    for value in value_array:
        dist = euclidean(value, dataset[0])
        vector = dataset[0].tolist()
        for dataset_value in dataset[1:]:
            temp_dist = euclidean(value, dataset_value)
            if dist > temp_dist:
                dist = temp_dist
                vector = dataset_value.tolist()
        answer.append([vector, dist])
    return answer

