def _initialize_medoids(n_samples: int, n_clusters: int, random_state: int | None=None) -> ndarray:
    rng = np.random.default_rng(random_state)
    return rng.choice(n_samples, n_clusters, replace=False)

def _update_medoids(data_matrix: ndarray, clusters: ndarray, n_clusters: int) -> ndarray:
    new_medoids = np.zeros(n_clusters, dtype=int)
    for k in range(n_clusters):
        cluster_points = np.where(clusters == k)[0]
        if len(cluster_points) == 0:
            continue
        intra_distances = np.sum(np.linalg.norm(data_matrix[cluster_points][:, np.newaxis] - data_matrix[cluster_points], axis=2), axis=1)
        new_medoids[k] = cluster_points[np.argmin(intra_distances)]
    return new_medoids

def apply_k_medoids(data_matrix: ndarray, n_clusters: int=3, max_iter: int=100, random_state: int | None=None) -> tuple[ndarray, ndarray]:
    if n_clusters < 1 or max_iter < 1:
        raise ValueError('n_clusters and max_iter must be >= 1')
    n_samples = data_matrix.shape[0]
    medoids = _initialize_medoids(n_samples, n_clusters, random_state)
    for _ in range(max_iter):
        distances = _compute_distances(data_matrix, medoids)
        clusters = _assign_clusters(distances)
        new_medoids = _update_medoids(data_matrix, clusters, n_clusters)
        if np.array_equal(medoids, new_medoids):
            break
        medoids = new_medoids
    return (medoids, clusters)

def compute_heterogeneity(data, k, centroids, cluster_assignment):
    heterogeneity = 0.0
    for i in range(k):
        member_data_points = data[cluster_assignment == i, :]
        if member_data_points.shape[0] > 0:
            distances = pairwise_distances(member_data_points, [centroids[i]], metric='euclidean')
            squared_distances = distances ** 2
            heterogeneity += np.sum(squared_distances)
    return heterogeneity

def kmeans(data, k, initial_centroids, maxiter=500, record_heterogeneity=None, verbose=False):
    centroids = initial_centroids[:]
    prev_cluster_assignment = None
    for itr in range(maxiter):
        if verbose:
            print(itr, end='')
        cluster_assignment = assign_clusters(data, centroids)
        centroids = revise_centroids(data, k, cluster_assignment)
        if prev_cluster_assignment is not None and (prev_cluster_assignment == cluster_assignment).all():
            break
        if prev_cluster_assignment is not None:
            num_changed = np.sum(prev_cluster_assignment != cluster_assignment)
            if verbose:
                print(f'    {num_changed:5d} elements changed their cluster assignment.')
        if record_heterogeneity is not None:
            score = compute_heterogeneity(data, k, centroids, cluster_assignment)
            record_heterogeneity.append(score)
        prev_cluster_assignment = cluster_assignment[:]
    return (centroids, cluster_assignment)

def astar(world, start, goal):
    _open = []
    _closed = []
    _open.append(start)
    while _open:
        min_f = np.argmin([n.f for n in _open])
        current = _open[min_f]
        _closed.append(_open.pop(min_f))
        if current == goal:
            break
        for n in world.get_neighbours(current):
            for c in _closed:
                if c == n:
                    continue
            n.g = current.g + 1
            (x1, y1) = n.position
            (x2, y2) = goal.position
            n.h = (y2 - y1) ** 2 + (x2 - x1) ** 2
            n.f = n.h + n.g
            for c in _open:
                if c == n and c.f < n.f:
                    continue
            _open.append(n)
    path = []
    while current.parent is not None:
        path.append(current.position)
        current = current.parent
    path.append(current.position)
    return path[::-1]

def log_likelihood(x, y, weights):
    scores = np.dot(x, weights)
    return np.sum(y * scores - np.log(1 + np.exp(scores)))

def term_frequency(term: str, document: str) -> int:
    document_without_punctuation = document.translate(str.maketrans('', '', string.punctuation)).replace('\n', '')
    tokenize_document = document_without_punctuation.split(' ')
    return len([word for word in tokenize_document if word.lower() == term.lower()])

def document_frequency(term: str, corpus: str) -> tuple[int, int]:
    corpus_without_punctuation = corpus.lower().translate(str.maketrans('', '', string.punctuation))
    docs = corpus_without_punctuation.split('\n')
    term = term.lower()
    return (len([doc for doc in docs if term in doc]), len(docs))

def inverse_document_frequency(df: int, n: int, smoothing=False) -> float:
    if smoothing:
        if n == 0:
            raise ValueError('log10(0) is undefined.')
        return round(1 + log10(n / (1 + df)), 3)
    if df == 0:
        raise ZeroDivisionError('df must be > 0')
    if n == 0:
        raise ValueError('log10(0) is undefined.')
    return round(log10(n / df), 3)

def _validate_clients(client_models: Sequence[Sequence[np.ndarray]]) -> None:
    if not client_models:
        raise ValueError('client_models must be a non-empty list')
    ref_shapes = [tuple(arr.shape) for arr in client_models[0]]
    for (idx, cm) in enumerate(client_models, start=1):
        if len(cm) != len(ref_shapes):
            raise ValueError('All clients must have the same number of tensors')
        for (s_ref, arr) in zip(ref_shapes, cm):
            if tuple(arr.shape) != s_ref:
                msg = f'Client {idx} tensor shape {tuple(arr.shape)} does not match {s_ref}'
                raise ValueError(msg)

def _normalize_weights(weights: np.ndarray, num_clients: int) -> np.ndarray:
    if weights.shape != (num_clients,):
        msg = f'weights must have shape ({num_clients},)'
        raise ValueError(msg)
    if np.any(weights < 0):
        raise ValueError('weights must be non-negative')
    total = float(weights.sum())
    if total <= 0.0:
        raise ValueError('weights must sum to a positive value')
    return weights / total

def prune(itemset: list, candidates: list, length: int) -> list:
    itemset_counter = Counter((tuple(item) for item in itemset))
    pruned = []
    for candidate in candidates:
        is_subsequence = True
        for item in candidate:
            item_tuple = tuple(item)
            if item_tuple not in itemset_counter or itemset_counter[item_tuple] < length - 1:
                is_subsequence = False
                break
        if is_subsequence:
            pruned.append(candidate)
    return pruned

def apriori(data: list[list[str]], min_support: int) -> list[tuple[list[str], int]]:
    itemset = [list(transaction) for transaction in data]
    frequent_itemsets = []
    length = 1
    while itemset:
        counts = [0] * len(itemset)
        for transaction in data:
            for (j, candidate) in enumerate(itemset):
                if all((item in transaction for item in candidate)):
                    counts[j] += 1
        itemset = [item for (i, item) in enumerate(itemset) if counts[i] >= min_support]
        for (i, item) in enumerate(itemset):
            frequent_itemsets.append((sorted(item), counts[i]))
        length += 1
        itemset = prune(itemset, list(combinations(itemset, length)), length)
    return frequent_itemsets

def covariance_within_classes(features: np.ndarray, labels: np.ndarray, classes: int) -> np.ndarray:
    covariance_sum = np.nan
    for i in range(classes):
        data = features[:, labels == i]
        data_mean = data.mean(1)
        centered_data = data - column_reshape(data_mean)
        if i > 0:
            covariance_sum += np.dot(centered_data, centered_data.T)
        else:
            covariance_sum = np.dot(centered_data, centered_data.T)
    return covariance_sum / features.shape[1]

def covariance_between_classes(features: np.ndarray, labels: np.ndarray, classes: int) -> np.ndarray:
    general_data_mean = features.mean(1)
    covariance_sum = np.nan
    for i in range(classes):
        data = features[:, labels == i]
        device_data = data.shape[1]
        data_mean = data.mean(1)
        if i > 0:
            covariance_sum += device_data * np.dot(column_reshape(data_mean) - column_reshape(general_data_mean), (column_reshape(data_mean) - column_reshape(general_data_mean)).T)
        else:
            covariance_sum = device_data * np.dot(column_reshape(data_mean) - column_reshape(general_data_mean), (column_reshape(data_mean) - column_reshape(general_data_mean)).T)
    return covariance_sum / features.shape[1]

def count_time(func):

