def generate_parentheses_iterative(length: int) -> list[str]:
    if length == 0:
        return ['']
    result: list[str] = []
    stack: list[tuple[str, int, int]] = []
    stack.append(('', 0, 0))
    while stack:
        (current_combination, open_count, close_count) = stack.pop()
        if len(current_combination) == 2 * length:
            result.append(current_combination)
            continue
        if open_count < length:
            stack.append((current_combination + '(', open_count + 1, close_count))
        if close_count < open_count:
            stack.append((current_combination + ')', open_count, close_count + 1))
    return result

def backtrack(needed_sum: int, power: int, current_number: int, current_sum: int, solutions_count: int) -> tuple[int, int]:
    if current_sum == needed_sum:
        solutions_count += 1
        return (current_sum, solutions_count)
    i_to_n = current_number ** power
    if current_sum + i_to_n <= needed_sum:
        current_sum += i_to_n
        (current_sum, solutions_count) = backtrack(needed_sum, power, current_number + 1, current_sum, solutions_count)
        current_sum -= i_to_n
    if i_to_n < needed_sum:
        (current_sum, solutions_count) = backtrack(needed_sum, power, current_number + 1, current_sum, solutions_count)
    return (current_sum, solutions_count)

def solve(needed_sum: int, power: int) -> int:
    if not (1 <= needed_sum <= 1000 and 2 <= power <= 10):
        raise ValueError('Invalid input\nneeded_sum must be between 1 and 1000, power between 2 and 10.')
    return backtrack(needed_sum, power, 1, 0, 0)[1]

def backtrack(partial: str, open_count: int, close_count: int, n: int, result: list[str]) -> None:
    if len(partial) == 2 * n:
        result.append(partial)
        return
    if open_count < n:
        backtrack(partial + '(', open_count + 1, close_count, n, result)
    if close_count < open_count:
        backtrack(partial + ')', open_count, close_count + 1, n, result)

def minimax(depth: int, node_index: int, is_max: bool, scores: list[int], height: float) -> int:
    if depth < 0:
        raise ValueError('Depth cannot be less than 0')
    if len(scores) == 0:
        raise ValueError('Scores cannot be empty')
    if len(scores) & len(scores) - 1 != 0:
        raise ValueError('Number of scores must be a power of 2')
    if depth == height:
        return scores[node_index]
    if is_max:
        return max(minimax(depth + 1, node_index * 2, False, scores, height), minimax(depth + 1, node_index * 2 + 1, False, scores, height))
    return min(minimax(depth + 1, node_index * 2, True, scores, height), minimax(depth + 1, node_index * 2 + 1, True, scores, height))

def depth_first_search(possible_board: list[int], diagonal_right_collisions: list[int], diagonal_left_collisions: list[int], boards: list[list[str]], n: int) -> None:
    row = len(possible_board)
    if row == n:
        boards.append(['. ' * i + 'Q ' + '. ' * (n - 1 - i) for i in possible_board])
        return
    for col in range(n):
        if col in possible_board or row - col in diagonal_right_collisions or row + col in diagonal_left_collisions:
            continue
        depth_first_search([*possible_board, col], [*diagonal_right_collisions, row - col], [*diagonal_left_collisions, row + col], boards, n)

