def is_valid(puzzle: list[list[str]], word: str, row: int, col: int, vertical: bool) -> bool:
    (rows, cols) = (len(puzzle), len(puzzle[0]))
    for (i, ch) in enumerate(word):
        (r, c) = (row + i, col) if vertical else (row, col + i)
        if r >= rows or c >= cols:
            return False
        cell = puzzle[r][c]
        if cell not in ('', ch):
            return False
    return True

def place_word(puzzle: list[list[str]], word: str, row: int, col: int, vertical: bool) -> None:
    for (i, ch) in enumerate(word):
        if vertical:
            puzzle[row + i][col] = ch
        else:
            puzzle[row][col + i] = ch

def remove_word(puzzle: list[list[str]], word: str, row: int, col: int, vertical: bool, snapshot: list[list[str]]) -> None:
    for i in range(len(word)):
        (r, c) = (row + i, col) if vertical else (row, col + i)
        if snapshot[r][c] == '':
            puzzle[r][c] = ''

def solve_crossword(puzzle: list[list[str]], words: list[str]) -> bool:
    if not words:
        return True
    remaining = sorted(words, key=len, reverse=True)
    (word, rest) = (remaining[0], remaining[1:])
    for row in range(len(puzzle)):
        for col in range(len(puzzle[0])):
            for vertical in (True, False):
                if is_valid(puzzle, word, row, col, vertical):
                    snapshot = [r[:] for r in puzzle]
                    place_word(puzzle, word, row, col, vertical)
                    if solve_crossword(puzzle, rest):
                        return True
                    remove_word(puzzle, word, row, col, vertical, snapshot)
    return False

def backtrack(current_word: str, path: list[str], end_word: str, word_set: set[str]) -> list[str]:
    if current_word == end_word:
        return path
    for i in range(len(current_word)):
        for c in string.ascii_lowercase:
            transformed_word = current_word[:i] + c + current_word[i + 1:]
            if transformed_word in word_set:
                word_set.remove(transformed_word)
                result = backtrack(transformed_word, [*path, transformed_word], end_word, word_set)
                if result:
                    return result
                word_set.add(transformed_word)
    return []

def word_ladder(begin_word: str, end_word: str, word_set: set[str]) -> list[str]:
    if end_word not in word_set:
        return []
    return backtrack(begin_word, [begin_word], end_word, word_set)

