def floyd(n):
    result = ''
    for i in range(n):
        for _ in range(n - i - 1):
            result += ' '
        for _ in range(i + 1):
            result += '* '
        result += '\n'
    return result

def reverse_floyd(n):
    result = ''
    for i in range(n, 0, -1):
        for _ in range(i, 0, -1):
            result += '* '
        result += '\n'
        for _ in range(n - i + 1, 0, -1):
            result += ' '
    return result

def pretty_print(n):
