def hilbert_curve(center: tuple[float, float], level: int, side: float=1, angle: int=90) -> list[tuple[float, float]]:
    (x, y) = center
    angle = angle % 360
    pnts = [(x + side / 4, y + side / 4), (x - side / 4, y + side / 4), (x - side / 4, y - side / 4), (x + side / 4, y - side / 4)]
    pnts = rotate_pnts(pnts, angle)
    if level == 1:
        return pnts
    else:
        return hilbert_curve(pnts[0], level - 1, side / 2, angle=angle + 90)[::-1] + hilbert_curve(pnts[1], level - 1, side / 2, angle=angle) + hilbert_curve(pnts[2], level - 1, side / 2, angle=angle) + hilbert_curve(pnts[3], level - 1, side / 2, angle=angle - 90)[::-1]

def transform(point: tuple[float, float], index: int) -> tuple[float, float]:
