def is_filled(row: int, col: int) -> bool:
    if row < 0 or col < 0:
        msg = f'row and col must be non-negative, got ({row}, {col})'
        raise ValueError(msg)
    while row > 0 or col > 0:
        if row % 3 == 1 and col % 3 == 1:
            return False
        row //= 3
        col //= 3
    return True

