def longest_subsequence(array: list[int]) -> list[int]:
    n = len(array)
    longest_increasing_subsequence = []
    for i in range(n):
        longest_increasing_subsequence.append([array[i]])
    for i in range(1, n):
        for prev in range(i):
            if array[prev] <= array[i] and len(longest_increasing_subsequence[prev]) + 1 > len(longest_increasing_subsequence[i]):
                longest_increasing_subsequence[i] = copy.copy(longest_increasing_subsequence[prev])
                longest_increasing_subsequence[i].append(array[i])
    result: list[int] = []
    for i in range(n):
        if len(longest_increasing_subsequence[i]) > len(result):
            result = longest_increasing_subsequence[i]
    return result

def minimum_squares_to_represent_a_number(number: int) -> int:
    if number != int(number):
        raise ValueError('the value of input must be a natural number')
    if number < 0:
        raise ValueError('the value of input must not be a negative number')
    if number == 0:
        return 1
    answers = [-1] * (number + 1)
    answers[0] = 0
    for i in range(1, number + 1):
        answer = sys.maxsize
        root = int(math.sqrt(i))
        for j in range(1, root + 1):
            current_answer = 1 + answers[i - j ** 2]
            answer = min(answer, current_answer)
        answers[i] = answer
    return answers[number]

def fizz_buzz(number: int, iterations: int) -> str:
    if not isinstance(iterations, int):
        raise ValueError('iterations must be defined as integers')
    if not isinstance(number, int) or not number >= 1:
        raise ValueError('starting number must be\n                         and integer and be more than 0')
    if not iterations >= 1:
        raise ValueError('Iterations must be done more than 0 times to play FizzBuzz')
    out = ''
    while number <= iterations:
        if number % 3 == 0:
            out += 'Fizz'
        if number % 5 == 0:
            out += 'Buzz'
        if 0 not in (number % 3, number % 5):
            out += str(number)
        number += 1
        out += ' '
    return out

def subset_combinations(elements: list[int], n: int) -> list:
    r = len(elements)
    if n > r:
        return []
    dp: list[list[tuple]] = [[] for _ in range(r + 1)]
    dp[0].append(())
    for i in range(1, r + 1):
        for j in range(i, 0, -1):
            for prev_combination in dp[j - 1]:
                dp[j].append((*prev_combination, elements[i - 1]))
    try:
        return sorted(dp[n])
    except TypeError:
        return dp[n]

def mincost_tickets(days: list[int], costs: list[int]) -> int:
    if not isinstance(days, list) or not all((isinstance(day, int) for day in days)):
        raise ValueError('The parameter days should be a list of integers')
    if len(costs) != 3 or not all((isinstance(cost, int) for cost in costs)):
        raise ValueError('The parameter costs should be a list of three integers')
    if len(days) == 0:
        return 0
    if min(days) <= 0:
        raise ValueError('All days elements should be greater than 0')
    if max(days) >= 366:
        raise ValueError('All days elements should be less than 366')
    days_set = set(days)

    @functools.cache
    def dynamic_programming(index: int) -> int:
        if index > 365:
            return 0
        if index not in days_set:
            return dynamic_programming(index + 1)
        return min(costs[0] + dynamic_programming(index + 1), costs[1] + dynamic_programming(index + 7), costs[2] + dynamic_programming(index + 30))
    return dynamic_programming(1)

def prefix_sum(array: list[int], queries: list[tuple[int, int]]) -> list[int]:
    dp = [0] * len(array)
    dp[0] = array[0]
    for i in range(1, len(array)):
        dp[i] = dp[i - 1] + array[i]
    result = []
    for query in queries:
        (left, right) = query
        res = dp[right]
        if left > 0:
            res -= dp[left - 1]
        result.append(res)
    return result

def naive_cut_rod_recursive(n: int, prices: list):
    _enforce_args(n, prices)
    if n == 0:
        return 0
    max_revue = float('-inf')
    for i in range(1, n + 1):
        max_revue = max(max_revue, prices[i - 1] + naive_cut_rod_recursive(n - i, prices))
    return max_revue

def top_down_cut_rod(n: int, prices: list):
    _enforce_args(n, prices)
    max_rev = [float('-inf') for _ in range(n + 1)]
    return _top_down_cut_rod_recursive(n, prices, max_rev)

def _top_down_cut_rod_recursive(n: int, prices: list, max_rev: list):
    if max_rev[n] >= 0:
        return max_rev[n]
    elif n == 0:
        return 0
    else:
        max_revenue = float('-inf')
        for i in range(1, n + 1):
            max_revenue = max(max_revenue, prices[i - 1] + _top_down_cut_rod_recursive(n - i, prices, max_rev))
        max_rev[n] = max_revenue
    return max_rev[n]

def bottom_up_cut_rod(n: int, prices: list):
    _enforce_args(n, prices)
    max_rev = [float('-inf') for _ in range(n + 1)]
    max_rev[0] = 0
    for i in range(1, n + 1):
        max_revenue_i = max_rev[i]
        for j in range(1, i + 1):
            max_revenue_i = max(max_revenue_i, prices[j - 1] + max_rev[i - j])
        max_rev[i] = max_revenue_i
    return max_rev[n]

def _enforce_args(n: int, prices: list) -> None:
    if n < 0:
        msg = f'n must be greater than or equal to 0. Got n = {n}'
        raise ValueError(msg)
    if n > len(prices):
        msg = f'Each integral piece of rod must have a corresponding price. Got n = {n} but length of prices = {len(prices)}'
        raise ValueError(msg)

def all_construct(target: str, word_bank: list[str] | None=None) -> list[list[str]]:
    word_bank = word_bank or []
    table_size: int = len(target) + 1
    table: list[list[list[str]]] = []
    for _ in range(table_size):
        table.append([])
    table[0] = [[]]
    for i in range(table_size):
        if table[i] != []:
            for word in word_bank:
                if target[i:i + len(word)] == word:
                    new_combinations: list[list[str]] = [[word, *way] for way in table[i]]
                    table[i + len(word)] += new_combinations
    for combination in table[len(target)]:
        combination.reverse()
    return table[len(target)]

def fibonacci(n: int) -> int:
    if n < 0:
        raise ValueError('Negative arguments are not supported')
    return _fib(n)[0]

def _fib(n: int) -> tuple[int, int]:
    if n == 0:
        return (0, 1)
    (a, b) = _fib(n // 2)
    c = a * (b * 2 - a)
    d = a * a + b * b
    return (d, c + d) if n % 2 else (c, d)

def max_subarray_sum(arr: Sequence[float], allow_empty_subarrays: bool=False) -> float:
    if not arr:
        return 0
    max_sum = 0 if allow_empty_subarrays else float('-inf')
    curr_sum = 0.0
    for num in arr:
        curr_sum = max(0 if allow_empty_subarrays else num, curr_sum + num)
        max_sum = max(max_sum, curr_sum)
    return max_sum

def min_distance_up_bottom(word1: str, word2: str) -> int:
    len_word1 = len(word1)
    len_word2 = len(word2)

    @functools.cache
    def min_distance(index1: int, index2: int) -> int:
        if index1 >= len_word1:
            return len_word2 - index2
        if index2 >= len_word2:
            return len_word1 - index1
        diff = int(word1[index1] != word2[index2])
        return min(1 + min_distance(index1 + 1, index2), 1 + min_distance(index1, index2 + 1), diff + min_distance(index1 + 1, index2 + 1))
    return min_distance(0, 0)

def abbr(a: str, b: str) -> bool:
    n = len(a)
    m = len(b)
    dp = [[False for _ in range(m + 1)] for _ in range(n + 1)]
    dp[0][0] = True
    for i in range(n):
        for j in range(m + 1):
            if dp[i][j]:
                if j < m and a[i].upper() == b[j]:
                    dp[i + 1][j + 1] = True
                if a[i].islower():
                    dp[i + 1][j] = True
    return dp[n][m]

def trapped_rainwater(heights: tuple[int, ...]) -> int:
    if not heights:
        return 0
    if any((h < 0 for h in heights)):
        raise ValueError('No height can be negative')
    length = len(heights)
    left_max = [0] * length
    left_max[0] = heights[0]
    for (i, height) in enumerate(heights[1:], start=1):
        left_max[i] = max(height, left_max[i - 1])
    right_max = [0] * length
    right_max[-1] = heights[-1]
    for i in range(length - 2, -1, -1):
        right_max[i] = max(heights[i], right_max[i + 1])
    return sum((min(left, right) - height for (left, right, height) in zip(left_max, right_max, heights)))

def longest_common_subsequence(x: str, y: str):
    assert x is not None
    assert y is not None
    m = len(x)
    n = len(y)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            match = 1 if x[i - 1] == y[j - 1] else 0
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1] + match)
    seq = ''
    (i, j) = (m, n)
    while i > 0 and j > 0:
        match = 1 if x[i - 1] == y[j - 1] else 0
        if dp[i][j] == dp[i - 1][j - 1] + match:
            if match == 1:
                seq = x[i - 1] + seq
            i -= 1
            j -= 1
        elif dp[i][j] == dp[i - 1][j]:
            i -= 1
        else:
            j -= 1
    return (dp[m][n], seq)

def longest_common_substring(text1: str, text2: str) -> str:
    if not (isinstance(text1, str) and isinstance(text2, str)):
        raise ValueError('longest_common_substring() takes two strings for inputs')
    if not text1 or not text2:
        return ''
    text1_length = len(text1)
    text2_length = len(text2)
    dp = [[0] * (text2_length + 1) for _ in range(text1_length + 1)]
    end_pos = 0
    max_length = 0
    for i in range(1, text1_length + 1):
        for j in range(1, text2_length + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
                if dp[i][j] > max_length:
                    end_pos = i
                    max_length = dp[i][j]
    return text1[end_pos - max_length:end_pos]

def mf_knapsack(i, wt, val, j):
    global f
    if f[i][j] < 0:
        if j < wt[i - 1]:
            val = mf_knapsack(i - 1, wt, val, j)
        else:
            val = max(mf_knapsack(i - 1, wt, val, j), mf_knapsack(i - 1, wt, val, j - wt[i - 1]) + val[i - 1])
        f[i][j] = val
    return f[i][j]

def knapsack(w, wt, val, n):
    dp = [[0] * (w + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w_ in range(1, w + 1):
            if wt[i - 1] <= w_:
                dp[i][w_] = max(val[i - 1] + dp[i - 1][w_ - wt[i - 1]], dp[i - 1][w_])
            else:
                dp[i][w_] = dp[i - 1][w_]
    return (dp[n][w_], dp)

def knapsack_with_example_solution(w: int, wt: list, val: list):
    if not (isinstance(wt, (list, tuple)) and isinstance(val, (list, tuple))):
        raise ValueError('Both the weights and values vectors must be either lists or tuples')
    num_items = len(wt)
    if num_items != len(val):
        msg = f'The number of weights must be the same as the number of values.\nBut got {num_items} weights and {len(val)} values'
        raise ValueError(msg)
    for i in range(num_items):
        if not isinstance(wt[i], int):
            msg = f'All weights must be integers but got weight of type {type(wt[i])} at index {i}'
            raise TypeError(msg)
    (optimal_val, dp_table) = knapsack(w, wt, val, num_items)
    example_optional_set: set = set()
    _construct_solution(dp_table, wt, num_items, w, example_optional_set)
    return (optimal_val, example_optional_set)

def _construct_solution(dp: list, wt: list, i: int, j: int, optimal_set: set) -> None:
    if i > 0 and j > 0:
        if dp[i - 1][j] == dp[i][j]:
            _construct_solution(dp, wt, i - 1, j, optimal_set)
        else:
            optimal_set.add(i)
            _construct_solution(dp, wt, i - 1, j - wt[i - 1], optimal_set)

def is_match(string: str, pattern: str) -> bool:
    dp = [[False] * (len(pattern) + 1) for _ in string + '1']
    dp[0][0] = True
    for (j, char) in enumerate(pattern, 1):
        if char == '*':
            dp[0][j] = dp[0][j - 1]
    for (i, s_char) in enumerate(string, 1):
        for (j, p_char) in enumerate(pattern, 1):
            if p_char in (s_char, '?'):
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[j - 1] == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
    return dp[len(string)][len(pattern)]

def largest_divisible_subset(items: list[int]) -> list[int]:
    items = sorted(items)
    number_of_items = len(items)
    memo = [1] * number_of_items
    hash_array = list(range(number_of_items))
    for (i, item) in enumerate(items):
        for prev_index in range(i):
            if (items[prev_index] != 0 and item % items[prev_index]) == 0 and 1 + memo[prev_index] > memo[i]:
                memo[i] = 1 + memo[prev_index]
                hash_array[i] = prev_index
    ans = -1
    last_index = -1
    for (i, memo_item) in enumerate(memo):
        if memo_item > ans:
            ans = memo_item
            last_index = i
    if last_index == -1:
        return []
    result = [items[last_index]]
    while hash_array[last_index] != last_index:
        last_index = hash_array[last_index]
        result.append(items[last_index])
    return result

def find_min(numbers: list[int]) -> int:
    n = len(numbers)
    s = sum(numbers)
    dp = [[False for x in range(s + 1)] for y in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True
    for i in range(1, s + 1):
        dp[0][i] = False
    for i in range(1, n + 1):
        for j in range(1, s + 1):
            dp[i][j] = dp[i - 1][j]
            if numbers[i - 1] <= j:
                dp[i][j] = dp[i][j] or dp[i - 1][j - numbers[i - 1]]
    for j in range(int(s / 2), -1, -1):
        if dp[n][j] is True:
            diff = s - 2 * j
            break
    return diff

def minimum_cost_path(matrix: list[list[int]]) -> int:
    for i in range(1, len(matrix[0])):
        matrix[0][i] += matrix[0][i - 1]
    for i in range(1, len(matrix)):
        matrix[i][0] += matrix[i - 1][0]
    for i in range(1, len(matrix)):
        for j in range(1, len(matrix[0])):
            matrix[i][j] += min(matrix[i - 1][j], matrix[i][j - 1])
    return matrix[-1][-1]

def dp_count(s, n):
    if n < 0:
        return 0
    table = [0] * (n + 1)
    table[0] = 1
    for coin_val in s:
        for j in range(coin_val, n + 1):
            table[j] += table[j - coin_val]
    return table[n]

def matrix_chain_order(array: list[int]) -> tuple[list[list[int]], list[list[int]]]:
    n = len(array)
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    sol = [[0 for _ in range(n)] for _ in range(n)]
    for chain_length in range(2, n):
        for a in range(1, n - chain_length + 1):
            b = a + chain_length - 1
            matrix[a][b] = sys.maxsize
            for c in range(a, b):
                cost = matrix[a][c] + matrix[c + 1][b] + array[a - 1] * array[c] * array[b]
                if cost < matrix[a][b]:
                    matrix[a][b] = cost
                    sol[a][b] = c
    return (matrix, sol)

