def sigmoid_function(value: float, deriv: bool=False) -> float:
    if deriv:
        return value * (1 - value)
    return 1 / (1 + math.exp(-value))

def change_contrast(img: Image.Image, level: int) -> Image.Image:
    factor = 259 * (level + 255) / (255 * (259 - level))

    def contrast(c: int) -> int:
        return int(128 + factor * (c - 128))
    return img.point(contrast)

def make_sepia(img, factor: int):
    (pixel_h, pixel_v) = (img.shape[0], img.shape[1])

    def to_grayscale(blue, green, red):
        return 0.2126 * red + 0.587 * green + 0.114 * blue

    def normalize(value):
        return min(value, 255)
    for i in range(pixel_h):
        for j in range(pixel_v):
            greyscale = int(to_grayscale(*img[i][j]))
            img[i][j] = [normalize(greyscale), normalize(greyscale + factor), normalize(greyscale + 2 * factor)]
    return img

def change_brightness(img: Image.Image, level: float) -> Image.Image:

    def brightness(c: int) -> float:
        return 128 + level + (c - 128)
    if not -255.0 <= level <= 255.0:
        raise ValueError('level must be between -255.0 (black) and 255.0 (white)')
    return img.point(brightness)

