def diophantine(a: int, b: int, c: int) -> tuple[float, float]:
    assert c % greatest_common_divisor(a, b) == 0
    (d, x, y) = extended_gcd(a, b)
    r = c / d
    return (r * x, r * y)

def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
    assert a >= 0
    assert b >= 0
    if b == 0:
        (d, x, y) = (a, 1, 0)
    else:
        (d, p, q) = extended_gcd(b, a % b)
        x = q
        y = p - q * (a // b)
    assert a % d == 0
    assert b % d == 0
    assert d == a * x + b * y
    return (d, x, y)

def all_diophantine_solutions(a: int, b: int, c: int, n: int=2) -> list[tuple[int, int]]:
    if a == 0 and b == 0:
        if c == 0:
            return [(0, 0)][:min(1, n)]
        raise ValueError('No integer solutions exist for a=0, b=0, c!=0')
    (g, xg, yg) = extended_gcd(abs(a), abs(b))
    if c % g != 0:
        msg = f'No integer solutions exist for a={a}, b={b}, c={c}'
        raise ValueError(msg)
    (x0, y0) = (xg * (c // g), yg * (c // g))
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0
    (dx, dy) = (b // g, a // g)
    return [(x0 + t * dx, y0 - t * dy) for t in range(n)]

def verify_proof(leaf: str, proof: list[str], root: str) -> bool:
    computed_hash = sha256(leaf)
    for sibling in proof:
        combined = sha256(computed_hash + sibling)
        computed_hash = combined
    return computed_hash == root

def proof_of_work(block_number: int, transactions: str, previous_hash: str, difficulty: int) -> tuple[int, str]:
    if difficulty < 0:
        raise ValueError('difficulty must be a non-negative integer')
    prefix = '0' * difficulty
    nonce = 0
    while True:
        text = f'{block_number}{transactions}{previous_hash}{nonce}'
        current_hash = hashlib.sha256(text.encode()).hexdigest()
        if current_hash.startswith(prefix):
            return (nonce, current_hash)
        nonce += 1

def chunker(seq: Iterable[str], size: int) -> Generator[tuple[str, ...]]:
    it = iter(seq)
    while True:
        chunk = tuple(itertools.islice(it, size))
        if not chunk:
            return
        yield chunk

def prepare_input(dirty: str) -> str:
    dirty = ''.join([c.upper() for c in dirty if c in string.ascii_letters])
    clean = ''
    if len(dirty) < 2:
        return dirty
    for i in range(len(dirty) - 1):
        clean += dirty[i]
        if dirty[i] == dirty[i + 1]:
            clean += 'X'
    clean += dirty[-1]
    if len(clean) & 1:
        clean += 'X'
    return clean

def generate_table(key: str) -> list[str]:
    alphabet = 'ABCDEFGHIKLMNOPQRSTUVWXYZ'
    table = []
    for char in key.upper():
        if char not in table and char in alphabet:
            table.append(char)
    for char in alphabet:
        if char not in table:
            table.append(char)
    return table

def decode(ciphertext: str, key: str) -> str:
    table = generate_table(key)
    plaintext = ''
    for (char1, char2) in chunker(ciphertext, 2):
        (row1, col1) = divmod(table.index(char1), 5)
        (row2, col2) = divmod(table.index(char2), 5)
        if row1 == row2:
            plaintext += table[row1 * 5 + (col1 - 1) % 5]
            plaintext += table[row2 * 5 + (col2 - 1) % 5]
        elif col1 == col2:
            plaintext += table[(row1 - 1) % 5 * 5 + col1]
            plaintext += table[(row2 - 1) % 5 * 5 + col2]
        else:
            plaintext += table[row1 * 5 + col2]
            plaintext += table[row2 * 5 + col1]
    return plaintext

def decrypt_caesar_with_chi_squared(ciphertext: str, cipher_alphabet: list[str] | None=None, frequencies_dict: dict[str, float] | None=None, case_sensitive: bool=False) -> tuple[int, float, str]:
    alphabet_letters = cipher_alphabet or [chr(i) for i in range(97, 123)]
    if not frequencies_dict:
        frequencies = {'a': 0.08497, 'b': 0.01492, 'c': 0.02202, 'd': 0.04253, 'e': 0.11162, 'f': 0.02228, 'g': 0.02015, 'h': 0.06094, 'i': 0.07546, 'j': 0.00153, 'k': 0.01292, 'l': 0.04025, 'm': 0.02406, 'n': 0.06749, 'o': 0.07507, 'p': 0.01929, 'q': 0.00095, 'r': 0.07587, 's': 0.06327, 't': 0.09356, 'u': 0.02758, 'v': 0.00978, 'w': 0.0256, 'x': 0.0015, 'y': 0.01994, 'z': 0.00077}
    else:
        frequencies = frequencies_dict
    if not case_sensitive:
        ciphertext = ciphertext.lower()
    chi_squared_statistic_values: dict[int, tuple[float, str]] = {}
    for shift in range(len(alphabet_letters)):
        decrypted_with_shift = ''
        for letter in ciphertext:
            try:
                new_key = (alphabet_letters.index(letter.lower()) - shift) % len(alphabet_letters)
                decrypted_with_shift += alphabet_letters[new_key].upper() if case_sensitive and letter.isupper() else alphabet_letters[new_key]
            except ValueError:
                decrypted_with_shift += letter
        chi_squared_statistic = 0.0
        for letter in decrypted_with_shift:
            if case_sensitive:
                letter = letter.lower()
                if letter in frequencies:
                    occurrences = decrypted_with_shift.lower().count(letter)
                    expected = frequencies[letter] * occurrences
                    chi_letter_value = (occurrences - expected) ** 2 / expected
                    chi_squared_statistic += chi_letter_value
            elif letter.lower() in frequencies:
                occurrences = decrypted_with_shift.count(letter)
                expected = frequencies[letter] * occurrences
                chi_letter_value = (occurrences - expected) ** 2 / expected
                chi_squared_statistic += chi_letter_value
        chi_squared_statistic_values[shift] = (chi_squared_statistic, decrypted_with_shift)

    def chi_squared_statistic_values_sorting_key(key: int) -> tuple[float, str]:
        return chi_squared_statistic_values[key]
    most_likely_cipher: int = min(chi_squared_statistic_values, key=chi_squared_statistic_values_sorting_key)
    (most_likely_cipher_chi_squared_value, decoded_most_likely_cipher) = chi_squared_statistic_values[most_likely_cipher]
    return (most_likely_cipher, most_likely_cipher_chi_squared_value, decoded_most_likely_cipher)

def primitive_root(p_val: int) -> int:
    print('Generating primitive root of p')
    while True:
        g = random.randrange(3, p_val)
