def prime_factorization(number: int) -> list[int]:
    assert isinstance(number, int) and number >= 0, "'number' must been an int and >= 0"
    ans = []
    factor = 2
    quotient = number
    if number in {0, 1}:
        ans.append(number)
    elif not is_prime(number):
        while quotient != 1:
            if is_prime(factor) and quotient % factor == 0:
                ans.append(factor)
                quotient //= factor
            else:
                factor += 1
    else:
        ans.append(number)
    assert isinstance(ans, list), "'ans' must been from type list"
    return ans

def kg_v(number1: int, number2: int) -> int:
    assert isinstance(number1, int) and isinstance(number2, int) and (number1 >= 1) and (number2 >= 1), "'number1' and 'number2' must been positive integer."
    ans = 1
    if number1 > 1 and number2 > 1:
        prime_fac_1 = prime_factorization(number1)
        prime_fac_2 = prime_factorization(number2)
    elif number1 == 1 or number2 == 1:
        prime_fac_1 = []
        prime_fac_2 = []
        ans = max(number1, number2)
    count1 = 0
    count2 = 0
    done = []
    for n in prime_fac_1:
        if n not in done:
            if n in prime_fac_2:
                count1 = prime_fac_1.count(n)
                count2 = prime_fac_2.count(n)
                for _ in range(max(count1, count2)):
                    ans *= n
            else:
                count1 = prime_fac_1.count(n)
                for _ in range(count1):
                    ans *= n
            done.append(n)
    for n in prime_fac_2:
        if n not in done:
            count2 = prime_fac_2.count(n)
            for _ in range(count2):
                ans *= n
            done.append(n)
    assert isinstance(ans, int) and ans >= 0, "'ans' must been from type int and positive"
    return ans

def get_primes_between(p_number_1: int, p_number_2: int) -> list[int]:
