def line_coefficients(p1: list[float] | tuple, p2: list[float] | tuple) -> tuple:
    if p1[0] == p2[0]:
        return (1, 0, p1[0])
    else:
        a = (p2[1] - p1[1]) / (p2[0] - p1[0])
        b = -1
        c = p2[1] - a * p2[0]
        return (a, b, c)

def segment_intersection(v1: list[float] | tuple, v2: list[float] | tuple, v1_prime: list[float] | tuple, v2_prime: list[float] | tuple, as_segments: bool=True) -> list[float] | None:
    (a, b, c) = line_coefficients(v1, v2)
    (a_prime, b_prime, c_prime) = line_coefficients(v1_prime, v2_prime)
    d = determinant(a, b, a_prime, b_prime)
    if d == 0:
        return None
    dx = determinant(-c, b, -c_prime, b_prime)
    dy = determinant(a, -c, a_prime, -c_prime)
    (x, y) = (dx / d, dy / d)
    if as_segments:
        if min(v1[0], v2[0]) <= x <= max(v1[0], v2[0]) and min(v1_prime[0], v2_prime[0]) <= x <= max(v1_prime[0], v2_prime[0]) and (min(v1[1], v2[1]) <= y <= max(v1[1], v2[1])) and (min(v1_prime[1], v2_prime[1]) <= y <= max(v1_prime[1], v2_prime[1])):
            return [x, y]
        return None
    else:
        return [x, y]

def extended_euclidean_algorithm(a: int, b: int) -> tuple[int, int]:
    if abs(a) == 1:
        return (a, 0)
    elif abs(b) == 1:
        return (0, b)
    (old_remainder, remainder) = (a, b)
    (old_coeff_a, coeff_a) = (1, 0)
    (old_coeff_b, coeff_b) = (0, 1)
    while remainder != 0:
        quotient = old_remainder // remainder
        (old_remainder, remainder) = (remainder, old_remainder - quotient * remainder)
        (old_coeff_a, coeff_a) = (coeff_a, old_coeff_a - quotient * coeff_a)
        (old_coeff_b, coeff_b) = (coeff_b, old_coeff_b - quotient * coeff_b)
    if a < 0:
        old_coeff_a = -old_coeff_a
    if b < 0:
        old_coeff_b = -old_coeff_b
    return (old_coeff_a, old_coeff_b)

