def bailey_borwein_plouffe(digit_position: int, precision: int=1000) -> str:
    if not isinstance(digit_position, int) or digit_position <= 0:
        raise ValueError('Digit position must be a positive integer')
    if not isinstance(precision, int) or precision < 0:
        raise ValueError('Precision must be a nonnegative integer')
    sum_result = 4 * _subsum(digit_position, 1, precision) - 2 * _subsum(digit_position, 4, precision) - _subsum(digit_position, 5, precision) - _subsum(digit_position, 6, precision)
    return hex(int(sum_result % 1 * 16))[2:]

def _subsum(digit_pos_to_extract: int, denominator_addend: int, precision: int) -> float:
    total = 0.0
    for sum_index in range(digit_pos_to_extract + precision):
        denominator = 8 * sum_index + denominator_addend
        if sum_index < digit_pos_to_extract:
            exponential_term = pow(16, digit_pos_to_extract - 1 - sum_index, denominator)
        else:
            exponential_term = pow(16, digit_pos_to_extract - 1 - sum_index)
        total += exponential_term / denominator
    return total

def prime_factors(n: int) -> list:
    if n <= 0:
        raise ValueError('Only positive integers have prime factors')
    pf = []
    while n % 2 == 0:
        pf.append(2)
        n = int(n / 2)
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            pf.append(i)
            n = int(n / i)
    if n > 2:
        pf.append(n)
    return pf

def number_of_divisors(n: int) -> int:
    if n <= 0:
        raise ValueError('Only positive numbers are accepted')
    div = 1
    temp = 1
    while n % 2 == 0:
        temp += 1
        n = int(n / 2)
    div *= temp
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        temp = 1
        while n % i == 0:
            temp += 1
            n = int(n / i)
        div *= temp
    if n > 1:
        div *= 2
    return div

def sum_of_divisors(n: int) -> int:
    if n <= 0:
        raise ValueError('Only positive numbers are accepted')
    s = 1
    temp = 1
    while n % 2 == 0:
        temp += 1
        n = int(n / 2)
    if temp > 1:
        s *= (2 ** temp - 1) / (2 - 1)
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        temp = 1
        while n % i == 0:
            temp += 1
            n = int(n / i)
        if temp > 1:
            s *= (i ** temp - 1) / (i - 1)
    return int(s)

def euler_phi(n: int) -> int:
    if n <= 0:
        raise ValueError('Only positive numbers are accepted')
    s = n
    for x in set(prime_factors(n)):
        s *= (x - 1) / x
    return int(s)

def lucas_lehmer_test(p: int) -> bool:
    if p < 2:
        raise ValueError('p should not be less than 2!')
    if p == 2:
        return True
    s = 4
    m = (1 << p) - 1
    for _ in range(p - 2):
        s = (s * s - 2) % m
    return s == 0

def factors_of_a_number(num: int) -> list:
