    facs.append(num)
    for i in range(2, int(sqrt(num)) + 1):
        if num % i == 0:
            facs.append(i)
            d = num // i
            if d != i:
                facs.append(d)
    facs.sort()
    return facs

def quadratic_roots(a: int, b: int, c: int) -> tuple[complex, complex]:
    if a == 0:
        raise ValueError("Coefficient 'a' must not be zero.")
    delta = b * b - 4 * a * c
    root_1 = (-b + sqrt(delta)) / (2 * a)
    root_2 = (-b - sqrt(delta)) / (2 * a)
    return (root_1.real if not root_1.imag else root_1, root_2.real if not root_2.imag else root_2)

