def padovan_sequence(n: int) -> int:
    if not isinstance(n, int) or n < 0:
        raise ValueError('Input must be a non-negative integer.')
    if n <= 2:
        return 1
    (p_prev_3, p_prev_2, p_prev_1) = (1, 1, 1)
    for _ in range(3, n + 1):
        curr = p_prev_2 + p_prev_3
        (p_prev_3, p_prev_2, p_prev_1) = (p_prev_2, p_prev_1, curr)
    return p_prev_1

def perfect(number: int) -> bool:
    if not isinstance(number, int):
        raise ValueError('number must be an integer')
    if number <= 0:
        return False
    if number == 1:
        return False
    divisor_sum = sum((i for i in range(1, number // 2 + 1) if number % i == 0))
    return divisor_sum == number

def perfect_optimized(number: int) -> bool:
    if not isinstance(number, int):
        raise ValueError('number must be an integer')
    if number <= 1:
        return False
    divisor_sum = 1
    i = 2
    while i * i <= number:
        if number % i == 0:
            divisor_sum += i
            if i != number // i:
                divisor_sum += number // i
        i += 1
    return divisor_sum == number

def find_perfect_numbers(limit: int) -> list[int]:
