def derangement(objects: int) -> int:
    if objects < 0:
        raise ValueError('k must be a non-negative integer. Retry')
    if objects in (0, 1):
        return 0
    derange_1 = 1
    derange_2 = 0
    answer = 1
    for i in range(3, objects + 1):
        answer = (i - 1) * (derange_1 + derange_2)
        derange_2 = derange_1
        derange_1 = answer
    return answer

def variance(values: list[int], probabilities: list[float]) -> float:
    mean = expectation(values, probabilities)
    return sum(((x - mean) ** 2 * p for (x, p) in zip(values, probabilities)))

def covariance(x_values: list[int], y_values: list[int], x_probabilities: list[float], y_probabilities: list[float]) -> float:
    mean_x = expectation(x_values, x_probabilities)
    mean_y = expectation(y_values, y_probabilities)
    return sum(((x - mean_x) * (y - mean_y) * px * py for (x, px) in zip(x_values, x_probabilities) for (y, py) in zip(y_values, y_probabilities)))

def trailing_zeroes(num: int) -> int:
    ans = 0
    if num < 0:
        return -1
    if num == 0:
        return 1
    while num > 0:
        if num % 10 == 0:
            ans += 1
        else:
            break
        num //= 10
    return ans

def binary_exponentiation(a: int, n: int, mod: int) -> int:
    if n == 0:
        return 1
    elif n % 2 == 1:
        return binary_exponentiation(a, n - 1, mod) * a % mod
    else:
        b = binary_exponentiation(a, n // 2, mod)
        return b * b % mod

def is_int_palindrome(num: int) -> bool:
    if num < 0:
        return False
    num_copy: int = num
    rev_num: int = 0
    while num > 0:
        rev_num = rev_num * 10 + num % 10
        num //= 10
    return num_copy == rev_num

def sieve_of_atkin(limit: int) -> list[int]:
    if limit < 0:
        msg = f'{limit}: Invalid input, please enter a non-negative integer.'
        raise ValueError(msg)
    if limit < 2:
        return []
    sieve = [False] * (limit + 1)
    if limit >= 2:
        sieve[2] = True
    if limit >= 3:
        sieve[3] = True
    sqrt_limit = int(math.sqrt(limit)) + 1
    for x in range(1, sqrt_limit):
        for y in range(1, sqrt_limit):
            n = 4 * x * x + y * y
            if n <= limit and (n % 12 == 1 or n % 12 == 5):
                sieve[n] = not sieve[n]
            n = 3 * x * x + y * y
            if n <= limit and n % 12 == 7:
                sieve[n] = not sieve[n]
            if x > y:
                n = 3 * x * x - y * y
                if n <= limit and n % 12 == 11:
                    sieve[n] = not sieve[n]
    for r in range(5, sqrt_limit):
        if sieve[r]:
            square = r * r
            for i in range(square, limit + 1, square):
                sieve[i] = False
    primes = []
    for i in range(2, limit + 1):
        if sieve[i]:
            primes.append(i)
    return primes

