    total_sum = digit_sum * repetitions
    while total_sum >= 10:
        total_sum = sum((int(digit) for digit in str(total_sum)))
    return total_sum

def calculate_spearman_rank_correlation(variable_1: Sequence[float], variable_2: Sequence[float]) -> float:
    n = len(variable_1)
    if n < 2:
        raise ValueError('Need at least 2 data points to calculate correlation')
    rank_var1 = assign_ranks(variable_1)
    rank_var2 = assign_ranks(variable_2)
    d = [rx - ry for (rx, ry) in zip(rank_var1, rank_var2)]
    d_squared = sum((di ** 2 for di in d))
    rho = 1 - 6 * d_squared / (n * (n ** 2 - 1))
    return round(rho, 1)

def max_sum_in_array(array: list[int], k: int) -> int:
    if len(array) < k or k < 0:
        raise ValueError('Invalid Input')
    max_sum = current_sum = sum(array[:k])
    for i in range(len(array) - k):
        current_sum = current_sum - array[i] + array[i + k]
        max_sum = max(max_sum, current_sum)
    return max_sum

def abs_min(x: list[int]) -> int:
