def abs_max(x: list[int]) -> int:
    if len(x) == 0:
        raise ValueError('abs_max() arg is an empty sequence')
    j = x[0]
    for i in x:
        if abs(i) > abs(j):
            j = i
    return j

def abs_max_sort(x: list[int]) -> int:
    if len(x) == 0:
        raise ValueError('abs_max_sort() arg is an empty sequence')
    return sorted(x, key=abs)[-1]

def differentiate(func, position, order):
    if not callable(func):
        raise ValueError('differentiate() requires a function as input for func')
    if not isinstance(position, (float, int)):
        raise ValueError('differentiate() requires a float as input for position')
    if not isinstance(order, int):
        raise ValueError('differentiate() requires an int as input for order')
    d = Dual(position, 1)
    result = func(d)
    if order == 0:
        return result.real
    return result.duals[order - 1] * factorial(order)

def legendre_symbol(residue: int, prime: int) -> int:
    if prime <= 2 or prime % 2 == 0:
        raise ValueError('prime must be an odd prime')
    symbol = pow(residue % prime, (prime - 1) // 2, prime)
    return -1 if symbol == prime - 1 else symbol

def tonelli_shanks(residue: int, prime: int) -> int:
    if prime <= 2 or prime % 2 == 0:
        raise ValueError('prime must be an odd prime')
    residue %= prime
    if residue == 0:
        return 0
    symbol = legendre_symbol(residue, prime)
    if symbol != 1:
        message = f'{residue} is not a quadratic residue modulo {prime}'
        raise ValueError(message)
    if prime % 4 == 3:
        root = pow(residue, (prime + 1) // 4, prime)
        return min(root, prime - root)
    exponent_q = prime - 1
    power_of_two_s = 0
    while exponent_q % 2 == 0:
        exponent_q //= 2
        power_of_two_s += 1
    non_residue = 2
    while legendre_symbol(non_residue, prime) != -1:
        non_residue += 1
    modular_c = pow(non_residue, exponent_q, prime)
    modular_r = pow(residue, (exponent_q + 1) // 2, prime)
    modular_t = pow(residue, exponent_q, prime)
    remaining_s = power_of_two_s
    while modular_t != 1:
        test_power = modular_t
        least_i = 0
        for candidate_i in range(1, remaining_s):
            test_power = pow(test_power, 2, prime)
            if test_power == 1:
                least_i = candidate_i
                break
        else:
            message = f'{residue} is not a quadratic residue modulo {prime}'
            raise ValueError(message)
        modular_b = pow(modular_c, 1 << remaining_s - least_i - 1, prime)
        modular_r = modular_r * modular_b % prime
        modular_c = pow(modular_b, 2, prime)
        modular_t = modular_t * modular_c % prime
        remaining_s = least_i
    return min(modular_r, prime - modular_r)

def combinations(total: float, choose: int) -> float:
    if not isinstance(choose, int) or choose < 0:
        raise ValueError('choose must be a non-negative integer')
    if choose == 0:
        return 1.0
    numerator = 1.0
    for i in range(choose):
        numerator *= total - i
    denominator = math_factorial(choose)
    return numerator / denominator

def make_dataset() -> tuple[list[int], int]:
    arr = [randint(-1000, 1000) for i in range(10)]
    r = randint(-5000, 5000)
    return (arr, r)

def triplet_sum1(arr: list[int], target: int) -> tuple[int, ...]:
    for triplet in permutations(arr, 3):
        if sum(triplet) == target:
            return tuple(sorted(triplet))
    return (0, 0, 0)

def triplet_sum2(arr: list[int], target: int) -> tuple[int, int, int]:
    arr.sort()
    n = len(arr)
    for i in range(n - 1):
        (left, right) = (i + 1, n - 1)
        while left < right:
            if arr[i] + arr[left] + arr[right] == target:
                return (arr[i], arr[left], arr[right])
            elif arr[i] + arr[left] + arr[right] < target:
                left += 1
            elif arr[i] + arr[left] + arr[right] > target:
                right -= 1
    return (0, 0, 0)

def mobius(n: int) -> int:
    factors = prime_factors(n)
    if is_square_free(factors):
        return -1 if len(factors) % 2 else 1
    return 0

def josephus_recursive(num_people: int, step_size: int) -> int:
    if not isinstance(num_people, int) or not isinstance(step_size, int) or num_people <= 0 or (step_size <= 0):
        raise ValueError('num_people or step_size is not a positive integer.')
    if num_people == 1:
        return 0
    return (josephus_recursive(num_people - 1, step_size) + step_size) % num_people

def maclaurin_sin(theta: float, accuracy: int=30) -> float:
    if not isinstance(theta, (int, float)):
        raise ValueError('maclaurin_sin() requires either an int or float for theta')
    if not isinstance(accuracy, int) or accuracy <= 0:
        raise ValueError('maclaurin_sin() requires a positive int for accuracy')
    theta = float(theta)
    div = theta // (2 * pi)
    theta -= 2 * div * pi
    return sum(((-1) ** r * theta ** (2 * r + 1) / factorial(2 * r + 1) for r in range(accuracy)))

def maclaurin_cos(theta: float, accuracy: int=30) -> float:
    if not isinstance(theta, (int, float)):
        raise ValueError('maclaurin_cos() requires either an int or float for theta')
    if not isinstance(accuracy, int) or accuracy <= 0:
        raise ValueError('maclaurin_cos() requires a positive int for accuracy')
    theta = float(theta)
    div = theta // (2 * pi)
    theta -= 2 * div * pi
    return sum(((-1) ** r * theta ** (2 * r) / factorial(2 * r) for r in range(accuracy)))

def find_median(nums: list[int | float]) -> float:
    (div, mod) = divmod(len(nums), 2)
    if mod:
        return nums[div]
    return (nums[div] + nums[div - 1]) / 2

def recursive_lucas_number(n_th_number: int) -> int:
    if not isinstance(n_th_number, int):
        raise TypeError('recursive_lucas_number accepts only integer arguments.')
    if n_th_number == 0:
        return 2
    if n_th_number == 1:
        return 1
    return recursive_lucas_number(n_th_number - 1) + recursive_lucas_number(n_th_number - 2)

def dynamic_lucas_number(n_th_number: int) -> int:
    if not isinstance(n_th_number, int):
        raise TypeError('dynamic_lucas_number accepts only integer arguments.')
    (a, b) = (2, 1)
    for _ in range(n_th_number):
        (a, b) = (b, a + b)
    return a

