def horner(poly: Sequence[float], x: float) -> float:
    result = 0.0
    for coeff in reversed(poly):
        result = result * x + coeff
    return result

def remove_digit(num: int) -> int:
    if not isinstance(num, int):
        raise TypeError('only integers accepted as input')
    num_str = str(abs(num))
    num_transpositions = [list(num_str) for char in range(len(num_str))]
    for index in range(len(num_str)):
        num_transpositions[index].pop(index)
    return max((int(''.join(list(transposition))) for transposition in num_transpositions))

def allocation_num(number_of_bytes: int, partitions: int) -> list[str]:
    if partitions <= 0:
        raise ValueError('partitions must be a positive number!')
    if partitions > number_of_bytes:
        raise ValueError('partitions can not > number_of_bytes!')
    bytes_per_partition = number_of_bytes // partitions
    allocation_list = []
    for i in range(partitions):
        start_bytes = i * bytes_per_partition + 1
        end_bytes = number_of_bytes if i == partitions - 1 else (i + 1) * bytes_per_partition
        allocation_list.append(f'{start_bytes}-{end_bytes}')
    return allocation_list

def sylvester(number: int) -> int:
    assert isinstance(number, int), f'The input value of [n={number}] is not an integer'
    if number == 1:
        return 2
    elif number < 1:
        msg = f'The input value of [n={number}] has to be > 0'
        raise ValueError(msg)
    else:
        num = sylvester(number - 1)
        lower = num - 1
        upper = num
        return lower * upper + 1

def vol_cube(side_length: float) -> float:
    if side_length < 0:
        raise ValueError('vol_cube() only accepts non-negative values')
    return pow(side_length, 3)

def vol_spherical_cap(height: float, radius: float) -> float:
    if height < 0 or radius < 0:
        raise ValueError('vol_spherical_cap() only accepts non-negative values')
    return 1 / 3 * pi * pow(height, 2) * (3 * radius - height)

def vol_spheres_intersect(radius_1: float, radius_2: float, centers_distance: float) -> float:
    if radius_1 < 0 or radius_2 < 0 or centers_distance < 0:
        raise ValueError('vol_spheres_intersect() only accepts non-negative values')
    if centers_distance == 0:
        return vol_sphere(min(radius_1, radius_2))
    h1 = (radius_1 - radius_2 + centers_distance) * (radius_1 + radius_2 - centers_distance) / (2 * centers_distance)
    h2 = (radius_2 - radius_1 + centers_distance) * (radius_2 + radius_1 - centers_distance) / (2 * centers_distance)
    return vol_spherical_cap(h1, radius_2) + vol_spherical_cap(h2, radius_1)

def vol_spheres_union(radius_1: float, radius_2: float, centers_distance: float) -> float:
    if radius_1 <= 0 or radius_2 <= 0 or centers_distance < 0:
        raise ValueError('vol_spheres_union() only accepts non-negative values, non-zero radius')
    if centers_distance == 0:
        return vol_sphere(max(radius_1, radius_2))
    return vol_sphere(radius_1) + vol_sphere(radius_2) - vol_spheres_intersect(radius_1, radius_2, centers_distance)

def vol_cuboid(width: float, height: float, length: float) -> float:
    if width < 0 or height < 0 or length < 0:
        raise ValueError('vol_cuboid() only accepts non-negative values')
    return float(width * height * length)

def vol_cone(area_of_base: float, height: float) -> float:
    if height < 0 or area_of_base < 0:
        raise ValueError('vol_cone() only accepts non-negative values')
    return area_of_base * height / 3.0

def vol_right_circ_cone(radius: float, height: float) -> float:
    if height < 0 or radius < 0:
        raise ValueError('vol_right_circ_cone() only accepts non-negative values')
    return pi * pow(radius, 2) * height / 3.0

def vol_prism(area_of_base: float, height: float) -> float:
    if height < 0 or area_of_base < 0:
        raise ValueError('vol_prism() only accepts non-negative values')
    return float(area_of_base * height)

def vol_pyramid(area_of_base: float, height: float) -> float:
    if height < 0 or area_of_base < 0:
        raise ValueError('vol_pyramid() only accepts non-negative values')
    return area_of_base * height / 3.0

def vol_sphere(radius: float) -> float:
    if radius < 0:
        raise ValueError('vol_sphere() only accepts non-negative values')
    return 4 / 3 * pi * pow(radius, 3)

def vol_hemisphere(radius: float) -> float:
    if radius < 0:
        raise ValueError('vol_hemisphere() only accepts non-negative values')
    return pow(radius, 3) * pi * 2 / 3

def vol_circular_cylinder(radius: float, height: float) -> float:
    if height < 0 or radius < 0:
        raise ValueError('vol_circular_cylinder() only accepts non-negative values')
    return pow(radius, 2) * height * pi

def vol_hollow_circular_cylinder(inner_radius: float, outer_radius: float, height: float) -> float:
    if inner_radius < 0 or outer_radius < 0 or height < 0:
        raise ValueError('vol_hollow_circular_cylinder() only accepts non-negative values')
    if outer_radius <= inner_radius:
        raise ValueError('outer_radius must be greater than inner_radius')
    return pi * (pow(outer_radius, 2) - pow(inner_radius, 2)) * height

def vol_conical_frustum(height: float, radius_1: float, radius_2: float) -> float:
    if radius_1 < 0 or radius_2 < 0 or height < 0:
        raise ValueError('vol_conical_frustum() only accepts non-negative values')
    return 1 / 3 * pi * height * (pow(radius_1, 2) + pow(radius_2, 2) + radius_1 * radius_2)

def vol_torus(torus_radius: float, tube_radius: float) -> float:
    if torus_radius < 0 or tube_radius < 0:
        raise ValueError('vol_torus() only accepts non-negative values')
    return 2 * pow(pi, 2) * torus_radius * pow(tube_radius, 2)

def vol_octahedron(oct_side: float) -> float:
    if oct_side < 0:
        raise ValueError('vol_octahedron() only accepts non-negative values')
    return oct_side ** 3 * 2 ** 0.5 / 3

def vol_icosahedron(tri_side: float) -> float:
    if tri_side < 0:
        raise ValueError('vol_icosahedron() only accepts non-negative values')
    return tri_side ** 3 * (3 + 5 ** 0.5) * 5 / 12

def shoelace_area(points: Iterable[tuple[float, float]]) -> float:
    pts = list(points)
    n = len(pts)
    if n < 3:
        raise ValueError('At least 3 points are required to form a polygon')
    try:
        coords: Sequence[tuple[float, float]] = [(float(x), float(y)) for (x, y) in pts]
    except Exception as exc:
        raise TypeError('points must be an iterable of (x, y) numeric pairs') from exc
    s = 0.0
    for i in range(n):
        (x1, y1) = coords[i]
        (x2, y2) = coords[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return abs(s) / 2.0

def least_common_multiple_slow(first_num: int, second_num: int) -> int:
    if first_num == 0 or second_num == 0:
        return 0
    max_num = first_num if first_num >= second_num else second_num
    common_mult = max_num
    while common_mult % first_num > 0 or common_mult % second_num > 0:
        common_mult += max_num
    return common_mult

def least_common_multiple_fast(first_num: int, second_num: int) -> int:
    if 0 in {first_num, second_num}:
        return 0
    return first_num // greatest_common_divisor(first_num, second_num) * second_num

def is_keith_number(number: int) -> bool:
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError('number must be an integer')
    if number < 10:
        return False
    digits = [int(digit) for digit in str(number)]
    window = deque(digits)
    current_sum = sum(digits)
    while current_sum < number:
        oldest = window.popleft()
        window.append(current_sum)
        current_sum = 2 * current_sum - oldest
    return current_sum == number

def find_keith_numbers(limit: int) -> list[int]:
    if not isinstance(limit, int) or isinstance(limit, bool):
        raise TypeError('limit must be an integer')
    if limit < 10:
        raise ValueError('limit must be an integer greater than or equal to 10')
    return [num for num in range(10, limit + 1) if is_keith_number(num)]

def prime_factors(n: int) -> list[int]:
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def unique_prime_factors(n: int) -> list[int]:
    i = 2
    factors = []
    while i * i <= n:
        if not n % i:
            while not n % i:
                n //= i
            factors.append(i)
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def two_pointer(nums: list[int], target: int) -> list[int]:
    i = 0
    j = len(nums) - 1
    while i < j:
        if nums[i] + nums[j] == target:
            return [i, j]
        elif nums[i] + nums[j] < target:
            i = i + 1
        else:
            j = j - 1
    return []

def double_factorial_recursive(n: int) -> int:
    if not isinstance(n, int):
        raise ValueError('double_factorial_recursive() only accepts integral values')
    if n < 0:
        raise ValueError('double_factorial_recursive() not defined for negative values')
    return 1 if n <= 1 else n * double_factorial_recursive(n - 2)

def double_factorial_iterative(num: int) -> int:
    if not isinstance(num, int):
        raise ValueError('double_factorial_iterative() only accepts integral values')
    if num < 0:
        raise ValueError('double_factorial_iterative() not defined for negative values')
    value = 1
    for i in range(num, 0, -2):
        value *= i
    return value

def find_min_iterative(nums: list[int | float]) -> int | float:
    if len(nums) == 0:
        raise ValueError('find_min_iterative() arg is an empty sequence')
    min_num = nums[0]
    for num in nums:
        min_num = min(min_num, num)
    return min_num

def find_min_recursive(nums: list[int | float], left: int, right: int) -> int | float:
    if len(nums) == 0:
        raise ValueError('find_min_recursive() arg is an empty sequence')
    if left >= len(nums) or left < -len(nums) or right >= len(nums) or (right < -len(nums)):
        raise IndexError('list index out of range')
    if left == right:
        return nums[left]
    mid = left + right >> 1
    left_min = find_min_recursive(nums, left, mid)
    right_min = find_min_recursive(nums, mid + 1, right)
    return left_min if left_min <= right_min else right_min

def make_points(a, b, h):
    x = a + h
    while x <= b - h:
        yield x
        x += h

def decimal_isolate(number: float, digit_amount: int) -> float:
    if digit_amount > 0:
        return round(number - int(number), digit_amount)
    return number - int(number)

def extended_euclid(a: int, b: int) -> tuple[int, int]:
    if b == 0:
        return (1, 0)
    (x, y) = extended_euclid(b, a % b)
    k = a // b
    return (y, x - k * y)

def invert_modulo(a: int, n: int) -> int:
    (b, _x) = extended_euclid(a, n)
    if b < 0:
        b = (b % n + n) % n
    return b

def binary_exp_recursive(base: float, exponent: int) -> float:
    if exponent < 0:
        raise ValueError('Exponent must be a non-negative integer')
    if exponent == 0:
        return 1
    if exponent % 2 == 1:
        return binary_exp_recursive(base, exponent - 1) * base
    b = binary_exp_recursive(base, exponent // 2)
    return b * b

def binary_exp_iterative(base: float, exponent: int) -> float:
    if exponent < 0:
        raise ValueError('Exponent must be a non-negative integer')
    res: int | float = 1
    while exponent > 0:
        if exponent & 1:
            res *= base
        base *= base
        exponent >>= 1
    return res

def binary_exp_mod_recursive(base: float, exponent: int, modulus: int) -> float:
    if exponent < 0:
        raise ValueError('Exponent must be a non-negative integer')
    if modulus <= 0:
        raise ValueError('Modulus must be a positive integer')
    if exponent == 0:
        return 1
    if exponent % 2 == 1:
        return binary_exp_mod_recursive(base, exponent - 1, modulus) * base % modulus
    r = binary_exp_mod_recursive(base, exponent // 2, modulus)
    return r * r % modulus

def binary_exp_mod_iterative(base: float, exponent: int, modulus: int) -> float:
    if exponent < 0:
        raise ValueError('Exponent must be a non-negative integer')
    if modulus <= 0:
        raise ValueError('Modulus must be a positive integer')
    res: int | float = 1
    while exponent > 0:
        if exponent & 1:
            res = res % modulus * (base % modulus) % modulus
        base *= base
        exponent >>= 1
    return res

def laplace_transform(function_values: np.ndarray, s_value: float, delta_t: float) -> float:
    if delta_t <= 0:
        raise ValueError('delta_t must be a positive value.')
    if function_values.size == 0:
        raise ValueError('function_values array cannot be empty.')
    if s_value < 0:
        error_msg = f's_value must be non-negative for this implementation, got {s_value}.'
        raise ValueError(error_msg)
    time_vector = np.linspace(0, (len(function_values) - 1) * delta_t, len(function_values))
    integrand = function_values * np.exp(-s_value * time_vector)
    result = np.trapezoid(integrand, dx=delta_t)
    return float(result)

def pell_number_iterative(subscript: int) -> int:
    if not isinstance(subscript, int):
        raise ValueError('The input must be an integer.')
    if subscript < 0:
        raise ValueError('The input number must be non-negative.')
    if subscript in (0, 1):
        return subscript
    prev_prev_num = 0
    prev_num = 1
    for _ in range(2, subscript + 1):
        temp = 2 * prev_num + prev_prev_num
        prev_prev_num = prev_num
        prev_num = temp
    return prev_num

def pell_number_recursive(subscript: int) -> int:
    if not isinstance(subscript, int):
        raise ValueError('The input must be an integer.')
    if subscript < 0:
        raise ValueError('The input number must be non-negative.')
    if subscript in (0, 1):
        return subscript
    return 2 * pell_number_recursive(subscript - 1) + pell_number_recursive(subscript - 2)

def pollard_rho(num: int, seed: int=2, step: int=1, attempts: int=3) -> int | None:
    if num < 2:
        raise ValueError('The input value cannot be less than 2')
    if num > 2 and num % 2 == 0:
        return 2

    def rand_fn(value: int, step: int, modulus: int) -> int:
        return (pow(value, 2) + step) % modulus
    for _ in range(attempts):
        tortoise = seed
        hare = seed
        while True:
            tortoise = rand_fn(tortoise, step, num)
            hare = rand_fn(hare, step, num)
            hare = rand_fn(hare, step, num)
            divisor = gcd(hare - tortoise, num)
            if divisor == 1:
                continue
            if divisor == num:
                break
            return divisor
        seed = hare
        step += 1
    return None

def compute_geometric_mean(*args: int) -> float:
    product = 1
    for number in args:
        if not isinstance(number, int) and (not isinstance(number, float)):
            raise TypeError('Not a Number')
        product *= number
    if product < 0 and len(args) % 2 == 0:
        raise ArithmeticError('Cannot Compute Geometric Mean for these numbers.')
    mean = abs(product) ** (1 / len(args))
    if product < 0:
        mean = -mean
    possible_mean = float(round(mean))
    if possible_mean ** len(args) == product:
        mean = possible_mean
    return mean

def three_sum(nums: list[int]) -> list[list[int]]:
    nums.sort()
    ans = []
    for i in range(len(nums) - 2):
        if i == 0 or nums[i] != nums[i - 1]:
            (low, high, c) = (i + 1, len(nums) - 1, 0 - nums[i])
            while low < high:
                if nums[low] + nums[high] == c:
                    ans.append([nums[i], nums[low], nums[high]])
                    while low < high and nums[low] == nums[low + 1]:
                        low += 1
                    while low < high and nums[high] == nums[high - 1]:
                        high -= 1
                    low += 1
                    high -= 1
                elif nums[low] + nums[high] < c:
                    low += 1
                else:
                    high -= 1
    return ans

def autocorrelation(data: list[float], lag: int) -> float:
    if lag >= len(data):
        raise ValueError('Lag must be less than the length of the data.')
    n = len(data)
    mean = sum(data) / n
    variance = sum(((x - mean) ** 2 for x in data)) / n
    if variance == 0:
        raise ValueError('Variance of data is zero, autocorrelation undefined.')
    covariance = sum(((data[i] - mean) * (data[i - lag] - mean) for i in range(lag, n))) / n
    return covariance / variance

def sieve(n: int) -> list[int]:
    if n <= 0 or isinstance(n, float):
        msg = f'Number {n} must instead be a positive integer'
        raise ValueError(msg)
    in_prime = []
    start = 2
    end = int(math.sqrt(n))
    temp = [True] * (end + 1)
    prime = []
    while start <= end:
        if temp[start] is True:
            in_prime.append(start)
            for i in range(start * start, end + 1, start):
                temp[i] = False
        start += 1
    prime += in_prime
    low = end + 1
    high = min(2 * end, n)
    while low <= n:
        temp = [True] * (high - low + 1)
        for each in in_prime:
            t = math.floor(low / each) * each
            if t < low:
                t += each
            for j in range(t, high + 1, each):
                temp[j - low] = False
        for j in range(len(temp)):
            if temp[j] is True:
                prime.append(j + low)
        low = high + 1
        high = min(high + end, n)
    return prime

def estimate_pi(number_of_simulations: int, seed: int | None=None) -> float:
    if number_of_simulations < 1:
        raise ValueError('At least one simulation is necessary to estimate PI.')
    number_in_unit_circle = 0
    ran = random.Random(seed)
    for _ in range(number_of_simulations):
        random_point = Point.random_unit_square(ran)
        if random_point.is_in_unit_circle():
            number_in_unit_circle += 1
    return 4 * number_in_unit_circle / number_of_simulations

def totient(n: int) -> list:
    is_prime = [True for i in range(n + 1)]
    totients = [i - 1 for i in range(n + 1)]
    primes = []
    for i in range(2, n + 1):
        if is_prime[i]:
            primes.append(i)
        for j in range(len(primes)):
            if i * primes[j] >= n:
                break
            is_prime[i * primes[j]] = False
            if i % primes[j] == 0:
                totients[i * primes[j]] = totients[i] * primes[j]
                break
            totients[i * primes[j]] = totients[i] * (primes[j] - 1)
    return totients

def factorial(number: int) -> int:
    if number != int(number):
        raise ValueError('factorial() only accepts integral values')
    if number < 0:
        raise ValueError('factorial() not defined for negative values')
    value = 1
    for i in range(1, number + 1):
        value *= i
    return value

def factorial_recursive(number: int) -> int:
    if not isinstance(number, int):
        raise ValueError('factorial_recursive() only accepts integral values')
    if number < 0:
        raise ValueError('factorial_recursive() not defined for negative values')
    return 1 if number in {0, 1} else number * factorial_recursive(number - 1)

def binomial_distribution(successes: int, trials: int, prob: float) -> float:
    if successes > trials:
        raise ValueError('successes must be lower or equal to trials')
    if trials < 0 or successes < 0:
        raise ValueError('the function is defined for non-negative integers')
    if not isinstance(successes, int) or not isinstance(trials, int):
        raise ValueError('the function is defined for non-negative integers')
    if not 0 < prob < 1:
        raise ValueError('prob has to be in range of 1 - 0')
    probability = prob ** successes * (1 - prob) ** (trials - successes)
    coefficient = float(factorial(trials))
    coefficient /= factorial(successes) * factorial(trials - successes)
    return probability * coefficient

def is_ear(polygon: list[tuple[float, float]], point_idx: int, direction: str) -> bool:
    prev_idx = (point_idx - 1) % len(polygon)
    next_idx = (point_idx + 1) % len(polygon)
    prev_point = polygon[prev_idx]
    point = polygon[point_idx]
    next_point = polygon[next_idx]
    if is_convex(prev_point, point, next_point, direction):
        for j in range(len(polygon)):
            if j not in (prev_idx, point_idx, next_idx) and is_point_inside_triangle(prev_point, point, next_point, polygon[j]):
                return False
        return True
    return False

def is_convex(point: tuple[float, float], prev_p: tuple[float, float], next_p: tuple[float, float], direction: str) -> bool:
    if direction == 'counter-clockwise':
        cross_product = (next_p[0] - point[0]) * (prev_p[1] - point[1]) - (prev_p[0] - point[0]) * (next_p[1] - point[1])
    else:
        cross_product = (prev_p[0] - point[0]) * (next_p[1] - point[1]) - (next_p[0] - point[0]) * (prev_p[1] - point[1])
    return cross_product >= 0

def slow_primes(max_n: int) -> Generator[int]:
    numbers: Generator = (i for i in range(1, max_n + 1))
    for i in (n for n in numbers if n > 1):
        for j in range(2, i):
            if i % j == 0:
                break
        else:
            yield i

def primes(max_n: int) -> Generator[int]:
    numbers: Generator = (i for i in range(1, max_n + 1))
    for i in (n for n in numbers if n > 1):
        bound = int(math.sqrt(i)) + 1
        for j in range(2, bound):
            if i % j == 0:
                break
        else:
            yield i

def fast_primes(max_n: int) -> Generator[int]:
    numbers: Generator = (i for i in range(1, max_n + 1, 2))
    if max_n > 2:
        yield 2
    for i in (n for n in numbers if n > 1):
        bound = int(math.sqrt(i)) + 1
        for j in range(3, bound, 2):
            if i % j == 0:
                break
        else:
            yield i

def check_polygon(nums: list[float]) -> bool:
    if len(nums) < 3:
        raise ValueError('Monogons and Digons are not polygons in the Euclidean space')
    if any((i <= 0 for i in nums)):
        raise ValueError('All values must be greater than 0')
    sorted_nums = sorted(nums)
    return sorted_nums[-1] < sum(sorted_nums[:-1])

def sum_of_harmonic_progression(first_term: float, common_difference: float, number_of_terms: int) -> float:
    arithmetic_progression = [1 / first_term]
    first_term = 1 / first_term
    for _ in range(number_of_terms - 1):
        first_term += common_difference
        arithmetic_progression.append(first_term)
    harmonic_series = [1 / step for step in arithmetic_progression]
    return sum(harmonic_series)

def is_ipv6_address_valid(address: str) -> bool:
    if not address:
        return False
    if address.startswith(':') and (not address.startswith('::')) or (address.endswith(':') and (not address.endswith('::'))):
        return False
    if ':::' in address:
        return False
    double_colon_count = address.count('::')
    if double_colon_count > 1:
        return False
    if double_colon_count == 0:
        parts: list[str] = address.split(':')
        return len(parts) == 8 and all((part != '' for part in parts)) and all((_is_valid_group(part) for part in parts))
    (left, right) = address.split('::', 1)
    left_groups = [g for g in left.split(':') if g != ''] if left else []
    right_groups = [g for g in right.split(':') if g != ''] if right else []
    total_groups = len(left_groups) + len(right_groups)
    return total_groups < 8 and all((_is_valid_group(g) for g in left_groups + right_groups))

def minkowski_distance(point_a: list[float], point_b: list[float], order: int) -> float:
    if order < 1:
        raise ValueError('The order must be greater than or equal to 1.')
    if len(point_a) != len(point_b):
        raise ValueError('Both points must have the same dimension.')
    return sum((abs(a - b) ** order for (a, b) in zip(point_a, point_b))) ** (1 / order)

def integer_square_root(num: int) -> int:
    if not isinstance(num, int) or num < 0:
        raise ValueError('num must be non-negative integer')
    if num < 2:
        return num
    left_bound = 0
    right_bound = num // 2
    while left_bound <= right_bound:
        mid = left_bound + (right_bound - left_bound) // 2
        mid_squared = mid * mid
        if mid_squared == num:
            return mid
        if mid_squared < num:
            left_bound = mid + 1
        else:
            right_bound = mid - 1
    return right_bound

def binomial_coefficient(n: int, r: int) -> int:
    if n < 0 or r < 0:
        raise ValueError('n and r must be non-negative integers')
    if 0 in (n, r):
        return 1
    c = [0 for i in range(r + 1)]
    c[0] = 1
    for i in range(1, n + 1):
        j = min(i, r)
        while j > 0:
            c[j] += c[j - 1]
            j -= 1
    return c[r]

def is_prime(number: int) -> bool:
    if number <= 1:
        return False
    if number <= 3:
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False
    factor = 5
    while factor * factor <= number:
        if number % factor == 0 or number % (factor + 2) == 0:
            return False
        factor += 6
    return True

def next_prime(number: int) -> int:
    if not isinstance(number, int):
        raise ValueError('next_prime() only accepts integral values')
    candidate = number + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

def create_vector(end_point1: Point3d, end_point2: Point3d) -> Vector3d:
    x = end_point2[0] - end_point1[0]
    y = end_point2[1] - end_point1[1]
    z = end_point2[2] - end_point1[2]
    return (x, y, z)

def get_3d_vectors_cross(ab: Vector3d, ac: Vector3d) -> Vector3d:
    x = ab[1] * ac[2] - ab[2] * ac[1]
    y = (ab[0] * ac[2] - ab[2] * ac[0]) * -1
    z = ab[0] * ac[1] - ab[1] * ac[0]
    return (x, y, z)

def are_collinear(a: Point3d, b: Point3d, c: Point3d, accuracy: int=10) -> bool:
    ab = create_vector(a, b)
    ac = create_vector(a, c)
    return is_zero_vector(get_3d_vectors_cross(ab, ac), accuracy)

def digital_root(number: int) -> int:
    number = abs(number)
    while number >= 10:
        number = sum((int(digit) for digit in str(number)))
    return number

def is_prime(number: int) -> bool:
    if not isinstance(number, int) or not number >= 0:
        raise ValueError('is_prime() only accepts positive integers')
    if 1 < number < 4:
        return True
    elif number < 2 or number % 2 == 0 or number % 3 == 0:
        return False
    for i in range(5, int(math.sqrt(number) + 1), 6):
        if number % i == 0 or number % (i + 2) == 0:
            return False
    return True

def exact_prime_factor_count(n: int) -> int:
    count = 0
    if n % 2 == 0:
        count += 1
        while n % 2 == 0:
            n = int(n / 2)
    i = 3
    while i <= int(math.sqrt(n)):
        if n % i == 0:
            count += 1
            while n % i == 0:
                n = int(n / i)
        i = i + 2
    if n > 2:
        count += 1
    return count

def prime_sieve_eratosthenes(num: int) -> list[int]:
    if num <= 0:
        raise ValueError('Input must be a positive integer')
    primes = [True] * (num + 1)
    p = 2
    while p * p <= num:
        if primes[p]:
            for i in range(p * p, num + 1, p):
                primes[i] = False
        p += 1
    return [prime for prime in range(2, num + 1) if primes[prime]]

def dodecahedron_surface_area(edge: float) -> float:
    if edge <= 0 or not isinstance(edge, int):
        raise ValueError('Length must be a positive.')
    return 3 * (25 + 10 * 5 ** (1 / 2)) ** (1 / 2) * edge ** 2

def dodecahedron_volume(edge: float) -> float:
    if edge <= 0 or not isinstance(edge, int):
        raise ValueError('Length must be a positive.')
    return (15 + 7 * 5 ** (1 / 2)) / 4 * edge ** 3

def sum_of_geometric_progression(first_term: int, common_ratio: int, num_of_terms: int) -> float:
    if common_ratio == 1:
        return num_of_terms * first_term
    return first_term / (1 - common_ratio) * (1 - common_ratio ** num_of_terms)

def perfect_square_binary_search(n: int) -> bool:
    left = 0
    right = n
    while left <= right:
        mid = (left + right) // 2
        if mid ** 2 == n:
            return True
        elif mid ** 2 > n:
            right = mid - 1
        else:
            left = mid + 1
    return False

def manhattan_distance(point_a: list, point_b: list) -> float:
    _validate_point(point_a)
    _validate_point(point_b)
    if len(point_a) != len(point_b):
        raise ValueError('Both points must be in the same n-dimensional space')
    return float(sum((abs(a - b) for (a, b) in zip(point_a, point_b))))

def _validate_point(point: list[float]) -> None:
    if point:
        if isinstance(point, list):
            for item in point:
                if not isinstance(item, (int, float)):
                    msg = f'Expected a list of numbers as input, found {type(item).__name__}'
                    raise TypeError(msg)
        else:
            msg = f'Expected a list of numbers as input, found {type(point).__name__}'
            raise TypeError(msg)
    else:
        raise ValueError('Missing an input')

def manhattan_distance_one_liner(point_a: list, point_b: list) -> float:
    _validate_point(point_a)
    _validate_point(point_b)
    if len(point_a) != len(point_b):
        raise ValueError('Both points must be in the same n-dimensional space')
    return float(sum((abs(x - y) for (x, y) in zip(point_a, point_b))))

def is_disarium(num: int) -> bool:
    digits = list(str(num))
    total = 0
    for i in range(len(digits)):
        total += int(digits[i]) ** (i + 1)
    return total == num

def simplify(current_set: list[list]) -> list[list]:
    duplicate_set = current_set.copy()
    for (row_index, row) in enumerate(duplicate_set):
        magnitude = row[0]
        for (column_index, column) in enumerate(row):
            if magnitude == 0:
                current_set[row_index][column_index] = column
                continue
            current_set[row_index][column_index] = column / magnitude
    first_row = current_set[0]
    final_set = [first_row]
    current_set = current_set[1:]
    for row in current_set:
        temp_row = []
        if row[0] == 0:
            final_set.append(row)
            continue
        for column_index in range(len(row)):
            temp_row.append(first_row[column_index] - row[column_index])
        final_set.append(temp_row)
    if len(final_set[0]) != 3:
        current_first_row = final_set[0]
        current_first_column = []
        next_iteration = []
        for row in final_set[1:]:
            current_first_column.append(row[0])
            next_iteration.append(row[1:])
        resultant = simplify(next_iteration)
        for i in range(len(resultant)):
            resultant[i].insert(0, current_first_column[i])
        resultant.insert(0, current_first_row)
        final_set = resultant
    return final_set

def solve_simultaneous(equations: list[list]) -> list:
    if len(equations) == 0:
        raise IndexError('solve_simultaneous() requires n lists of length n+1')
    _length = len(equations) + 1
    if any((len(item) != _length for item in equations)):
        raise IndexError('solve_simultaneous() requires n lists of length n+1')
    for row in equations:
        if any((not isinstance(column, (int, float)) for column in row)):
            raise ValueError('solve_simultaneous() requires lists of integers')
    if len(equations) == 1:
        return [equations[0][-1] / equations[0][0]]
    data_set = equations.copy()
    if any((0 in row for row in data_set)):
        temp_data = data_set.copy()
        full_row = []
        for (row_index, row) in enumerate(temp_data):
            if 0 not in row:
                full_row = data_set.pop(row_index)
                break
        if not full_row:
            raise ValueError('solve_simultaneous() requires at least 1 full equation')
        data_set.insert(0, full_row)
    useable_form = data_set.copy()
    simplified = simplify(useable_form)
    simplified = simplified[::-1]
    solutions: list = []
    for row in simplified:
        current_solution = row[-1]
        if not solutions:
            if row[-2] == 0:
                solutions.append(0)
                continue
            solutions.append(current_solution / row[-2])
            continue
        temp_row = row.copy()[:len(row) - 1]
        while temp_row[0] == 0:
            temp_row.pop(0)
        if len(temp_row) == 0:
            solutions.append(0)
            continue
        temp_row = temp_row[1:]
        temp_row = temp_row[::-1]
        for (column_index, column) in enumerate(temp_row):
            current_solution -= column * solutions[column_index]
        solutions.append(current_solution)
    final = []
    for item in solutions:
        final.append(float(round(item, 5)))
    return final[::-1]

def combinations(n: int, k: int) -> int:
    if n < k or k < 0:
        raise ValueError('Please enter positive integers for n and k where n >= k')
    res = 1
    for i in range(k):
        res *= n - i
        res //= i + 1
    return res

def surface_area_cube(side_length: float) -> float:
    if side_length < 0:
        raise ValueError('surface_area_cube() only accepts non-negative values')
    return 6 * side_length ** 2

def surface_area_cuboid(length: float, breadth: float, height: float) -> float:
    if length < 0 or breadth < 0 or height < 0:
        raise ValueError('surface_area_cuboid() only accepts non-negative values')
    return 2 * (length * breadth + breadth * height + length * height)

def surface_area_sphere(radius: float) -> float:
    if radius < 0:
        raise ValueError('surface_area_sphere() only accepts non-negative values')
    return 4 * pi * radius ** 2

def surface_area_hemisphere(radius: float) -> float:
    if radius < 0:
        raise ValueError('surface_area_hemisphere() only accepts non-negative values')
