def area_triangle(base: float, height: float) -> float:
    if base < 0 or height < 0:
        raise ValueError('area_triangle() only accepts non-negative values')
    return base * height / 2

def area_triangle_three_sides(side1: float, side2: float, side3: float) -> float:
    if side1 < 0 or side2 < 0 or side3 < 0:
        raise ValueError('area_triangle_three_sides() only accepts non-negative values')
    if side1 + side2 < side3 or side1 + side3 < side2 or side2 + side3 < side1:
        raise ValueError('Given three sides do not form a triangle')
    semi_perimeter = (side1 + side2 + side3) / 2
    area = sqrt(semi_perimeter * (semi_perimeter - side1) * (semi_perimeter - side2) * (semi_perimeter - side3))
    return area

def area_parallelogram(base: float, height: float) -> float:
    if base < 0 or height < 0:
        raise ValueError('area_parallelogram() only accepts non-negative values')
    return base * height

def area_trapezium(base1: float, base2: float, height: float) -> float:
    if base1 < 0 or base2 < 0 or height < 0:
        raise ValueError('area_trapezium() only accepts non-negative values')
    return 1 / 2 * (base1 + base2) * height

def area_circle(radius: float) -> float:
    if radius < 0:
        raise ValueError('area_circle() only accepts non-negative values')
    return pi * radius ** 2

def area_ellipse(radius_x: float, radius_y: float) -> float:
    if radius_x < 0 or radius_y < 0:
        raise ValueError('area_ellipse() only accepts non-negative values')
    return pi * radius_x * radius_y

def area_rhombus(diagonal_1: float, diagonal_2: float) -> float:
    if diagonal_1 < 0 or diagonal_2 < 0:
        raise ValueError('area_rhombus() only accepts non-negative values')
    return 1 / 2 * diagonal_1 * diagonal_2

def area_reg_polygon(sides: int, length: float) -> float:
    if not isinstance(sides, int) or sides < 3:
        raise ValueError('area_reg_polygon() only accepts integers greater than or equal to three as number of sides')
    if length < 0:
        raise ValueError('area_reg_polygon() only accepts non-negative values as length of a side')
    return sides * length ** 2 / (4 * tan(pi / sides))

def surface_area_reg_prism(sides: int, edge: float, height: float) -> float:
    if not isinstance(sides, int) or sides < 3:
        raise ValueError('surface_area_reg_prism() only accepts integers greater than or equal to three as number of sides')
    if edge < 0 or height < 0:
        raise ValueError('surface_area_reg_prism() only accepts non-negative values as length of an edge or height')
    return 2 * area_reg_polygon(sides, edge) + sides * edge * height

def get_inputs() -> tuple[str, float, float]:
    func = input('Enter function with variable as x: ')
    lower_limit = float(input('Enter lower limit: '))
    upper_limit = float(input('Enter upper limit: '))
    return (func, lower_limit, upper_limit)

def compute_table(func: Callable, lower_limit: float, upper_limit: float, acc: int) -> tuple[np.ndarray, float]:
    n_points = acc * 6 + 1
    h = (upper_limit - lower_limit) / (n_points - 1)
    x_vals = np.linspace(lower_limit, upper_limit, n_points)
    table = func(x_vals)
    return (table, h)

def apply_weights(table: list[float]) -> list[float]:
    add = []
    for i in range(1, len(table) - 1):
        if i % 2 == 0 and i % 3 != 0:
            add.append(table[i])
        elif i % 2 != 0 and i % 3 != 0:
            add.append(5 * table[i])
        elif i % 6 == 0:
            add.append(2 * table[i])
        elif i % 3 == 0 and i % 2 != 0:
            add.append(6 * table[i])
    return add

def is_ip_v4_address_valid(ip: str) -> bool:
    octets = ip.split('.')
    if len(octets) != 4:
        return False
    for octet in octets:
        if not octet.isdigit():
            return False
        number = int(octet)
        if len(str(number)) != len(octet):
            return False
        if not 0 <= number <= 255:
            return False
    return True

def modular_exponential(base: int, power: int, mod: int):
    if power < 0:
        return -1
    base %= mod
    result = 1
    while power > 0:
        if power & 1:
            result = result * base % mod
        power = power >> 1
        base = base * base % mod
    return result

def juggler_sequence(number: int) -> list[int]:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        msg = f'Input value of [number={number}] must be a positive integer'
        raise ValueError(msg)
    sequence = [number]
    while number != 1:
        if number % 2 == 0:
            number = math.floor(math.sqrt(number))
        else:
            number = math.floor(math.sqrt(number) * math.sqrt(number) * math.sqrt(number))
        sequence.append(number)
    return sequence

def jacobi_symbol(random_a: int, number: int) -> int:
    if random_a in (0, 1):
        return random_a
    random_a %= number
    t = 1
    while random_a != 0:
        while random_a % 2 == 0:
            random_a //= 2
            r = number % 8
            if r in (3, 5):
                t = -t
        (random_a, number) = (number, random_a)
        if random_a % 4 == number % 4 == 3:
            t = -t
        random_a %= number
    return t if number == 1 else 0

def solovay_strassen(number: int, iterations: int) -> bool:
    if number <= 1:
        return False
    if number <= 3:
        return True
    for _ in range(iterations):
        a = random.randint(2, number - 2)
        x = jacobi_symbol(a, number)
        y = pow(a, (number - 1) // 2, number)
        if x == 0 or y != x % number:
            return False
    return True

def cholesky_decomposition(matrix: np.ndarray) -> np.ndarray:
    assert matrix.shape[0] == matrix.shape[1], f'Input matrix is not square, matrix.shape={matrix.shape!r}'
    assert np.allclose(matrix, matrix.T), 'Input matrix must be symmetric'
    n = matrix.shape[0]
    lower_triangle = np.tril(matrix)
    for i in range(n):
        for j in range(i + 1):
            lower_triangle[i, j] -= np.sum(lower_triangle[i, :j] * lower_triangle[j, :j])
            if i == j:
                if lower_triangle[i, i] <= 0:
                    raise ValueError('Matrix A is not positive definite')
                lower_triangle[i, i] = np.sqrt(lower_triangle[i, i])
            else:
                lower_triangle[i, j] /= lower_triangle[j, j]
    return lower_triangle

def solve_cholesky(lower_triangle: np.ndarray, right_hand_side: np.ndarray) -> np.ndarray:
    assert lower_triangle.shape[0] == lower_triangle.shape[1], f'Matrix L is not square, lower_triangle.shape={lower_triangle.shape!r}'
    assert np.allclose(np.tril(lower_triangle), lower_triangle), 'Matrix L is not lower triangular'
    if len(right_hand_side.shape) == 1:
        return solve_cholesky(lower_triangle, right_hand_side.reshape(-1, 1)).ravel()
    n = right_hand_side.shape[0]
    w = right_hand_side.copy()
    for i in range(n):
        for j in range(i):
            w[i] -= lower_triangle[i, j] * w[j]
        w[i] /= lower_triangle[i, i]
    x = w
    for i in reversed(range(n)):
        for j in range(i + 1, n):
            x[i] -= lower_triangle[j, i] * x[j]
        x[i] /= lower_triangle[i, i]
    return x

def softmax(vector: np.ndarray, axis: int | None=-1) -> np.ndarray:
    try:
        vector = np.asarray(vector, dtype=float)
    except (ValueError, TypeError) as exc:
        error_message = f'softmax input must be numeric, got {type(vector).__name__}'
        raise ValueError(error_message) from exc
    if vector.size == 0:
        raise ValueError('softmax input must be non-empty')
    if axis is not None:
        ndim = vector.ndim
        if axis >= ndim or axis < -ndim:
            error_message = f'axis {axis} is out of bounds for array of dimension {ndim}'
            raise AxisError(error_message)
    vector_max = np.max(vector, axis=axis, keepdims=True)
    exponent_vector = np.exp(vector - vector_max)
    sum_of_exponents = np.sum(exponent_vector, axis=axis, keepdims=True)
    softmax_vector = exponent_vector / sum_of_exponents
    return softmax_vector

def fib_iterative_yield(n: int) -> Iterator[int]:
    if n < 0:
        raise ValueError('n is negative')
    (a, b) = (0, 1)
    yield a
    for _ in range(n):
        yield b
        (a, b) = (b, a + b)

def fib_iterative(n: int) -> list[int]:
    if n < 0:
        raise ValueError('n is negative')
    if n == 0:
        return [0]
    fib = [0, 1]
    for _ in range(n - 1):
        fib.append(fib[-1] + fib[-2])
    return fib

def fib_recursive(n: int) -> list[int]:

    def fib_recursive_term(i: int) -> int:
        if i < 0:
            raise ValueError('n is negative')
        if i < 2:
            return i
        return fib_recursive_term(i - 1) + fib_recursive_term(i - 2)
    if n < 0:
        raise ValueError('n is negative')
    return [fib_recursive_term(i) for i in range(n + 1)]

def fib_recursive_cached(n: int) -> list[int]:

    @functools.cache
    def fib_recursive_term(i: int) -> int:
        if i < 0:
            raise ValueError('n is negative')
        if i < 2:
            return i
        return fib_recursive_term(i - 1) + fib_recursive_term(i - 2)
    if n < 0:
        raise ValueError('n is negative')
    return [fib_recursive_term(i) for i in range(n + 1)]

def fib_memoization(n: int) -> list[int]:
    if n < 0:
        raise ValueError('n is negative')
    cache: dict[int, int] = {0: 0, 1: 1, 2: 1}

    def rec_fn_memoized(num: int) -> int:
        if num in cache:
            return cache[num]
        value = rec_fn_memoized(num - 1) + rec_fn_memoized(num - 2)
        cache[num] = value
        return value
    return [rec_fn_memoized(i) for i in range(n + 1)]

def fib_binet(n: int) -> list[int]:
    if n < 0:
        raise ValueError('n is negative')
    if n >= 1475:
        raise ValueError('n is too large')
    sqrt_5 = sqrt(5)
    phi = (1 + sqrt_5) / 2
    return [round(phi ** i / sqrt_5) for i in range(n + 1)]

def matrix_pow_np(m: ndarray, power: int) -> ndarray:
    result = np.array([[1, 0], [0, 1]], dtype=int)
    base = m
    if power < 0:
        raise ValueError('power is negative')
    while power:
        if power % 2 == 1:
            result = np.dot(result, base)
        base = np.dot(base, base)
        power //= 2
    return result

def fib_matrix_np(n: int) -> int:
    if n < 0:
        raise ValueError('n is negative')
    if n == 0:
        return 0
    m = np.array([[1, 1], [1, 0]], dtype=int)
    result = matrix_pow_np(m, n - 1)
    return int(result[0, 0])

def aliquot_sum(input_num: int) -> int:
    if not isinstance(input_num, int):
        raise ValueError('Input must be an integer')
    if input_num <= 0:
        raise ValueError('Input must be positive')
    return sum((divisor for divisor in range(1, input_num // 2 + 1) if input_num % divisor == 0))

def two_sum(nums: list[int], target: int) -> list[int]:
    chk_map: dict[int, int] = {}
    for (index, val) in enumerate(nums):
        compl = target - val
        if compl in chk_map:
            return [chk_map[compl], index]
        chk_map[val] = index
    return []

def sum_of_digits_recursion(n: int) -> int:
    n = abs(n)
    return n if n < 10 else n % 10 + sum_of_digits_recursion(n // 10)

