def is_safe_prime(number: int) -> bool:
    if not isinstance(number, int) or number < 1:
        msg = f'Input value must be a positive integer. Input value: {number}'
        raise TypeError(msg)
    return (number - 1) % 2 == 0 and is_prime(number) and is_prime((number - 1) // 2)

