def is_arithmetic_series(series: list) -> bool:
    if not isinstance(series, list):
        raise ValueError('Input series is not valid, valid series - [2, 4, 6]')
    if len(series) == 0:
        raise ValueError('Input list must be a non empty list')
    if len(series) == 1:
        return True
    common_diff = series[1] - series[0]
    for index in range(len(series) - 1):
        if series[index + 1] - series[index] != common_diff:
            return False
    return True

def arithmetic_mean(series: list) -> float:
    if not isinstance(series, list):
        raise ValueError('Input series is not valid, valid series - [2, 4, 6]')
    if len(series) == 0:
        raise ValueError('Input list must be a non empty list')
    answer = 0
    for val in series:
        answer += val
    return answer / len(series)

def is_geometric_series(series: list) -> bool:
    if not isinstance(series, list):
        raise ValueError('Input series is not valid, valid series - [2, 4, 8]')
    if len(series) == 0:
        raise ValueError('Input list must be a non empty list')
    if len(series) == 1:
        return True
    try:
        common_ratio = series[1] / series[0]
        for index in range(len(series) - 1):
            if series[index + 1] / series[index] != common_ratio:
                return False
    except ZeroDivisionError:
        return False
    return True

def geometric_mean(series: list) -> float:
    if not isinstance(series, list):
        raise ValueError('Input series is not valid, valid series - [2, 4, 8]')
    if len(series) == 0:
        raise ValueError('Input list must be a non empty list')
    answer = 1
    for value in series:
        answer *= value
    return pow(answer, 1 / len(series))

def logarithmic_series(x_value: float, n_terms: int=5, expand: bool=False) -> list:
    n_times_x_minus_1: float = x_value - 1
    n: int = 1
    series: list = []
    for _ in range(n_terms):
        if expand:
            series.append((-1) ** (n + 1) * (n_times_x_minus_1 / n))
            n_times_x_minus_1 *= x_value - 1
        else:
            sign: str = '-' if (-1) ** (n + 1) == -1 else ''
            term: str = sign + '(' + str(x_value - 1) + '^' + str(n) + ')' + '/' + str(n)
            if term.startswith('-(-'):
                term = '(' + term[3:]
            elif term.startswith('(-'):
                term = '-(' + term[2:]
            series.append(term)
        n += 1
    return series

def is_alternate_harmonic_series(series: list) -> bool:
    if not series:
        return False
    for (i, value) in enumerate(series):
        expected = (-1) ** i * (1 / (i + 1))
        if abs(value - expected) > 1e-09:
            return False
    return True

def hexagonal_numbers(length: int) -> list[int]:
    if length <= 0 or not isinstance(length, int):
        raise ValueError('Length must be a positive integer.')
    return [n * (2 * n - 1) for n in range(length)]

def geometric_series(nth_term: float, start_term_a: float, common_ratio_r: float) -> list[float]:
    if not all((nth_term, start_term_a, common_ratio_r)):
        return []
    series: list[float] = []
    power = 1
    multiple = common_ratio_r
    for _ in range(int(nth_term)):
        if not series:
            series.append(start_term_a)
        else:
            power += 1
            series.append(float(start_term_a * multiple))
            multiple = pow(float(common_ratio_r), power)
    return series

def is_alternate_harmonic_series(series: list) -> bool:
    if not isinstance(series, list):
        raise ValueError('Input series is not valid, valid series - [1, 2/3, 2]')
    if len(series) == 0:
        raise ValueError('Input list must be a non empty list')
    if len(series) == 1 and series[0] != 0:
        return True
    receprocal = []
    series_len = len(series)
    for i in range(series_len):
        if series[i] == 0:
            raise ValueError('Input series cannot have 0 as an element')
        receprocal.append(1 / series[i])
    common_diff = abs(receprocal[1]) - abs(receprocal[0])
    for index in range(2, series_len):
        if abs(receprocal[index]) - abs(receprocal[index - 1]) != common_diff or receprocal[index] * receprocal[index - 1] >= 0:
            return False
    return True

def harmonic_series(n_term: str) -> list:
