def p_series(nth_term: float | str, power: float | str) -> list[str]:
    if nth_term == '':
        return ['']
    nth_term = int(nth_term)
    power = int(power)
    series: list[str] = []
    for temp in range(int(nth_term)):
        series.append(f'1 / {pow(temp + 1, int(power))}' if series else '1')
