def is_harmonic_series(series: list) -> bool:
    if not isinstance(series, list):
        raise ValueError('Input series is not valid, valid series - [1, 2/3, 2]')
    if len(series) == 0:
        raise ValueError('Input list must be a non empty list')
    if len(series) == 1 and series[0] != 0:
        return True
    rec_series = []
    series_len = len(series)
    for i in range(series_len):
        if series[i] == 0:
            raise ValueError('Input series cannot have 0 as an element')
        rec_series.append(1 / series[i])
    common_diff = rec_series[1] - rec_series[0]
    for index in range(2, series_len):
        if rec_series[index] - rec_series[index - 1] != common_diff:
            return False
    return True

def harmonic_mean(series: list) -> float:
    if not isinstance(series, list):
        raise ValueError('Input series is not valid, valid series - [2, 4, 6]')
    if len(series) == 0:
        raise ValueError('Input list must be a non empty list')
    answer = 0
    for val in series:
        answer += 1 / val
    return len(series) / answer

def is_happy_number(number: int) -> bool:
    if not isinstance(number, int) or number <= 0:
        msg = f'number={number!r} must be a positive integer'
        raise ValueError(msg)
    seen = set()
    while number != 1 and number not in seen:
        seen.add(number)
        number = sum((int(digit) ** 2 for digit in str(number)))
    return number == 1

def is_abundant_number(number: int) -> bool:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        return False
    divisor_sum = 1
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            divisor_sum += i
            if i != number // i:
                divisor_sum += number // i
    return divisor_sum > number

def jacobsthal_number(n: int) -> int:
    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        msg = f'n must be a non-negative integer, got {n!r}'
        raise ValueError(msg)
    (previous, current) = (0, 1)
    for _ in range(n):
        (previous, current) = (current, current + 2 * previous)
    return previous

def jacobsthal_sequence(length: int) -> list[int]:
    if not isinstance(length, int) or isinstance(length, bool) or length < 0:
        msg = f'length must be a non-negative integer, got {length!r}'
        raise ValueError(msg)
    sequence = []
    (previous, current) = (0, 1)
    for _ in range(length):
        sequence.append(previous)
        (previous, current) = (current, current + 2 * previous)
    return sequence

def is_trimorphic(number: int) -> bool:
    if number < 0:
        raise ValueError('Input must be a non-negative integer')
    if number == 0:
        return True
    cube = number ** 3
    return str(cube).endswith(str(number))

def is_disarium_number(number: int) -> bool:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        return False
    digits = str(number)
    total = sum((int(digit) ** (idx + 1) for (idx, digit) in enumerate(digits)))
    return total == number

def perfect(number: int) -> bool:
    if not isinstance(number, int):
        raise ValueError('number must be an integer')
    if number <= 0:
        return False
    return sum((i for i in range(1, number // 2 + 1) if number % i == 0)) == number

def catalan(number: int) -> int:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        msg = f'Input value of [number={number}] must be > 0'
        raise ValueError(msg)
    current_number = 1
    for i in range(1, number):
        current_number *= 4 * i - 2
        current_number //= i + 1
    return current_number

def factors(number: int) -> list[int]:
    values = [1]
    for i in range(2, int(sqrt(number)) + 1, 1):
        if number % i == 0:
            values.append(i)
            if int(number // i) != i:
                values.append(int(number // i))
    return sorted(values)

def semi_perfect(number: int) -> bool:
    values = factors(number)
    r = len(values)
    subset = [[0 for i in range(number + 1)] for j in range(r + 1)]
    for i in range(r + 1):
        subset[i][0] = True
    for i in range(1, number + 1):
        subset[0][i] = False
    for i in range(1, r + 1):
        for j in range(1, number + 1):
            if j < values[i - 1]:
                subset[i][j] = subset[i - 1][j]
            else:
                subset[i][j] = subset[i - 1][j] or subset[i - 1][j - values[i - 1]]
    return subset[r][number] != 0

def hamming(n_element: int) -> list:
    n_element = int(n_element)
    if n_element < 1:
        my_error = ValueError('n_element should be a positive number')
        raise my_error
    hamming_list = [1]
    (i, j, k) = (0, 0, 0)
    index = 1
    while index < n_element:
        while hamming_list[i] * 2 <= hamming_list[-1]:
            i += 1
        while hamming_list[j] * 3 <= hamming_list[-1]:
            j += 1
        while hamming_list[k] * 5 <= hamming_list[-1]:
            k += 1
        hamming_list.append(min(hamming_list[i] * 2, hamming_list[j] * 3, hamming_list[k] * 5))
        index += 1
    return hamming_list

def triangular_number(position: int) -> int:
    if position < 0:
        raise ValueError('param `position` must be non-negative')
    return position * (position + 1) // 2

def hexagonal(number: int) -> int:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        raise ValueError('Input must be a positive integer')
    return number * (2 * number - 1)

def is_pronic(number: int) -> bool:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 0 or number % 2 == 1:
        return False
    number_sqrt = int(number ** 0.5)
    return number == number_sqrt * (number_sqrt + 1)

def is_kaprekar(number: int) -> bool:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        return False
    if number == 1:
        return True
    square = number ** 2
    digits = len(str(square))
    for split in range(1, digits):
        right = square % 10 ** split
        left = square // 10 ** split
        if right > 0 and left + right == number:
            return True
    return False

def bell_numbers(max_set_length: int) -> list[int]:
    if max_set_length < 0:
        raise ValueError('max_set_length must be non-negative')
    bell = [0] * (max_set_length + 1)
    bell[0] = 1
    for i in range(1, max_set_length + 1):
        for j in range(i):
            bell[i] += _binomial_coefficient(i - 1, j) * bell[j]
    return bell

def _binomial_coefficient(total_elements: int, elements_to_choose: int) -> int:
    if elements_to_choose in {0, total_elements}:
        return 1
    elements_to_choose = min(elements_to_choose, total_elements - elements_to_choose)
    coefficient = 1
    for i in range(elements_to_choose):
        coefficient *= total_elements - i
        coefficient //= i + 1
    return coefficient

def narcissistic_number(n: int) -> bool:
    if not isinstance(n, int) or n < 1:
        return False
    expo = len(str(n))
    return n == sum((int(i) ** expo for i in str(n)))

def is_deficient_number(number: int) -> bool:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        return False
    if number == 1:
        return True
    divisor_sum = 1
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            divisor_sum += i
            if i != number // i:
                divisor_sum += number // i
    return divisor_sum < number

def power(x: int, y: int, mod: int) -> int:
    if y == 0:
        return 1
    temp = power(x, y // 2, mod) % mod
    temp = temp * temp % mod
    if y % 2 == 1:
        temp = temp * x % mod
    return temp

def is_carmichael_number(n: int) -> bool:
    if n <= 0 or not isinstance(n, int):
        msg = f'Number {n} must instead be a positive integer'
        raise ValueError(msg)
    return all((power(b, n - 1, n) == 1 for b in range(2, n) if greatest_common_divisor(b, n) == 1))

def is_evil_number(number: int) -> bool:
    if not isinstance(number, int):
        raise TypeError('Input must be an integer')
    if number < 0:
        raise ValueError('Input must be a non-negative integer')
    count = 0
    temp = number
    while temp > 0:
        if temp % 2 == 1:
            count += 1
        temp = temp // 2
    return count % 2 == 0

def int_to_base(number: int, base: int) -> str:
    if base < 2 or base > 36:
        raise ValueError("'base' must be between 2 and 36 inclusive")
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    result = ''
    if number < 0:
        raise ValueError('number must be a positive integer')
    while number > 0:
        (number, remainder) = divmod(number, base)
        result = digits[remainder] + result
    if result == '':
        result = '0'
    return result

def harshad_numbers_in_base(limit: int, base: int) -> list[str]:
    if base < 2 or base > 36:
        raise ValueError("'base' must be between 2 and 36 inclusive")
    if limit < 0:
        return []
    numbers = [int_to_base(i, base) for i in range(1, limit) if i % int(sum_of_digits(i, base), base) == 0]
    return numbers

def is_harshad_number_in_base(num: int, base: int) -> bool:
    if base < 2 or base > 36:
        raise ValueError("'base' must be between 2 and 36 inclusive")
    if num < 0:
        return False
    n = int_to_base(num, base)
    d = sum_of_digits(num, base)
    return int(n, base) % int(d, base) == 0

def is_automorphic_number(number: int) -> bool:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 0:
        return False
    number_square = number * number
    while number > 0:
        if number % 10 != number_square % 10:
            return False
        number //= 10
        number_square //= 10
    return True

def polygonal_num(num: int, sides: int) -> int:
    if num < 0 or sides < 3:
        raise ValueError('Invalid input: num must be >= 0 and sides must be >= 3.')
    return ((sides - 2) * num ** 2 - (sides - 4) * num) // 2

def secant_method(lower_bound: float, upper_bound: float, repeats: int) -> float:
    x0 = lower_bound
    x1 = upper_bound
    for _ in range(repeats):
        (x0, x1) = (x1, x1 - f(x1) * (x1 - x0) / (f(x1) - f(x0)))
    return x1

def nth_root(radicand: float, index: int, tolerance: float=0.0001) -> float:
    if not isinstance(radicand, (int, float)):
        error_message = f'radicand must be a real number, not a {type(radicand).__name__}'
        raise TypeError(error_message)
    if not isinstance(index, int):
        error_message = f'index must be an integer, not a {type(index).__name__}'
        raise TypeError(error_message)
    if index <= 0:
        error_message = f'index must be a positive integer, {index} <= 0'
        raise ValueError(error_message)
    if not isinstance(tolerance, (int, float)):
        error_message = f'tolerance must be a real number, not {type(tolerance).__name__}'
        raise TypeError(error_message)
    if tolerance <= 0:
        error_message = f'tolerance must be a positive real number, {tolerance} <= 0'
        raise ValueError(error_message)
    if radicand < 0 and index % 2 == 0:
        error_message = 'math domain error, radicand must be nonnegative for even index'
        raise ValueError(error_message)
    if radicand == 0.0:
        return 0.0
    new_approximation = radicand
    old_approximation = new_approximation + tolerance + 0.1
    while tolerance <= abs(old_approximation - new_approximation):
        old_approximation = new_approximation
        first_summand = (index - 1) / index * old_approximation
        second_summand = radicand / (index * pow(old_approximation, index - 1))
        new_approximation = first_summand + second_summand
    return new_approximation

def bisection(a: float, b: float) -> float:
    if equation(a) * equation(b) >= 0:
        raise ValueError('Wrong space!')
    c = a
    while b - a >= 0.01:
        c = (a + b) / 2
        if equation(c) == 0.0:
            break
        if equation(c) * equation(a) < 0:
            b = c
        else:
            a = c
    return c

def gauss_seidel(coefficients: list[list[float]], rhs: list[float], tol: float=1e-10, max_iter: int=1000) -> list[float]:
    n = len(coefficients)
    x = [0.0 for _ in range(n)]
    for _ in range(max_iter):
        x_new = x.copy()
        for i in range(n):
            sum_before = sum((coefficients[i][j] * x_new[j] for j in range(i)))
            sum_after = sum((coefficients[i][j] * x[j] for j in range(i + 1, n)))
            x_new[i] = (rhs[i] - sum_before - sum_after) / coefficients[i][i]
        if all((abs(x_new[i] - x[i]) < tol for i in range(n))):
            return [round(val, 10) for val in x_new]
        x = x_new
    return [round(val, 10) for val in x]

def ucal(u: float, p: int) -> float:
    temp = u
    for i in range(1, p):
        temp = temp * (u - i)
    return temp

