def neville_interpolate(x_points: list, y_points: list, x0: int) -> list:
    n = len(x_points)
    q = [[0] * n for i in range(n)]
    for i in range(n):
        q[i][1] = y_points[i]
    for i in range(2, n):
        for j in range(i, n):
            q[j][i] = ((x0 - x_points[j - i + 1]) * q[j][i - 1] - (x0 - x_points[j]) * q[j - 1][i - 1]) / (x_points[j] - x_points[j - i + 1])
    return [q[n - 1][n - 1], q]

def proper_fractions(denominator: int) -> list[str]:
    if denominator < 0:
        raise ValueError('The Denominator Cannot be less than 0')
    if isinstance(denominator, float):
        raise ValueError('The Denominator must be an integer')
    return [f'{numerator}/{denominator}' for numerator in range(1, denominator) if gcd(numerator, denominator) == 1]

def make_points(a, b, h):
    x = a + h
    while x < b - h:
        yield x
        x = x + h

def f(x):
    y = (x - 0) * (x - 0)
    return y

def newton_raphson(f: RealFunc, x0: float=0, max_iter: int=100, step: float=1e-06, max_error: float=1e-06, log_steps: bool=False) -> tuple[float, float, list[float]]:

    def f_derivative(x: float) -> float:
        return calc_derivative(f, x, step)
    a = x0
    steps = []
    for _ in range(max_iter):
        if log_steps:
            steps.append(a)
        error = abs(f(a))
        if error < max_error:
            return (a, error, steps)
        if f_derivative(a) == 0:
            raise ZeroDivisionError('No converging solution found, zero derivative')
        a -= f(a) / f_derivative(a)
    raise ArithmeticError('No converging solution found, iteration limit reached')

def brent_method(func: Callable[[float], float], left: float, right: float, tol: float=1e-08, max_iter: int=100) -> float:
    fl = func(left)
    fr = func(right)
    if fl * fr >= 0:
        raise ValueError('func(left) and func(right) must have opposite signs')
    if abs(fl) < abs(fr):
        (left, right) = (right, left)
        (fl, fr) = (fr, fl)
    c = left
    fc = fl
    d = right - left
    for iteration in range(max_iter):
        if fr == 0:
            return right
        if fc not in (fl, fr):
            s = left * fr * fc / ((fl - fr) * (fl - fc)) + right * fl * fc / ((fr - fl) * (fr - fc)) + c * fl * fr / ((fc - fl) * (fc - fr))
        else:
            s = right - fr * (right - left) / (fr - fl)
        conditions = [not (3 * left + right) / 4 < s < right if right > left else not right < s < (3 * left + right) / 4, iteration > 1 and abs(s - right) >= abs(right - c) / 2, iteration <= 1 and abs(s - right) >= abs(c - d) / 2, iteration > 1 and abs(right - c) < tol, iteration <= 1 and abs(c - d) < tol]
        if any(conditions):
            s = (left + right) / 2
            d = right - left
        fs = func(s)
        (d, c) = (c, right)
        fc = fr
        if fl * fs < 0:
            right = s
            fr = fs
        else:
            left = s
            fl = fs
        if abs(fl) < abs(fr):
            (left, right) = (right, left)
            (fl, fr) = (fr, fl)
        if abs(right - left) < tol:
            return right
    return right

def get_initial_point(a: float) -> float:
    start = 2.0
    while start <= a:
        start = math.pow(start, 2)
    return start

def square_root_iterative(a: float, max_iter: int=9999, tolerance: float=1e-14) -> float:
    if a < 0:
        raise ValueError('math domain error')
    value = get_initial_point(a)
    for _ in range(max_iter):
        prev_value = value
        value = value - fx(value, a) / fx_derivative(value)
        if abs(prev_value - value) < tolerance:
            return value
    return value

def weierstrass_method(polynomial: Callable[[np.ndarray], np.ndarray], degree: int, roots: np.ndarray | None=None, max_iter: int=100) -> np.ndarray:
    if degree < 1:
        raise ValueError('Degree of the polynomial must be at least 1.')
    if roots is None:
        rng = np.random.default_rng()
        roots = np.array([np.exp(2j * np.pi * i / degree) * (1 + 0.001 * rng.random()) for i in range(degree)], dtype=np.complex128)
    else:
        roots = np.asarray(roots, dtype=np.complex128)
        if roots.shape[0] != degree:
            raise ValueError('Length of initial roots must match the degree of the polynomial.')
    for _ in range(max_iter):
        denominator = np.array([root - roots for root in roots], dtype=np.complex128)
        np.fill_diagonal(denominator, 1.0)
        denominator = np.prod(denominator, axis=1)
        numerator = polynomial(roots).astype(np.complex128)
        delta = numerator / denominator
        delta = np.clip(delta, -10000000000.0, 10000000000.0)
        roots -= delta
    return roots

def intersection(function: Callable[[float], float], x0: float, x1: float) -> float:
    x_n: float = x0
    x_n1: float = x1
    while True:
        if x_n == x_n1 or function(x_n1) == function(x_n):
            raise ZeroDivisionError('float division by zero, could not find root')
        x_n2: float = x_n1 - function(x_n1) / ((function(x_n1) - function(x_n)) / (x_n1 - x_n))
        if abs(x_n2 - x_n1) < 10 ** (-5):
            return x_n2
        x_n = x_n1
        x_n1 = x_n2

def bisection(function: Callable[[float], float], a: float, b: float) -> float:
    start: float = a
    end: float = b
    if function(a) == 0:
        return a
    elif function(b) == 0:
        return b
    elif function(a) * function(b) > 0:
        raise ValueError('could not find root in given interval.')
    else:
        mid: float = start + (end - start) / 2.0
        while abs(start - mid) > 10 ** (-7):
            if function(mid) == 0:
                return mid
            elif function(mid) * function(start) < 0:
                end = mid
            else:
                start = mid
            mid = start + (end - start) / 2.0
        return mid

def minimum_waiting_time(queries: list[int]) -> int:
    n = len(queries)
    if n in (0, 1):
        return 0
    return sum((query * (n - i - 1) for (i, query) in enumerate(sorted(queries))))

def sliding_window(input_string: str) -> int:
    if not isinstance(input_string, str):
        raise TypeError('Input must be a string')
    if len(input_string) == 0:
        return 0
    char_index_map: dict[str, int] = {}
    left: int = 0
    max_len: int = 0
    for (right, char) in enumerate(input_string):
        if char in char_index_map and char_index_map[char] >= left:
            left = char_index_map[char] + 1
        char_index_map[char] = right
        current_len = right - left + 1
        max_len = max(max_len, current_len)
    return max_len

def find_minimum_change(denominations: list[int], value: str) -> list[int]:
    total_value = int(value)
    answer = []
    for denomination in reversed(denominations):
        while int(total_value) >= int(denomination):
            total_value -= int(denomination)
            answer.append(denomination)
    return answer

def max_profit(prices: list[int]) -> int:
    if not prices:
        return 0
    min_price = prices[0]
    max_profit: int = 0
    for price in prices:
        min_price = min(price, min_price)
        max_profit = max(price - min_price, max_profit)
    return max_profit

def fractional_cover(items: list[Item], capacity: int) -> float:
    if capacity < 0:
        raise ValueError('Capacity cannot be negative')
    total_value = 0.0
    remaining_capacity = capacity
    for item in sorted(items, key=attrgetter('ratio'), reverse=True):
        if remaining_capacity == 0:
            break
        weight_taken = min(item.weight, remaining_capacity)
        total_value += weight_taken * item.ratio
        remaining_capacity -= weight_taken
    return total_value

def frac_knapsack(vl, wt, w, n):
    r = sorted(zip(vl, wt), key=lambda x: x[0] / x[1], reverse=True)
    (vl, wt) = ([i[0] for i in r], [i[1] for i in r])
    acc = list(accumulate(wt))
    k = bisect(acc, w)
    return 0 if k == 0 else sum(vl[:k]) + (w - acc[k - 1]) * vl[k] / wt[k] if k != n else sum(vl[:k])

def fractional_knapsack(value: list[int], weight: list[int], capacity: int) -> tuple[float, list[float]]:
    index = list(range(len(value)))
    ratio = [v / w for (v, w) in zip(value, weight)]
    index.sort(key=lambda i: ratio[i], reverse=True)
    max_value: float = 0
    fractions: list[float] = [0] * len(value)
    for i in index:
        if weight[i] <= capacity:
            fractions[i] = 1
            max_value += value[i]
            capacity -= weight[i]
        else:
            fractions[i] = capacity / weight[i]
            max_value += value[i] * capacity / weight[i]
            break
    return (max_value, fractions)

def activity_selection(activities: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not activities:
        return []
    sorted_activities = sorted(activities, key=lambda activity: activity[1])
    selected_activities = [sorted_activities[0]]
    for i in range(1, len(sorted_activities)):
        if sorted_activities[i][0] >= selected_activities[-1][1]:
            selected_activities.append(sorted_activities[i])
    return selected_activities

def can_complete_journey(gas_stations: tuple[GasStation, ...]) -> int:
    total_gas = sum((gas_station.gas_quantity for gas_station in gas_stations))
    total_cost = sum((gas_station.cost for gas_station in gas_stations))
    if total_gas < total_cost:
        return -1
    start = 0
    net = 0
    for (i, gas_station) in enumerate(gas_stations):
        net += gas_station.gas_quantity - gas_station.cost
        if net < 0:
            start = i + 1
            net = 0
    return start

def triangular_membership(grid: NDArray[np.float64], left: float, peak: float, right: float) -> NDArray[np.float64]:
    if not left <= peak <= right:
        msg = f'Expected left <= peak <= right, got {left}, {peak}, {right}'
        raise ValueError(msg)
    left_slope = (grid - left) / (peak - left) if peak > left else np.where(grid < peak, 0, 1)
    right_slope = (right - grid) / (right - peak) if right > peak else np.where(grid > peak, 0, 1)
    return np.clip(np.minimum(left_slope, right_slope), 0.0, 1.0)

def pass_and_relaxation(graph: dict, v: str, visited_forward: set, visited_backward: set, cst_fwd: dict, cst_bwd: dict, queue: PriorityQueue, parent: dict, shortest_distance: float) -> float:
    for (nxt, d) in graph[v]:
        if nxt in visited_forward:
            continue
        old_cost_f = cst_fwd.get(nxt, np.inf)
        new_cost_f = cst_fwd[v] + d
        if new_cost_f < old_cost_f:
            queue.put((new_cost_f, nxt))
            cst_fwd[nxt] = new_cost_f
            parent[nxt] = v
        if nxt in visited_backward and cst_fwd[v] + d + cst_bwd[nxt] < shortest_distance:
            shortest_distance = cst_fwd[v] + d + cst_bwd[nxt]
    return shortest_distance

def bidirectional_dij(source: str, destination: str, graph_forward: dict, graph_backward: dict) -> int:
    shortest_path_distance = -1
    visited_forward = set()
    visited_backward = set()
    cst_fwd = {source: 0}
    cst_bwd = {destination: 0}
    parent_forward = {source: None}
    parent_backward = {destination: None}
    queue_forward: PriorityQueue[Any] = PriorityQueue()
    queue_backward: PriorityQueue[Any] = PriorityQueue()
    shortest_distance = np.inf
    queue_forward.put((0, source))
    queue_backward.put((0, destination))
    if source == destination:
        return 0
    while not queue_forward.empty() and (not queue_backward.empty()):
        (_, v_fwd) = queue_forward.get()
        visited_forward.add(v_fwd)
        (_, v_bwd) = queue_backward.get()
        visited_backward.add(v_bwd)
        shortest_distance = pass_and_relaxation(graph_forward, v_fwd, visited_forward, visited_backward, cst_fwd, cst_bwd, queue_forward, parent_forward, shortest_distance)
        shortest_distance = pass_and_relaxation(graph_backward, v_bwd, visited_backward, visited_forward, cst_bwd, cst_fwd, queue_backward, parent_backward, shortest_distance)
        if cst_fwd[v_fwd] + cst_bwd[v_bwd] >= shortest_distance:
            break
    if shortest_distance != np.inf:
        shortest_path_distance = shortest_distance
    return shortest_path_distance

def page_rank(nodes, max_iter=100, d=0.85, tol=1e-08):
    n = len(nodes)
    ranks = {node.name: 1.0 / n for node in nodes}
    outbounds = {}
    for node in nodes:
        outbounds[node.name] = len(node.outbound)
    for _ in range(max_iter):
        dangling_sum = sum((ranks[node.name] for node in nodes if outbounds[node.name] == 0))
        new_ranks = {}
        for node in nodes:
            new_ranks[node.name] = (1 - d) / n + d * (sum((ranks[ib] / outbounds[ib] for ib in node.inbound)) + dangling_sum / n)
        if sum((abs(new_ranks[k] - ranks[k]) for k in ranks)) < tol:
            ranks = new_ranks
            break
        ranks = new_ranks
    return ranks

