def bfs_shortest_path(graph: dict, start, goal) -> list[str]:
    explored = set()
    queue = deque([[start]])
    if start == goal:
        return [start]
    while queue:
        path = queue.popleft()
        node = path[-1]
        if node not in explored:
            neighbours = graph[node]
            for neighbour in neighbours:
                new_path = list(path)
                new_path.append(neighbour)
                queue.append(new_path)
                if neighbour == goal:
                    return new_path
            explored.add(node)
    return []

def bfs_shortest_path_distance(graph: dict, start, target) -> int:
    if not graph or start not in graph or target not in graph:
        return -1
    if start == target:
        return 0
    queue = deque([start])
    visited = set(start)
    dist = {start: 0, target: -1}
    while queue:
        node = queue.popleft()
        if node == target:
            dist[target] = dist[node] if dist[target] == -1 else min(dist[target], dist[node])
        for adjacent in graph[node]:
            if adjacent not in visited:
                visited.add(adjacent)
                queue.append(adjacent)
                dist[adjacent] = dist[node] + 1
    return dist[target]

def _collect_nodes_and_edges(graph: adjacency) -> tuple[list[Node], list[edge]]:
    nodes = set()
    edges: list[edge] = []
    for (u, neighbors) in graph.items():
        nodes.add(u)
        for (v, w) in neighbors:
            nodes.add(v)
            edges.append((u, v, w))
    return (list(nodes), edges)

def _bellman_ford(nodes: list[Node], edges: list[edge]) -> dict[Node, float]:
    dist: dict[Node, float] = dict.fromkeys(nodes, 0.0)
    n = len(nodes)
    for _ in range(n - 1):
        updated = False
        for (u, v, w) in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break
    else:
        for (u, v, w) in edges:
            if dist[u] + w < dist[v]:
                raise ValueError('Negative weight cycle detected')
    return dist

def _dijkstra(start: Node, nodes: list[Node], graph: adjacency, potentials: dict[Node, float]) -> dict[Node, float]:
    inf = float('inf')
    dist: dict[Node, float] = dict.fromkeys(nodes, inf)
    dist[start] = 0.0
    heap: list[tuple[float, Node]] = [(0.0, start)]
    while heap:
        (d_u, u) = heapq.heappop(heap)
        if d_u > dist[u]:
            continue
        for (v, w) in graph.get(u, []):
            w_prime = w + potentials[u] - potentials[v]
            if w_prime < 0:
                raise ValueError('Negative edge weight after reweighting: numeric error')
            new_dist = d_u + w_prime
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))
    return dist

def johnson(graph: adjacency) -> dict[Node, dict[Node, float]]:
    (nodes, edges) = _collect_nodes_and_edges(graph)
    potentials = _bellman_ford(nodes, edges)
    all_pairs: dict[Node, dict[Node, float]] = {}
    inf = float('inf')
    for s in nodes:
        dist_reweighted = _dijkstra(s, nodes, graph, potentials)
        dists_orig: dict[Node, float] = {}
        for v in nodes:
            d_prime = dist_reweighted[v]
            if d_prime < inf:
                dists_orig[v] = d_prime - potentials[s] + potentials[v]
            else:
                dists_orig[v] = inf
        all_pairs[s] = dists_orig
    return all_pairs

def topology_sort(graph: dict[int, list[int]], vert: int, visited: list[bool]) -> list[int]:
    visited[vert] = True
    order = []
    for neighbour in graph[vert]:
        if not visited[neighbour]:
            order += topology_sort(graph, neighbour, visited)
    order.append(vert)
    return order

def find_components(reversed_graph: dict[int, list[int]], vert: int, visited: list[bool]) -> list[int]:
    visited[vert] = True
    component = [vert]
    for neighbour in reversed_graph[vert]:
        if not visited[neighbour]:
            component += find_components(reversed_graph, neighbour, visited)
    return component

def strongly_connected_components(graph: dict[int, list[int]]) -> list[list[int]]:
    visited = len(graph) * [False]
    reversed_graph: dict[int, list[int]] = {vert: [] for vert in range(len(graph))}
    for (vert, neighbours) in graph.items():
        for neighbour in neighbours:
            reversed_graph[neighbour].append(vert)
    order = []
    for (i, was_visited) in enumerate(visited):
        if not was_visited:
            order += topology_sort(graph, i, visited)
    components_list = []
    visited = len(graph) * [False]
    for i in range(len(graph)):
        vert = order[len(graph) - i - 1]
        if not visited[vert]:
            component = find_components(reversed_graph, vert, visited)
            components_list.append(component)
    return components_list

def dijkstra(grid: np.ndarray, source: tuple[int, int], destination: tuple[int, int], allow_diagonal: bool) -> tuple[float | int, list[tuple[int, int]]]:
    (rows, cols) = grid.shape
    dx = [-1, 1, 0, 0]
    dy = [0, 0, -1, 1]
    if allow_diagonal:
        dx += [-1, -1, 1, 1]
        dy += [-1, 1, -1, 1]
    (queue, visited) = ([(0, source)], set())
    matrix = np.full((rows, cols), np.inf)
    matrix[source] = 0
    predecessors = np.empty((rows, cols), dtype=object)
    predecessors[source] = None
    while queue:
        (dist, (x, y)) = heappop(queue)
        if (x, y) in visited:
            continue
        visited.add((x, y))
        if (x, y) == destination:
            path = []
            while (x, y) != source:
                path.append((x, y))
                (x, y) = predecessors[x, y]
            path.append(source)
            path.reverse()
            return (float(matrix[destination]), path)
        for i in range(len(dx)):
            (nx, ny) = (x + dx[i], y + dy[i])
            if 0 <= nx < rows and 0 <= ny < cols:
                next_node = grid[nx][ny]
                if next_node == 1 and matrix[nx, ny] > dist + 1:
                    heappush(queue, (dist + 1, (nx, ny)))
                    matrix[nx, ny] = dist + 1
                    predecessors[nx, ny] = (x, y)
    return (np.inf, [])

def dijkstra(graph: dict[str, list[tuple[str, int]]], start: str, end: str) -> int:
    heap: list[tuple[int, str]] = [(0, start)]
    visited: set[str] = set()
    costs: dict[str, int] = {start: 0}
    while heap:
        (cost, u) = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        if u == end:
            return cost
        for (v, c) in graph[u]:
            if v in visited:
                continue
            next_cost = cost + c
            if next_cost < costs.get(v, float('inf')):
                costs[v] = next_cost
                heapq.heappush(heap, (next_cost, v))
    return -1

def initialize_distance_matrix(graph: dict[int, list[tuple[int, float]]], number_of_nodes: int) -> np.ndarray:
    distance_matrix: np.ndarray = np.full((number_of_nodes, number_of_nodes), np.inf)
    np.fill_diagonal(distance_matrix, 0)
    for (node_index, edges) in graph.items():
        for (neighbor_index, edge_weight) in edges:
            if edge_weight <= 0:
                error_message: str = f'Edge weight must be positive. Found {edge_weight} between nodes {node_index} and {neighbor_index}.'
                raise ValueError(error_message)
            distance_matrix[node_index, neighbor_index] = edge_weight
    return distance_matrix

def floyd_warshall_algorithm(graph: dict[int, list[tuple[int, float]]]) -> np.ndarray:
    number_of_nodes: int = len(graph)
    distance_matrix: np.ndarray = initialize_distance_matrix(graph, number_of_nodes)
    for k in range(number_of_nodes):
        distance_matrix[:] = np.minimum(distance_matrix, distance_matrix[:, k][:, np.newaxis] + distance_matrix[k, :])
    return distance_matrix

def find_peripheral_and_far_node(distance_matrix: np.ndarray) -> tuple[tuple[int, float], tuple[int, float]]:
    num_nodes: int = len(distance_matrix)
    if num_nodes == 1:
        return ((0, 0.0), (0, 0.0))
    eccentricities: list[tuple[int, float]] = []
    farnesses: list[tuple[int, float]] = []
    all_disconnected = True
    for i in range(num_nodes):
        reachable_distances = get_reachable_distances(distance_matrix[i])
        if reachable_distances.size == 0:
            eccentricity = float('inf')
            farness = float('inf')
        else:
            all_disconnected = False
            eccentricity = float(np.max(reachable_distances))
            farness = float(np.sum(reachable_distances))
        eccentricities.append((i, eccentricity))
        farnesses.append((i, farness))
    if all_disconnected:
        return ((-1, float('inf')), (-1, float('inf')))
    peripheral_node = find_peripheral_node(eccentricities)
    far_node = find_far_node(farnesses)
    return (peripheral_node, far_node)

def greedy_min_vertex_cover(graph: dict) -> set[int]:
    queue: list[list] = []
    for (key, value) in graph.items():
        heapq.heappush(queue, [-1 * len(value), (key, value)])
    chosen_vertices = set()
    while queue and queue[0][0] != 0:
        argmax = heapq.heappop(queue)[1][0]
        chosen_vertices.add(argmax)
        for elem in queue:
            if elem[0] == 0:
                continue
            if argmax in elem[1][1]:
                index = elem[1][1].index(argmax)
                del elem[1][1][index]
                elem[0] += 1
        heapq.heapify(queue)
    return chosen_vertices

def matching_min_vertex_cover(graph: dict) -> set:
    chosen_vertices = set()
    edges = get_edges(graph)
    while edges:
        (from_node, to_node) = edges.pop()
        chosen_vertices.add(from_node)
        chosen_vertices.add(to_node)
        for edge in edges.copy():
            if from_node in edge or to_node in edge:
                edges.discard(edge)
    return chosen_vertices

def get_edges(graph: dict) -> set:
    edges = set()
    for (from_node, to_nodes) in graph.items():
        for to_node in to_nodes:
            edges.add((from_node, to_node))
    return edges

def check_cycle(graph: dict) -> bool:
    visited: set[int] = set()
    rec_stk: set[int] = set()
    return any((node not in visited and depth_first_search(graph, node, visited, rec_stk) for node in graph))

def depth_first_search(graph: dict, vertex: int, visited: set, rec_stk: set) -> bool:
    visited.add(vertex)
    rec_stk.add(vertex)
    for node in graph[vertex]:
        if node not in visited:
            if depth_first_search(graph, node, visited, rec_stk):
                return True
        elif node in rec_stk:
            return True
    rec_stk.remove(vertex)
    return False

def validate_adjacency_list(graph: list[list[int | None]]) -> None:
    if not isinstance(graph, list):
        raise ValueError('Graph should be a list of lists.')
    for (node_index, neighbors) in enumerate(graph):
        if not isinstance(neighbors, list):
            no_neighbors_message: str = f'Node {node_index} should have a list of neighbors.'
            raise ValueError(no_neighbors_message)
        for neighbor_index in neighbors:
            if not isinstance(neighbor_index, int) or neighbor_index < 0 or neighbor_index >= len(graph):
                invalid_neighbor_message: str = f'Invalid neighbor {neighbor_index} in node {node_index} adjacency list.'
                raise ValueError(invalid_neighbor_message)

def multiply_matrix_vector(graph: list[list[int | None]], vector: np.ndarray) -> np.ndarray:
    num_nodes: int = len(graph)
    if vector.shape[0] != num_nodes:
        raise ValueError('Vector length must match the number of nodes in the graph.')
    result: np.ndarray = np.zeros(num_nodes)
    for (node_index, neighbors) in enumerate(graph):
        for neighbor_index in neighbors:
            result[node_index] += vector[neighbor_index]
    return result

def find_lanczos_eigenvectors(graph: list[list[int | None]], num_eigenvectors: int) -> tuple[np.ndarray, np.ndarray]:
    validate_adjacency_list(graph)
    (tridiagonal_matrix, orthonormal_basis) = lanczos_iteration(graph, num_eigenvectors)
    (eigenvalues, eigenvectors) = np.linalg.eigh(tridiagonal_matrix)
    return (eigenvalues[::-1], np.dot(orthonormal_basis, eigenvectors[:, ::-1]))

