        visited[node] += 1
    return visited

def prim(graph: list, root: Vertex) -> list:
    a = []
    for u in graph:
        u.key = math.inf
        u.pi = None
    root.key = 0
    q = graph[:]
    while q:
        u = min(q)
        q.remove(u)
        for v in u.neighbors:
            if v in q and u.edges[v.id] < v.key:
                v.pi = u
                v.key = u.edges[v.id]
    for i in range(1, len(graph)):
        a.append((int(graph[i].id) + 1, int(graph[i].pi.id) + 1))
    return a

def prim_heap(graph: list, root: Vertex) -> Iterator[tuple]:
    for u in graph:
        u.key = math.inf
        u.pi = None
    root.key = 0
    h = list(graph)
    hq.heapify(h)
    while h:
        u = hq.heappop(h)
        for v in u.neighbors:
            if v in h and u.edges[v.id] < v.key:
                v.pi = u
                v.key = u.edges[v.id]
                hq.heapify(h)
    for i in range(1, len(graph)):
        yield (int(graph[i].id) + 1, int(graph[i].pi.id) + 1)

def compute_bridges(graph: dict[int, list[int]]) -> list[tuple[int, int]]:
    id_ = 0
    n = len(graph)
    low = [0] * n
    visited = [False] * n

    def dfs(at, parent, bridges, id_) -> None:
        visited[at] = True
        low[at] = id_
        id_ += 1
        for to in graph[at]:
            if to == parent:
                pass
            elif not visited[to]:
                dfs(to, at, bridges, id_)
                low[at] = min(low[at], low[to])
                if id_ <= low[to]:
                    bridges.append((at, to) if at < to else (to, at))
            else:
                low[at] = min(low[at], low[to])
    bridges: list[tuple[int, int]] = []
    for i in range(n):
        if not visited[i]:
            dfs(i, -1, bridges, id_)
    return bridges

