def is_bipartite_bfs(graph: dict[int, list[int]]) -> bool:
    visited: defaultdict[int, int] = defaultdict(lambda : -1)
    for node in graph:
        if visited[node] == -1:
            queue: deque[int] = deque()
            queue.append(node)
            visited[node] = 0
            while queue:
                curr_node = queue.popleft()
                if curr_node not in graph:
                    continue
                for neighbor in graph[curr_node]:
                    if visited[neighbor] == -1:
                        visited[neighbor] = 1 - visited[curr_node]
                        queue.append(neighbor)
                    elif visited[neighbor] == visited[curr_node]:
                        return False
    return True

def topological_sort(graph: dict[int, list[int]]) -> list[int] | None:
    indegree = dict.fromkeys(graph, 0)
    queue: deque[int] = deque()
    topo_order = []
    processed_vertices_count = 0
    for values in graph.values():
        for i in values:
            indegree[i] += 1
    for (vertex, count) in indegree.items():
        if count == 0:
            queue.append(vertex)
    while queue:
        vertex = queue.popleft()
        processed_vertices_count += 1
        topo_order.append(vertex)
        for neighbor in graph[vertex]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)
    if processed_vertices_count != len(graph):
        return None
    return topo_order

def euclidean_distance(point1: list[float], point2: list[float]) -> float:
    try:
        return math.sqrt((point2[0] - point1[0]) ** 2 + (point2[1] - point1[1]) ** 2)
    except TypeError:
        raise ValueError('Invalid input: Points must be numerical coordinates')

def validate_graph(graph_points: dict[str, list[float]]) -> None:
    if not isinstance(graph_points, dict):
        raise InvalidGraphError('Graph must be a dictionary with node names and coordinates')
    for (node, coordinates) in graph_points.items():
        if not isinstance(node, str) or not isinstance(coordinates, list) or len(coordinates) != 2 or (not all((isinstance(c, (int, float)) for c in coordinates))):
            raise InvalidGraphError('Each node must have a valid 2D coordinate [x, y]')

def travelling_salesman_brute_force(graph_points: dict[str, list[float]]) -> tuple[list[str], float]:
    validate_graph(graph_points)
    nodes = list(graph_points.keys())
    if len(nodes) < 2:
        raise InvalidGraphError('Graph must have at least two nodes')
    min_path = []
    min_distance = float('inf')
    start_node = nodes[0]
    other_nodes = nodes[1:]
    for perm in itertools.permutations(other_nodes):
        path = [start_node, *perm, start_node]
        total_distance = sum((euclidean_distance(graph_points[path[i]], graph_points[path[i + 1]]) for i in range(len(path) - 1)))
        if total_distance < min_distance:
            min_distance = total_distance
            min_path = path
    return (min_path, min_distance)

def travelling_salesman_dynamic_programming(graph_points: dict[str, list[float]]) -> tuple[list[str], float]:
    validate_graph(graph_points)
    n = len(graph_points)
    if n < 2:
        raise InvalidGraphError('Graph must have at least two nodes')
    nodes = list(graph_points.keys())
    dist = [[euclidean_distance(graph_points[nodes[i]], graph_points[nodes[j]]) for j in range(n)] for i in range(n)]
    dp = [[float('inf')] * n for _ in range(1 << n)]
    dp[1][0] = 0
    for mask in range(1 << n):
        for u in range(n):
            if mask & 1 << u:
                for v in range(n):
                    if mask & 1 << v == 0:
                        next_mask = mask | 1 << v
                        dp[next_mask][v] = min(dp[next_mask][v], dp[mask][u] + dist[u][v])
    final_mask = (1 << n) - 1
    min_cost = float('inf')
    end_node = -1
    for u in range(1, n):
        if min_cost > dp[final_mask][u] + dist[u][0]:
            min_cost = dp[final_mask][u] + dist[u][0]
            end_node = u
    path = []
    mask = final_mask
    while end_node != 0:
        path.append(nodes[end_node])
        for u in range(n):
            if mask & 1 << u and dp[mask][end_node] == dp[mask ^ 1 << end_node][u] + dist[u][end_node]:
                mask ^= 1 << end_node
                end_node = u
                break
    path.append(nodes[0])
    path.reverse()
    path.append(nodes[0])
    return (path, min_cost)

def main(cities: dict[int, list[int]], ants_num: int, iterations_num: int, pheromone_evaporation: float, alpha: float, beta: float, q: float) -> tuple[list[int], float]:
    cities_num = len(cities)
    pheromone = [[1.0] * cities_num] * cities_num
    best_path: list[int] = []
    best_distance = float('inf')
    for _ in range(iterations_num):
        ants_route = []
        for _ in range(ants_num):
            unvisited_cities = copy.deepcopy(cities)
            current_city = {next(iter(cities.keys())): next(iter(cities.values()))}
            del unvisited_cities[next(iter(current_city.keys()))]
            ant_route = [next(iter(current_city.keys()))]
            while unvisited_cities:
                (current_city, unvisited_cities) = city_select(pheromone, current_city, unvisited_cities, alpha, beta)
                ant_route.append(next(iter(current_city.keys())))
            ant_route.append(0)
            ants_route.append(ant_route)
        (pheromone, best_path, best_distance) = pheromone_update(pheromone, cities, pheromone_evaporation, ants_route, q, best_path, best_distance)
    return (best_path, best_distance)

def pheromone_update(pheromone: list[list[float]], cities: dict[int, list[int]], pheromone_evaporation: float, ants_route: list[list[int]], q: float, best_path: list[int], best_distance: float) -> tuple[list[list[float]], list[int], float]:
    for a in range(len(cities)):
        for b in range(len(cities)):
            pheromone[a][b] *= pheromone_evaporation
    for ant_route in ants_route:
        total_distance = 0.0
        for i in range(len(ant_route) - 1):
            total_distance += distance(cities[ant_route[i]], cities[ant_route[i + 1]])
        delta_pheromone = q / total_distance
        for i in range(len(ant_route) - 1):
            pheromone[ant_route[i]][ant_route[i + 1]] += delta_pheromone
            pheromone[ant_route[i + 1]][ant_route[i]] = pheromone[ant_route[i]][ant_route[i + 1]]
        if total_distance < best_distance:
            best_path = ant_route
            best_distance = total_distance
    return (pheromone, best_path, best_distance)

def city_select(pheromone: list[list[float]], current_city: dict[int, list[int]], unvisited_cities: dict[int, list[int]], alpha: float, beta: float) -> tuple[dict[int, list[int]], dict[int, list[int]]]:
    probabilities = []
    for (city, value) in unvisited_cities.items():
        city_distance = distance(value, next(iter(current_city.values())))
        probability = pheromone[city][next(iter(current_city.keys()))] ** alpha * (1 / city_distance) ** beta
        probabilities.append(probability)
    chosen_city_i = random.choices(list(unvisited_cities.keys()), weights=probabilities)[0]
    chosen_city = {chosen_city_i: unvisited_cities[chosen_city_i]}
    del unvisited_cities[next(iter(chosen_city.keys()))]
    return (chosen_city, unvisited_cities)

def longest_distance(graph) -> None:
    indegree = [0] * len(graph)
    queue = []
    long_dist = [1] * len(graph)
    for values in graph.values():
        for i in values:
            indegree[i] += 1
    for i in range(len(indegree)):
        if indegree[i] == 0:
            queue.append(i)
    while queue:
        vertex = queue.pop(0)
        for x in graph[vertex]:
            indegree[x] -= 1
            long_dist[x] = max(long_dist[x], long_dist[vertex] + 1)
            if indegree[x] == 0:
                queue.append(x)
    print(max(long_dist))

def initialize_distance_matrix(graph: dict[int, list[tuple[int, float]]], number_of_nodes: int) -> np.ndarray:
    distance_matrix: np.ndarray = np.full((number_of_nodes, number_of_nodes), np.inf)
    np.fill_diagonal(distance_matrix, 0)
    for (node_index, edges) in graph.items():
        for (neighbor_index, edge_weight) in edges:
            if edge_weight <= 0:
                error_message: str = f'Edge weight must be positive. Found {edge_weight} between nodes {node_index} and {neighbor_index}.'
                raise ValueError(error_message)
            distance_matrix[node_index, neighbor_index] = edge_weight
    return distance_matrix

def floyd_warshall_algorithm(graph: dict[int, list[tuple[int, float]]]) -> np.ndarray:
    number_of_nodes: int = len(graph)
    distance_matrix: np.ndarray = initialize_distance_matrix(graph, number_of_nodes)
    for k in range(number_of_nodes):
        distance_matrix[:] = np.minimum(distance_matrix, distance_matrix[:, k][:, np.newaxis] + distance_matrix[k, :])
    return distance_matrix

def find_central_node(eccentricities: list[tuple[int, float]]) -> tuple[int, float]:
    valid_eccentricities = [e for e in eccentricities if e[1] != float('inf')]
    return min(valid_eccentricities, key=lambda node_eccentricity: (node_eccentricity[1], node_eccentricity[0]), default=(-1, float('inf')))

def find_median_node(closenesses: list[tuple[int, float]]) -> tuple[int, float]:
    valid_closenesses = [c for c in closenesses if c[1] != float('inf')]
    return max(valid_closenesses, key=lambda node_closeness: (node_closeness[1], -node_closeness[0]), default=(-1, float('inf')))

def find_central_and_median_node(distance_matrix: np.ndarray) -> tuple[tuple[int, float], tuple[int, float]]:
    num_nodes: int = len(distance_matrix)
    if num_nodes == 1:
        return ((0, 0.0), (0, 0.0))
    eccentricities: list[tuple[int, float]] = []
    closenesses: list[tuple[int, float]] = []
    for i in range(num_nodes):
        reachable_distances = get_reachable_distances(distance_matrix[i])
        if reachable_distances.size == 0:
            eccentricity = float('inf')
            closeness = float('inf')
        else:
            eccentricity = float(np.max(reachable_distances))
            closeness = float(np.sum(1 / reachable_distances))
        eccentricities.append((i, eccentricity))
        closenesses.append((i, closeness))
    central_node = find_central_node(eccentricities)
    median_node = find_median_node(closenesses)
    return (central_node, median_node)

def _print_dist(dist, v) -> None:
    print('\nThe shortest path matrix using Floyd Warshall algorithm\n')
    for i in range(v):
        for j in range(v):
            end_char = '' if j == v - 1 else '  '
            if dist[i][j] != float('inf'):
                print(int(dist[i][j]), end=end_char)
            else:
                print('INF', end=end_char)
        print()

def floyd_warshall(graph, v):
    dist = [[float('inf') for _ in range(v)] for _ in range(v)]
    for i in range(v):
        for j in range(v):
            dist[i][j] = graph[i][j]
    for k in range(v):
        for i in range(v):
            for j in range(v):
                if dist[i][k] != float('inf') and dist[k][j] != float('inf') and (dist[i][k] + dist[k][j] < dist[i][j]):
                    dist[i][j] = dist[i][k] + dist[k][j]
    _print_dist(dist, v)
    return (dist, v)

