def graham_scan(points: Sequence[Point]) -> list[Point]:
    if len(points) <= 2:
        return []
    min_point = min(points)
    points_list = [p for p in points if p != min_point]
    if not points_list:
        return []

    def polar_angle_key(point: Point) -> tuple[float, float, float]:
        dx = point.x - min_point.x
        dy = point.y - min_point.y
        distance = min_point.euclidean_distance(point)
        return (dx, dy, -distance)

    def compare_points(point_a: Point, point_b: Point) -> int:
        orientation = min_point.consecutive_orientation(point_a, point_b)
        if orientation < 0.0:
            return 1
        elif orientation > 0.0:
            return -1
        else:
            dist_a = min_point.euclidean_distance(point_a)
            dist_b = min_point.euclidean_distance(point_b)
            if dist_b < dist_a:
                return -1
            elif dist_b > dist_a:
                return 1
            else:
                return 0
    from functools import cmp_to_key
    points_list.sort(key=cmp_to_key(compare_points))
    convex_hull: list[Point] = [min_point, points_list[0]]
    for point in points_list[1:]:
        if min_point.consecutive_orientation(point, convex_hull[-1]) == 0.0:
            continue
        while len(convex_hull) >= 2:
            orientation = convex_hull[-2].consecutive_orientation(convex_hull[-1], point)
            if orientation <= 0.0:
                convex_hull.pop()
            else:
                break
        convex_hull.append(point)
    if len(convex_hull) <= 2:
        return []
    return convex_hull

def segments_intersect(p1: Point, p2: Point, p3: Point, p4: Point) -> bool:
    d1 = direction(p3, p4, p1)
    d2 = direction(p3, p4, p2)
    d3 = direction(p1, p2, p3)
    d4 = direction(p1, p2, p4)
    if (d1 < 0 < d2 or d2 < 0 < d1) and (d3 < 0 < d4 or d4 < 0 < d3):
        return True
    if d1 == 0 and on_segment(p3, p4, p1):
        return True
    if d2 == 0 and on_segment(p3, p4, p2):
        return True
    if d3 == 0 and on_segment(p1, p2, p3):
        return True
    return d4 == 0 and on_segment(p1, p2, p4)

def convex_hull(points: list[Point]) -> list[Point]:
    unique_points = sorted(set(points))
    if len(unique_points) <= 1:
        return unique_points
    lower_hull: list[Point] = []
    for candidate_point in unique_points:
        while len(lower_hull) >= 2 and cross_product(lower_hull[-2], lower_hull[-1], candidate_point) <= 0.0:
            lower_hull.pop()
        lower_hull.append(candidate_point)
    upper_hull: list[Point] = []
    for candidate_point in reversed(unique_points):
        while len(upper_hull) >= 2 and cross_product(upper_hull[-2], upper_hull[-1], candidate_point) <= 0.0:
            upper_hull.pop()
        upper_hull.append(candidate_point)
    return lower_hull[:-1] + upper_hull[:-1]

def rotating_calipers(points: list[Point]) -> tuple[float, tuple[Point, Point]]:
    if len(points) < 2:
        raise ValueError('At least 2 points are required to compute polygon diameter.')
    hull = convex_hull(points)
    hull_size = len(hull)
    if hull_size == 1:
        return (0.0, (hull[0], hull[0]))
    if hull_size == 2:
        return (math.hypot(hull[0].x - hull[1].x, hull[0].y - hull[1].y), (hull[0], hull[1]))
    max_dist_squared = 0.0
    best_pair = (hull[0], hull[1])
    antipodal_idx = 1
    while cross_product(hull[0], hull[1], hull[(antipodal_idx + 1) % hull_size]) > cross_product(hull[0], hull[1], hull[antipodal_idx]):
        antipodal_idx = (antipodal_idx + 1) % hull_size
    for current_idx in range(hull_size):
        next_idx = (current_idx + 1) % hull_size
        while cross_product(hull[current_idx], hull[next_idx], hull[(antipodal_idx + 1) % hull_size]) > cross_product(hull[current_idx], hull[next_idx], hull[antipodal_idx]):
            antipodal_idx = (antipodal_idx + 1) % hull_size
        for p in (hull[current_idx], hull[next_idx]):
            for candidate_idx in (antipodal_idx, (antipodal_idx + 1) % hull_size):
                dist_sq = distance_squared(p, hull[candidate_idx])
                if dist_sq > max_dist_squared:
                    max_dist_squared = dist_sq
                    best_pair = (p, hull[candidate_idx])
    return (math.sqrt(max_dist_squared), best_pair)

def _is_point_on_segment(p1: Point, p2: Point, point: Point) -> bool:
    cross = (point.y - p1.y) * (p2.x - p1.x) - (point.x - p1.x) * (p2.y - p1.y)
    if abs(cross) > 1e-09:
        return False
    return min(p1.x, p2.x) <= point.x <= max(p1.x, p2.x) and min(p1.y, p2.y) <= point.y <= max(p1.y, p2.y)

def _find_leftmost_point(points: list[Point]) -> int:
    left_idx = 0
    for i in range(1, len(points)):
        if points[i].x < points[left_idx].x or (points[i].x == points[left_idx].x and points[i].y < points[left_idx].y):
            left_idx = i
    return left_idx

def _find_next_hull_point(points: list[Point], current_idx: int) -> int:
    next_idx = (current_idx + 1) % len(points)
    while next_idx == current_idx:
        next_idx = (next_idx + 1) % len(points)
    for i in range(len(points)):
        if i == current_idx:
            continue
        cross = _cross_product(points[current_idx], points[i], points[next_idx])
        if cross > 0:
            next_idx = i
    return next_idx

def _is_valid_polygon(hull: list[Point]) -> bool:
    for i in range(len(hull)):
        p1 = hull[i]
        p2 = hull[(i + 1) % len(hull)]
        p3 = hull[(i + 2) % len(hull)]
        if abs(_cross_product(p1, p2, p3)) > 1e-09:
            return True
    return False

def _add_point_to_hull(hull: list[Point], point: Point) -> None:
    last = len(hull) - 1
    if len(hull) > 1 and _is_point_on_segment(hull[last - 1], hull[last], point):
        hull[last] = Point(point.x, point.y)
    else:
        hull.append(Point(point.x, point.y))

def jarvis_march(points: list[Point]) -> list[Point]:
    if len(points) <= 2:
        return []
    unique_points = list(set(points))
    if len(unique_points) <= 2:
        return []
    convex_hull: list[Point] = []
    left_point_idx = _find_leftmost_point(unique_points)
    convex_hull.append(Point(unique_points[left_point_idx].x, unique_points[left_point_idx].y))
    current_idx = left_point_idx
    while True:
        next_idx = _find_next_hull_point(unique_points, current_idx)
        if next_idx == left_point_idx:
            break
        if next_idx == current_idx:
            break
        current_idx = next_idx
        _add_point_to_hull(convex_hull, unique_points[current_idx])
    if len(convex_hull) <= 2:
        return []
    last = len(convex_hull) - 1
    if _is_point_on_segment(convex_hull[last - 1], convex_hull[last], convex_hull[0]):
        convex_hull.pop()
        if len(convex_hull) == 2:
            return []
    if not _is_valid_polygon(convex_hull):
        return []
    return convex_hull

def _perpendicular_distance(point: tuple[float, float], line_start: tuple[float, float], line_end: tuple[float, float]) -> float:
    (px, py) = point
    (ax, ay) = line_start
    (bx, by) = line_end
    (dx, dy) = (bx - ax, by - ay)
    seg_len_sq = dx * dx + dy * dy
    if seg_len_sq == 0.0:
        return _euclidean_distance(point, line_start)
    t = max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / seg_len_sq))
    nearest_x = ax + t * dx
    nearest_y = ay + t * dy
    return math.hypot(px - nearest_x, py - nearest_y)

def ramer_douglas_peucker(pts: list[tuple[float, float]], epsilon: float) -> list[tuple[float, float]]:
    if epsilon < 0:
        msg = f'epsilon must be non-negative, got {epsilon!r}'
        raise ValueError(msg)
    if len(pts) < 3:
        return list(pts)
    n = len(pts)
    keep: list[bool] = [False] * n
    keep[0] = True
    keep[-1] = True
    stack: list[tuple[int, int]] = [(0, n - 1)]
    while stack:
        (start, end) = stack.pop()
        if end - start < 2:
            continue
        max_dist = 0.0
        max_index = start
        for i in range(start + 1, end):
            dist = _perpendicular_distance(pts[i], pts[start], pts[end])
            if dist > max_dist:
                max_dist = dist
                max_index = i
        if max_dist > epsilon:
            keep[max_index] = True
            stack.append((start, max_index))
            stack.append((max_index, end))
    return [pts[i] for i in range(n) if keep[i]]

def monotone_chain(points: list[Point]) -> list[Point]:
    unique_sorted_points = sorted(set(points))
    if len(unique_sorted_points) <= 1:
        return unique_sorted_points
    lower_hull: list[Point] = []
    for candidate_point in unique_sorted_points:
        while len(lower_hull) >= 2 and cross_product_direction(lower_hull[-2], lower_hull[-1], candidate_point) <= 0:
            lower_hull.pop()
        lower_hull.append(candidate_point)
    upper_hull: list[Point] = []
    for candidate_point in reversed(unique_sorted_points):
        while len(upper_hull) >= 2 and cross_product_direction(upper_hull[-2], upper_hull[-1], candidate_point) <= 0:
            upper_hull.pop()
        upper_hull.append(candidate_point)
    return lower_hull[:-1] + upper_hull[:-1]

