def generate_image(cells: list[list[int]]) -> Image.Image:
    img = Image.new('RGB', (len(cells[0]), len(cells)))
    pixels = img.load()
    assert pixels is not None
    for w in range(img.width):
        for h in range(img.height):
            color = 255 - int(255 * cells[h][w])
            pixels[w, h] = (color, color, color)
    return img

def new_generation(cells: list[list[int]]) -> list[list[int]]:
    next_generation = []
    for i in range(len(cells)):
        next_generation_row = []
        for j in range(len(cells[i])):
            neighbour_count = 0
            if i > 0 and j > 0:
                neighbour_count += cells[i - 1][j - 1]
            if i > 0:
                neighbour_count += cells[i - 1][j]
            if i > 0 and j < len(cells[i]) - 1:
                neighbour_count += cells[i - 1][j + 1]
            if j > 0:
                neighbour_count += cells[i][j - 1]
            if j < len(cells[i]) - 1:
                neighbour_count += cells[i][j + 1]
            if i < len(cells) - 1 and j > 0:
                neighbour_count += cells[i + 1][j - 1]
            if i < len(cells) - 1:
                neighbour_count += cells[i + 1][j]
            if i < len(cells) - 1 and j < len(cells[i]) - 1:
                neighbour_count += cells[i + 1][j + 1]
            alive = cells[i][j] == 1
            if alive and 2 <= neighbour_count <= 3 or (not alive and neighbour_count == 3):
                next_generation_row.append(1)
            else:
                next_generation_row.append(0)
        next_generation.append(next_generation_row)
    return next_generation

def generate_images(cells: list[list[int]], frames: int) -> list[Image.Image]:
    images = []
    for _ in range(frames):
        img = Image.new('RGB', (len(cells[0]), len(cells)))
        pixels = img.load()
        assert pixels is not None
        for x in range(len(cells)):
            for y in range(len(cells[0])):
                colour = 255 - cells[y][x] * 255
                pixels[x, y] = (colour, colour, colour)
        images.append(img)
        cells = new_generation(cells)
    return images

def create_canvas(size: int) -> list[list[bool]]:
    canvas = [[False for i in range(size)] for j in range(size)]
    return canvas

def seed(canvas: list[list[bool]]) -> None:
    for (i, row) in enumerate(canvas):
        for (j, _) in enumerate(row):
            canvas[i][j] = bool(random.getrandbits(1))

def run(canvas: list[list[bool]]) -> list[list[bool]]:
    current_canvas = np.array(canvas)
    next_gen_canvas = np.array(create_canvas(current_canvas.shape[0]))
    for (r, row) in enumerate(current_canvas):
        for (c, pt) in enumerate(row):
            next_gen_canvas[r][c] = __judge_point(pt, current_canvas[r - 1:r + 2, c - 1:c + 2])
    return next_gen_canvas.tolist()

def __judge_point(pt: bool, neighbours: list[list[bool]]) -> bool:
    dead = 0
    alive = 0
    for i in neighbours:
        for status in i:
            if status:
                alive += 1
            else:
                dead += 1
    if pt:
        alive -= 1
    else:
        dead -= 1
    state = pt
    if pt:
        if alive < 2:
            state = False
        elif alive in {2, 3}:
            state = True
        elif alive > 3:
            state = False
    elif alive == 3:
        state = True
    return state

def get_distance(highway_now: list, car_index: int) -> int:
    distance = 0
    cells = highway_now[car_index + 1:]
    for cell in range(len(cells)):
        if cells[cell] != -1:
            return distance
        distance += 1
    return distance + get_distance(highway_now, -1)

def update(highway_now: list, probability: float, max_speed: int) -> list:
    number_of_cells = len(highway_now)
    next_highway = [-1] * number_of_cells
    for car_index in range(number_of_cells):
        if highway_now[car_index] != -1:
            next_highway[car_index] = min(highway_now[car_index] + 1, max_speed)
            dn = get_distance(highway_now, car_index) - 1
            next_highway[car_index] = min(next_highway[car_index], dn)
            if random() < probability:
                next_highway[car_index] = max(next_highway[car_index] - 1, 0)
    return next_highway

def simulate(highway: list, number_of_update: int, probability: float, max_speed: int) -> list:
    number_of_cells = len(highway[0])
    for i in range(number_of_update):
        next_speeds_calculated = update(highway[i], probability, max_speed)
        real_next_speeds = [-1] * number_of_cells
        for car_index in range(number_of_cells):
            speed = next_speeds_calculated[car_index]
            if speed != -1:
                index = (car_index + speed) % number_of_cells
                real_next_speeds[index] = speed
        highway.append(real_next_speeds)
    return highway

def generate_rule_30(size: int=31, generations: int=15) -> list[list[int]]:
    grid = [[0] * size for _ in range(generations)]
    grid[0][size // 2] = 1
    for i in range(1, generations):
        grid[i] = rule_30_step(grid[i - 1])
    return grid

def validate(*values: float) -> bool:
    result = len(values) > 0 and all((value > 0.0 for value in values))
    return result

def newtons_second_law_of_motion(mass: float, acceleration: float) -> float:
    force = 0.0
    try:
        force = mass * acceleration
    except Exception:
        return -0.0
    return force

def shear_stress(stress: float, tangential_force: float, area: float) -> tuple[str, float]:
    if (stress, tangential_force, area).count(0) != 1:
        raise ValueError('You cannot supply more or less than 2 values')
    if stress < 0:
        raise ValueError('Stress cannot be negative')
    if tangential_force < 0:
        raise ValueError('Tangential Force cannot be negative')
    if area < 0:
        raise ValueError('Area cannot be negative')
    if stress == 0:
        return ('stress', tangential_force / area)
    elif tangential_force == 0:
        return ('tangential_force', stress * area)
    else:
        return ('area', tangential_force / stress)

def malus_law(initial_intensity: float, angle: float) -> float:
    if initial_intensity < 0:
        raise ValueError('The value of intensity cannot be negative')
    if angle < 0 or angle > 360:
        raise ValueError('In Malus Law, the angle is in the range 0-360 degrees')
    return initial_intensity * math.cos(math.radians(angle)) ** 2

def orbital_transfer_work(mass_central: float, mass_object: float, r_initial: float, r_final: float) -> str:
    gravitational_constant = 6.6743e-11
    if r_initial <= 0 or r_final <= 0:
        raise ValueError('Orbital radii must be greater than zero.')
    work = gravitational_constant * mass_central * mass_object / 2 * (1 / r_initial - 1 / r_final)
    return f'{work:.3e}'

def relativistic_velocity_summation(object_velocity: float, frame_velocity: float) -> float:
    if object_velocity > c or frame_velocity >= c or object_velocity < -c or (frame_velocity <= -c):
        raise ValueError('Speeds must not exceed light speed, and the frame speed must be lower than the light speed!')
    numerator = object_velocity + frame_velocity
    denominator = 1 + object_velocity * frame_velocity / c ** 2
    return numerator / denominator

def reynolds_number(density: float, velocity: float, diameter: float, viscosity: float) -> float:
    if density <= 0 or diameter <= 0 or viscosity <= 0:
        raise ValueError('please ensure that density, diameter and viscosity are positive')
    return density * abs(velocity) * diameter / viscosity

def focal_length(distance_of_object: float, distance_of_image: float) -> float:
    if distance_of_object == 0 or distance_of_image == 0:
        raise ValueError('Invalid inputs. Enter non zero values with respect to the sign convention.')
    focal_length = 1 / (1 / distance_of_object + 1 / distance_of_image)
    return focal_length

def object_distance(focal_length: float, distance_of_image: float) -> float:
    if distance_of_image == 0 or focal_length == 0:
        raise ValueError('Invalid inputs. Enter non zero values with respect to the sign convention.')
    object_distance = 1 / (1 / focal_length - 1 / distance_of_image)
    return object_distance

def image_distance(focal_length: float, distance_of_object: float) -> float:
    if distance_of_object == 0 or focal_length == 0:
        raise ValueError('Invalid inputs. Enter non zero values with respect to the sign convention.')
    image_distance = 1 / (1 / focal_length - 1 / distance_of_object)
    return image_distance

def bragg_angle(distance: float, order: int, wavelength: float) -> float:
    sine_theta = order * wavelength / (2 * distance)
    if sine_theta > 1 or sine_theta < -1:
        raise ValueError('The calculated sine value is out of the valid range.')
    theta_radians = math.asin(sine_theta)
    theta_degrees = math.degrees(theta_radians)
    return round(theta_degrees, 1)

def kinetic_energy(mass: float, velocity: float) -> float:
    if mass < 0:
        raise ValueError('The mass of a body cannot be negative')
    return 0.5 * mass * abs(velocity) * abs(velocity)

def polar_force(magnitude: float, angle: float, radian_mode: bool=False) -> list[float]:
    if radian_mode:
        return [magnitude * cos(angle), magnitude * sin(angle)]
    return [magnitude * cos(radians(angle)), magnitude * sin(radians(angle))]

def in_static_equilibrium(forces: NDArray[float64], location: NDArray[float64], eps: float=10 ** (-1)) -> bool:
    moments: NDArray[float64] = location[:, 0] * forces[:, 1] - location[:, 1] * forces[:, 0]
    sum_moments: float = sum(moments)
    return bool(abs(sum_moments) < eps)

def __check_args(magnetic_field: float, area: float, angle: float) -> None:
    if not isinstance(magnetic_field, (int, float)):
        raise TypeError('Invalid magnetic field. Should be an integer or float.')
    if not isinstance(area, (int, float)):
        raise TypeError('Invalid area. Should be an integer or float.')
    if not isinstance(angle, (int, float)):
        raise TypeError('Invalid angle. Should be an integer or float.')
    if angle < 0 or angle > 180:
        raise ValueError('Invalid angle. Range is 0-180 degrees.')
    if magnetic_field < 0:
        raise ValueError('Invalid magnetic field. Should be a positive number.')
    if area < 0:
        raise ValueError('Invalid area. Should be a positive number.')

def magnetic_flux(magnetic_field: float, area: float, angle: float) -> float:
    __check_args(magnetic_field, area, angle)
    rad = radians(angle)
    return round(magnetic_field * area * cos(rad), 1)

def archimedes_principle(fluid_density: float, volume: float, gravity: float=g) -> float:
    if fluid_density <= 0:
        raise ValueError('Impossible fluid density')
    if volume <= 0:
        raise ValueError('Impossible object volume')
    if gravity < 0:
        raise ValueError('Impossible gravity')
    return fluid_density * gravity * volume

def period_of_pendulum(length: float) -> float:
    if length < 0:
        raise ValueError('The length should be non-negative')
    return 2 * pi * (length / g) ** 0.5

def beta(velocity: float) -> float:
    if velocity > c:
        raise ValueError('Speed must not exceed light speed 299,792,458 [m/s]!')
    if velocity < 1:
        raise ValueError('Speed must be greater than or equal to 1!')
    return velocity / c

def transform(velocity: float, event: np.ndarray | None=None) -> np.ndarray:
    if event is None:
        event = np.array([ct, x, y, z])
    else:
        event[0] *= c
    return transformation_matrix(velocity) @ event

def relativistic_kinetic_energy(mass: float, velocity: float) -> float:
    if mass < 0:
        raise ValueError('The mass of a body cannot be negative')
    gamma = 1 / sqrt(1 - velocity ** 2 / c ** 2)
    return (gamma - 1) * mass * c ** 2

def hookes_law(spring_constant: float, displacement: float) -> float:
    if spring_constant <= 0:
        raise ValueError('Spring constant must be positive.')
    return -spring_constant * displacement

def avg_speed_of_molecule(temperature: float, molar_mass: float) -> float:
    if temperature < 0:
        raise Exception('Absolute temperature cannot be less than 0 K')
    if molar_mass <= 0:
        raise Exception('Molar mass should be greater than 0 kg/mol')
    return (8 * R * temperature / (pi * molar_mass)) ** 0.5

def mps_speed_of_molecule(temperature: float, molar_mass: float) -> float:
    if temperature < 0:
        raise Exception('Absolute temperature cannot be less than 0 K')
    if molar_mass <= 0:
        raise Exception('Molar mass should be greater than 0 kg/mol')
    return (2 * R * temperature / molar_mass) ** 0.5

def fresnel_diffract(wavefunc_0: np.ndarray, pixel_size: float, wavelength: float, prop_dist: float) -> np.ndarray:
    if len(wavefunc_0.shape) == 1:
        return _fresnel_diffract_1d(wavefunc_0, pixel_size, wavelength, prop_dist)
    elif len(wavefunc_0.shape) == 2:
        return _fresnel_diffract_2d(wavefunc_0, pixel_size, wavelength, prop_dist)
    else:
        error_message = f'Expected a 1D or 2D wavefield, but got {wavefunc_0.shape}'
        raise ValueError(error_message)

def maximum_kinetic_energy(frequency: float, work_function: float, in_ev: bool=False) -> float:
    if frequency < 0:
        raise ValueError("Frequency can't be negative.")
    if in_ev:
        return max(PLANCK_CONSTANT_EVS * frequency - work_function, 0)
    return max(PLANCK_CONSTANT_JS * frequency - work_function, 0)

def calculate_refraction_angle(index_of_refraction_1: float, index_of_refraction_2: float, incident_angle_degrees: float) -> float:
    incident_angle_radians = math.radians(incident_angle_degrees)
    refraction_sine = index_of_refraction_1 / index_of_refraction_2 * math.sin(incident_angle_radians)
    if math.isclose(refraction_sine, 1.0):
        return 90.0
    if math.isclose(refraction_sine, -1.0):
        return -90.0
    if not -1 <= refraction_sine <= 1:
        raise ValueError('Invalid physical inputs: ratio cannot be outside [-1, 1].')
    refraction_angle = round(math.degrees(math.asin(refraction_sine)), 2)
    return refraction_angle

def coulombs_law(q1: float, q2: float, radius: float) -> float:
    if radius <= 0:
        raise ValueError('The radius is always a positive number')
    return round(8.9875517923 * 10 ** 9 * q1 * q2 / radius ** 2, 2)

def casimir_force(force: float, area: float, distance: float) -> dict[str, float]:
    if (force, area, distance).count(0) != 1:
        raise ValueError('One and only one argument must be 0')
    if force < 0:
        raise ValueError('Magnitude of force can not be negative')
    if distance < 0:
        raise ValueError('Distance can not be negative')
    if area < 0:
        raise ValueError('Area can not be negative')
    if force == 0:
        force = REDUCED_PLANCK_CONSTANT * SPEED_OF_LIGHT * pi ** 2 * area / (240 * distance ** 4)
        return {'force': force}
    elif area == 0:
        area = 240 * force * distance ** 4 / (REDUCED_PLANCK_CONSTANT * SPEED_OF_LIGHT * pi ** 2)
        return {'area': area}
    elif distance == 0:
        distance = (REDUCED_PLANCK_CONSTANT * SPEED_OF_LIGHT * pi ** 2 * area / (240 * force)) ** (1 / 4)
        return {'distance': distance}
    raise ValueError('One and only one argument must be 0')

def check_args(init_velocity: float, angle: float) -> None:
    if not isinstance(init_velocity, (int, float)):
        raise TypeError('Invalid velocity. Should be an integer or float.')
    if not isinstance(angle, (int, float)):
        raise TypeError('Invalid angle. Should be an integer or float.')
    if angle > 90 or angle < 1:
        raise ValueError('Invalid angle. Range is 1-90 degrees.')
    if init_velocity < 0:
        raise ValueError('Invalid velocity. Should be a positive number.')

def horizontal_distance(init_velocity: float, angle: float) -> float:
    check_args(init_velocity, angle)
    radians = deg_to_rad(2 * angle)
    return round(init_velocity ** 2 * sin(radians) / g, 2)

def max_height(init_velocity: float, angle: float) -> float:
    check_args(init_velocity, angle)
    radians = deg_to_rad(angle)
    return round(init_velocity ** 2 * sin(radians) ** 2 / (2 * g), 2)

def total_time(init_velocity: float, angle: float) -> float:
    check_args(init_velocity, angle)
    radians = deg_to_rad(angle)
    return round(2 * init_velocity * sin(radians) / g, 2)

def get_altitude_at_pressure(pressure: float) -> float:
    if pressure > 101325:
        raise ValueError('Value Higher than Pressure at Sea Level !')
    if pressure < 0:
        raise ValueError('Atmospheric Pressure can not be negative !')
    return 44330 * (1 - (pressure / 101325) ** (1 / 5.5255))

def speed_of_sound_in_a_fluid(density: float, bulk_modulus: float) -> float:
    if density <= 0:
        raise ValueError('Impossible fluid density')
    if bulk_modulus <= 0:
        raise ValueError('Impossible bulk modulus')
    return (bulk_modulus / density) ** 0.5

def gravitational_law(force: float, mass_1: float, mass_2: float, distance: float) -> dict[str, float]:
    product_of_mass = mass_1 * mass_2
    if (force, mass_1, mass_2, distance).count(0) != 1:
        raise ValueError('One and only one argument must be 0')
    if force < 0:
        raise ValueError('Gravitational force can not be negative')
    if distance < 0:
        raise ValueError('Distance can not be negative')
    if mass_1 < 0 or mass_2 < 0:
        raise ValueError('Mass can not be negative')
    if force == 0:
        force = GRAVITATIONAL_CONSTANT * product_of_mass / distance ** 2
        return {'force': force}
    elif mass_1 == 0:
        mass_1 = force * distance ** 2 / (GRAVITATIONAL_CONSTANT * mass_2)
        return {'mass_1': mass_1}
    elif mass_2 == 0:
        mass_2 = force * distance ** 2 / (GRAVITATIONAL_CONSTANT * mass_1)
        return {'mass_2': mass_2}
    elif distance == 0:
        distance = (GRAVITATIONAL_CONSTANT * product_of_mass / force) ** 0.5
        return {'distance': distance}
    raise ValueError('One and only one argument must be 0')

def escape_velocity(mass: float, radius: float) -> float:
    gravitational_constant = 6.6743e-11
    if radius == 0:
        raise ZeroDivisionError('Radius cannot be zero.')
    velocity = math.sqrt(2 * gravitational_constant * mass / radius)
    return round(velocity, 3)

def rms_speed_of_molecule(temperature: float, molar_mass: float) -> float:
    if temperature < 0:
        raise Exception('Temperature cannot be less than 0 K')
    if molar_mass <= 0:
        raise Exception('Molar mass cannot be less than or equal to 0 kg/mol')
    return (3 * UNIVERSAL_GAS_CONSTANT * temperature / molar_mass) ** 0.5

def hubble_parameter(hubble_constant: float, radiation_density: float, matter_density: float, dark_energy: float, redshift: float) -> float:
    parameters = [redshift, radiation_density, matter_density, dark_energy]
    if any((p < 0 for p in parameters)):
        raise ValueError('All input parameters must be positive')
    if any((p > 1 for p in parameters[1:4])):
        raise ValueError('Relative densities cannot be greater than one')
    curvature = 1 - (matter_density + radiation_density + dark_energy)
    e_2 = radiation_density * (redshift + 1) ** 4 + matter_density * (redshift + 1) ** 3 + curvature * (redshift + 1) ** 2 + dark_energy
    hubble = hubble_constant * e_2 ** (1 / 2)
    return hubble

def doppler_effect(org_freq: float, wave_vel: float, obs_vel: float, src_vel: float) -> float:
    if wave_vel == src_vel:
        raise ZeroDivisionError('Division by zero implies vs=v and observer in front of the source')
    doppler_freq = org_freq * (wave_vel + obs_vel) / (wave_vel - src_vel)
    if doppler_freq <= 0:
        raise ValueError('Non-positive frequency implies vs>v or v0>v (in the opposite direction)')
    return doppler_freq

def capture_radii(target_body_radius: float, target_body_mass: float, projectile_velocity: float) -> float:
    if target_body_mass < 0:
        raise ValueError('Mass cannot be less than 0')
    if target_body_radius < 0:
        raise ValueError('Radius cannot be less than 0')
    if projectile_velocity > c:
        raise ValueError('Cannot go beyond speed of light')
    escape_velocity_squared = 2 * G * target_body_mass / target_body_radius
    capture_radius = target_body_radius * sqrt(1 + escape_velocity_squared / pow(projectile_velocity, 2))
    return round(capture_radius, 0)

def capture_area(capture_radius: float) -> float:
    if capture_radius < 0:
        raise ValueError('Cannot have a capture radius less than 0')
    sigma = pi * pow(capture_radius, 2)
    return round(sigma, 0)

def focal_length_of_lens(object_distance_from_lens: float, image_distance_from_lens: float) -> float:
    if object_distance_from_lens == 0 or image_distance_from_lens == 0:
        raise ValueError('Invalid inputs. Enter non zero values with respect to the sign convention.')
    focal_length = 1 / (1 / image_distance_from_lens - 1 / object_distance_from_lens)
    return focal_length

def object_distance(focal_length_of_lens: float, image_distance_from_lens: float) -> float:
    if image_distance_from_lens == 0 or focal_length_of_lens == 0:
        raise ValueError('Invalid inputs. Enter non zero values with respect to the sign convention.')
    object_distance = 1 / (1 / image_distance_from_lens - 1 / focal_length_of_lens)
