def image_distance(focal_length_of_lens: float, object_distance_from_lens: float) -> float:
    if object_distance_from_lens == 0 or focal_length_of_lens == 0:
        raise ValueError('Invalid inputs. Enter non zero values with respect to the sign convention.')
    image_distance = 1 / (1 / object_distance_from_lens + 1 / focal_length_of_lens)
    return image_distance

def centripetal(mass: float, velocity: float, radius: float) -> float:
    if mass < 0:
        raise ValueError('The mass of the body cannot be negative')
    if radius <= 0:
        raise ValueError('The radius is always a positive non zero integer')
    return mass * velocity ** 2 / radius

def rainfall_intensity(coefficient_k: float, coefficient_a: float, coefficient_b: float, coefficient_c: float, return_period: float, duration: float) -> float:
    if coefficient_k <= 0 or coefficient_a <= 0 or coefficient_b <= 0 or (coefficient_c <= 0) or (return_period <= 0) or (duration <= 0):
        raise ValueError('All parameters must be positive.')
    intensity = coefficient_k * return_period ** coefficient_a / (duration + coefficient_b) ** coefficient_c
    return intensity

def __check_args(final_flux: float, initinal_flux: float, time_interval: float) -> None:
