    flux_variation = final_flux - initinal_flux
    return round(-flux_variation / time_interval, 1)

def gauss_law_electric(electric_field_magnitude: float, surface_area: float, enclosed_charge: float, permittivity: float=VACUUM_PERMITTIVITY) -> bool:
    if surface_area < 0:
        raise ValueError('Surface area must be non-negative')
    if permittivity <= 0:
        raise ValueError('Permittivity must be positive')
    electric_flux = electric_field_magnitude * surface_area
    expected_flux = enclosed_charge / permittivity
    tolerance = 0.01 * abs(expected_flux) if expected_flux != 0 else 1e-10
    return abs(electric_flux - expected_flux) <= tolerance

def gauss_law_magnetic(surface_area: float) -> bool:
    if surface_area < 0:
        raise ValueError('Surface area must be non-negative')
    magnetic_flux = 0.0
    tolerance = 1e-10
    return abs(magnetic_flux) <= tolerance

def ampere_maxwell_law(magnetic_field_circulation: float, enclosed_current: float, electric_flux_change_rate: float, permeability: float=VACUUM_PERMEABILITY, permittivity: float=VACUUM_PERMITTIVITY) -> bool:
    if permeability <= 0:
        raise ValueError('Permeability must be positive')
    if permittivity <= 0:
        raise ValueError('Permittivity must be positive')
    displacement_current = permittivity * electric_flux_change_rate
    total_current = enclosed_current + displacement_current
    expected_circulation = permeability * total_current
    tolerance = 0.01 * abs(expected_circulation) if expected_circulation != 0 else 1e-10
    return abs(magnetic_field_circulation - expected_circulation) <= tolerance

def electromagnetic_wave_speed(permeability: float=VACUUM_PERMEABILITY, permittivity: float=VACUUM_PERMITTIVITY) -> float:
    if permeability <= 0:
        raise ValueError('Permeability must be positive')
    if permittivity <= 0:
        raise ValueError('Permittivity must be positive')
    return 1.0 / math.sqrt(permeability * permittivity)

def electromagnetic_wave_impedance(permeability: float=VACUUM_PERMEABILITY, permittivity: float=VACUUM_PERMITTIVITY) -> float:
    if permeability <= 0:
        raise ValueError('Permeability must be positive')
    if permittivity <= 0:
        raise ValueError('Permittivity must be positive')
    return math.sqrt(permeability / permittivity)

def poynting_vector_magnitude(electric_field: float, magnetic_field: float, permeability: float=VACUUM_PERMEABILITY) -> float:
    if permeability <= 0:
        raise ValueError('Permeability must be positive')
    return electric_field * magnetic_field / permeability

def energy_density_electromagnetic(electric_field: float, magnetic_field: float, permittivity: float=VACUUM_PERMITTIVITY, permeability: float=VACUUM_PERMEABILITY) -> float:
    if permittivity <= 0:
        raise ValueError('Permittivity must be positive')
    if permeability <= 0:
        raise ValueError('Permeability must be positive')
    electric_energy_density = 0.5 * permittivity * electric_field ** 2
    magnetic_energy_density = 0.5 * magnetic_field ** 2 / permeability
    return electric_energy_density + magnetic_energy_density

def pressure_of_gas_system(moles: float, kelvin: float, volume: float) -> float:
    if moles < 0 or kelvin < 0 or volume < 0:
        raise ValueError('Invalid inputs. Enter positive value.')
    return moles * kelvin * UNIVERSAL_GAS_CONSTANT / volume

def volume_of_gas_system(moles: float, kelvin: float, pressure: float) -> float:
    if moles < 0 or kelvin < 0 or pressure < 0:
        raise ValueError('Invalid inputs. Enter positive value.')
    return moles * kelvin * UNIVERSAL_GAS_CONSTANT / pressure

def temperature_of_gas_system(moles: float, volume: float, pressure: float) -> float:
    if moles < 0 or volume < 0 or pressure < 0:
        raise ValueError('Invalid inputs. Enter positive value.')
    return pressure * volume / (moles * UNIVERSAL_GAS_CONSTANT)

def moles_of_gas_system(kelvin: float, volume: float, pressure: float) -> float:
    if kelvin < 0 or volume < 0 or pressure < 0:
        raise ValueError('Invalid inputs. Enter positive value.')
    return pressure * volume / (kelvin * UNIVERSAL_GAS_CONSTANT)

def center_of_mass(particles: list[Particle]) -> Coord3D:
    if not particles:
        raise ValueError('No particles provided')
    if any((particle.mass <= 0 for particle in particles)):
        raise ValueError('Mass of all particles must be greater than 0')
    total_mass = sum((particle.mass for particle in particles))
    center_of_mass_x = round(sum((particle.x * particle.mass for particle in particles)) / total_mass, 2)
    center_of_mass_y = round(sum((particle.y * particle.mass for particle in particles)) / total_mass, 2)
    center_of_mass_z = round(sum((particle.z * particle.mass for particle in particles)) / total_mass, 2)
    return Coord3D(center_of_mass_x, center_of_mass_y, center_of_mass_z)

def classical_hamiltonian(mass: float, velocity: float, potential_energy: float) -> float:
    if mass <= 0:
        raise ValueError('mass must be positive')
    kinetic_energy = 0.5 * mass * velocity ** 2
    return kinetic_energy + potential_energy

def quantum_hamiltonian(num_points: int, potential: list[float], mass: float=1.0, hbar: float=1.0, dx: float=1.0) -> list[list[float]]:
    if num_points <= 0:
        raise ValueError('num_points must be positive')
    if len(potential) != num_points:
        raise ValueError('potential must have length num_points')
    diag_term = hbar ** 2 / (mass * dx ** 2)
    off_diag_term = -hbar ** 2 / (2 * mass * dx ** 2)
    hamiltonian = [[0.0] * num_points for _ in range(num_points)]
    for i in range(num_points):
        hamiltonian[i][i] = diag_term + potential[i]
        if i > 0:
            hamiltonian[i][i - 1] = off_diag_term
        if i < num_points - 1:
            hamiltonian[i][i + 1] = off_diag_term
    return hamiltonian

def get_aberration_angle(angle_rest: float, velocity_over_c: float) -> float:
    factor = sqrt((1 - velocity_over_c) / (1 + velocity_over_c))
    angle_ab = 2 * atan(factor * tan(angle_rest / 2))
    return round(angle_ab, 5)

def potential_energy(mass: float, height: float) -> float:
