def terminal_velocity(mass: float, density: float, area: float, drag_coefficient: float) -> float:
    if mass <= 0 or density <= 0 or area <= 0 or (drag_coefficient <= 0):
        raise ValueError('mass, density, area and the drag coefficient all need to be positive')
    return (2 * mass * g / (density * area * drag_coefficient)) ** 0.5

def strictly_diagonally_dominant(table: NDArray[float64]) -> bool:
    (rows, cols) = table.shape
    is_diagonally_dominant = True
    for i in range(rows):
        total = 0
        for j in range(cols - 1):
            if i == j:
                continue
            total += table[i][j]
        if table[i][i] <= total:
            raise ValueError('Coefficient matrix is not strictly diagonally dominant')
    return is_diagonally_dominant

def invert_matrix(matrix: list[list[float]]) -> list[list[float]]:
    np_matrix = np.array(matrix)
    try:
        inv_matrix = np.linalg.inv(np_matrix)
    except np.linalg.LinAlgError:
        raise ValueError('Matrix is not invertible')
    return inv_matrix.tolist()

def gauss_jordan(coefficients: np.ndarray, vertices: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    if coefficients.ndim != 2 or vertices.ndim != 2:
        raise ValueError('Both inputs must be 2D arrays.')
    if coefficients.shape[0] != vertices.shape[0]:
        raise ValueError('Number of rows in coefficients and vertices must match.')
    coefficients = coefficients.astype(float).copy()
    vertices = vertices.astype(float).copy()
    (rows, cols) = coefficients.shape
    for col in range(cols):
        pivot_row = None
        for row in range(col, rows):
            if not np.isclose(coefficients[row, col], 0):
                pivot_row = row
                break
        if pivot_row is None:
            continue
        if pivot_row != col:
            coefficients[[col, pivot_row]] = coefficients[[pivot_row, col]]
            vertices[[col, pivot_row]] = vertices[[pivot_row, col]]
        pivot_val = coefficients[col, col]
        coefficients[col] /= pivot_val
        vertices[col] /= pivot_val
        for row in range(rows):
            if row == col:
                continue
            factor = coefficients[row, col]
            coefficients[row] -= factor * coefficients[col]
            vertices[row] -= factor * vertices[col]
    return (coefficients, vertices)

def gaussian_elimination(coefficients: NDArray[float64], vector: NDArray[float64]) -> NDArray[float64]:
    (rows, columns) = np.shape(coefficients)
    if rows != columns:
        return np.array((), dtype=float)
    augmented_mat: NDArray[float64] = np.concatenate((coefficients, vector), axis=1)
    augmented_mat = augmented_mat.astype('float64')
    for row in range(rows - 1):
        pivot = augmented_mat[row, row]
        for col in range(row + 1, columns):
            factor = augmented_mat[col, row] / pivot
            augmented_mat[col, :] -= factor * augmented_mat[row, :]
    x = retroactive_resolution(augmented_mat[:, 0:columns], augmented_mat[:, columns:columns + 1])
    return x

def lower_upper_decomposition(table: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    (rows, columns) = np.shape(table)
    if rows != columns:
        msg = f"'table' has to be of square shaped array but got a {rows}x{columns} array:\n{table}"
        raise ValueError(msg)
    lower = np.zeros((rows, columns))
    upper = np.zeros((rows, columns))
    for i in range(columns):
        for j in range(i):
            total = np.sum(lower[i, :i] * upper[:i, j])
            if upper[j][j] == 0:
                raise ArithmeticError('No LU decomposition exists')
            lower[i][j] = (table[i][j] - total) / upper[j][j]
        lower[i][i] = 1
        for j in range(i, columns):
            total = np.sum(lower[i, :i] * upper[:i, j])
            upper[i][j] = table[i][j] - total
    return (lower, upper)

def _is_matrix_spd(matrix: np.ndarray) -> bool:
    assert np.shape(matrix)[0] == np.shape(matrix)[1]
    if np.allclose(matrix, matrix.T) is False:
        return False
    (eigen_values, _) = np.linalg.eigh(matrix)
    return bool(np.all(eigen_values > 0))

def points_to_polynomial(coordinates: list[list[int]]) -> str:
    if len(coordinates) == 0 or not all((len(pair) == 2 for pair in coordinates)):
        raise ValueError('The program cannot work out a fitting polynomial.')
    if len({tuple(pair) for pair in coordinates}) != len(coordinates):
        raise ValueError('The program cannot work out a fitting polynomial.')
    set_x = {x for (x, _) in coordinates}
    if len(set_x) == 1:
        return f'x={coordinates[0][0]}'
    if len(set_x) != len(coordinates):
        raise ValueError('The program cannot work out a fitting polynomial.')
    x = len(coordinates)
    matrix: list[list[float]] = [[coordinates[count_of_line][0] ** (x - (count_in_line + 1)) for count_in_line in range(x)] for count_of_line in range(x)]
    vector: list[float] = [coordinates[count_of_line][1] for count_of_line in range(x)]
    for count in range(x):
        if matrix[count][count] == 0:
            pivot_row = max(range(count + 1, x), key=lambda row: abs(matrix[row][count]))
            if pivot_row == count or matrix[pivot_row][count] == 0:
                raise ValueError('The program cannot work out a fitting polynomial.')
            (matrix[count], matrix[pivot_row]) = (matrix[pivot_row], matrix[count])
            (vector[count], vector[pivot_row]) = (vector[pivot_row], vector[count])
        for number in range(x):
            if count == number:
                continue
            fraction = matrix[number][count] / matrix[count][count]
            for (counting_columns, item) in enumerate(matrix[count]):
                matrix[number][counting_columns] -= item * fraction
            vector[number] -= vector[count] * fraction
    solution: list[str] = [str(vector[count] / matrix[count][count]) for count in range(x)]
    solved = 'f(x)='
    for count in range(x):
        remove_e: list[str] = solution[count].split('E')
        if len(remove_e) > 1:
            solution[count] = f'{remove_e[0]}*10^{remove_e[1]}'
        solved += f'x^{x - (count + 1)}*{solution[count]}'
        if count + 1 != x:
            solved += '+'
    return solved

def solve_linear_system(matrix: np.ndarray) -> np.ndarray:
    ab = np.copy(matrix)
    num_of_rows = ab.shape[0]
    num_of_columns = ab.shape[1] - 1
    x_lst: list[float] = []
    if num_of_rows != num_of_columns:
        raise ValueError('Matrix is not square')
    for column_num in range(num_of_rows):
        for i in range(column_num, num_of_columns):
            if abs(ab[i][column_num]) > abs(ab[column_num][column_num]):
                ab[[column_num, i]] = ab[[i, column_num]]
        if abs(ab[column_num, column_num]) < 1e-08:
            raise ValueError('Matrix is singular')
        if column_num != 0:
            for i in range(column_num, num_of_rows):
                ab[i, :] -= ab[i, column_num - 1] / ab[column_num - 1, column_num - 1] * ab[column_num - 1, :]
    for column_num in range(num_of_rows - 1, -1, -1):
        x = ab[column_num, -1] / ab[column_num, column_num]
        x_lst.insert(0, x)
        for i in range(column_num - 1, -1, -1):
            ab[i, -1] -= ab[i, column_num] * x
    return np.asarray(x_lst)

def schur_complement(mat_a: np.ndarray, mat_b: np.ndarray, mat_c: np.ndarray, pseudo_inv: np.ndarray | None=None) -> np.ndarray:
    shape_a = np.shape(mat_a)
    shape_b = np.shape(mat_b)
    shape_c = np.shape(mat_c)
    if shape_a[0] != shape_b[0]:
        msg = f'Expected the same number of rows for A and B. Instead found A of size {shape_a} and B of size {shape_b}'
        raise ValueError(msg)
    if shape_b[1] != shape_c[1]:
        msg = f'Expected the same number of columns for B and C. Instead found B of size {shape_b} and C of size {shape_c}'
        raise ValueError(msg)
    a_inv = pseudo_inv
    if a_inv is None:
        try:
            a_inv = np.linalg.inv(mat_a)
        except np.linalg.LinAlgError:
            raise ValueError('Input matrix A is not invertible. Cannot compute Schur complement.')
    return mat_c - mat_b.T @ a_inv @ mat_b

def scaling(scaling_factor: float) -> list[list[float]]:
    scaling_factor = float(scaling_factor)
    return [[scaling_factor * int(x == y) for x in range(2)] for y in range(2)]

def rotation(angle: float) -> list[list[float]]:
    (c, s) = (cos(angle), sin(angle))
    return [[c, -s], [s, c]]

def rank_of_matrix(matrix: list[list[int | float]]) -> int:
    rows = len(matrix)
    columns = len(matrix[0])
    rank = min(rows, columns)
    for row in range(rank):
        if matrix[row][row] != 0:
            for col in range(row + 1, rows):
                multiplier = matrix[col][row] / matrix[row][row]
                for i in range(row, columns):
                    matrix[col][i] -= multiplier * matrix[row][i]
        else:
            reduce = True
            for i in range(row + 1, rows):
                if matrix[i][row] != 0:
                    (matrix[row], matrix[i]) = (matrix[i], matrix[row])
                    reduce = False
                    break
            if reduce:
                rank -= 1
                for i in range(rows):
                    matrix[i][row] = matrix[i][rank]
            row -= 1
    return rank

def rayleigh_quotient(a: np.ndarray, v: np.ndarray) -> Any:
    v_star = v.conjugate().T
    v_star_dot = v_star.dot(a)
    assert isinstance(v_star_dot, np.ndarray)
    return v_star_dot.dot(v) / v_star.dot(v)

