def find_negative_index(array: list[int]) -> int:
    left = 0
    right = len(array) - 1
    if not array or array[0] < 0:
        return 0
    while right + 1 > left:
        mid = (left + right) // 2
        num = array[mid]
        if num < 0 and array[mid - 1] >= 0:
            return mid
        if num >= 0:
            left = mid + 1
        else:
            right = mid - 1
    return len(array)

def count_negatives_brute_force_with_break(grid: list[list[int]]) -> int:
    total = 0
    for row in grid:
        for (i, number) in enumerate(row):
            if number < 0:
                total += len(row) - i
                break
    return total

def add(*matrix_s: list[list[int]]) -> list[list[int]]:
    if all((_check_not_integer(m) for m in matrix_s)):
        for i in matrix_s[1:]:
            _verify_matrix_sizes(matrix_s[0], i)
        return [[sum(t) for t in zip(*m)] for m in zip(*matrix_s)]
    raise TypeError('Expected a matrix, got int/list instead')

def subtract(matrix_a: list[list[int]], matrix_b: list[list[int]]) -> list[list[int]]:
    if _check_not_integer(matrix_a) and _check_not_integer(matrix_b) and _verify_matrix_sizes(matrix_a, matrix_b):
        return [[i - j for (i, j) in zip(*m)] for m in zip(matrix_a, matrix_b)]
    raise TypeError('Expected a matrix, got int/list instead')

def multiply(matrix_a: list[list[int]], matrix_b: list[list[int]]) -> list[list[int]]:
    if _check_not_integer(matrix_a) and _check_not_integer(matrix_b):
        (rows, cols) = _verify_matrix_sizes(matrix_a, matrix_b)
    if cols[0] != rows[1]:
        msg = f'Cannot multiply matrix of dimensions ({rows[0]},{cols[0]}) and ({rows[1]},{cols[1]})'
        raise ValueError(msg)
    return [[sum((m * n for (m, n) in zip(i, j))) for j in zip(*matrix_b)] for i in matrix_a]

def identity(n: int) -> list[list[int]]:
    n = int(n)
    return [[int(row == column) for column in range(n)] for row in range(n)]

def transpose(matrix: list[list[int]], return_map: bool=True) -> list[list[int]] | map[list[int]]:
    if _check_not_integer(matrix):
        if return_map:
            return map(list, zip(*matrix))
        else:
            return list(map(list, zip(*matrix)))
    raise TypeError('Expected a matrix, got int/list instead')

def minor(matrix: list[list[int]], row: int, column: int) -> list[list[int]]:
    minor = matrix[:row] + matrix[row + 1:]
    return [row[:column] + row[column + 1:] for row in minor]

def determinant(matrix: list[list[int]]) -> Any:
    if len(matrix) == 1:
        return matrix[0][0]
    return sum((x * determinant(minor(matrix, 0, i)) * (-1) ** i for (i, x) in enumerate(matrix[0])))

def permanent(matrix: list[list[int]]) -> Any:
    if len(matrix) == 1:
        return matrix[0][0]
    return sum((x * permanent(minor(matrix, 0, i)) for (i, x) in enumerate(matrix[0])))

def inverse(matrix: list[list[int]]) -> list[list[float]] | None:
    det = determinant(matrix)
    if det == 0:
        return None
    matrix_minor = [[determinant(minor(matrix, i, j)) for j in range(len(matrix))] for i in range(len(matrix))]
    cofactors = [[x * (-1) ** (row + col) for (col, x) in enumerate(matrix_minor[row])] for row in range(len(matrix))]
    adjugate = list(transpose(cofactors))
    return scalar_multiply(adjugate, 1 / det)

def _verify_matrix_sizes(matrix_a: list[list[int]], matrix_b: list[list[int]]) -> tuple[tuple[int, int], tuple[int, int]]:
    shape = _shape(matrix_a) + _shape(matrix_b)
    if shape[0] != shape[3] or shape[1] != shape[2]:
        msg = f'operands could not be broadcast together with shape ({(shape[0], shape[1])}), ({(shape[2], shape[3])})'
        raise ValueError(msg)
    return ((shape[0], shape[2]), (shape[1], shape[3]))

def kronecker_product(matrix_a: list[list[int]], matrix_b: list[list[int]]) -> list[list[int]]:
    if not all((is_2d(matrix_a), is_2d(matrix_b))):
        raise ValueError('Input matrices must be 2-D.')
    if not matrix_a or not matrix_b:
        return []
    (rows_matrix_a, cols_matrix_a) = (len(matrix_a), len(matrix_a[0]))
    (rows_matrix_b, cols_matrix_b) = (len(matrix_b), len(matrix_b[0]))
    result = [[0] * (cols_matrix_a * cols_matrix_b) for _ in range(rows_matrix_a * rows_matrix_b)]
    for r_index_a in range(rows_matrix_a):
        for c_index_a in range(cols_matrix_a):
            for r_index_b in range(rows_matrix_b):
                for c_index_b in range(cols_matrix_b):
                    result[r_index_a * rows_matrix_b + r_index_b][c_index_a * cols_matrix_b + c_index_b] = matrix_a[r_index_a][c_index_a] * matrix_b[r_index_b][c_index_b]
    return result

