    while mid <= high:
        if sequence[mid] == colors[0]:
            (sequence[low], sequence[mid]) = (sequence[mid], sequence[low])
            low += 1
            mid += 1
        elif sequence[mid] == colors[1]:
            mid += 1
        elif sequence[mid] == colors[2]:
            (sequence[mid], sequence[high]) = (sequence[high], sequence[mid])
            high -= 1
        else:
            msg = f'The elements inside the sequence must contains only {colors} values'
            raise ValueError(msg)
    return sequence

def cyclic_sort(nums: list[int]) -> list[int]:
    seen = set()
    n = len(nums)
    for num in nums:
        if num in seen:
            message = f'All numbers must be unique, got {num}'
            raise ValueError(message)
        if num < 1 or num > n:
            message = f'All numbers must be in range 1 to {n}, got {num}'
            raise ValueError(message)
        seen.add(num)
    index = 0
    while index < len(nums):
        correct_index = nums[index] - 1
        if index != correct_index:
            (nums[index], nums[correct_index]) = (nums[correct_index], nums[index])
        else:
            index += 1
    return nums

def msd_radix_sort(list_of_ints: list[int]) -> list[int]:
    if not list_of_ints:
        return []
    if min(list_of_ints) < 0:
        raise ValueError('All numbers must be positive')
    most_bits = max((len(bin(x)[2:]) for x in list_of_ints))
    return _msd_radix_sort(list_of_ints, most_bits)

def _msd_radix_sort(list_of_ints: list[int], bit_position: int) -> list[int]:
    if bit_position == 0 or len(list_of_ints) in [0, 1]:
        return list_of_ints
    zeros = []
    ones = []
    for number in list_of_ints:
        if number >> bit_position - 1 & 1:
            ones.append(number)
        else:
            zeros.append(number)
    zeros = _msd_radix_sort(zeros, bit_position - 1)
    ones = _msd_radix_sort(ones, bit_position - 1)
    res = zeros
    res.extend(ones)
    return res

def msd_radix_sort_inplace(list_of_ints: list[int]) -> None:
    length = len(list_of_ints)
    if not list_of_ints or length == 1:
        return
    if min(list_of_ints) < 0:
        raise ValueError('All numbers must be positive')
    most_bits = max((len(bin(x)[2:]) for x in list_of_ints))
    _msd_radix_sort_inplace(list_of_ints, most_bits, 0, length)

def _msd_radix_sort_inplace(list_of_ints: list[int], bit_position: int, begin_index: int, end_index: int) -> None:
    if bit_position == 0 or end_index - begin_index <= 1:
        return
    bit_position -= 1
    i = begin_index
    j = end_index - 1
    while i <= j:
        changed = False
        if not list_of_ints[i] >> bit_position & 1:
            i += 1
            changed = True
        if list_of_ints[j] >> bit_position & 1:
            j -= 1
            changed = True
        if changed:
            continue
        (list_of_ints[i], list_of_ints[j]) = (list_of_ints[j], list_of_ints[i])
        j -= 1
        if j != i:
            i += 1
    _msd_radix_sort_inplace(list_of_ints, bit_position, begin_index, i)
    _msd_radix_sort_inplace(list_of_ints, bit_position, i, end_index)

def radix_sort(list_of_ints: list[int]) -> list[int]:
    if not list_of_ints:
        return []
    if any((i < 0 for i in list_of_ints)):
        raise ValueError('All elements in list_of_ints must be non-negative integers')
    placement = 1
    max_digit = max(list_of_ints)
    while placement <= max_digit:
        buckets: list[list] = [[] for _ in range(RADIX)]
        for i in list_of_ints:
            tmp = int(i / placement % RADIX)
            buckets[tmp].append(i)
        a = 0
        for b in range(RADIX):
            for i in buckets[b]:
                list_of_ints[a] = i
                a += 1
        placement *= RADIX
    return list_of_ints

def flash_sort(arr: list[int | float]) -> list[int | float]:
    if len(arr) <= 1:
        return arr.copy()
    result = arr.copy()
    n = len(result)
    min_val = min(result)
    max_val = max(result)
    if min_val == max_val:
        return result
    m = max(1, int(0.45 * n))
    class_sizes = [0] * m
    c1 = (m - 1) / (max_val - min_val)
    for value in result:
        class_index = int(c1 * (value - min_val))
        if class_index >= m:
            class_index = m - 1
        class_sizes[class_index] += 1
    for i in range(1, m):
        class_sizes[i] += class_sizes[i - 1]

    def class_of(value: float) -> int:
        return min(int(c1 * (value - min_val)), m - 1)
    moves = 0
    j = 0
    k = m - 1
    while moves < n - 1:
        while j > class_sizes[k] - 1:
            j += 1
            k = class_of(result[j])
        flash = result[j]
        while j != class_sizes[k]:
            k = class_of(flash)
            class_sizes[k] -= 1
            (result[class_sizes[k]], flash) = (flash, result[class_sizes[k]])
            moves += 1
    for i in range(1, n):
        key = result[i]
        j = i - 1
        while j >= 0 and result[j] > key:
            result[j + 1] = result[j]
            j -= 1
        result[j + 1] = key
    return result

def wiggle_sort(nums: list) -> list:
    for i in range(1, len(nums)):
        if i % 2 == 1 and nums[i - 1] > nums[i] or (i % 2 == 0 and nums[i - 1] < nums[i]):
            (nums[i - 1], nums[i]) = (nums[i], nums[i - 1])
    return nums

def bead_sort(sequence: list) -> list:
    if any((not isinstance(x, int) or x < 0 for x in sequence)):
        raise TypeError('Sequence must be list of non-negative integers')
    for _ in range(len(sequence)):
        for (i, (rod_upper, rod_lower)) in enumerate(zip(sequence, sequence[1:])):
            if rod_upper > rod_lower:
                sequence[i] -= rod_upper - rod_lower
                sequence[i + 1] += rod_upper - rod_lower
    return sequence

def stalin_sort(sequence: list[int]) -> list[int]:
    if not sequence:
        return []
    result = [sequence[0]]
    for element in sequence[1:]:
        if element >= result[-1]:
            result.append(element)
    return result

def natural_sort(input_list: list[str]) -> list[str]:

    def alphanum_key(key):
        return [int(s) if s.isdigit() else s.lower() for s in re.split('([0-9]+)', key)]
    return sorted(input_list, key=alphanum_key)

def _numerator(impulse_response: np.ndarray, denominator: np.ndarray, numerator_order: int) -> np.ndarray:
    length = impulse_response.size
    impulse = lfilter([1.0], denominator.ravel(), unit_impulse(length))
    toep = toeplitz(impulse, unit_impulse(numerator_order + 1))
    return np.linalg.lstsq(toep.conj(), impulse_response.ravel().conj(), rcond=None)[0].conj()

def get_bounds(fft_results: np.ndarray, samplerate: int) -> tuple[int | float, int | float]:
    lowest = min([-20, np.min(fft_results[1:samplerate // 2 - 1])])
    highest = max([20, np.max(fft_results[1:samplerate // 2 - 1])])
    return (lowest, highest)

def _validate_frequency(frequency: int, samplerate: int, q_factor: float) -> None:
    if not isinstance(frequency, int) or frequency <= 0:
        raise ValueError('frequency must be a positive integer')
    if not isinstance(samplerate, int) or samplerate <= 0:
        raise ValueError('samplerate must be a positive integer')
    if frequency >= samplerate / 2:
        raise ValueError('frequency must be less than half the samplerate')
    if q_factor <= 0:
        raise ValueError('q_factor must be positive')

def has_path_sum(root: TreeNode | None, sum: int) -> bool:
    if root is None:
        return False
    if root.left is None and root.right is None and (root.val == sum):
        return True
    sum -= root.val
    return has_path_sum(root.left, sum) or has_path_sum(root.right, sum)

def has_path_sum2(root: TreeNode | None, sum: int) -> bool:
    if root is None:
        return False
    stack: list[tuple[TreeNode, int]] = [(root, root.val)]
    while stack:
        (node, val) = stack.pop()
        if node.left is None and node.right is None and (val == sum):
            return True
        if node.left is not None:
            stack.append((node.left, val + node.left.val))
        if node.right is not None:
            stack.append((node.right, val + node.right.val))
    return False

def has_path_sum3(root: TreeNode | None, sum: int) -> bool:
    if root is None:
        return False
    queue: deque[tuple[TreeNode, int]] = deque([(root, sum - root.val)])
    while queue:
        (node, val) = queue.popleft()
        if node.left is None and node.right is None and (val == 0):
            return True
        if node.left is not None:
            queue.append((node.left, val - node.left.val))
        if node.right is not None:
            queue.append((node.right, val - node.right.val))
    return False

def depth_sum(root, n):
    if root:
        return recur_depth_sum(root, 1)

def recur_depth_sum(root, n):
    if root is None:
        return 0
    elif root.left is None and root.right is None:
        return root.data * n
    else:
        return n * root.data + recur_depth_sum(root.left, n + 1) + recur_depth_sum(root.right, n + 1)

def max_path_sum(root: TreeNode | None) -> float:
    (_, maximum) = _helper(root)
    return maximum

def _helper(root: TreeNode | None) -> tuple[float, float]:
    if root is None:
        return (0, float('-inf'))
    (left_branch, left_maximum) = _helper(root.left)
    (right_branch, right_maximum) = _helper(root.right)
    branch = root.val + max(0, left_branch, right_branch)
    through_root = root.val + max(0, left_branch) + max(0, right_branch)
    maximum = max(through_root, left_maximum, right_maximum)
    return (branch, maximum)

def is_same_tree(tree_p: TreeNode | None, tree_q: TreeNode | None) -> bool:
    if tree_p is None and tree_q is None:
        return True
    if tree_p is not None and tree_q is not None and (tree_p.val == tree_q.val):
        return is_same_tree(tree_p.left, tree_q.left) and is_same_tree(tree_p.right, tree_q.right)
    return False

def reverse(root: TreeNode | None) -> None:
    if root is None:
        return
    (root.left, root.right) = (root.right, root.left)
    if root.left:
        reverse(root.left)
    if root.right:
        reverse(root.right)

def lowest_common_ancestor(root, p, q):
    while root:
        if p.val > root.val < q.val:
            root = root.right
        elif p.val < root.val > q.val:
            root = root.left
        else:
            return root

def num_trees(n):
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1):
        for j in range(i + 1):
            dp[i] += dp[i - j] * dp[j - 1]
    return dp[-1]

def _get_depth(root: TreeNode | None) -> int:
    if root is None:
        return 0
    left = _get_depth(root.left)
    right = _get_depth(root.right)
    if abs(left - right) > 1 or -1 in [left, right]:
        return -1
    return 1 + max(left, right)

def preorder(root):
    res = []
    if not root:
        return res
    stack = []
    stack.append(root)
    while stack:
        root = stack.pop()
        res.append(root.val)
        if root.right:
            stack.append(root.right)
        if root.left:
            stack.append(root.left)
    return res

def preorder_rec(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    res.append(root.val)
    preorder_rec(root.left, res)
    preorder_rec(root.right, res)
    return res

def successor(root, node):
    succ = None
    while root:
        if node.val < root.val:
            succ = root
            root = root.left
        else:
            root = root.right
    return succ

def binary_tree_paths(root: TreeNode | None) -> list[str]:
    result: list[str] = []
    if root is None:
        return result
    _dfs(result, root, str(root.val))
    return result

def _dfs(result: list[str], root: TreeNode, current: str) -> None:
    if root.left is None and root.right is None:
        result.append(current)
    if root.left:
        _dfs(result, root.left, current + '->' + str(root.left.val))
    if root.right:
        _dfs(result, root.right, current + '->' + str(root.right.val))

def is_bst(root):
    stack = []
    pre = None
    while root or stack:
        while root:
            stack.append(root)
            root = root.left
        root = stack.pop()
        if pre and root.val <= pre.val:
            return False
        pre = root
        root = root.right
    return True

def kth_smallest(root, k):
    stack = []
    while root or stack:
        while root:
            stack.append(root)
            root = root.left
        root = stack.pop()
        k -= 1
        if k == 0:
            break
        root = root.right
    return root.val

def tree_print(tree: dict) -> list[str]:
    lines: list[str] = []
    for key in tree:
        parts = [str(key)]
        tree_element = tree[key]
        for sub_elem in tree_element:
            parts.append(str(sub_elem))
        lines.append(' -> '.join(parts))
    return lines

def is_symmetric(root: TreeNode | None) -> bool:
    if root is None:
        return True
    return _helper(root.left, root.right)

def _helper(p: TreeNode | None, q: TreeNode | None) -> bool:
    if p is None and q is None:
        return True
    if p is not None or q is not None or q.val != p.val:
        return False
    return _helper(p.left, q.right) and _helper(p.right, q.left)

def is_symmetric_iterative(root: TreeNode | None) -> bool:
    if root is None:
        return True
    stack: list[list[TreeNode | None]] = [[root.left, root.right]]
    while stack:
        (left, right) = stack.pop()
        if left is None and right is None:
            continue
        if left is None or right is None:
            return False
        if left.val == right.val:
            stack.append([left.left, right.right])
            stack.append([left.right, right.left])
        else:
            return False
    return True

def is_subtree(big: TreeNode, small: TreeNode) -> bool:
    flag = False
    queue: collections.deque[TreeNode] = collections.deque()
    queue.append(big)
    while queue:
        node = queue.popleft()
        if node.val == small.val:
            flag = _comp(node, small)
            break
        else:
            queue.append(node.left)
            queue.append(node.right)
    return flag

def _comp(p: TreeNode | None, q: TreeNode | None) -> bool:
    if p is None and q is None:
        return True
    if p is not None and q is not None:
        return p.val == q.val and _comp(p.left, q.left) and _comp(p.right, q.right)
    return False

def max_height(root: TreeNode | None) -> int:
    if root is None:
        return 0
    height = 0
    queue: deque[TreeNode] = deque([root])
    while queue:
        height += 1
        level: deque[TreeNode] = deque()
        while queue:
            node = queue.popleft()
            if node.left is not None:
                level.append(node.left)
            if node.right is not None:
                level.append(node.right)
        queue = level
    return height

def postorder(root):
    res_temp = []
    res = []
    if not root:
        return res
    stack = []
    stack.append(root)
    while stack:
        root = stack.pop()
        res_temp.append(root.val)
        if root.left:
            stack.append(root.left)
        if root.right:
            stack.append(root.right)
    while res_temp:
        res.append(res_temp.pop())
    return res

def postorder_rec(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    postorder_rec(root.left, res)
    postorder_rec(root.right, res)
    res.append(root.val)
    return res

def count_left_node(root):
    if root is None:
        return 0
    elif root.left is None:
        return count_left_node(root.right)
    else:
        return 1 + count_left_node(root.left) + count_left_node(root.right)

def min_depth(self: object, root: TreeNode | None) -> int:
    if root is None:
        return 0
    if root.left is not None or root.right is not None:
        return max(self.minDepth(root.left), self.minDepth(root.right)) + 1
    return min(self.minDepth(root.left), self.minDepth(root.right)) + 1

def min_height(root: TreeNode | None) -> int:
    if root is None:
        return 0
    height = 0
    level: list[TreeNode] = [root]
    while level:
        height += 1
        new_level: list[TreeNode] = []
        for node in level:
            if node.left is None and node.right is None:
                return height
            if node.left is not None:
                new_level.append(node.left)
            if node.right is not None:
                new_level.append(node.right)
        level = new_level
    return height

def bin_tree_to_list(root: TreeNode | None) -> TreeNode | None:
    if not root:
        return root
    root = _bin_tree_to_list_util(root)
    while root.left:
        root = root.left
    return root

def _bin_tree_to_list_util(root: TreeNode | None) -> TreeNode | None:
    if not root:
        return root
    if root.left:
        left = _bin_tree_to_list_util(root.left)
        while left.right:
            left = left.right
        left.right = root
        root.left = left
    if root.right:
        right = _bin_tree_to_list_util(root.right)
        while right.left:
            right = right.left
        right.left = root
        root.right = right
    return root

def validate_bst(node):
    if not node:
        return (True, None, None)
    (valid_left, minn_left, maxx_left) = validate_bst(node.left)
    (valid_right, minn_right, maxx_right) = validate_bst(node.right)
    if not valid_left or not valid_right:
        return (False, minn_left if minn_left is not None else node.val, maxx_right if maxx_right is not None else node.val)
    if maxx_left is not None and maxx_left > node.val:
        return (False, minn_left if minn_left is not None else node.val, maxx_right if maxx_right is not None else node.val)
    if minn_right is not None and minn_right < node.val:
        return (False, minn_left if minn_left is not None else node.val, maxx_right if maxx_right is not None else node.val)
    return (True, minn_left if minn_left is not None else node.val, maxx_right if maxx_right is not None else node.val)

def serialize(root):

    def build_string(node):
        if node:
            vals.append(str(node.val))
            build_string(node.left)
            build_string(node.right)
        else:
            vals.append('#')
    vals = []
    build_string(root)
    return ' '.join(vals)

def deserialize(data):

    def build_tree():
        val = next(vals)
        if val == '#':
            return None
        node = TreeNode(int(val))
        node.left = build_tree()
        node.right = build_tree()
        return node
    vals = iter(data.split())
    return build_tree()

def predecessor(root, node):
    pred = None
    while root:
        if node.val > root.val:
            pred = root
            root = root.right
        else:
            root = root.left
    return pred

def construct_tree_util(pre: list[int], post: list[int], low: int, high: int, size: int) -> TreeNode | None:
    global pre_index
    if low == 0 and high == size - 1:
        pre_index = 0
    if pre_index >= size or low > high:
        return None
    root = TreeNode(pre[pre_index])
    pre_index += 1
    if low == high or pre_index >= size:
        return root
    i = low
    while i <= high:
        if pre[pre_index] == post[i]:
            break
        i += 1
    if i <= high:
        root.left = construct_tree_util(pre, post, low, i, size)
        root.right = construct_tree_util(pre, post, i + 1, high, size)
    return root

def construct_tree(pre: list[int], post: list[int], size: int) -> list[int]:
    root = construct_tree_util(pre, post, 0, size - 1, size)
    return _inorder(root)

def _inorder(root: TreeNode | None, result: list[int] | None=None) -> list[int]:
    if root is None:
        return []
    if result is None:
        result = []
    _inorder(root.left, result)
    result.append(root.val)
    _inorder(root.right, result)
    return result

def closest_value(root, target):
    a = root.val
    kid = root.left if target < a else root.right
    if not kid:
        return a
    b = closest_value(kid, target)
    return min((a, b), key=lambda x: abs(target - x))

def lca(root: TreeNode | None, p: TreeNode, q: TreeNode) -> TreeNode | None:
    if root is None or root is p or root is q:
        return root
    left = lca(root.left, p, q)
    right = lca(root.right, p, q)
    if left is not None and right is not None:
        return root
    return left if left else right

def path_sum(root: TreeNode | None, sum: int) -> list[list[int]]:
    if root is None:
        return []
    result: list[list[int]] = []
    _dfs(root, sum, [], result)
    return result

def _dfs(root: TreeNode, sum: int, path: list[int], result: list[list[int]]) -> None:
    if root.left is None and root.right is None and (root.val == sum):
        path.append(root.val)
        result.append(path)
    if root.left is not None:
        _dfs(root.left, sum - root.val, path + [root.val], result)
    if root.right is not None:
        _dfs(root.right, sum - root.val, path + [root.val], result)

def path_sum2(root: TreeNode | None, target: int) -> list[list[int]]:
    if root is None:
        return []
    result: list[list[int]] = []
    stack: list[tuple[TreeNode, list[int]]] = [(root, [root.val])]
    while stack:
        (node, path) = stack.pop()
        if node.left is None and node.right is None and (sum(path) == target):
            result.append(path)
        if node.left is not None:
            stack.append((node.left, path + [node.left.val]))
        if node.right is not None:
            stack.append((node.right, path + [node.right.val]))
    return result

def path_sum3(root: TreeNode | None, sum: int) -> list[list[int]]:
    if root is None:
        return []
    result: list[list[int]] = []
    initial = (root, root.val, [root.val])
    queue: deque[tuple[TreeNode, int, list[int]]] = deque([initial])
    while queue:
        (node, val, path) = queue.popleft()
        if node.left is None and node.right is None and (val == sum):
            result.append(path)
        if node.left is not None:
            queue.append((node.left, val + node.left.val, path + [node.left.val]))
        if node.right is not None:
            queue.append((node.right, val + node.right.val, path + [node.right.val]))
    return result

def zigzag_level(root):
    res = []
    if not root:
        return res
    level = [root]
    flag = 1
    while level:
        current = []
        new_level = []
        for node in level:
            current.append(node.val)
            if node.left:
                new_level.append(node.left)
            if node.right:
                new_level.append(node.right)
        level = new_level
        res.append(current[::flag])
        flag *= -1
    return res

def longest_consecutive(root: TreeNode | None) -> int:
    if root is None:
        return 0
    max_len = 0
    _dfs(root, 0, root.val, max_len)
    return max_len

def _dfs(root: TreeNode | None, current: int, target: int, max_len: int) -> None:
    if root is None:
        return
    if root.val == target:
        current += 1
    else:
        current = 1
    max_len = max(current, max_len)
    _dfs(root.left, current, root.val + 1, max_len)
    _dfs(root.right, current, root.val + 1, max_len)

def height(root):
    if root is None:
        return 0
    else:
        return 1 + max(height(root.left), height(root.right))

def num_empty(root):
    if root is None:
        return 1
    elif root.left is None and root.right:
        return 1 + num_empty(root.right)
    elif root.right is None and root.left:
        return 1 + num_empty(root.left)
    else:
        return num_empty(root.left) + num_empty(root.right)

def level_order(root):
    ans = []
    if not root:
        return ans
    level = [root]
    while level:
        current = []
        new_level = []
        for node in level:
            current.append(node.val)
            if node.left:
                new_level.append(node.left)
            if node.right:
                new_level.append(node.right)
        level = new_level
        ans.append(current)
    return ans

def left_view(root: TreeNode | None) -> list[int]:
    if root is None:
        return []
    result: list[int] = []
    queue: deque[TreeNode] = deque([root])
    while queue:
        level_size = len(queue)
        for i in range(level_size):
            node = queue.popleft()
            if i == 0:
                result.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
    return result

def right_view(root: TreeNode | None) -> list[int]:
    if root is None:
        return []
    result: list[int] = []
    queue: deque[TreeNode] = deque([root])
    while queue:
        level_size = len(queue)
        for i in range(level_size):
            node = queue.popleft()
            if i == level_size - 1:
                result.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
    return result

def top_view(root: TreeNode | None) -> list[int]:
    if root is None:
        return []
    hd_map: dict[int, int] = {}
    queue: deque[tuple[TreeNode, int]] = deque([(root, 0)])
    while queue:
        (node, hd) = queue.popleft()
        if hd not in hd_map:
            hd_map[hd] = node.val
        if node.left:
            queue.append((node.left, hd - 1))
        if node.right:
            queue.append((node.right, hd + 1))
    return [hd_map[k] for k in sorted(hd_map)]

def bottom_view(root: TreeNode | None) -> list[int]:
    if root is None:
        return []
    hd_map: dict[int, int] = {}
    queue: deque[tuple[TreeNode, int]] = deque([(root, 0)])
    while queue:
        (node, hd) = queue.popleft()
        hd_map[hd] = node.val
        if node.left:
            queue.append((node.left, hd - 1))
        if node.right:
            queue.append((node.right, hd + 1))
    return [hd_map[k] for k in sorted(hd_map)]

def find_deepest_left(root: TreeNode | None, is_left: bool, depth: int, res: DeepestLeft) -> None:
    if not root:
        return
    if is_left and depth > res.depth:
        res.depth = depth
        res.Node = root
    find_deepest_left(root.left, True, depth + 1, res)
    find_deepest_left(root.right, False, depth + 1, res)

def inorder(root):
    res = []
    if not root:
        return res
    stack = []
    while root or stack:
        while root:
            stack.append(root)
            root = root.left
        root = stack.pop()
        res.append(root.val)
        root = root.right
    return res

def inorder_rec(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    inorder_rec(root.left, res)
    res.append(root.val)
    inorder_rec(root.right, res)
    return res

def flip_bit_longest_seq(number: int) -> int:
    current_length = 0
    previous_length = 0
    max_length = 0
    while number:
        if number & 1 == 1:
            current_length += 1
        elif number & 1 == 0:
            previous_length = 0 if number & 2 == 0 else current_length
            current_length = 0
        max_length = max(max_length, previous_length + current_length)
        number >>= 1
    return max_length + 1

def count_ones_recur(number: int) -> int:
    if not number:
        return 0
    return 1 + count_ones_recur(number & number - 1)

def count_ones_iter(number: int) -> int:
    count = 0
    while number:
        number &= number - 1
        count += 1
    return count

def binary_gap(number: int) -> int:
    last_one_position = None
    longest_gap = 0
    index = 0
    while number != 0:
        if number & 1:
            if last_one_position is not None:
                longest_gap = max(longest_gap, index - last_one_position)
            last_one_position = index
        index += 1
        number >>= 1
    return longest_gap

def reverse_bits(number: int) -> int:
    result = 0
    for _ in range(32):
        result = (result << 1) + (number & 1)
        number >>= 1
    return result

def clear_bit(number: int, position: int) -> int:
    mask = ~(1 << position)
    return number & mask

def update_bit(number: int, position: int, bit: int) -> int:
    mask = ~(1 << position)
    return number & mask | bit << position

def single_number3(nums: list[int]) -> list[int]:
    xor_both = 0
    for number in nums:
        xor_both ^= number
    rightmost_set_bit = xor_both & -xor_both
    (first, second) = (0, 0)
    for number in nums:
        if number & rightmost_set_bit:
            first ^= number
        else:
            second ^= number
    return [first, second]

def gray_to_binary(gray: int) -> int:
    mask = gray >> 1
    while mask:
        gray ^= mask
        mask >>= 1
    return gray

def single_number2(nums: list[int]) -> int:
    (ones, twos) = (0, 0)
    for index in range(len(nums)):
        ones = (ones ^ nums[index]) & ~twos
        twos = (twos ^ nums[index]) & ~ones
    return ones

def single_number(nums: list[int]) -> int:
    result = 0
    for number in nums:
        result ^= number
    return result

def add_bitwise_operator(first: int, second: int) -> int:
    if first < 0 or second < 0:
        raise ValueError('The provided values must be non-negative!')
    while second:
        carry = first & second
        first = first ^ second
        second = carry << 1
    return first

def int_to_bytes_big_endian(number: int) -> bytes:
    byte_buffer: deque[int] = deque()
    while number > 0:
        byte_buffer.appendleft(number & 255)
        number >>= 8
    return bytes(byte_buffer)

def int_to_bytes_little_endian(number: int) -> bytes:
    byte_buffer: list[int] = []
    while number > 0:
        byte_buffer.append(number & 255)
        number >>= 8
    return bytes(byte_buffer)

def bytes_big_endian_to_int(byte_string: bytes) -> int:
    number = 0
    for byte in byte_string:
        number <<= 8
        number += byte
    return number

def find_difference(original: str, shuffled: str) -> str:
    xor_result = 0
    for character in original + shuffled:
        xor_result ^= ord(character)
    return chr(xor_result)

def find_missing_number(nums: list[int]) -> int:
    missing = 0
    for (index, number) in enumerate(nums):
        missing ^= number
        missing ^= index + 1
    return missing

def has_alternative_bit(number: int) -> bool:
    first_bit = 0
    second_bit = 0
    while number:
        first_bit = number & 1
        if number >> 1:
            second_bit = number >> 1 & 1
            if not first_bit ^ second_bit:
                return False
        else:
            return True
        number >>= 1
    return True

def has_alternative_bit_fast(number: int) -> bool:
    mask_even_bits = int('aaaaaaaa', 16)
    mask_odd_bits = int('55555555', 16)
    return mask_even_bits == number + (number ^ mask_even_bits) or mask_odd_bits == number + (number ^ mask_odd_bits)

def longest_non_repeat_v1(string: str) -> int:
    if string is None:
        return 0
    char_index = {}
    max_length = 0
    start = 0
    for index in range(len(string)):
        if string[index] in char_index:
            start = max(char_index[string[index]], start)
        char_index[string[index]] = index + 1
        max_length = max(max_length, index - start + 1)
    return max_length

def longest_non_repeat_v2(string: str) -> int:
    if string is None:
        return 0
    (start, max_length) = (0, 0)
    used_char = {}
    for (index, char) in enumerate(string):
        if char in used_char and start <= used_char[char]:
            start = used_char[char] + 1
        else:
            max_length = max(max_length, index - start + 1)
        used_char[char] = index
    return max_length

def get_longest_non_repeat_v1(string: str) -> tuple[int, str]:
    if string is None:
        return (0, '')
    substring = ''
    char_index = {}
    max_length = 0
    start = 0
    for index in range(len(string)):
        if string[index] in char_index:
            start = max(char_index[string[index]], start)
        char_index[string[index]] = index + 1
        if index - start + 1 > max_length:
            max_length = index - start + 1
            substring = string[start:index + 1]
    return (max_length, substring)

def get_longest_non_repeat_v2(string: str) -> tuple[int, str]:
    if string is None:
        return (0, '')
    substring = ''
    (start, max_length) = (0, 0)
    used_char = {}
    for (index, char) in enumerate(string):
        if char in used_char and start <= used_char[char]:
            start = used_char[char] + 1
        elif index - start + 1 > max_length:
            max_length = index - start + 1
            substring = string[start:index + 1]
        used_char[char] = index
    return (max_length, substring)

def get_longest_non_repeat_v3(string: str) -> tuple[int, str]:
    longest_substring = ''
    seen = set()
    start_index = 0
    for i in range(len(string)):
        while string[i] in seen:
            seen.remove(string[start_index])
            start_index += 1
        seen.add(string[i])
        longest_substring = max(longest_substring, string[start_index:i + 1], key=len)
    return (len(longest_substring), longest_substring)

def flatten(input_arr: Iterable[Any], output_arr: list[Any] | None=None) -> list[Any]:
    if output_arr is None:
        output_arr = []
    for element in input_arr:
        if not isinstance(element, str) and isinstance(element, Iterable):
            flatten(element, output_arr)
        else:
            output_arr.append(element)
    return output_arr

def flatten_iter(iterable: Iterable[Any]) -> Generator[Any, None, None]:
    for element in iterable:
        if not isinstance(element, str) and isinstance(element, Iterable):
            yield from flatten_iter(element)
        else:
            yield element

def max_ones_index(array: list[int]) -> int:
    length = len(array)
    max_count = 0
    max_index = 0
    prev_zero = -1
    prev_prev_zero = -1
    for current in range(length):
        if array[current] == 0:
            if current - prev_prev_zero > max_count:
                max_count = current - prev_prev_zero
                max_index = prev_zero
            prev_prev_zero = prev_zero
            prev_zero = current
    if length - prev_prev_zero > max_count:
        max_index = prev_zero
    return max_index

def plus_one_v2(digits: list[int]) -> list[int]:
    length = len(digits)
    for index in range(length - 1, -1, -1):
        if digits[index] < 9:
            digits[index] += 1
            return digits
        digits[index] = 0
    digits.insert(0, 1)
    return digits

def plus_one_v3(num_arr: list[int]) -> list[int]:
    for idx in reversed(list(enumerate(num_arr))):
        num_arr[idx[0]] = (num_arr[idx[0]] + 1) % 10
        if num_arr[idx[0]]:
            return num_arr
    return [1] + num_arr

def n_sum(n: int, nums: list[Any], target: Any, **kv: Callable[..., Any]) -> list[list[Any]]:

    def _sum_closure_default(a: Any, b: Any) -> Any:
        return a + b

    def _compare_closure_default(num: Any, target: Any) -> int:
        if num < target:
            return -1
        elif num > target:
            return 1
        else:
            return 0

    def _same_closure_default(a: Any, b: Any) -> bool:
        return a == b

    def _n_sum_inner(n: int, nums: list[Any], target: Any) -> list[list[Any]]:
        if n == 2:
            results = _two_sum(nums, target)
        else:
            results = []
            prev_num = None
            for (index, num) in enumerate(nums):
                if prev_num is not None and same_closure(prev_num, num):
                    continue
                prev_num = num
                n_minus1_results = _n_sum_inner(n - 1, nums[index + 1:], target - num)
                n_minus1_results = _append_elem_to_each_list(num, n_minus1_results)
                results += n_minus1_results
        return _union(results)

    def _two_sum(nums: list[Any], target: Any) -> list[list[Any]]:
        nums.sort()
        left = 0
        right = len(nums) - 1
        results = []
        while left < right:
            current_sum = sum_closure(nums[left], nums[right])
            flag = compare_closure(current_sum, target)
            if flag == -1:
                left += 1
            elif flag == 1:
                right -= 1
            else:
                results.append(sorted([nums[left], nums[right]]))
                left += 1
                right -= 1
                while left < len(nums) and same_closure(nums[left - 1], nums[left]):
                    left += 1
                while right >= 0 and same_closure(nums[right], nums[right + 1]):
                    right -= 1
        return results

    def _append_elem_to_each_list(elem: Any, container: list[list[Any]]) -> list[list[Any]]:
        results = []
        for elems in container:
            elems.append(elem)
            results.append(sorted(elems))
        return results

    def _union(duplicate_results: list[list[Any]]) -> list[list[Any]]:
        results = []
        if len(duplicate_results) != 0:
            duplicate_results.sort()
            results.append(duplicate_results[0])
            for result in duplicate_results[1:]:
                if results[-1] != result:
                    results.append(result)
        return results
    sum_closure = kv.get('sum_closure', _sum_closure_default)
    same_closure = kv.get('same_closure', _same_closure_default)
    compare_closure = kv.get('compare_closure', _compare_closure_default)
    nums.sort()
    return _n_sum_inner(n, nums, target)

def missing_ranges(array: list[int], low: int, high: int) -> list[tuple[int, int]]:
    result = []
    start = low
    for num in array:
        if num == start:
            start += 1
        elif num > start:
            result.append((start, num - 1))
            start = num + 1
    if start <= high:
        result.append((start, high))
    return result

def limit(array: list[int], min_lim: int | None=None, max_lim: int | None=None) -> list[int]:
    if len(array) == 0:
        return array
    if min_lim is None:
        min_lim = min(array)
    if max_lim is None:
        max_lim = max(array)
    return list(filter(lambda x: min_lim <= x <= max_lim, array))

def summarize_ranges(array: list[int]) -> list[tuple[int, ...]]:
    result = []
    if len(array) == 0:
        return []
    if len(array) == 1:
        return [(array[0], array[0])]
    iterator = iter(array)
    start = end = next(iterator)
    for num in iterator:
        if num - end == 1:
            end = num
        else:
            result.append((start, end))
            start = end = num
    result.append((start, end))
    return result

def move_zeros(array: list[Any]) -> list[Any]:
    result = []
    zeros = 0
    for element in array:
        if element == 0 and type(element) is not bool:
            zeros += 1
        else:
            result.append(element)
    result.extend([0] * zeros)
    return result

def three_sum(array: list[int]) -> set[tuple[int, int, int]]:
    result = set()
    array.sort()
    for i in range(len(array) - 2):
        if i > 0 and array[i] == array[i - 1]:
            continue
        (left, right) = (i + 1, len(array) - 1)
        while left < right:
            current_sum = array[i] + array[left] + array[right]
            if current_sum > 0:
                right -= 1
            elif current_sum < 0:
                left += 1
            else:
                result.add((array[i], array[left], array[right]))
                while left < right and array[left] == array[left + 1]:
                    left += 1
                while left < right and array[right] == array[right - 1]:
                    right -= 1
                left += 1
                right -= 1
    return result

def trimmean(array: list[float], percentage: float) -> float:
    ratio = percentage / 200
    array.sort()
    trim_count = int(len(array) * ratio)
    trimmed = array[trim_count:len(array) - trim_count]
    total = 0
    for value in trimmed:
        total += value
    return total / len(trimmed)

def top_1(array: list[Any]) -> list[Any]:
    frequency = {}
    for element in array:
        if element in frequency:
            frequency[element] += 1
        else:
            frequency[element] = 1
    max_count = max(frequency.values())
    result = []
    for (element, count) in frequency.items():
        if count == max_count:
            result.append(element)
    return result

def delete_nth_naive(array: list[int], n: int) -> list[int]:
    result = []
    for num in array:
        if result.count(num) < n:
            result.append(num)
    return result

def delete_nth(array: list[int], n: int) -> list[int]:
    result = []
    counts = collections.defaultdict(int)
    for element in array:
        if counts[element] < n:
            result.append(element)
            counts[element] += 1
    return result

def rotate_v1(array: list[int], k: int) -> list[int]:
    array = array[:]
    length = len(array)
    for _ in range(k):
        temp = array[length - 1]
        for position in range(length - 1, 0, -1):
            array[position] = array[position - 1]
        array[0] = temp
    return array

def rotate_v3(array: list[int] | None, k: int) -> list[int] | None:
    if array is None:
        return None
    length = len(array)
    k = k % length
    return array[length - k:] + array[:length - k]

def two_sum(array: list[int], target: int) -> tuple[int, int] | None:
    seen = {}
    for (index, num) in enumerate(array):
        if num in seen:
            return (seen[num], index)
        else:
            seen[target - num] = index
    return None

def merge_intervals(intervals: list[list[int]]) -> list[list[int]] | None:
    if intervals is None:
        return None
    intervals.sort(key=lambda i: i[0])
    out = [intervals.pop(0)]
    for interval in intervals:
        if out[-1][-1] >= interval[0]:
            out[-1][-1] = max(out[-1][-1], interval[-1])
        else:
            out.append(interval)
    return out

def garage(initial: list[int], final: list[int]) -> tuple[int, list[list[int]]]:
    current = initial[:]
    sequence = []
    steps = 0
    while current != final:
        zero_pos = current.index(0)
        if zero_pos != final.index(0):
            target_car = final[zero_pos]
            target_pos = current.index(target_car)
            (current[zero_pos], current[target_pos]) = (current[target_pos], current[zero_pos])
        else:
            for i in range(len(current)):
                if current[i] != final[i]:
                    (current[zero_pos], current[i]) = (current[i], current[zero_pos])
                    break
        sequence.append(current[:])
        steps += 1
    return (steps, sequence)

def remove_duplicates(array: list[Any]) -> list[Any]:
    seen = set()
    unique_array = []
    for item in array:
        if isinstance(item, Hashable):
            if item not in seen:
                seen.add(item)
                unique_array.append(item)
        elif item not in unique_array:
            unique_array.append(item)
    return unique_array

def search_rotate(array: list[int], val: int) -> int:
    (low, high) = (0, len(array) - 1)
    while low <= high:
        mid = (low + high) // 2
        if val == array[mid]:
            return mid
        if array[low] <= array[mid]:
            if array[low] <= val <= array[mid]:
                high = mid - 1
            else:
                low = mid + 1
        elif array[mid] <= val <= array[high]:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def search_rotate_recur(array: list[int], low: int, high: int, val: int) -> int:
    if low > high:
        return -1
    mid = (low + high) // 2
    if val == array[mid]:
        return mid
    if array[low] <= array[mid]:
        if array[low] <= val <= array[mid]:
            return search_rotate_recur(array, low, mid - 1, val)
        return search_rotate_recur(array, mid + 1, high, val)
    if array[mid] <= val <= array[high]:
        return search_rotate_recur(array, mid + 1, high, val)
    return search_rotate_recur(array, low, mid - 1, val)

def binary_search(array: list[int], query: int) -> int:
    (low, high) = (0, len(array) - 1)
    while low <= high:
        mid = low + (high - low) // 2
        val = array[mid]
        if val == query:
            return mid
        if val < query:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_recur(array: list[int], low: int, high: int, val: int) -> int:
    if low > high:
        return -1
    mid = low + (high - low) // 2
    if val < array[mid]:
        return binary_search_recur(array, low, mid - 1, val)
    if val > array[mid]:
        return binary_search_recur(array, mid + 1, high, val)
    return mid

def search_range(nums: list[int], target: int) -> list[int]:
    low = 0
    high = len(nums) - 1
    while low < high:
        mid = low + (high - low) // 2
        if target <= nums[mid]:
            high = mid
        else:
            low = mid + 1
    for j in range(len(nums) - 1, -1, -1):
        if nums[j] == target:
            return [low, j]
    return [-1, -1]

def exponential_search(arr: list[int], target: int) -> int:
    if not arr:
        return -1
    if arr[0] == target:
        return 0
    bound = 1
    while bound < len(arr) and arr[bound] <= target:
        bound *= 2
    low = bound // 2
    high = min(bound, len(arr) - 1)
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def first_occurrence(array: list[int], query: int) -> int:
    (low, high) = (0, len(array) - 1)
    while low <= high:
        mid = low + (high - low) // 2
        if low == high:
            break
        if array[mid] < query:
            low = mid + 1
        else:
            high = mid
    if array[low] == query:
        return low
    return -1

def ternary_search(left: int, right: int, key: int, array: list[int]) -> int:
    while right >= left:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3
        if key == array[mid1]:
            return mid1
        if key == array[mid2]:
            return mid2
        if key < array[mid1]:
            right = mid1 - 1
        elif key > array[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1
    return -1

def next_greatest_letter(letters: list[str], target: str) -> str:
    index = bisect.bisect(letters, target)
    return letters[index % len(letters)]

def next_greatest_letter_v1(letters: list[str], target: str) -> str:
    if letters[0] > target:
        return letters[0]
    if letters[len(letters) - 1] <= target:
        return letters[0]
    (left, right) = (0, len(letters) - 1)
    while left <= right:
        mid = left + (right - left) // 2
        if letters[mid] > target:
            right = mid - 1
        else:
            left = mid + 1
    return letters[left]

def next_greatest_letter_v2(letters: list[str], target: str) -> str:
    for letter in letters:
        if letter > target:
            return letter
    return letters[0]

def search_insert(array: list[int], val: int) -> int:
    low = 0
    high = len(array) - 1
    while low <= high:
        mid = low + (high - low) // 2
        if val > array[mid]:
            low = mid + 1
        else:
            high = mid - 1
    return low

def linear_search(array: list[int], query: int) -> int:
    for (i, value) in enumerate(array):
        if value == query:
            return i
    return -1

def find_min_rotate(array: list[int]) -> int:
    low = 0
    high = len(array) - 1
    while low < high:
        mid = (low + high) // 2
        if array[mid] > array[high]:
            low = mid + 1
        else:
            high = mid
    return array[low]

def find_min_rotate_recur(array: list[int], low: int, high: int) -> int:
    mid = (low + high) // 2
    if mid == low:
        return array[low]
    if array[mid] > array[high]:
        return find_min_rotate_recur(array, mid + 1, high)
    return find_min_rotate_recur(array, low, mid)

def sentinel_search(arr: list[int], target: int) -> int:
    n = len(arr)
    if n == 0:
        return -1
    last = arr[-1]
    arr[-1] = target
    i = 0
    while arr[i] != target:
        i += 1
    arr[-1] = last
    if i < n - 1 or arr[-1] == target:
        return i
    return -1

def interpolation_search(array: list[int], search_key: int) -> int:
    high = len(array) - 1
    low = 0
    while low <= high and array[low] <= search_key <= array[high]:
        pos = low + int((search_key - array[low]) * (high - low) / (array[high] - array[low]))
        if array[pos] == search_key:
            return pos
        if array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1
    return -1

def two_sum(numbers: list[int], target: int) -> list[int] | None:
    for (i, number) in enumerate(numbers):
        second_val = target - number
        (low, high) = (i + 1, len(numbers) - 1)
        while low <= high:
            mid = low + (high - low) // 2
            if second_val == numbers[mid]:
                return [i + 1, mid + 1]
            if second_val > numbers[mid]:
                low = mid + 1
            else:
                high = mid - 1
    return None

def two_sum1(numbers: list[int], target: int) -> list[int] | None:
    seen: dict[int, int] = {}
    for (i, num) in enumerate(numbers):
        if target - num in seen:
            return [seen[target - num] + 1, i + 1]
        seen[num] = i
    return None

def two_sum2(numbers: list[int], target: int) -> list[int] | None:
    left = 0
    right = len(numbers) - 1
    while left < right:
        current_sum = numbers[left] + numbers[right]
        if current_sum == target:
            return [left + 1, right + 1]
        if current_sum > target:
            right = right - 1
        else:
            left = left + 1
    return None

def binary_search_first_true(low: int, high: int, predicate: Callable[[int], bool]) -> int:
    result = -1
    while low <= high:
        mid = low + (high - low) // 2
        if predicate(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1
    return result

def last_occurrence(array: list[int], query: int) -> int:
    (low, high) = (0, len(array) - 1)
    while low <= high:
        mid = (high + low) // 2
        if array[mid] == query and mid == len(array) - 1 or (array[mid] == query and array[mid + 1] > query):
            return mid
        if array[mid] <= query:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def jump_search(array: list[int], target: int) -> int:
    length = len(array)
    block_size = int(math.sqrt(length))
    block_prev = 0
    block = block_size
    if array[length - 1] < target:
        return -1
    while block <= length and array[block - 1] < target:
        block_prev = block
        block += block_size
    while array[block_prev] < target:
        block_prev += 1
        if block_prev == min(block, length):
            return -1
    if array[block_prev] == target:
        return block_prev
    return -1

def find_words(board: list[list[str]], words: list[str]) -> list[str]:
    trie: dict = {}
    for word in words:
        current_node = trie
        for char in word:
            if char not in current_node:
                current_node[char] = {}
            current_node = current_node[char]
        current_node['#'] = '#'
    found: set[str] = set()
    used = [[False] * len(board[0]) for _ in range(len(board))] if board else []
    for row in range(len(board)):
        for col in range(len(board[0])):
            _backtrack(board, row, col, trie, '', used, found)
    return list(found)

def _backtrack(board: list[list[str]], row: int, col: int, trie: dict, prefix: str, used: list[list[bool]], found: set[str]) -> None:
    if '#' in trie:
        found.add(prefix)
    if row < 0 or row >= len(board) or col < 0 or (col >= len(board[0])):
        return
    if not used[row][col] and board[row][col] in trie:
        used[row][col] = True
        next_char = board[row][col]
        _backtrack(board, row + 1, col, trie[next_char], prefix + next_char, used, found)
        _backtrack(board, row, col + 1, trie[next_char], prefix + next_char, used, found)
        _backtrack(board, row - 1, col, trie[next_char], prefix + next_char, used, found)
        _backtrack(board, row, col - 1, trie[next_char], prefix + next_char, used, found)
        used[row][col] = False

def permute(elements: list | str) -> list:
    if len(elements) <= 1:
        return [elements]
    result = []
    for perm in permute(elements[1:]):
        for i in range(len(elements)):
            result.append(perm[:i] + elements[0:1] + perm[i:])
    return result

def permute_iter(elements: list | str) -> Generator:
    if len(elements) <= 1:
        yield elements
    else:
        for perm in permute_iter(elements[1:]):
            for i in range(len(elements)):
                yield (perm[:i] + elements[0:1] + perm[i:])

def _dfs(result: list[list[int]], nums: list[int], path: list[int]) -> None:
    if not nums:
        result.append(path)
    for i in range(len(nums)):
        _dfs(result, nums[:i] + nums[i + 1:], path + [nums[i]])

def minimax(depth: int, is_maximizing: bool, scores: list[int], alpha: float=-math.inf, beta: float=math.inf) -> float:
    if depth == 0:
        return scores[0]
    mid = len(scores) // 2
    if is_maximizing:
        value = -math.inf
        value = max(value, minimax(depth - 1, False, scores[:mid], alpha, beta))
        alpha = max(alpha, value)
        if alpha < beta:
            value = max(value, minimax(depth - 1, False, scores[mid:], alpha, beta))
        return value
    else:
        value = math.inf
        value = min(value, minimax(depth - 1, True, scores[:mid], alpha, beta))
        beta = min(beta, value)
        if alpha < beta:
            value = min(value, minimax(depth - 1, True, scores[mid:], alpha, beta))
        return value

def subsets_unique(nums: list[int]) -> list[tuple[int, ...]]:
    found: set[tuple[int, ...]] = set()
    _backtrack(found, nums, [], 0)
    return list(found)

def _backtrack(found: set[tuple[int, ...]], nums: list[int], stack: list[int], position: int) -> None:
    if position == len(nums):
        found.add(tuple(stack))
    else:
        stack.append(nums[position])
        _backtrack(found, nums, stack, position + 1)
        stack.pop()
        _backtrack(found, nums, stack, position + 1)

def array_sum_combinations(array_a: list[int], array_b: list[int], array_c: list[int], target: int) -> list[list[int]]:
    arrays = [array_a, array_b, array_c]

    def _is_complete(constructed_so_far: list[int]) -> tuple[bool, bool]:
        total = sum(constructed_so_far)
        should_stop = total >= target or len(constructed_so_far) >= 3
        reached_target = total == target and len(constructed_so_far) == 3
        return (should_stop, reached_target)

    def _get_candidates(constructed_so_far: list[int]) -> list[int]:
        return arrays[len(constructed_so_far)]

    def _backtrack(constructed_so_far: list[int] | None=None, result: list[list[int]] | None=None) -> None:
        if constructed_so_far is None:
            constructed_so_far = []
        if result is None:
            result = []
        (should_stop, reached_target) = _is_complete(constructed_so_far)
        if should_stop:
            if reached_target:
                result.append(constructed_so_far)
            return
        candidates = _get_candidates(constructed_so_far)
        for candidate in candidates:
            constructed_so_far.append(candidate)
            _backtrack(constructed_so_far[:], result)
            constructed_so_far.pop()
    result: list[list[int]] = []
    _backtrack([], result)
    return result

def unique_array_sum_combinations(array_a: list[int], array_b: list[int], array_c: list[int], target: int) -> list[tuple[int, ...]]:

    def _check_sum(expected: int, *nums: int) -> tuple[bool, tuple[int, ...]]:
        if sum(nums) == expected:
            return (True, nums)
        else:
            return (False, nums)
    product = itertools.product(array_a, array_b, array_c)
    func = partial(_check_sum, target)
    sums = list(itertools.starmap(func, product))
    seen: set[tuple[int, ...]] = set()
    for (is_match, values) in sums:
        if is_match and values not in seen:
            seen.add(values)
    return list(seen)

def anagram(first: str, second: str) -> bool:
    count_first = [0] * 26
    count_second = [0] * 26
    for char in first:
        index = ord(char) - ord('a')
        count_first[index] += 1
    for char in second:
        index = ord(char) - ord('a')
        count_second[index] += 1
    return count_first == count_second

def permute_unique(nums: list[int]) -> list[list[int]]:
    permutations: list[list[int]] = [[]]
    for number in nums:
        new_permutations: list[list[int]] = []
        for existing in permutations:
            for i in range(len(existing) + 1):
                new_permutations.append(existing[:i] + [number] + existing[i:])
                if i < len(existing) and existing[i] == number:
                    break
        permutations = new_permutations
    return permutations

def letter_combinations(digits: str) -> list[str]:
    if digits == '':
        return []
    keypad_map = {'2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl', '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'}
    combinations: list[str] = ['']
    for digit in digits:
        expanded: list[str] = []
        for existing in combinations:
            for char in keypad_map[digit]:
                expanded.append(existing + char)
        combinations = expanded
    return combinations

def get_factors(number: int) -> list[list[int]]:
    todo: list[tuple[int, int, list[int]]] = [(number, 2, [])]
    combinations: list[list[int]] = []
    while todo:
        (remaining, divisor, partial) = todo.pop()
        while divisor * divisor <= remaining:
            if remaining % divisor == 0:
                combinations.append(partial + [divisor, remaining // divisor])
                todo.append((remaining // divisor, divisor, partial + [divisor]))
            divisor += 1
    return combinations

def recursive_get_factors(number: int) -> list[list[int]]:

    def _factor(remaining: int, divisor: int, partial: list[int], combinations: list[list[int]]) -> list[list[int]]:
        while divisor * divisor <= remaining:
            if remaining % divisor == 0:
                combinations.append(partial + [divisor, remaining // divisor])
                _factor(remaining // divisor, divisor, partial + [divisor], combinations)
            divisor += 1
        return combinations
    return _factor(number, 2, [], [])

def add_operators(digits: str, target: int) -> list[str]:
    result: list[str] = []
    if not digits:
        return result
    _dfs(result, '', digits, target, 0, 0, 0)
    return result

def _dfs(result: list[str], path: str, digits: str, target: int, position: int, evaluated: int, multed: int) -> None:
    if position == len(digits):
        if target == evaluated:
            result.append(path)
        return
    for i in range(position, len(digits)):
        if i != position and digits[position] == '0':
            break
        current = int(digits[position:i + 1])
        if position == 0:
            _dfs(result, path + str(current), digits, target, i + 1, current, current)
        else:
            _dfs(result, path + '+' + str(current), digits, target, i + 1, evaluated + current, current)
            _dfs(result, path + '-' + str(current), digits, target, i + 1, evaluated - current, -current)
            _dfs(result, path + '*' + str(current), digits, target, i + 1, evaluated - multed + multed * current, multed * current)

def _backtrack(result: list[list[int]], nums: list[int], stack: list[int], position: int) -> None:
    if position == len(nums):
        result.append(list(stack))
    else:
        stack.append(nums[position])
        _backtrack(result, nums, stack, position + 1)
        stack.pop()
        _backtrack(result, nums, stack, position + 1)

def subsets_v2(nums: list[int]) -> list[list[int]]:
    result: list[list[int]] = [[]]
    for number in sorted(nums):
        result += [item + [number] for item in result]
    return result

def _add_pair_v1(result: list[str], current: str, left: int, right: int) -> None:
    if left == 0 and right == 0:
        result.append(current)
        return
    if right > 0:
        _add_pair_v1(result, current + ')', left, right - 1)
    if left > 0:
        _add_pair_v1(result, current + '(', left - 1, right + 1)

def _add_pair_v2(result: list[str], current: str, left: int, right: int) -> None:
    if left == 0 and right == 0:
        result.append(current)
    if left > 0:
        _add_pair_v2(result, current + '(', left - 1, right)
    if right > 0 and left < right:
        _add_pair_v2(result, current + ')', left, right - 1)

def _backtrack(result: list[str], word: str, position: int, count: int, current: str) -> None:
    if position == len(word):
        if count > 0:
            current += str(count)
        result.append(current)
        return
    if count > 0:
        _backtrack(result, word, position + 1, 0, current + str(count) + word[position])
    else:
        _backtrack(result, word, position + 1, 0, current + word[position])
    _backtrack(result, word, position + 1, count + 1, current)

def _backtrack(pattern: str, string: str, mapping: dict[str, str]) -> bool:
    if len(pattern) == 0 and len(string) > 0:
        return False
    if len(pattern) == 0 and len(string) == 0:
        return True
    for end in range(1, len(string) - len(pattern) + 2):
        if pattern[0] not in mapping and string[:end] not in mapping.values():
            mapping[pattern[0]] = string[:end]
            if _backtrack(pattern[1:], string[end:], mapping):
                return True
            del mapping[pattern[0]]
        elif pattern[0] in mapping and mapping[pattern[0]] == string[:end]:
            if _backtrack(pattern[1:], string[end:], mapping):
                return True
    return False

def palindromic_substrings(text: str) -> list[list[str]]:
    if not text:
        return [[]]
    results: list[list[str]] = []
    for i in range(len(text), 0, -1):
        substring = text[:i]
        if substring == substring[::-1]:
            for rest in palindromic_substrings(text[i:]):
                results.append([substring] + rest)
    return results

def palindromic_substrings_iter(text: str) -> Generator[list[str], None, None]:
    if not text:
        yield []
        return
    for i in range(len(text), 0, -1):
        substring = text[:i]
        if substring == substring[::-1]:
            for rest in palindromic_substrings_iter(text[i:]):
                yield ([substring] + rest)

def _dfs(nums: list[int], target: int, index: int, path: list[int], result: list[list[int]]) -> None:
    if target < 0:
        return
    if target == 0:
        result.append(path)
        return
    for i in range(index, len(nums)):
        _dfs(nums, target - nums[i], i, path + [nums[i]], result)

def count_components(adjacency_list: list[list[int]], size: int) -> int:
    count = 0
    visited = [False] * (size + 1)
    for i in range(1, size + 1):
        if not visited[i]:
            _dfs(i, visited, adjacency_list)
            count += 1
    return count

def _dfs(source: int, visited: list[bool], adjacency_list: list[list[int]]) -> None:
    visited[source] = True
    for child in adjacency_list[source]:
        if not visited[child]:
            _dfs(child, visited, adjacency_list)

def shortest_distance(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return -1
    matrix = [[[0, 0] for _ in range(len(grid[0]))] for _ in range(len(grid))]
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                _bfs(grid, matrix, i, j, count)
                count += 1
    res = float('inf')
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j][1] == count:
                res = min(res, matrix[i][j][0])
    return res if res != float('inf') else -1

def _bfs(grid: list[list[int]], matrix: list[list[list[int]]], i: int, j: int, count: int) -> None:
    q: deque[tuple[int, int, int]] = deque([(i, j, 0)])
    while q:
        (i, j, step) = q.popleft()
        for (k, col) in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
            if 0 <= k < len(grid) and 0 <= col < len(grid[0]) and (matrix[k][col][1] == count) and (grid[k][col] == 0):
                matrix[k][col][0] += step + 1
                matrix[k][col][1] = count + 1
                q.append((k, col, step + 1))

def num_islands(grid: list[list[int]]) -> int:
    count = 0
    for i in range(len(grid)):
        for (j, col) in enumerate(grid[i]):
            if col == 1:
                _dfs(grid, i, j)
                count += 1
    return count

def _dfs(grid: list[list[int]], i: int, j: int) -> None:
    if i < 0 or i >= len(grid) or j < 0 or (j >= len(grid[0])):
        return
    if grid[i][j] != 1:
        return
    grid[i][j] = 0
    _dfs(grid, i + 1, j)
    _dfs(grid, i - 1, j)
    _dfs(grid, i, j + 1)
    _dfs(grid, i, j - 1)

def find_path(maze: list[list[int]]) -> int:
    cnt = _dfs(maze, 0, 0, 0, -1)
    return cnt

def _dfs(maze: list[list[int]], i: int, j: int, depth: int, cnt: int) -> int:
    directions = [(0, -1), (0, 1), (-1, 0), (1, 0)]
    row = len(maze)
    col = len(maze[0])
    if i == row - 1 and j == col - 1:
        if cnt == -1:
            cnt = depth
        elif cnt > depth:
            cnt = depth
        return cnt
    maze[i][j] = 0
    for k in range(len(directions)):
        nx_i = i + directions[k][0]
        nx_j = j + directions[k][1]
        if 0 <= nx_i < row and 0 <= nx_j < col and (maze[nx_i][nx_j] == 1):
            cnt = _dfs(maze, nx_i, nx_j, depth + 1, cnt)
    maze[i][j] = 1
    return cnt

def _choose_state(state_map: dict[Any, float]) -> Any | None:
    choice = random.random()
    probability_reached = 0.0
    for (state, probability) in state_map.items():
        probability_reached += probability
        if probability_reached > choice:
            return state
    return None

def next_state(chain: dict[Any, dict[Any, float]], current_state: Any) -> Any:
    next_state_map = chain.get(current_state)
    return _choose_state(next_state_map)

def iterating_markov_chain(chain: dict[Any, dict[Any, float]], state: Any) -> Iterator[Any]:
    while True:
        state = next_state(chain, state)
        yield state

def dfs_traverse(graph: dict[Any, list[Any]], start: Any) -> set[Any]:
    visited: set[Any] = set()
    stack = [start]
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            for next_node in graph[node]:
                if next_node not in visited:
                    stack.append(next_node)
    return visited

def bfs_traverse(graph: dict[Any, list[Any]], start: Any) -> set[Any]:
    visited: set[Any] = set()
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            for next_node in graph[node]:
                if next_node not in visited:
                    queue.append(next_node)
    return visited

def dfs_traverse_recursive(graph: dict[Any, list[Any]], start: Any, visited: set[Any] | None=None) -> set[Any]:
    if visited is None:
        visited = set()
    visited.add(start)
    for next_node in graph[start]:
        if next_node not in visited:
            dfs_traverse_recursive(graph, next_node, visited)
    return visited

def find_path(graph: dict[Any, list[Any]], start: Any, end: Any, path: list[Any] | None=None) -> list[Any] | None:
    if path is None:
        path = []
    path = path + [start]
    if start == end:
        return path
    if start not in graph:
        return None
    for node in graph[start]:
        if node not in path:
            newpath = find_path(graph, node, end, path)
            return newpath
    return None

def find_all_path(graph: dict[Any, list[Any]], start: Any, end: Any, path: list[Any] | None=None) -> list[list[Any]]:
    if path is None:
        path = []
    path = path + [start]
    if start == end:
        return [path]
    if start not in graph:
        return []
    paths: list[list[Any]] = []
    for node in graph[start]:
        if node not in path:
            newpaths = find_all_path(graph, node, end, path)
            for newpath in newpaths:
                paths.append(newpath)
    return paths

def find_shortest_path(graph: dict[Any, list[Any]], start: Any, end: Any, path: list[Any] | None=None) -> list[Any] | None:
    if path is None:
        path = []
    path = path + [start]
    if start == end:
        return path
    if start not in graph:
        return None
    shortest: list[Any] | None = None
    for node in graph[start]:
        if node not in path:
            newpath = find_shortest_path(graph, node, end, path)
            if newpath and (not shortest or len(newpath) < len(shortest)):
                shortest = newpath
    return shortest

def prims_minimum_spanning(graph_used: dict[Any, list[list[int | Any]]]) -> int:
    vis: list[Any] = []
    heap: list[list[int | Any]] = [[0, 1]]
    prim: set[Any] = set()
    mincost = 0
    while len(heap) > 0:
        (cost, node) = heapq.heappop(heap)
        if node in vis:
            continue
        mincost += cost
        prim.add(node)
        vis.append(node)
        for (distance, adjacent) in graph_used[node]:
            if adjacent not in vis:
                heapq.heappush(heap, [distance, adjacent])
    return mincost

def clone_graph1(node: UndirectedGraphNode | None) -> UndirectedGraphNode | None:
    if not node:
        return None
    node_copy = node.shallow_copy()
    dic: dict[UndirectedGraphNode, UndirectedGraphNode] = {node: node_copy}
    queue: collections.deque[UndirectedGraphNode] = collections.deque([node])
    while queue:
        node = queue.popleft()
        for neighbor in node.neighbors:
            if neighbor not in dic:
                neighbor_copy = neighbor.shallow_copy()
                dic[neighbor] = neighbor_copy
                dic[node].add_neighbor(neighbor_copy)
                queue.append(neighbor)
            else:
                dic[node].add_neighbor(dic[neighbor])
    return node_copy

def clone_graph2(node: UndirectedGraphNode | None) -> UndirectedGraphNode | None:
    if not node:
        return None
    node_copy = node.shallow_copy()
    dic: dict[UndirectedGraphNode, UndirectedGraphNode] = {node: node_copy}
    stack = [node]
    while stack:
        node = stack.pop()
        for neighbor in node.neighbors:
            if neighbor not in dic:
                neighbor_copy = neighbor.shallow_copy()
                dic[neighbor] = neighbor_copy
                dic[node].add_neighbor(neighbor_copy)
                stack.append(neighbor)
            else:
                dic[node].add_neighbor(dic[neighbor])
    return node_copy

def clone_graph(node: UndirectedGraphNode | None) -> UndirectedGraphNode | None:
    if not node:
        return None
    node_copy = node.shallow_copy()
    dic: dict[UndirectedGraphNode, UndirectedGraphNode] = {node: node_copy}
    _dfs(node, dic)
    return node_copy

def _dfs(node: UndirectedGraphNode, dic: dict[UndirectedGraphNode, UndirectedGraphNode]) -> None:
    for neighbor in node.neighbors:
        if neighbor not in dic:
            neighbor_copy = neighbor.shallow_copy()
            dic[neighbor] = neighbor_copy
            dic[node].add_neighbor(neighbor_copy)
            _dfs(neighbor, dic)
        else:
            dic[node].add_neighbor(dic[neighbor])

def kruskal(vertex_count: int, edges: list[Edge], forest: DisjointSet) -> int:
    edges.sort(key=lambda edge: edge.weight)
    mst: list[Edge] = []
    for edge in edges:
        set_u = forest.find_set(edge.source)
        set_v = forest.find_set(edge.target)
        if set_u != set_v:
            forest.merge_set(set_u, set_v)
            mst.append(edge)
            if len(mst) == vertex_count - 1:
                break
    return sum((edge.weight for edge in mst))

def a_star(graph: dict[Any, list[tuple[Any, float]]], start: Any, goal: Any, h: Callable[[Any], float]) -> tuple[list[Any] | None, float]:
    open_set: list[tuple[float, float, Any, list[Any]]] = []
    heapq.heappush(open_set, (h(start), 0, start, [start]))
    visited: set[Any] = set()
    while open_set:
        (f_score, g_score, current, path) = heapq.heappop(open_set)
        if current == goal:
            return (path, g_score)
        if current in visited:
            continue
        visited.add(current)
        for (neighbor, cost) in graph.get(current, []):
            if neighbor not in visited:
                g = g_score + cost
                f = g + h(neighbor)
                heapq.heappush(open_set, (f, g, neighbor, path + [neighbor]))
    return (None, float('inf'))

def num_islands(positions: list[list[int]]) -> list[int]:
    result: list[int] = []
    islands = Union()
    for position in map(tuple, positions):
        islands.add(position)
        for delta in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            adjacent = (position[0] + delta[0], position[1] + delta[1])
            if adjacent in islands.parents:
                islands.unite(position, adjacent)
        result.append(islands.count)
    return result

def pacific_atlantic(matrix: list[list[int]]) -> list[list[int]]:
    n = len(matrix)
    if not n:
        return []
    m = len(matrix[0])
    if not m:
        return []
    res: list[list[int]] = []
    atlantic = [[False for _ in range(n)] for _ in range(m)]
    pacific = [[False for _ in range(n)] for _ in range(m)]
    for i in range(n):
        _dfs(pacific, matrix, float('-inf'), i, 0)
        _dfs(atlantic, matrix, float('-inf'), i, m - 1)
    for i in range(m):
        _dfs(pacific, matrix, float('-inf'), 0, i)
        _dfs(atlantic, matrix, float('-inf'), n - 1, i)
    for i in range(n):
        for j in range(m):
            if pacific[i][j] and atlantic[i][j]:
                res.append([i, j])
    return res

def _dfs(grid: list[list[bool]], matrix: list[list[int]], height: float, i: int, j: int) -> None:
    if i < 0 or i >= len(matrix) or j < 0 or (j >= len(matrix[0])):
        return
    if grid[i][j] or matrix[i][j] < height:
        return
    grid[i][j] = True
    _dfs(grid, matrix, matrix[i][j], i - 1, j)
    _dfs(grid, matrix, matrix[i][j], i + 1, j)
    _dfs(grid, matrix, matrix[i][j], i, j - 1)
    _dfs(grid, matrix, matrix[i][j], i, j + 1)

def count_islands(grid: list[list[int]]) -> int:
    row = len(grid)
    col = len(grid[0])
    num_islands = 0
    visited = [[0] * col for _ in range(row)]
    directions = [[-1, 0], [1, 0], [0, -1], [0, 1]]
    queue: deque[tuple[int, int]] = deque()
    for i in range(row):
        for (j, num) in enumerate(grid[i]):
            if num == 1 and visited[i][j] != 1:
                visited[i][j] = 1
                queue.append((i, j))
                while queue:
                    (x, y) = queue.popleft()
                    for k in range(len(directions)):
                        nx_x = x + directions[k][0]
                        nx_y = y + directions[k][1]
                        if 0 <= nx_x < row and 0 <= nx_y < col and (visited[nx_x][nx_y] != 1) and (grid[nx_x][nx_y] == 1):
                            queue.append((nx_x, nx_y))
                            visited[nx_x][nx_y] = 1
                num_islands += 1
    return num_islands

def bellman_ford(graph: dict[str, dict[str, float]], source: str) -> bool:
    distance: dict[str, float] = {}
    predecessor: dict[str, str | None] = {}
    _initialize_single_source(graph, source, distance, predecessor)
    num_vertices = len(graph)
    for _ in range(1, num_vertices):
        for current_node in graph:
            for neighbor in graph[current_node]:
                edge_weight = graph[current_node][neighbor]
                if distance[neighbor] > distance[current_node] + edge_weight:
                    distance[neighbor] = distance[current_node] + edge_weight
                    predecessor[neighbor] = current_node
    for current_node in graph:
        for neighbor in graph[current_node]:
            edge_weight = graph[current_node][neighbor]
            if distance[neighbor] > distance[current_node] + edge_weight:
                return False
    return True

def _initialize_single_source(graph: dict[str, dict[str, float]], source: str, distance: dict[str, float], predecessor: dict[str, str | None]) -> None:
    all_nodes: set[str] = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors.keys())
    for node in all_nodes:
        distance[node] = float('inf')
        predecessor[node] = None
    distance[source] = 0

def bellman_ford_paths(graph: dict[str, dict[str, float]], source: str) -> tuple[dict[str, float] | None, dict[str, str | None] | None, bool]:
    distance: dict[str, float] = {}
    predecessor: dict[str, str | None] = {}
    _initialize_single_source(graph, source, distance, predecessor)
    num_vertices = len(graph)
    for _ in range(1, num_vertices):
        for current_node in graph:
            if distance[current_node] == float('inf'):
                continue
            for (neighbor, edge_weight) in graph[current_node].items():
                if distance[neighbor] > distance[current_node] + edge_weight:
                    distance[neighbor] = distance[current_node] + edge_weight
                    predecessor[neighbor] = current_node
    for current_node in graph:
        if distance[current_node] == float('inf'):
            continue
        for (neighbor, edge_weight) in graph[current_node].items():
            if distance[neighbor] > distance[current_node] + edge_weight:
                return (None, None, True)
    return (distance, predecessor, False)

def find_all_cliques(edges: dict[str, set[str]]) -> list[list[str]]:
    compsub: list[str] = []
    solutions: list[list[str]] = []

    def _expand_clique(candidates: set[str], nays: set[str]) -> None:
        if not candidates and (not nays):
            solutions.append(compsub.copy())
        else:
            for selected in candidates.copy():
                candidates.remove(selected)
                candidates_temp = _get_connected(selected, candidates)
                nays_temp = _get_connected(selected, nays)
                compsub.append(selected)
                _expand_clique(candidates_temp, nays_temp)
                nays.add(compsub.pop())

    def _get_connected(vertex: str, old_set: set[str]) -> set[str]:
        new_set: set[str] = set()
        for neighbor in edges[str(vertex)]:
            if neighbor in old_set:
                new_set.add(neighbor)
        return new_set
    possibles = set(edges.keys())
    _expand_clique(possibles, set())
    return sorted((sorted(clique) for clique in solutions))

def get_factors(n: int) -> list[list[int]]:

    def _factor(n: int, i: int, combi: list[int], res: list[list[int]]) -> list[list[int]]:
        while i * i <= n:
            if n % i == 0:
                res += (combi + [i, int(n / i)],)
                _factor(n / i, i, combi + [i], res)
            i += 1
        return res
    return _factor(n, 2, [], [])

def get_factors_iterative1(n: int) -> list[list[int]]:
    todo: list[tuple[int, int, list[int]]] = [(n, 2, [])]
    res: list[list[int]] = []
    while todo:
        (n, i, combi) = todo.pop()
        while i * i <= n:
            if n % i == 0:
                res += (combi + [i, n // i],)
                todo.append((n // i, i, combi + [i]))
            i += 1
    return res

def get_factors_iterative2(n: int) -> list[list[int]]:
    ans: list[list[int]] = []
    stack: list[int] = []
    x = 2
    while True:
        if x > n // x:
            if not stack:
                return ans
            ans.append(stack + [n])
            x = stack.pop()
            n *= x
            x += 1
        elif n % x == 0:
            stack.append(x)
            n //= x
        else:
            x += 1

def walls_and_gates(rooms: list[list[int]]) -> None:
    for i in range(len(rooms)):
        for j in range(len(rooms[0])):
            if rooms[i][j] == 0:
                _dfs(rooms, i, j, 0)

def _dfs(rooms: list[list[int]], i: int, j: int, depth: int) -> None:
    if i < 0 or i >= len(rooms) or j < 0 or (j >= len(rooms[0])):
        return
    if rooms[i][j] < depth:
        return
    rooms[i][j] = depth
    _dfs(rooms, i + 1, j, depth + 1)
    _dfs(rooms, i - 1, j, depth + 1)
    _dfs(rooms, i, j + 1, depth + 1)
    _dfs(rooms, i, j - 1, depth + 1)

def all_pairs_shortest_path(adjacency_matrix: list[list[float]]) -> list[list[float]]:
    new_array = copy.deepcopy(adjacency_matrix)
    size = len(new_array)
    for k in range(size):
        for i in range(size):
            for j in range(size):
                if new_array[i][j] > new_array[i][k] + new_array[k][j]:
                    new_array[i][j] = new_array[i][k] + new_array[k][j]
    return new_array

def dijkstra(graph: dict[str, dict[str, int | float]], source: str, target: str='') -> tuple[int | float, list[str]]:
    dist: dict[str, int | float] = {v: float('inf') for v in graph}
    dist[source] = 0
    prev: dict[str, str | None] = {v: None for v in graph}
    heap: list[tuple[int | float, str]] = [(0, source)]
    while heap:
        (d, u) = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == target:
            break
        for (v, weight) in graph[u].items():
            alt = dist[u] + weight
            if alt < dist.get(v, float('inf')):
                dist[v] = alt
                prev[v] = u
                heapq.heappush(heap, (alt, v))
    path: list[str] = []
    node: str | None = target if target else None
    if node and dist.get(node, float('inf')) < float('inf'):
        while node is not None:
            path.append(node)
            node = prev.get(node)
        path.reverse()
    return (dist.get(target, float('inf')), path) if target else (0, [])

def ladder_length(begin_word: str, end_word: str, word_list: list[str]) -> int:
    if len(begin_word) != len(end_word):
        return -1
    if begin_word == end_word:
        return 0
    if sum((c1 != c2 for (c1, c2) in zip(begin_word, end_word, strict=False))) == 1:
        return 1
    begin_set: set[str] = set()
    end_set: set[str] = set()
    begin_set.add(begin_word)
    end_set.add(end_word)
    result = 2
    while begin_set and end_set:
        if len(begin_set) > len(end_set):
            (begin_set, end_set) = (end_set, begin_set)
        next_begin_set: set[str] = set()
        for word in begin_set:
            for ladder_word in _word_range(word):
                if ladder_word in end_set:
                    return result
                if ladder_word in word_list:
                    next_begin_set.add(ladder_word)
                    word_list.remove(ladder_word)
        begin_set = next_begin_set
        result += 1
    return -1

def _word_range(word: str) -> Iterator[str]:
    for ind in range(len(word)):
        temp = word[ind]
        for c in [chr(x) for x in range(ord('a'), ord('z') + 1)]:
            if c != temp:
                yield (word[:ind] + c + word[ind + 1:])

def maximum_flow_dfs(adjacency_matrix: list[list[int]]) -> int:
    new_array = copy.deepcopy(adjacency_matrix)
    total = 0
    while True:
        min_flow = math.inf
        visited = [0] * len(new_array)
        path = [0] * len(new_array)
        stack: list[int] = []
        visited[0] = 1
        stack.append(0)
        while len(stack) > 0:
            src = stack.pop()
            for k in range(len(new_array)):
                if new_array[src][k] > 0 and visited[k] == 0:
                    visited[k] = 1
                    stack.append(k)
                    path[k] = src
        if visited[len(new_array) - 1] == 0:
            break
        tmp = len(new_array) - 1
        while tmp != 0:
            if min_flow > new_array[path[tmp]][tmp]:
                min_flow = new_array[path[tmp]][tmp]
            tmp = path[tmp]
        tmp = len(new_array) - 1
        while tmp != 0:
            new_array[path[tmp]][tmp] = new_array[path[tmp]][tmp] - min_flow
            tmp = path[tmp]
        total = total + min_flow
    return total

def topological_sort(vertices: int, edges: list[tuple[int, int]]) -> list[int]:
    graph: dict[int, list[int]] = defaultdict(list)
    in_degree = [0] * vertices
    for (u, v) in edges:
        graph[u].append(v)
        in_degree[v] += 1
    queue: deque[int] = deque()
    for i in range(vertices):
        if in_degree[i] == 0:
            queue.append(i)
    sorted_order: list[int] = []
    processed = 0
    while queue:
        node = queue.popleft()
        sorted_order.append(node)
        processed += 1
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
    if processed != vertices:
        raise ValueError('Cycle detected, topological sort failed')
    return sorted_order

def is_in_cycle(graph: dict[str, list[str]], traversal_states: dict[str, TraversalState], vertex: str) -> bool:
    if traversal_states[vertex] == TraversalState.GRAY:
        return True
    traversal_states[vertex] = TraversalState.GRAY
    for neighbor in graph[vertex]:
        if is_in_cycle(graph, traversal_states, neighbor):
            return True
    traversal_states[vertex] = TraversalState.BLACK
    return False

def contains_cycle(graph: dict[str, list[str]]) -> bool:
    traversal_states = {vertex: TraversalState.WHITE for vertex in graph}
    for (vertex, state) in traversal_states.items():
        if state == TraversalState.WHITE and is_in_cycle(graph, traversal_states, vertex):
            return True
    return False

def _dfs_transposed(vertex: Any, graph: dict[Any, list[Any]], order: list[Any], visited: dict[Any, bool]) -> None:
    visited[vertex] = True
    for adjacent in graph[vertex]:
        if not visited[adjacent]:
            _dfs_transposed(adjacent, graph, order, visited)
    order.append(vertex)

def _dfs(vertex: Any, current_comp: int, vertex_scc: dict[Any, int], graph: dict[Any, list[Any]], visited: dict[Any, bool]) -> None:
    visited[vertex] = True
    vertex_scc[vertex] = current_comp
    for adjacent in graph[vertex]:
        if not visited[adjacent]:
            _dfs(adjacent, current_comp, vertex_scc, graph, visited)

def _add_edge(graph: dict[Any, list[Any]], vertex_from: Any, vertex_to: Any) -> None:
    if vertex_from not in graph:
        graph[vertex_from] = []
    graph[vertex_from].append(vertex_to)

def _scc(graph: dict[Any, list[Any]]) -> dict[Any, int]:
    order: list[Any] = []
    visited = {vertex: False for vertex in graph}
    graph_transposed: dict[Any, list[Any]] = {vertex: [] for vertex in graph}
    for (source, neighbours) in graph.items():
        for target in neighbours:
            _add_edge(graph_transposed, target, source)
    for vertex in graph:
        if not visited[vertex]:
            _dfs_transposed(vertex, graph_transposed, order, visited)
    visited = {vertex: False for vertex in graph}
    vertex_scc: dict[Any, int] = {}
    current_comp = 0
    for vertex in reversed(order):
        if not visited[vertex]:
            _dfs(vertex, current_comp, vertex_scc, graph, visited)
            current_comp += 1
    return vertex_scc

def _build_graph(formula: list[tuple[tuple[str, bool], tuple[str, bool]]]) -> dict[tuple[str, bool], list[tuple[str, bool]]]:
    graph: dict[tuple[str, bool], list[tuple[str, bool]]] = {}
    for clause in formula:
        for (lit, _) in clause:
            for neg in [False, True]:
                graph[lit, neg] = []
    for ((a_lit, a_neg), (b_lit, b_neg)) in formula:
        _add_edge(graph, (a_lit, a_neg), (b_lit, not b_neg))
        _add_edge(graph, (b_lit, b_neg), (a_lit, not a_neg))
    return graph

def solve_sat(formula: list[tuple[tuple[str, bool], tuple[str, bool]]]) -> dict[str, bool] | None:
    graph = _build_graph(formula)
    vertex_scc = _scc(graph)
    for (var, _) in graph:
        if vertex_scc[var, False] == vertex_scc[var, True]:
            return None
    comp_repr: dict[int, tuple[str, bool]] = {}
    for vertex in graph:
        if vertex_scc[vertex] not in comp_repr:
            comp_repr[vertex_scc[vertex]] = vertex
    comp_value: dict[int, bool] = {}
    components = sorted(vertex_scc.values())
    for comp in components:
        if comp not in comp_value:
            comp_value[comp] = False
            (lit, neg) = comp_repr[comp]
            comp_value[vertex_scc[lit, not neg]] = True
    value = {var: comp_value[vertex_scc[var, False]] for (var, _) in graph}
    return value

def maximum_flow_bfs(adjacency_matrix: list[list[int]]) -> int:
    new_array = copy.deepcopy(adjacency_matrix)
    total = 0
    while True:
        min_flow = math.inf
        visited = [0] * len(new_array)
        path = [0] * len(new_array)
        bfs: queue.Queue[int] = queue.Queue()
        visited[0] = 1
        bfs.put(0)
        while bfs.qsize() > 0:
            src = bfs.get()
            for k in range(len(new_array)):
                if new_array[src][k] > 0 and visited[k] == 0:
                    visited[k] = 1
                    bfs.put(k)
                    path[k] = src
        if visited[len(new_array) - 1] == 0:
            break
        tmp = len(new_array) - 1
        while tmp != 0:
            if min_flow > new_array[path[tmp]][tmp]:
                min_flow = new_array[path[tmp]][tmp]
            tmp = path[tmp]
        tmp = len(new_array) - 1
        while tmp != 0:
            new_array[path[tmp]][tmp] = new_array[path[tmp]][tmp] - min_flow
            tmp = path[tmp]
        total = total + min_flow
    return total

def top_sort_recursive(graph: dict[str, list[str]]) -> list[str]:
    order: list[str] = []
    enter = set(graph)
    state: dict[str, int] = {}

    def _dfs(node: str) -> None:
        state[node] = _GRAY
        for neighbour in graph.get(node, ()):
            neighbour_state = state.get(neighbour)
            if neighbour_state == _GRAY:
                raise ValueError('cycle')
            if neighbour_state == _BLACK:
                continue
            enter.discard(neighbour)
            _dfs(neighbour)
        order.append(node)
        state[node] = _BLACK
    while enter:
        _dfs(enter.pop())
    return order

def top_sort(graph: dict[str, list[str]]) -> list[str]:
    order: list[str] = []
    enter = set(graph)
    state: dict[str, int] = {}

    def _is_ready(node: str) -> bool:
        neighbours = graph.get(node, ())
        if len(neighbours) == 0:
            return True
        for neighbour in neighbours:
            neighbour_state = state.get(neighbour)
            if neighbour_state == _GRAY:
                raise ValueError('cycle')
            if neighbour_state != _BLACK:
                return False
        return True
    while enter:
        node = enter.pop()
        stack: list[str] = []
        while True:
            state[node] = _GRAY
            stack.append(node)
            for neighbour in graph.get(node, ()):
                neighbour_state = state.get(neighbour)
                if neighbour_state == _GRAY:
                    raise ValueError('cycle')
                if neighbour_state == _BLACK:
                    continue
                enter.discard(neighbour)
                stack.append(neighbour)
            while stack and _is_ready(stack[-1]):
                node = stack.pop()
                order.append(node)
                state[node] = _BLACK
            if len(stack) == 0:
                break
            node = stack.pop()
    return order

def check_bipartite(adj_list: list[list[int]]) -> bool:
    vertices = len(adj_list)
    set_type = [-1 for _ in range(vertices)]
    set_type[0] = 0
    queue = deque([0])
    while queue:
        current = queue.popleft()
        if adj_list[current][current]:
            return False
        for adjacent in range(vertices):
            if adj_list[current][adjacent]:
                if set_type[adjacent] == set_type[current]:
                    return False
                if set_type[adjacent] == -1:
                    set_type[adjacent] = 1 - set_type[current]
                    queue.append(adjacent)
    return True

def max_matching(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    adj: list[list[int]] = [[] for _ in range(n)]
    for (u, v) in edges:
        adj[u].append(v)
        adj[v].append(u)
    match = [-1] * n

    def find_augmenting_path() -> bool:
        parent = [-1] * n
        visited = [False] * n
        for start in range(n):
            if match[start] != -1:
                continue
            queue: deque[int] = deque([start])
            visited[start] = True
            found = False
            while queue and (not found):
                u = queue.popleft()
                for v in adj[u]:
                    if visited[v] or v == match[u]:
                        continue
                    if match[v] == -1 and v != start:
                        _augment(parent, match, u, v)
                        return True
                    if match[v] != -1:
                        visited[v] = True
                        visited[match[v]] = True
                        parent[match[v]] = u
                        queue.append(match[v])
        return False
    while find_augmenting_path():
        pass
    result = []
    seen = set()
    for i in range(n):
        if match[i] != -1 and i not in seen:
            result.append((i, match[i]))
            seen.add(i)
            seen.add(match[i])
    return result

def _dfs(capacity: list[list[int]], flow: list[list[int]], visit: list[bool], vertices: int, idx: int, sink: int, current_flow: int=1 << 63) -> int:
    if idx == sink:
        return current_flow
    visit[idx] = True
    for nxt in range(vertices):
        if not visit[nxt] and flow[idx][nxt] < capacity[idx][nxt]:
            available_flow = min(current_flow, capacity[idx][nxt] - flow[idx][nxt])
            tmp = _dfs(capacity, flow, visit, vertices, nxt, sink, available_flow)
            if tmp:
                flow[idx][nxt] += tmp
                flow[nxt][idx] -= tmp
                return tmp
    return 0

def ford_fulkerson(capacity: list[list[int]], source: int, sink: int) -> int:
    vertices = len(capacity)
    ret = 0
    flow = [[0] * vertices for _ in range(vertices)]
    while True:
        visit = [False for _ in range(vertices)]
        tmp = _dfs(capacity, flow, visit, vertices, source, sink)
        if tmp:
            ret += tmp
        else:
            break
    return ret

def _dinic_bfs(capacity: list[list[int]], flow: list[list[int]], level: list[int], source: int, sink: int) -> bool:
    vertices = len(capacity)
    queue: Queue[int] = Queue()
    queue.put(source)
    level[source] = 0
    while queue.qsize():
        front = queue.get()
        for nxt in range(vertices):
            if level[nxt] == -1 and flow[front][nxt] < capacity[front][nxt]:
                level[nxt] = level[front] + 1
                queue.put(nxt)
    return level[sink] != -1

def _dinic_dfs(capacity: list[list[int]], flow: list[list[int]], level: list[int], idx: int, sink: int, work: list[int], current_flow: int=1 << 63) -> int:
    if idx == sink:
        return current_flow
    vertices = len(capacity)
    while work[idx] < vertices:
        nxt = work[idx]
        if level[nxt] == level[idx] + 1 and flow[idx][nxt] < capacity[idx][nxt]:
            available_flow = min(current_flow, capacity[idx][nxt] - flow[idx][nxt])
            tmp = _dinic_dfs(capacity, flow, level, nxt, sink, work, available_flow)
            if tmp > 0:
                flow[idx][nxt] += tmp
                flow[nxt][idx] -= tmp
                return tmp
        work[idx] += 1
    return 0

def dinic(capacity: list[list[int]], source: int, sink: int) -> int:
    vertices = len(capacity)
    flow = [[0] * vertices for _ in range(vertices)]
    ret = 0
    while True:
        level = [-1 for _ in range(vertices)]
        work = [0 for _ in range(vertices)]
        if not _dinic_bfs(capacity, flow, level, source, sink):
            break
        while True:
            tmp = _dinic_dfs(capacity, flow, level, source, sink, work)
            if tmp > 0:
                ret += tmp
            else:
                break
    return ret

def cut_rod(price: list[int]) -> int:
    n = len(price)
    val = [0] * (n + 1)
    for i in range(1, n + 1):
        max_val = _INT_MIN
        for j in range(i):
            max_val = max(max_val, price[j] + val[i - j - 1])
        val[i] = max_val
    return val[n]

def house_robber(houses: list[int]) -> int:
    (last, now) = (0, 0)
    for house in houses:
        (last, now) = (now, max(last + house, now))
    return now

def _binary_search(job: list[Job], start_index: int) -> int:
    left = 0
    right = start_index - 1
    while left <= right:
        mid = (left + right) // 2
        if job[mid].finish <= job[start_index].start:
            if job[mid + 1].finish <= job[start_index].start:
                left = mid + 1
            else:
                return mid
        else:
            right = mid - 1
    return -1

def longest_common_subsequence(s_1: str, s_2: str) -> int:
    m = len(s_1)
    n = len(s_2)
    mat = [[0] * (n + 1) for i in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                mat[i][j] = 0
            elif s_1[i - 1] == s_2[j - 1]:
                mat[i][j] = mat[i - 1][j - 1] + 1
            else:
                mat[i][j] = max(mat[i - 1][j], mat[i][j - 1])
    return mat[m][n]

def max_profit_naive(prices: list[int]) -> int:
    max_so_far = 0
    for i in range(0, len(prices) - 1):
        for j in range(i + 1, len(prices)):
            max_so_far = max(max_so_far, prices[j] - prices[i])
    return max_so_far

def max_profit_optimized(prices: list[int]) -> int:
    (cur_max, max_so_far) = (0, 0)
    for i in range(1, len(prices)):
        cur_max = max(0, cur_max + prices[i] - prices[i - 1])
        max_so_far = max(max_so_far, cur_max)
    return max_so_far

def is_match(str_a: str, str_b: str) -> bool:
    (len_a, len_b) = (len(str_a) + 1, len(str_b) + 1)
    matches = [[False] * len_b for _ in range(len_a)]
    matches[0][0] = True
    for (i, element) in enumerate(str_b[1:], 2):
        matches[0][i] = matches[0][i - 2] and element == '*'
    for (i, char_a) in enumerate(str_a, 1):
        for (j, char_b) in enumerate(str_b, 1):
            if char_b != '*':
                matches[i][j] = matches[i - 1][j - 1] and char_b in (char_a, '.')
            else:
                matches[i][j] |= matches[i][j - 2]
                if char_a == str_b[j - 2] or str_b[j - 2] == '.':
                    matches[i][j] |= matches[i - 1][j]
    return matches[-1][-1]

def get_maximum_value(items: list[Item], capacity: int) -> int:
    dp = [0] * (capacity + 1)
    for item in items:
        for cur_weight in reversed(range(item.weight, capacity + 1)):
            dp[cur_weight] = max(dp[cur_weight], item.value + dp[cur_weight - item.weight])
    return dp[capacity]

def max_subarray(array: list[int]) -> int:
    max_so_far = max_now = array[0]
    for i in range(1, len(array)):
        max_now = max(array[i], max_now + array[i])
        max_so_far = max(max_so_far, max_now)
    return max_so_far

def matrix_chain_order(array: list[int]) -> tuple[list[list[int]], list[list[int]]]:
    n = len(array)
    matrix = [[0 for x in range(n)] for x in range(n)]
    sol = [[0 for x in range(n)] for x in range(n)]
    for chain_length in range(2, n):
        for a in range(1, n - chain_length + 1):
            b = a + chain_length - 1
            matrix[a][b] = _INF
            for c in range(a, b):
                cost = matrix[a][c] + matrix[c + 1][b] + array[a - 1] * array[c] * array[b]
                if cost < matrix[a][b]:
                    matrix[a][b] = cost
                    sol[a][b] = c
    return (matrix, sol)

def count_paths_recursive(m: int, n: int) -> int:
    if m == 1 or n == 1:
        return 1
    return count_paths_recursive(m - 1, n) + count_paths_recursive(m, n - 1)

def count_paths_memo(m: int, n: int) -> int:

    @cache
    def helper(i: int, j: int) -> int:
        if i == 1 or j == 1:
            return 1
        return helper(i - 1, j) + helper(i, j - 1)
    return helper(m, n)

def count_paths_dp(m: int, n: int) -> int:
    row = [1] * n
    for _ in range(1, m):
        for j in range(1, n):
            row[j] += row[j - 1]
    return row[n - 1]

def fib_recursive(n: int) -> int:
    assert n >= 0, 'n must be a positive integer'
    if n <= 1:
        return n
    return fib_recursive(n - 1) + fib_recursive(n - 2)

def fib_list(n: int) -> int:
    assert n >= 0, 'n must be a positive integer'
    list_results = [0, 1]
    for i in range(2, n + 1):
        list_results.append(list_results[i - 1] + list_results[i - 2])
    return list_results[n]

def count(coins: list[int], value: int) -> int:
    dp_array = [1] + [0] * value
    for coin in coins:
        for i in range(coin, value + 1):
            dp_array[i] += dp_array[i - coin]
    return dp_array[value]

def tsp(dist: list[list[float]]) -> float:
    n = len(dist)
    full_mask = (1 << n) - 1
    dp: dict[tuple[int, int], float] = {}

    def solve(mask: int, pos: int) -> float:
        if mask == full_mask:
            return dist[pos][0]
        key = (mask, pos)
        if key in dp:
            return dp[key]
        ans = math.inf
        for city in range(n):
            if not mask & 1 << city:
                ans = min(ans, dist[pos][city] + solve(mask | 1 << city, city))
        dp[key] = ans
        return ans
    return solve(1, 0)

def longest_increasing_subsequence(sequence: list[int]) -> int:
    length = len(sequence)
    counts = [1 for _ in range(length)]
    for i in range(1, length):
        for j in range(0, i):
            if sequence[i] > sequence[j]:
                counts[i] = max(counts[i], counts[j] + 1)
    return max(counts)

def longest_increasing_subsequence_optimized(sequence: list[int]) -> int:
    max_val = max(sequence)
    tree = [0] * (max_val << 2)

    def _update(pos: int, left: int, right: int, target: int, vertex: int) -> None:
        if left == right:
            tree[pos] = vertex
            return
        mid = left + right >> 1
        if target <= mid:
            _update(pos << 1, left, mid, target, vertex)
        else:
            _update(pos << 1 | 1, mid + 1, right, target, vertex)
        tree[pos] = max(tree[pos << 1], tree[pos << 1 | 1])

    def _get_max(pos: int, left: int, right: int, start: int, end: int) -> int:
        if left > end or right < start:
            return 0
        if left >= start and right <= end:
            return tree[pos]
        mid = left + right >> 1
        return max(_get_max(pos << 1, left, mid, start, end), _get_max(pos << 1 | 1, mid + 1, right, start, end))
    ans = 0
    for element in sequence:
        cur = _get_max(1, 0, max_val, 0, element - 1) + 1
        ans = max(ans, cur)
        _update(1, 0, max_val, element, cur)
    return ans

def longest_increasing_subsequence_optimized2(sequence: list[int]) -> int:
    length = len(sequence)
    tree = [0] * (length << 2)
    sorted_seq = sorted(((x, -i) for (i, x) in enumerate(sequence)))

    def _update(pos: int, left: int, right: int, target: int, vertex: int) -> None:
        if left == right:
            tree[pos] = vertex
            return
        mid = left + right >> 1
        if target <= mid:
            _update(pos << 1, left, mid, target, vertex)
        else:
            _update(pos << 1 | 1, mid + 1, right, target, vertex)
        tree[pos] = max(tree[pos << 1], tree[pos << 1 | 1])

    def _get_max(pos: int, left: int, right: int, start: int, end: int) -> int:
        if left > end or right < start:
            return 0
        if left >= start and right <= end:
            return tree[pos]
        mid = left + right >> 1
        return max(_get_max(pos << 1, left, mid, start, end), _get_max(pos << 1 | 1, mid + 1, right, start, end))
    ans = 0
    for tup in sorted_seq:
        i = -tup[1]
        cur = _get_max(1, 0, length - 1, 0, i - 1) + 1
        ans = max(ans, cur)
        _update(1, 0, length - 1, i, cur)
    return ans

def num_decodings(enc_mes: str) -> int:
    if not enc_mes or enc_mes[0] == '0':
        return 0
    (last_char, last_two_chars) = (1, 1)
    for i in range(1, len(enc_mes)):
        last = last_char if enc_mes[i] != '0' else 0
        last_two = last_two_chars if int(enc_mes[i - 1:i + 1]) < 27 and enc_mes[i - 1] != '0' else 0
        last_two_chars = last_char
        last_char = last + last_two
    return last_char

def num_decodings2(enc_mes: str) -> int:
    if not enc_mes or enc_mes.startswith('0'):
        return 0
    stack = [1, 1]
    for i in range(1, len(enc_mes)):
        if enc_mes[i] == '0':
            if enc_mes[i - 1] == '0' or enc_mes[i - 1] > '2':
                return 0
            stack.append(stack[-2])
        elif 9 < int(enc_mes[i - 1:i + 1]) < 27:
            stack.append(stack[-2] + stack[-1])
        else:
            stack.append(stack[-1])
    return stack[-1]

def int_divide(decompose: int) -> int:
    arr = [[0 for i in range(decompose + 1)] for j in range(decompose + 1)]
    arr[1][1] = 1
    for i in range(1, decompose + 1):
        for j in range(1, decompose + 1):
            if i < j:
                arr[i][j] = arr[i][i]
            elif i == j:
                arr[i][j] = 1 + arr[i][j - 1]
            else:
                arr[i][j] = arr[i][j - 1] + arr[i - j][j]
    return arr[decompose][decompose]

def edit_distance(word_a: str, word_b: str) -> int:
    (length_a, length_b) = (len(word_a) + 1, len(word_b) + 1)
    edit = [[0 for _ in range(length_b)] for _ in range(length_a)]
    for i in range(1, length_a):
        edit[i][0] = i
    for j in range(1, length_b):
        edit[0][j] = j
    for i in range(1, length_a):
        for j in range(1, length_b):
            cost = 0 if word_a[i - 1] == word_b[j - 1] else 1
            edit[i][j] = min(edit[i - 1][j] + 1, edit[i][j - 1] + 1, edit[i - 1][j - 1] + cost)
    return edit[-1][-1]

def subarray_with_max_product(arr: list[int]) -> tuple[int, list[int]]:
    length = len(arr)
    product_so_far = max_product_end = 1
    max_start_i = 0
    so_far_start_i = so_far_end_i = 0
    all_negative_flag = True
    for i in range(length):
        max_product_end *= arr[i]
        if arr[i] > 0:
            all_negative_flag = False
        if max_product_end <= 0:
            max_product_end = arr[i]
            max_start_i = i
        if product_so_far <= max_product_end:
            product_so_far = max_product_end
            so_far_end_i = i
            so_far_start_i = max_start_i
    if all_negative_flag:
        product = reduce(lambda x, y: x * y, arr)
        return (product, arr)
    return (product_so_far, arr[so_far_start_i:so_far_end_i + 1])

def climb_stairs(steps: int) -> int:
    arr = [1, 1]
    for _ in range(1, steps):
        arr.append(arr[-1] + arr[-2])
    return arr[-1]

def climb_stairs_optimized(steps: int) -> int:
    a_steps = b_steps = 1
    for _ in range(steps):
        (a_steps, b_steps) = (b_steps, a_steps + b_steps)
    return a_steps

def word_break(word: str, word_dict: set[str]) -> bool:
    dp_array = [False] * (len(word) + 1)
    dp_array[0] = True
    for i in range(1, len(word) + 1):
        for j in range(0, i):
            if dp_array[j] and word[j:i] in word_dict:
                dp_array[i] = True
                break
    return dp_array[-1]

def hosoya(height: int, width: int) -> int:
    if width == 0 and height in (0, 1):
        return 1
    if width == 1 and height in (1, 2):
        return 1
    if height > width:
        return hosoya(height - 1, width) + hosoya(height - 2, width)
    if width == height:
        return hosoya(height - 1, width - 1) + hosoya(height - 2, width - 2)
    return 0

def hosoya_testing(height: int) -> list[int]:
    res = []
    for i in range(height):
        for j in range(i + 1):
            res.append(hosoya(i, j))
    return res

def min_cost(cost: list[list[int]]) -> int:
    length = len(cost)
    dist = [_INF] * length
    dist[0] = 0
    for i in range(length):
        for j in range(i + 1, length):
            dist[j] = min(dist[j], dist[i] + cost[i][j])
    return dist[length - 1]

def _helper_topdown(nums: list[int], target: int, dp: list[int]) -> int:
    if dp[target] != -1:
        return dp[target]
    result = 0
    for num in nums:
        if target >= num:
            result += _helper_topdown(nums, target - num, dp)
    dp[target] = result
    return result

def combination_sum_topdown(nums: list[int], target: int) -> int:
    dp = [-1] * (target + 1)
    dp[0] = 1
    return _helper_topdown(nums, target, dp)

def combination_sum_bottom_up(nums: list[int], target: int) -> int:
    combs = [0] * (target + 1)
    combs[0] = 1
    for i in range(0, len(combs)):
        for num in nums:
            if i - num >= 0:
                combs[i] += combs[i - num]
    return combs[target]

def planting_trees(trees: list[int], length: int, width: int) -> float:
    trees = [0] + trees
    n_pairs = int(len(trees) / 2)
    space_between_pairs = length / (n_pairs - 1)
    target_locations = [location * space_between_pairs for location in range(n_pairs)]
    cmatrix = [[0 for _ in range(n_pairs + 1)] for _ in range(n_pairs + 1)]
    for r_i in range(1, n_pairs + 1):
        cmatrix[r_i][0] = cmatrix[r_i - 1][0] + sqrt(width + abs(trees[r_i] - target_locations[r_i - 1]) ** 2)
    for l_i in range(1, n_pairs + 1):
        cmatrix[0][l_i] = cmatrix[0][l_i - 1] + abs(trees[l_i] - target_locations[l_i - 1])
    for r_i in range(1, n_pairs + 1):
        for l_i in range(1, n_pairs + 1):
            cmatrix[r_i][l_i] = min(cmatrix[r_i - 1][l_i] + sqrt(width + (trees[l_i + r_i] - target_locations[r_i - 1]) ** 2), cmatrix[r_i][l_i - 1] + abs(trees[l_i + r_i] - target_locations[l_i - 1]))
    return cmatrix[n_pairs][n_pairs]

def egg_drop(n: int, k: int) -> int:
    egg_floor = [[0 for _ in range(k + 1)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        egg_floor[i][1] = 1
        egg_floor[i][0] = 0
    for j in range(1, k + 1):
        egg_floor[1][j] = j
    for i in range(2, n + 1):
        for j in range(2, k + 1):
            egg_floor[i][j] = _INT_MAX
            for x in range(1, j + 1):
                res = 1 + max(egg_floor[i - 1][x - 1], egg_floor[i][j - x])
                if res < egg_floor[i][j]:
                    egg_floor[i][j] = res
    return egg_floor[n][k]

def partition(head: Node | None, x: int) -> None:
    left = None
    right = None
    prev = None
    current = head
    while current:
        if int(current.val) >= x:
            if not right:
                right = current
        elif not left:
            left = current
        else:
            prev.next = current.next
            left.next = current
            left = current
            left.next = right
        if prev and prev.next is None:
            break
        prev = current
        current = current.next

def reverse_list(head: object | None) -> object | None:
    if not head or not head.next:
        return head
    prev = None
    while head:
        current = head
        head = head.next
        current.next = prev
        prev = current
    return prev

def merge_two_list(l1: Node | None, l2: Node | None) -> Node | None:
    sentinel = current = Node(0)
    while l1 and l2:
        if l1.val < l2.val:
            current.next = l1
            l1 = l1.next
        else:
            current.next = l2
            l2 = l2.next
        current = current.next
    current.next = l1 or l2
    return sentinel.next

def merge_two_list_recur(l1: Node | None, l2: Node | None) -> Node | None:
    if not l1 or not l2:
        return l1 or l2
    if l1.val < l2.val:
        l1.next = merge_two_list_recur(l1.next, l2)
        return l1
    else:
        l2.next = merge_two_list_recur(l1, l2.next)
        return l2

def delete_node(node: Node | None) -> None:
    if node is None or node.next is None:
        raise ValueError
    node.val = node.next.val
    node.next = node.next.next

def is_palindrome_stack(head: object | None) -> bool:
    if not head or not head.next:
        return True
    slow = fast = current = head
    while fast and fast.next:
        (fast, slow) = (fast.next.next, slow.next)
    stack = [slow.val]
    while slow.next:
        slow = slow.next
        stack.append(slow.val)
    while stack:
        if stack.pop() != current.val:
            return False
        current = current.next
    return True

def is_palindrome_dict(head: object | None) -> bool:
    if not head or not head.next:
        return True
    positions: dict[object, list[int]] = {}
    pos = 0
    current = head
    while current:
        if current.val in positions:
            positions[current.val].append(pos)
        else:
            positions[current.val] = [pos]
        current = current.next
        pos += 1
    checksum = pos - 1
    middle = 0
    for indices in positions.values():
        if len(indices) % 2 != 0:
            middle += 1
        else:
            for (step, i) in enumerate(range(len(indices))):
                if indices[i] + indices[len(indices) - 1 - step] != checksum:
                    return False
        if middle > 1:
            return False
    return True

def remove_range(head: object | None, start: int, end: int) -> object | None:
    assert start <= end
    if start == 0:
        for _ in range(end + 1):
            if head is not None:
                head = head.next
    else:
        current = head
        for _ in range(start - 1):
            current = current.next
        for _ in range(end - start + 1):
            if current is not None and current.next is not None:
                current.next = current.next.next
    return head

def convert_to_str(node: Node | None) -> str:
    result = ''
    while node:
        result += str(node.val)
        node = node.next
    return result

def is_cyclic(head: Node | None) -> bool:
    if not head:
        return False
    runner = head
    walker = head
    while runner.next and runner.next.next:
        runner = runner.next.next
        walker = walker.next
        if runner == walker:
            return True
    return False

def copy_random_pointer_v1(head: RandomListNode | None) -> RandomListNode | None:
    node_map: dict[RandomListNode, RandomListNode] = {}
    current = head
    while current:
        node_map[current] = RandomListNode(current.label)
        current = current.next
    current = head
    while current:
        node_map[current].next = node_map.get(current.next)
        node_map[current].random = node_map.get(current.random)
        current = current.next
    return node_map.get(head)

def kth_to_last_eval(head: Node, k: int) -> Node | bool:
    if not isinstance(k, int) or not head.val:
        return False
    while head:
        seeker = head
        for _ in range(k):
            if seeker is None:
                return False
            seeker = seeker.next
        if seeker is None:
            return head
        head = head.next
    return False

def kth_to_last_dict(head: Node | None, k: int) -> Node | bool:
    if not (head and k > -1):
        return False
    index_map: dict[int, Node] = {}
    count = 0
    while head:
        index_map[count] = head
        head = head.next
        count += 1
    return len(index_map) - k in index_map and index_map[len(index_map) - k]

def kth_to_last(head: Node | None, k: int) -> Node | bool:
    if not (head or k > -1):
        return False
    ahead = head
    behind = head
    for _ in range(1, k + 1):
        if ahead is None:
            raise IndexError
        ahead = ahead.next
    while ahead:
        ahead = ahead.next
        behind = behind.next
    return behind

def intersection(h1: Node, h2: Node) -> Node | None:
    count = 0
    flag = None
    h1_orig = h1
    h2_orig = h2
    while h1 or h2:
        count += 1
        if not flag and (h1.next is None or h2.next is None):
            flag = (count, h1.next, h2.next)
        if h1:
            h1 = h1.next
        if h2:
            h2 = h2.next
    long_len = count
    short_len = flag[0]
    if flag[1] is None:
        shorter = h1_orig
        longer = h2_orig
    elif flag[2] is None:
        shorter = h2_orig
        longer = h1_orig
    while longer and shorter:
        while long_len > short_len:
            longer = longer.next
            long_len -= 1
        if longer == shorter:
            return longer
        else:
            longer = longer.next
            shorter = shorter.next
    return None

def first_cyclic_node(head: Node | None) -> Node | None:
    runner = walker = head
    while runner and runner.next:
        runner = runner.next.next
        walker = walker.next
        if runner is walker:
            break
    if runner is None or runner.next is None:
        return None
    walker = head
    while runner is not walker:
        (runner, walker) = (runner.next, walker.next)
    return runner

def remove_dups(head: Node | None) -> None:
    seen: set[object] = set()
    prev = Node()
    while head:
        if head.val in seen:
            prev.next = head.next
        else:
            seen.add(head.val)
            prev = head
        head = head.next

def remove_dups_wothout_set(head: Node | None) -> None:
    current = head
    while current:
        runner = current
        while runner.next:
            if runner.next.val == current.val:
                runner.next = runner.next.next
            else:
                runner = runner.next
        current = current.next

def is_sorted(head: object | None) -> bool:
    if not head:
        return True
    current = head
    while current.next:
        if current.val > current.next.val:
            return False
        current = current.next
    return True

def get_primes(n: int) -> list[int]:
    if n <= 0:
        raise ValueError("'n' must be a positive integer.")
    sieve_size = n // 2 - 1 if n % 2 == 0 else n // 2
    sieve = [True for _ in range(sieve_size)]
    primes: list[int] = []
    if n >= 2:
        primes.append(2)
    for i in range(sieve_size):
        if sieve[i]:
            value_at_i = i * 2 + 3
            primes.append(value_at_i)
            for j in range(i, sieve_size, value_at_i):
                sieve[j] = False
    return primes

def _prime_check(num: int) -> bool:
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    j = 5
    while j * j <= num:
        if num % j == 0 or num % (j + 2) == 0:
            return False
        j += 6
    return True

def _find_order(a: int, n: int) -> int:
    if (a == 1) & (n == 1):
        return 1
    if math.gcd(a, n) != 1:
        return -1
    for i in range(1, n):
        if pow(a, i) % n == 1:
            return i
    return -1

def _euler_totient(n: int) -> int:
    result = n
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
    if n > 1:
        result -= result // n
    return result

def _find_primitive_root(n: int) -> list[int]:
    if n == 1:
        return [0]
    phi = _euler_totient(n)
    p_root_list = []
    for i in range(1, n):
        if math.gcd(i, n) != 1:
            continue
        order = _find_order(i, n)
        if order == phi:
            p_root_list.append(i)
    return p_root_list

