def decimal_to_binary_util(val: str) -> str:
    bits = [128, 64, 32, 16, 8, 4, 2, 1]
    val_int = int(val)
    binary_rep = ''
    for bit in bits:
        if val_int >= bit:
            binary_rep += str(1)
            val_int -= bit
        else:
            binary_rep += str(0)
    return binary_rep

def decimal_to_binary_ip(ip: str) -> str:
