    return True

def gcd(a: int, b: int) -> int:
    a_int = isinstance(a, int)
    b_int = isinstance(b, int)
    a = abs(a)
    b = abs(b)
    if not (a_int and b_int):
        raise ValueError('Input arguments are not integers')
    if a == 0 or b == 0:
        raise ValueError('One or more input arguments equals zero')
    while b != 0:
        (a, b) = (b, a % b)
    return a

def trailing_zero(x: int) -> int:
    count = 0
    while x and (not x & 1):
        count += 1
        x >>= 1
    return count

def gcd_bit(a: int, b: int) -> int:
    tza = trailing_zero(a)
    tzb = trailing_zero(b)
    a >>= tza
    b >>= tzb
    while b:
        if a < b:
            (a, b) = (b, a)
        a -= b
        a >>= trailing_zero(a)
    return a << min(tza, tzb)

def _extended_gcd(a: int, b: int) -> tuple[int, int, int]:
    (old_r, r) = (a, b)
    (old_s, s) = (1, 0)
    (old_t, t) = (0, 1)
    while r != 0:
        q = old_r // r
        (old_r, r) = (r, old_r - q * r)
        (old_s, s) = (s, old_s - q * s)
        (old_t, t) = (t, old_t - q * t)
    return (old_r, old_s, old_t)

def _modinv(a: int, m: int) -> int:
    (g, x, _) = _extended_gcd(a, m)
    if g != 1:
        raise ValueError(f'Modular inverse does not exist: gcd({a}, {m}) = {g}')
    return x % m

def generate_key(k: int, seed: int | None=None) -> tuple[int, int, int]:

    def _gen_prime(k: int, seed: int | None=None) -> int:

        def _is_prime(num: int) -> bool:
            if num == 2:
                return True
            return all((num % i != 0 for i in range(2, int(num ** 0.5) + 1)))
        while True:
            key = secrets.randbelow(int(2 ** k) - int(2 ** (k - 1))) + int(2 ** (k - 1))
            if _is_prime(key):
                return key
    p_size = k // 2
    q_size = k - p_size
    e = _gen_prime(k, seed)
    while True:
        p = _gen_prime(p_size, seed)
        if p % e != 1:
            break
    while True:
        q = _gen_prime(q_size, seed)
        if q % e != 1:
            break
    n = p * q
    totient = (p - 1) * (q - 1)
    d = _modinv(e, totient)
    return (int(n), int(e), int(d))

