def num_perfect_squares(number: int) -> int:
    if int(math.sqrt(number)) ** 2 == number:
        return 1
    while number > 0 and number % 4 == 0:
        number //= 4
    if number % 8 == 7:
        return 4
    for i in range(1, int(math.sqrt(number)) + 1):
        if int(math.sqrt(number - i ** 2)) ** 2 == number - i ** 2:
            return 2
    return 3

