    return int(math.log10(n)) + 1

def combination(n: int, r: int) -> int:
    if n == r or r == 0:
        return 1
    return combination(n - 1, r - 1) + combination(n - 1, r)

def combination_memo(n: int, r: int) -> int:
    memo: dict[tuple[int, int], int] = {}

    def _recur(n: int, r: int) -> int:
        if n == r or r == 0:
            return 1
        if (n, r) not in memo:
            memo[n, r] = _recur(n - 1, r - 1) + _recur(n - 1, r)
        return memo[n, r]
    return _recur(n, r)

def _l2_distance(vec: list[float]) -> float:
    norm = 0.0
    for element in vec:
        norm += element * element
    norm = math.sqrt(norm)
    return norm

def cosine_similarity(vec1: list[float], vec2: list[float]) -> float:
    if len(vec1) != len(vec2):
        raise ValueError('The two vectors must be the same length. Got shape ' + str(len(vec1)) + ' and ' + str(len(vec2)))
    norm_a = _l2_distance(vec1)
    norm_b = _l2_distance(vec2)
    similarity = 0.0
    for (vec1_element, vec2_element) in zip(vec1, vec2, strict=False):
        similarity += vec1_element * vec2_element
    similarity /= norm_a * norm_b
    return similarity

def euler_totient(n: int) -> int:
    result = n
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
    if n > 1:
