    return result

def recursive_binomial_coefficient(n: int, k: int) -> int:
    if k > n:
        raise ValueError('Invalid Inputs, ensure that n >= k')
    if k == 0 or n == k:
        return 1
    if k > n / 2:
        return recursive_binomial_coefficient(n, n - k)
    return int(n / k * recursive_binomial_coefficient(n - 1, k - 1))

def int_to_base(num: int, base: int) -> str:
    is_negative = False
    if num == 0:
        return '0'
    if num < 0:
        is_negative = True
        num *= -1
    digit = string.digits + string.ascii_uppercase
    res = ''
    while num > 0:
        res += digit[num % base]
        num //= base
    if is_negative:
        return '-' + res[::-1]
    return res[::-1]

def base_to_int(str_to_convert: str, base: int) -> int:
    digit = {}
    for (ind, char) in enumerate(string.digits + string.ascii_uppercase):
        digit[char] = ind
    multiplier = 1
    res = 0
    for char in str_to_convert[::-1]:
        res += digit[char] * multiplier
        multiplier *= base
    return res

def solve_chinese_remainder(nums: list[int], rems: list[int]) -> int:
    if not len(nums) == len(rems):
        raise Exception('nums and rems should have equal length')
    if not len(nums) > 0:
        raise Exception('Lists nums and rems need to contain at least one element')
    for num in nums:
        if not num > 1:
            raise Exception('All numbers in nums needs to be > 1')
    if not _check_coprime(nums):
        raise Exception('All pairs of numbers in nums are not coprime')
    k = len(nums)
    x = 1
    while True:
        i = 0
        while i < k:
            if x % nums[i] != rems[i]:
                break
            i += 1
        if i == k:
            return x
        x += 1

def _check_coprime(list_to_check: list[int]) -> bool:
    for (ind, num) in enumerate(list_to_check):
        for num2 in list_to_check[ind + 1:]:
            if gcd(num, num2) != 1:
                return False
    return True

def cycle_product(m1: Monomial, m2: Monomial) -> Monomial:
    assert isinstance(m1, Monomial) and isinstance(m2, Monomial)
    a_vars = m1.variables
    b_vars = m2.variables
    result_variables: dict[int, int] = dict()
    for i in a_vars:
        for j in b_vars:
            k = lcm(i, j)
            g = i * j // k
            if k in result_variables:
                result_variables[k] += a_vars[i] * b_vars[j] * g
            else:
                result_variables[k] = a_vars[i] * b_vars[j] * g
    return Monomial(result_variables, Fraction(m1.coeff * m2.coeff, 1))

def cycle_product_for_two_polynomials(p1: Polynomial, p2: Polynomial, q: float | int | Fraction) -> float | int | Fraction:
    ans = Fraction(0, 1)
    for m1 in p1.monomials:
        for m2 in p2.monomials:
            ans += cycle_product(m1, m2).substitute(q)
    return ans

def _cycle_index_sym_helper(n: int, memo: dict[int, Polynomial]) -> Polynomial:
    if n in memo:
        return memo[n]
    ans = Polynomial([Monomial({}, Fraction(0, 1))])
    for t in range(1, n + 1):
        ans = ans.__add__(Polynomial([Monomial({t: 1}, Fraction(1, 1))]) * _cycle_index_sym_helper(n - t, memo))
    ans *= Fraction(1, n)
    memo[n] = ans
    return memo[n]

def get_cycle_index_sym(n: int) -> Polynomial:
    if n < 0:
        raise ValueError('n should be a non-negative integer.')
    memo = {0: Polynomial([Monomial({}, Fraction(1, 1))]), 1: Polynomial([Monomial({1: 1}, Fraction(1, 1))]), 2: Polynomial([Monomial({1: 2}, Fraction(1, 2)), Monomial({2: 1}, Fraction(1, 2))]), 3: Polynomial([Monomial({1: 3}, Fraction(1, 6)), Monomial({1: 1, 2: 1}, Fraction(1, 2)), Monomial({3: 1}, Fraction(1, 3))]), 4: Polynomial([Monomial({1: 4}, Fraction(1, 24)), Monomial({2: 1, 1: 2}, Fraction(1, 4)), Monomial({3: 1, 1: 1}, Fraction(1, 3)), Monomial({2: 2}, Fraction(1, 8)), Monomial({4: 1}, Fraction(1, 4))])}
    result = _cycle_index_sym_helper(n, memo)
    return result

def geometric_mean(numbers: list[float]) -> float:
    if not numbers:
        msg = 'List cannot be empty'
        raise ValueError(msg)
    if any((num <= 0 for num in numbers)):
        msg = 'All numbers must be positive'
        raise ValueError(msg)
    n = len(numbers)
    product = 1.0
    for num in numbers:
        product *= num
    return product ** (1 / n)

def geometric_mean_logarithm(numbers: list[float]) -> float:
    if not numbers:
        msg = 'List cannot be empty'
        raise ValueError(msg)
    if any((num <= 0 for num in numbers)):
        msg = 'All numbers must be positive'
        raise ValueError(msg)
    log_sum = sum((math.log(num) for num in numbers))
    return math.exp(log_sum / len(numbers))

def magic_number(n: int) -> bool:
    total_sum = 0
    while n > 0 or total_sum > 9:
        if n == 0:
            n = total_sum
            total_sum = 0
        total_sum += n % 10
        n //= 10
    return total_sum == 1

def factorial(n: int, mod: int | None=None) -> int:
    if not (isinstance(n, int) and n >= 0):
        raise ValueError("'n' must be a non-negative integer.")
    if mod is not None and (not (isinstance(mod, int) and mod > 0)):
        raise ValueError("'mod' must be a positive integer")
    result = 1
    if n == 0:
        return 1
    for i in range(2, n + 1):
        result *= i
        if mod:
            result %= mod
    return result

def factorial_recur(n: int, mod: int | None=None) -> int:
    if not (isinstance(n, int) and n >= 0):
        raise ValueError("'n' must be a non-negative integer.")
    if mod is not None and (not (isinstance(mod, int) and mod > 0)):
        raise ValueError("'mod' must be a positive integer")
    if n == 0:
        return 1
    result = n * factorial(n - 1, mod)
    if mod:
        result %= mod
    return result

def _helper(n: int, length: int) -> list[str]:
    if n == 0:
        return ['']
    if n == 1:
        return ['1', '0', '8']
    middles = _helper(n - 2, length)
    result = []
    for middle in middles:
        if n != length:
            result.append('0' + middle + '0')
        result.append('8' + middle + '8')
        result.append('1' + middle + '1')
        result.append('9' + middle + '6')
        result.append('6' + middle + '9')
