def rmse(x: list[float], y: list[float]) -> float:
    (slope, intercept) = linear_regression(x, y)
    n = len(y)
    return math.sqrt(sum(((yi - (slope * xi + intercept)) ** 2 for (xi, yi) in zip(x, y, strict=False))) / n)

def extended_gcd(num1: int, num2: int) -> tuple[int, int, int]:
    (old_s, s) = (1, 0)
    (old_t, t) = (0, 1)
    (old_r, r) = (num1, num2)
    while r != 0:
        quotient = old_r // r
        (old_r, r) = (r, old_r - quotient * r)
        (old_s, s) = (s, old_s - quotient * s)
        (old_t, t) = (t, old_t - quotient * t)
    if old_r < 0:
        (old_s, old_t, old_r) = (-old_s, -old_t, -old_r)
    return (old_s, old_t, old_r)

