    sum_of_digits = 0
    temp = n
    while temp != 0:
        sum_of_digits += _find_factorial(temp % 10)
        temp //= 10
    return sum_of_digits == n

def prime_check(n: int) -> bool:
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    j = 5
    while j * j <= n:
        if n % j == 0 or n % (j + 2) == 0:
            return False
        j += 6
    return True

def _extended_gcd(a: int, b: int) -> tuple[int, int, int]:
    (old_s, s) = (1, 0)
    (old_t, t) = (0, 1)
    (old_r, r) = (a, b)
    while r != 0:
        quotient = old_r // r
        (old_r, r) = (r, old_r - quotient * r)
        (old_s, s) = (s, old_s - quotient * s)
        (old_t, t) = (t, old_t - quotient * t)
    return (old_s, old_t, old_r)

def modular_inverse(a: int, m: int) -> int:
    (s, _, g) = _extended_gcd(a, m)
    if g != 1:
        raise ValueError('a and m must be coprime')
    return s % m

def surface_area_of_torus(major_radius: float, minor_radius: float) -> float:
    if major_radius < 0 or minor_radius < 0:
        raise ValueError('Radii must be non-negative')
    return 4 * pi ** 2 * major_radius * minor_radius

def hailstone(n: int) -> list[int]:
    sequence = [n]
    while n > 1:
        n = 3 * n + 1 if n % 2 != 0 else int(n / 2)
        sequence.append(n)
    return sequence

def find_order(a: int, n: int) -> int:
    if (a == 1) & (n == 1):
        return 1
    if math.gcd(a, n) != 1:
        return -1
    for i in range(1, n):
        if pow(a, i) % n == 1:
            return i
    return -1

def modular_exponential(base: int, exponent: int, mod: int) -> int:
    if exponent < 0:
        raise ValueError('Exponent must be positive.')
    base %= mod
    result = 1
    while exponent > 0:
        if exponent & 1:
            result = result * base % mod
        exponent = exponent >> 1
        base = base * base % mod
    return result

def power(a: int, n: int, mod: int | None=None) -> int:
    ans = 1
    while n:
        if n & 1:
            ans = ans * a
        a = a * a
        if mod:
            ans %= mod
            a %= mod
        n >>= 1
    return ans

def power_recur(a: int, n: int, mod: int | None=None) -> int:
    if n == 0:
        ans = 1
    elif n == 1:
        ans = a
    else:
        ans = power_recur(a, n // 2, mod)
        ans = ans * ans
        if n % 2:
            ans = ans * a
    if mod:
        ans %= mod
    return ans

def square_root(n: float, epsilon: float=0.001) -> float:
    guess = n / 2
    while abs(guess * guess - n) > epsilon:
        guess = (guess + n / guess) / 2
    return guess

def _is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def goldbach(n: int) -> tuple[int, int]:
    if n <= 2 or n % 2 != 0:
        msg = f'n must be an even integer greater than 2, got {n}'
        raise ValueError(msg)
    for i in range(2, n // 2 + 1):
        if _is_prime(i) and _is_prime(n - i):
            return (i, n - i)
    msg = f'no prime pair found for {n}'
    raise RuntimeError(msg)

def sum_dig_pow(low: int, high: int) -> list[int]:
    result = []
    for number in range(low, high + 1):
        exponent = 1
        summation = 0
        number_as_string = str(number)
        tokens = list(map(int, number_as_string))
        for k in tokens:
            summation = summation + k ** exponent
            exponent += 1
        if summation == number:
            result.append(number)
    return result

def one_sparse(array: list[tuple[int, str]]) -> int | None:
    sum_signs = 0
    bitsum: list[int] = [0] * 32
    sum_values = 0
    for (val, sign) in array:
        if sign == '+':
            sum_signs += 1
            sum_values += val
        else:
            sum_signs -= 1
            sum_values -= val
        _update_bit_sum(bitsum, val, sign)
    if sum_signs > 0 and _check_bit_sum_consistency(bitsum, sum_signs):
        return int(sum_values / sum_signs)
    return None

def _update_bit_sum(bitsum: list[int], val: int, sign: str) -> None:
    idx = 0
    if sign == '+':
        while val:
            bitsum[idx] += val & 1
            idx += 1
            val >>= 1
    else:
        while val:
            bitsum[idx] -= val & 1
            idx += 1
            val >>= 1

def misras_gries(array: list[int], k: int=2) -> dict[str, int] | None:
    keys: dict[str, int] = {}
    for item in array:
        val = str(item)
        if val in keys:
            keys[val] += 1
        elif len(keys) < k - 1:
            keys[val] = 1
        else:
            for key in list(keys):
                keys[key] -= 1
                if keys[key] == 0:
                    del keys[key]
    suspects = keys.keys()
    frequencies: dict[str, int] = {}
    for suspect in suspects:
        freq = _count_frequency(array, int(suspect))
        if freq >= len(array) / k:
            frequencies[suspect] = freq
    return frequencies if frequencies else None

def is_isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    mapping: dict[str, str] = {}
    mapped_values: set[str] = set()
    for i in range(len(s)):
        if s[i] not in mapping:
            if t[i] in mapped_values:
                return False
            mapping[s[i]] = t[i]
            mapped_values.add(t[i])
        elif mapping[s[i]] != t[i]:
            return False
    return True

def word_pattern(pattern: str, string: str) -> bool:
    mapping: dict[str, str] = {}
    mapped_values: set[str] = set()
    words = string.split()
    if len(words) != len(pattern):
        return False
    for i in range(len(pattern)):
        if pattern[i] not in mapping:
            if words[i] in mapped_values:
                return False
            mapping[pattern[i]] = words[i]
            mapped_values.add(words[i])
        elif mapping[pattern[i]] != words[i]:
            return False
    return True

def max_common_sub_string(s1: str, s2: str) -> str:
    char_index = {s2[i]: i for i in range(len(s2))}
    max_length = 0
    best_substring = ''
    i = 0
    while i < len(s1):
        if s1[i] in char_index:
            j = char_index[s1[i]]
            k = i
            while j < len(s2) and k < len(s1) and (s1[k] == s2[j]):
                k += 1
                j += 1
            if k - i > max_length:
                max_length = k - i
                best_substring = s1[i:k]
            i = k
        else:
            i += 1
    return best_substring

def is_anagram(s: str, t: str) -> bool:
    freq_s: dict[str, int] = {}
    freq_t: dict[str, int] = {}
    for char in s:
        freq_s[char] = freq_s.get(char, 0) + 1
    for char in t:
        freq_t[char] = freq_t.get(char, 0) + 1
    return freq_s == freq_t

def longest_palindromic_subsequence(s: str) -> int:
    length = len(s)
    previous_row = [0] * length
    current_row = [0] * length
    longest_length = 0
    for end in range(length):
        for start in range(end + 1):
            if end - start <= 1:
                if s[start] == s[end]:
                    current_row[start] = 1
                    span = end - start + 1
                    if longest_length < span:
                        longest_length = span
            elif s[start] == s[end] and previous_row[start + 1]:
                current_row[start] = 1
                span = end - start + 1
                if longest_length < span:
                    longest_length = span
        previous_row = current_row
        current_row = [0] * length
    return longest_length

def is_valid_sudoku(board: list[list[str]]) -> bool:
    seen: list[tuple[str, ...]] = []
    for (i, row) in enumerate(board):
        for (j, cell) in enumerate(row):
            if cell != '.':
                seen += [(cell, j), (i, cell), (i // 3, j // 3, cell)]
    return len(seen) == len(set(seen))

def max_sliding_window(nums: list[int], k: int) -> list[int]:
    if not nums:
        return nums
    queue: collections.deque[int] = collections.deque()
    result: list[int] = []
    for num in nums:
        if len(queue) < k:
            queue.append(num)
        else:
            result.append(max(queue))
            queue.popleft()
            queue.append(num)
    result.append(max(queue))
    return result

def merge_k_lists(lists: list[ListNode | None]) -> ListNode | None:
    dummy = node = ListNode(0)
    heap: list[tuple[int, int, ListNode]] = []
    for (idx, head) in enumerate(lists):
        if head:
            heap.append((head.val, idx, head))
    heapify(heap)
    while heap:
        (val, idx, n_val) = heap[0]
        if n_val.next is None:
            heappop(heap)
        else:
            heapreplace(heap, (n_val.next.val, idx, n_val.next))
        node.next = n_val
        node = node.next
    return dummy.next

def get_skyline(lrh: list[list[int]]) -> list[list[int]]:
    skyline: list[list[int]] = []
    live: list[list[int]] = []
    (i, n) = (0, len(lrh))
    while i < n or live:
        if not live or (i < n and lrh[i][0] <= -live[0][1]):
            x = lrh[i][0]
            while i < n and lrh[i][0] == x:
                heapq.heappush(live, [-lrh[i][2], -lrh[i][1]])
                i += 1
        else:
            x = -live[0][1]
            while live and -live[0][1] <= x:
                heapq.heappop(live)
        height = len(live) and -live[0][0]
        if not skyline or height != skyline[-1][1]:
            skyline += [[x, height]]
    return skyline

def _binary(x: int, length: int=1) -> str:
    fmt = f'{{0:0{length}b}}'
    return fmt.format(x)

def lzw_encode(data: str) -> tuple[list[int], dict[int, str]]:
    if not data:
        return ([], {})
    dictionary = _build_initial_dictionary(data)
    next_code = len(dictionary)
    encoded: list[int] = []
    current: str = ''
    for char in data:
        combined = current + char
        if combined in dictionary:
            current = combined
        else:
            encoded.append(dictionary[current])
            dictionary[combined] = next_code
            next_code += 1
            current = char
    if current:
        encoded.append(dictionary[current])
    initial_dictionary = {code: char for (char, code) in dictionary.items() if len(char) == 1}
    return (encoded, initial_dictionary)

def lzw_decode(encoded: list[int], initial_dictionary: dict[int, str]) -> str:
    if not encoded:
        return ''
    codes_to_strings = dict(initial_dictionary)
    next_code = max(codes_to_strings.keys()) + 1
    decoded: str = ''
    previous: str = ''
    for code in encoded:
        if code in codes_to_strings:
            current = codes_to_strings[code]
        elif code == next_code and previous:
            current = previous + previous[0]
        else:
            raise ValueError(f'Invalid LZW code: {code}')
        decoded += current
        if previous:
            codes_to_strings[next_code] = previous + current[0]
            next_code += 1
        previous = current
    return decoded

def encode_rle(data: str) -> str:
    if not data:
        return ''
    encoded: str = ''
    prev_char: str = ''
    count: int = 1
    for char in data:
        if char != prev_char:
            if prev_char:
                encoded += str(count) + prev_char
            count = 1
            prev_char = char
        else:
            count += 1
    return encoded + str(count) + prev_char

def decode_rle(data: str) -> str:
    decoded: str = ''
    count: str = ''
    for char in data:
        if not char.isdigit():
            decoded += char * int(count)
            count = ''
        else:
            count += char
    return decoded

def max_contiguous_subsequence_sum(arr: list[int]) -> int:
    if not arr:
        return 0
    max_sum = arr[0]
    current_sum = 0
    for value in arr:
        if current_sum + value < value:
            current_sum = value
        else:
            current_sum += value
        max_sum = max(max_sum, current_sum)
    return max_sum

def gale_shapley(men: dict[str, list[str]], women: dict[str, list[str]]) -> dict[str, str]:
    men_available: list[str] = list(men.keys())
    married: dict[str, str] = {}
    proposal_counts: dict[str, int] = {man: 0 for man in men}
    while men_available:
        man = men_available.pop(0)
        woman = men[man][proposal_counts[man]]
        proposal_counts[man] += 1
        if woman not in married:
            married[woman] = man
        else:
            current_partner = married[woman]
            if women[woman].index(man) < women[woman].index(current_partner):
                married[woman] = man
                men_available.append(current_partner)
            else:
                men_available.append(man)
    return {man: woman for (woman, man) in married.items()}

def _insertion_sort(array: list[int]) -> list[int]:
    for i in range(1, len(array)):
        key = array[i]
        j = i - 1
        while j >= 0 and array[j] > key:
            array[j + 1] = array[j]
            j -= 1
        array[j + 1] = key
    return array

def quick_sort(array: list[int]) -> list[int]:
    _quick_sort_recursive(array, 0, len(array) - 1)
    return array

def _quick_sort_recursive(array: list[int], first: int, last: int) -> None:
    if first < last:
        pivot = _partition(array, first, last)
        _quick_sort_recursive(array, first, pivot - 1)
        _quick_sort_recursive(array, pivot + 1, last)

def _partition(array: list[int], first: int, last: int) -> int:
    wall = first
    for pos in range(first, last):
        if array[pos] < array[last]:
            (array[pos], array[wall]) = (array[wall], array[pos])
            wall += 1
    (array[wall], array[last]) = (array[last], array[wall])
    return wall

def _merge(left: list[int], right: list[int], merged: list[int]) -> None:
    left_cursor = 0
    right_cursor = 0
    while left_cursor < len(left) and right_cursor < len(right):
        if left[left_cursor] <= right[right_cursor]:
            merged[left_cursor + right_cursor] = left[left_cursor]
            left_cursor += 1
        else:
            merged[left_cursor + right_cursor] = right[right_cursor]
            right_cursor += 1
    for left_cursor in range(left_cursor, len(left)):
        merged[left_cursor + right_cursor] = left[left_cursor]
    for right_cursor in range(right_cursor, len(right)):
        merged[left_cursor + right_cursor] = right[right_cursor]

def cycle_sort(array: list[int]) -> list[int]:
    length = len(array)
    for start in range(length - 1):
        item = array[start]
        position = start
        for i in range(start + 1, length):
            if array[i] < item:
                position += 1
        if position == start:
            continue
        while item == array[position]:
            position += 1
        (array[position], item) = (item, array[position])
        while position != start:
            position = start
            for i in range(start + 1, length):
                if array[i] < item:
                    position += 1
            while item == array[position]:
                position += 1
            (array[position], item) = (item, array[position])
    return array

def pancake_sort(array: list[int]) -> list[int]:
    if len(array) <= 1:
        return array
    for cur in range(len(array), 1, -1):
        index_max = array.index(max(array[0:cur]))
        if index_max + 1 != cur:
            if index_max != 0:
                array[:index_max + 1] = reversed(array[:index_max + 1])
            array[:cur] = reversed(array[:cur])
    return array

def insertion_sort(array: list[int]) -> list[int]:
    for i in range(len(array)):
        cursor = array[i]
        pos = i
        while pos > 0 and array[pos - 1] > cursor:
            array[pos] = array[pos - 1]
            pos -= 1
        array[pos] = cursor
    return array

def gnome_sort(array: list[int]) -> list[int]:
    n = len(array)
    index = 0
    while index < n:
        if index == 0 or array[index] >= array[index - 1]:
            index += 1
        else:
            (array[index], array[index - 1]) = (array[index - 1], array[index])
            index -= 1
    return array

def bubble_sort(array: list[int]) -> list[int]:
    n = len(array)
    swapped = True
    passes = 0
    while swapped:
        swapped = False
        for i in range(1, n - passes):
            if array[i - 1] > array[i]:
                (array[i - 1], array[i]) = (array[i], array[i - 1])
                swapped = True
        passes += 1
    return array

def stooge_sort(array: list[int]) -> list[int]:
    _stooge_sort(array, 0, len(array) - 1)
    return array

def _stooge_sort(array: list[int], low: int, high: int) -> None:
    if low >= high:
        return
    if array[low] > array[high]:
        (array[low], array[high]) = (array[high], array[low])
    if high - low + 1 > 2:
        third = (high - low + 1) // 3
        _stooge_sort(array, low, high - third)
        _stooge_sort(array, low + third, high)
        _stooge_sort(array, low, high - third)

def selection_sort(array: list[int]) -> list[int]:
    for i in range(len(array)):
        minimum = i
        for j in range(i + 1, len(array)):
            if array[j] < array[minimum]:
                minimum = j
        (array[minimum], array[i]) = (array[i], array[minimum])
    return array

def bogo_sort(array: list[int]) -> list[int]:
    while not _is_sorted(array):
        random.shuffle(array)
    return array

def radix_sort(array: list[int]) -> list[int]:
    position = 1
    max_number = max(array)
    while position <= max_number:
        buckets: list[list[int]] = [[] for _ in range(10)]
        for num in array:
            digit = num // position % 10
            buckets[digit].append(num)
        index = 0
        for bucket in buckets:
            for num in bucket:
                array[index] = num
                index += 1
        position *= 10
    return array

def wiggle_sort(array: list[int]) -> list[int]:
    for i in range(len(array)):
        if (i % 2 == 1) == (array[i - 1] > array[i]):
            (array[i - 1], array[i]) = (array[i], array[i - 1])
    return array

def sort_colors(array: list[int]) -> list[int]:
    red = white = 0
    for k in range(len(array)):
        value = array[k]
        array[k] = 2
        if value < 2:
            array[white] = 1
            white += 1
        if value == 0:
            array[red] = 0
            red += 1
    return array

def max_heap_sort(array: list[int]) -> list[int]:
    for i in range(len(array) - 1, 0, -1):
        _max_heapify(array, i)
    return array

def _max_heapify(array: list[int], end: int) -> None:
    last_parent = (end - 1) // 2
    for parent in range(last_parent, -1, -1):
        current = parent
        while current <= last_parent:
            child = 2 * current + 1
            if child + 1 <= end and array[child] < array[child + 1]:
                child += 1
            if array[child] > array[current]:
                (array[current], array[child]) = (array[child], array[current])
                current = child
            else:
                break
    (array[0], array[end]) = (array[end], array[0])

def min_heap_sort(array: list[int]) -> list[int]:
    for i in range(len(array) - 1):
        _min_heapify(array, i)
    return array

def _min_heapify(array: list[int], start: int) -> None:
    end = len(array) - 1
    last_parent = (end - start - 1) // 2
    for parent in range(last_parent, -1, -1):
        current = parent
        while current <= last_parent:
            child = 2 * current + 1
            if child + 1 <= end - start and array[child + start] > array[child + 1 + start]:
                child += 1
            if array[child + start] < array[current + start]:
                (array[current + start], array[child + start]) = (array[child + start], array[current + start])
                current = child
            else:
                break

def exchange_sort(array: list[int]) -> list[int]:
    n = len(array)
    for i in range(n - 1):
        for j in range(i + 1, n):
            if array[i] > array[j]:
                (array[i], array[j]) = (array[j], array[i])
    return array

def cocktail_shaker_sort(array: list[int]) -> list[int]:
    n = len(array)
    swapped = True
    while swapped:
        swapped = False
        for i in range(1, n):
            if array[i - 1] > array[i]:
                (array[i - 1], array[i]) = (array[i], array[i - 1])
                swapped = True
        if not swapped:
            return array
        swapped = False
        for i in range(n - 1, 0, -1):
            if array[i - 1] > array[i]:
                (array[i - 1], array[i]) = (array[i], array[i - 1])
                swapped = True
    return array

def bead_sort(array: list[int]) -> list[int]:
    if any((num < 0 for num in array)):
        raise ValueError('Bead sort only works with non-negative integers.')
    max_value = max(array) if array else 0
    grid = [[0] * len(array) for _ in range(max_value)]
    for (col, num) in enumerate(array):
        for row in range(num):
            grid[row][col] = 1
    for row in grid:
        bead_count = sum(row)
        for col in range(len(array)):
            row[col] = 1 if col < bead_count else 0
    n = len(array)
    sorted_array = [0] * n
    for col in range(n):
        sorted_array[col] = sum((grid[row][n - 1 - col] for row in range(max_value)))
    return sorted_array

def can_attend_meetings(intervals: list) -> bool:
    intervals = sorted(intervals, key=lambda x: x.start)
    for i in range(1, len(intervals)):
        if intervals[i].start < intervals[i - 1].end:
            return False
    return True

def bitonic_sort(array: list[int], reverse: bool=False) -> list[int]:
    n = len(array)
    if n <= 1:
        return array
    if not (n and (not n & n - 1)):
        raise ValueError('the size of input should be power of two')
    left = bitonic_sort(array[:n // 2], True)
    right = bitonic_sort(array[n // 2:], False)
    return _bitonic_merge(left + right, reverse)

def _compare(array: list[int], reverse: bool) -> list[int]:
    half = len(array) // 2
    for i in range(half):
        if reverse != (array[i] > array[i + half]):
            (array[i], array[i + half]) = (array[i + half], array[i])
    return array

def reconstruct_queue(people: list[list[int]]) -> list[list[int]]:
    queue: list[list[int]] = []
    people.sort(key=lambda x: (-x[0], x[1]))
    for (height, count) in people:
        queue.insert(count, [height, count])
    return queue

def max_sliding_window(arr: list[int], k: int) -> list[int]:
    index_deque: collections.deque[int] = collections.deque()
    result: list[int] = []
    for (i, value) in enumerate(arr):
        while index_deque and arr[index_deque[-1]] < value:
            index_deque.pop()
        index_deque.append(i)
        if index_deque[0] == i - k:
            index_deque.popleft()
        if i >= k - 1:
            result.append(arr[index_deque[0]])
    return result

def match_symbol(words: list[str], symbols: list[str]) -> list[str]:
    combined = []
    for symbol in symbols:
        for word in words:
            match = re.search(symbol, word)
            if match:
                combined.append(re.sub(symbol, f'[{symbol}]', word))
    return combined

def match_symbol_1(words: list[str], symbols: list[str]) -> list[str]:
    result = []
    symbols = sorted(symbols, key=lambda item: len(item), reverse=True)
    for word in words:
        word_replaced = ''
        for symbol in symbols:
            if word.find(symbol) != -1:
                word_replaced = word.replace(symbol, '[' + symbol + ']')
                result.append(word_replaced)
                break
        if word_replaced == '':
            result.append(word)
    return result

def bracket(words: list[str], symbols: list[str]) -> tuple[str, ...]:
    root = _TrieNode()
    for symbol in symbols:
        node = root
        for char in symbol:
            if char not in node.children:
                node.children[char] = _TrieNode()
            node = node.children[char]
        node.symbol = symbol
    matched = {}
    for word in words:
        index = 0
        symbol_list = []
        while index < len(word):
            (cursor, node) = (index, root)
            while cursor < len(word) and word[cursor] in node.children:
                node = node.children[word[cursor]]
                if node.symbol is not None:
                    symbol_list.append((cursor + 1 - len(node.symbol), cursor + 1, node.symbol))
                cursor += 1
            index += 1
        if len(symbol_list) > 0:
            best = reduce(lambda x, y: x if x[1] - x[0] >= y[1] - y[0] else y, symbol_list)
            matched[word] = f'{word[:best[0]]}[{best[2]}]{word[best[1]:]}'
    return tuple((matched.get(word, word) for word in words))

def license_number(key: str, group_size: int) -> str:
    result: list[str] = []
    alphanumeric: list[str] = []
    for char in key:
        if char != '-':
            alphanumeric.append(char)
    for (index, char) in enumerate(reversed(alphanumeric)):
        result.append(char)
        if (index + 1) % group_size == 0 and index != len(alphanumeric) - 1:
            result.append('-')
    return ''.join(result[::-1])

def check_pangram(input_string: str) -> bool:
