def can_swap_to_equal(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    diffs = [(a, b) for (a, b) in zip(s, t, strict=False) if a != b]
    return len(diffs) == 2 and diffs[0] == diffs[1][::-1]

def strong_password(length: int, password: str) -> int:
    missing_types = 0
    if not any((char.isdigit() for char in password)):
        missing_types += 1
    if not any((char.islower() for char in password)):
        missing_types += 1
    if not any((char.isupper() for char in password)):
        missing_types += 1
    if not any((char in '!@#$%^&*()-+' for char in password)):
        missing_types += 1
    return max(missing_types, 6 - length)

def delete_reoccurring_characters(string: str) -> str:
