def alphabet_board_path(target: str) -> str:
    moves: list[str] = []
    (row, col) = (0, 0)
    for ch in target:
        idx = ord(ch) - ord('a')
        (target_row, target_col) = divmod(idx, 5)
        if target_row < row:
            moves.append('U' * (row - target_row))
        if target_col < col:
            moves.append('L' * (col - target_col))
        if target_row > row:
            moves.append('D' * (target_row - row))
        if target_col > col:
            moves.append('R' * (target_col - col))
        moves.append('!')
        (row, col) = (target_row, target_col)
    return ''.join(moves)

def strip_url_params1(url: str, params_to_strip: list[str] | None=None) -> str:
    if not params_to_strip:
        params_to_strip = []
    if url:
        result = ''
        tokens = url.split('?')
        domain = tokens[0]
        query_string = tokens[-1]
        result += domain
        if len(tokens) > 1:
            result += '?'
        if not query_string:
            return url
        else:
            key_value_pairs: list[str] = []
            fragment = ''
            for char in query_string:
                if char.isdigit():
                    key_value_pairs.append(fragment + char)
                    fragment = ''
                else:
                    fragment += char
            seen: dict[str, int] = defaultdict(int)
            for pair in key_value_pairs:
                token_parts = pair.split('=')
                if token_parts[0]:
                    length = len(token_parts[0])
                    if length == 1:
                        if token_parts and token_parts[0] not in seen:
                            if params_to_strip:
                                if token_parts[0] != params_to_strip[0]:
                                    seen[token_parts[0]] = token_parts[1]
                                    result = result + token_parts[0] + '=' + token_parts[1]
                            elif token_parts[0] not in seen:
                                seen[token_parts[0]] = token_parts[1]
                                result = result + token_parts[0] + '=' + token_parts[1]
                    else:
                        check = token_parts[0]
                        letter = check[1]
                        if token_parts and letter not in seen:
                            if params_to_strip:
                                if letter != params_to_strip[0]:
                                    seen[letter] = token_parts[1]
                                    result = result + token_parts[0] + '=' + token_parts[1]
                            elif letter not in seen:
                                seen[letter] = token_parts[1]
                                result = result + token_parts[0] + '=' + token_parts[1]
    return result

def strip_url_params2(url: str, param_to_strip: list[str] | None=None) -> str:
    if param_to_strip is None:
        param_to_strip = []
    if '?' not in url:
        return url
    (domain, query_string) = url.split('?', 1)
    seen: set[str] = set()
    queries: list[str] = []
    for query in query_string.split('&'):
        key = query.split('=', 1)[0]
        if key not in param_to_strip and key not in seen:
            seen.add(key)
            queries.append(query)
    return domain + '?' + '&'.join(queries)

def strip_url_params3(url: str, strip: list[str] | None=None) -> str:
    if not strip:
        strip = []
    parsed = urllib.parse.urlparse(url)
    query = urllib.parse.parse_qs(parsed.query)
    query = {key: values[0] for (key, values) in query.items() if key not in strip}
    query_string = urllib.parse.urlencode(query)
    new_parsed = parsed._replace(query=query_string)
    return new_parsed.geturl()

def repeat_substring(text: str) -> bool:
