def is_palindrome_stack(text: str) -> bool:
    stack: list[str] = []
    text = _remove_punctuation(text)
    for index in range(len(text) // 2, len(text)):
        stack.append(text[index])
    return all((text[index] == stack.pop() for index in range(0, len(text) // 2)))

def is_palindrome_deque(text: str) -> bool:
    text = _remove_punctuation(text)
    character_deque: deque[str] = deque()
    for char in text:
        character_deque.appendleft(char)
    equal = True
    while len(character_deque) > 1 and equal:
        first = character_deque.pop()
        last = character_deque.popleft()
        if first != last:
            equal = False
    return equal

def fizzbuzz(number: int) -> list[int | str]:
    if number < 1:
        raise ValueError('n cannot be less than one')
    if number is None:
        raise TypeError('n cannot be None')
    result: list[int | str] = []
    for value in range(1, number + 1):
        if value % 3 == 0 and value % 5 == 0:
            result.append('FizzBuzz')
        elif value % 3 == 0:
            result.append('Fizz')
        elif value % 5 == 0:
            result.append('Buzz')
        else:
            result.append(value)
    return result

def _fb(value: int) -> int | str:
    result = (value % 3 == 0) * 'Fizz' + (value % 5 == 0) * 'Buzz'
