def rabin_karp(word: str, text: str) -> int | None:
    if word == '' or text == '':
        return None
    if len(word) > len(text):
        return None
    rolling_hash = RollingHash(text, len(word))
    word_hash = RollingHash(word, len(word))
    for _ in range(len(text) - len(word) + 1):
        if rolling_hash.hash == word_hash.hash and rolling_hash.window_text() == word:
            return rolling_hash.window_start
        rolling_hash.move_window()
    return None

def compute_z_array(s: str) -> list[int]:
    n = len(s)
    if n == 0:
        return []
    z = [0] * n
    z[0] = n
    left = right = 0
    for i in range(1, n):
        if i < right:
            z[i] = min(right - i, z[i - left])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > right:
            (left, right) = (i, i + z[i])
    return z

def knuth_morris_pratt(text: Sequence, pattern: Sequence) -> list[int]:
    text_length = len(text)
    pattern_length = len(pattern)
    prefix_table = [0 for _ in range(pattern_length)]
    match_length = 0
    for index in range(1, pattern_length):
        while match_length and pattern[index] != pattern[match_length]:
            match_length = prefix_table[match_length - 1]
        if pattern[index] == pattern[match_length]:
            match_length += 1
            prefix_table[index] = match_length
    match_length = 0
    matches: list[int] = []
    for index in range(text_length):
        while match_length and text[index] != pattern[match_length]:
            match_length = prefix_table[match_length - 1]
        if text[index] == pattern[match_length]:
            match_length += 1
            if match_length == pattern_length:
                matches.append(index - pattern_length + 1)
                match_length = prefix_table[match_length - 1]
    return matches

def atbash(text: str) -> str:
    translated = ''
    for char in text:
        code = ord(char)
        if char.isalpha():
            if char.isupper():
                offset = code - ord('A')
                translated += chr(ord('Z') - offset)
            elif char.islower():
                offset = code - ord('a')
                translated += chr(ord('z') - offset)
        else:
            translated += char
    return translated

def word_squares(words: list[str]) -> list[list[str]]:
    word_length = len(words[0])
    prefix_map: dict[str, list[str]] = collections.defaultdict(list)
    for word in words:
        for index in range(word_length):
            prefix_map[word[:index]].append(word)

    def _build(square: list[str]) -> None:
        if len(square) == word_length:
            squares.append(square)
            return
        prefix = ''
        for row in range(len(square)):
            prefix += square[row][len(square)]
        for word in prefix_map[prefix]:
            _build(square + [word])
    squares: list[list[str]] = []
    for word in words:
        _build([word])
    return squares

def _common_prefix(first: str, second: str) -> str:
    if not first or not second:
        return ''
    index = 0
    while first[index] == second[index]:
        index = index + 1
        if index >= len(first) or index >= len(second):
            return first[0:index]
    return first[0:index]

def longest_common_prefix_v1(strings: list[str]) -> str:
