def manacher(s: str) -> str:
    t = '^#' + '#'.join(s) + '#$'
    n = len(t)
    p = [0] * n
    centre = right = 0
    for i in range(1, n - 1):
        mirror = 2 * centre - i
        if i < right:
            p[i] = min(right - i, p[mirror])
        while t[i + p[i] + 1] == t[i - p[i] - 1]:
            p[i] += 1
        if i + p[i] > right:
            (centre, right) = (i, i + p[i])
    (max_len, centre_index) = max(((v, i) for (i, v) in enumerate(p)))
    start = (centre_index - max_len) // 2
    return s[start:start + max_len]

def decode_string(text: str) -> str:
    stack: list[tuple[str, int]] = []
    current_num = 0
    current_string = ''
    for char in text:
        if char == '[':
            stack.append((current_string, current_num))
            current_string = ''
            current_num = 0
        elif char == ']':
            (prev_string, num) = stack.pop()
            current_string = prev_string + num * current_string
        elif char.isdigit():
            current_num = current_num * 10 + int(char)
        else:
            current_string += char
    return current_string

def is_merge_recursive(text: str, part1: str, part2: str) -> bool:
    if not part1:
        return text == part2
    if not part2:
        return text == part1
    if not text:
        return part1 + part2 == ''
    if text[0] == part1[0] and is_merge_recursive(text[1:], part1[1:], part2):
        return True
    return text[0] == part2[0] and is_merge_recursive(text[1:], part1, part2[1:])

def is_merge_iterative(text: str, part1: str, part2: str) -> bool:
    tuple_list = [(text, part1, part2)]
    while tuple_list:
        (string, first_part, second_part) = tuple_list.pop()
        if string:
            if first_part and string[0] == first_part[0]:
                tuple_list.append((string[1:], first_part[1:], second_part))
            if second_part and string[0] == second_part[0]:
                tuple_list.append((string[1:], first_part, second_part[1:]))
        elif not first_part and (not second_part):
            return True
    return False

def longest_palindrome(text: str) -> str:
    if len(text) < 2:
        return text
    separator = object()
    expanded: list[object] = [separator]
    for char in text:
        expanded.extend((char, separator))
    palindrome_radii = [0] * len(expanded)
    (center, right_boundary) = (0, 0)
    (best_index, best_length) = (0, 0)
    for index in range(len(expanded)):
        if index < right_boundary and 2 * center - index < len(expanded):
            palindrome_radii[index] = min(right_boundary - index, palindrome_radii[2 * center - index])
        else:
            palindrome_radii[index] = 1
        while palindrome_radii[index] + index < len(expanded) and index - palindrome_radii[index] >= 0 and (expanded[index - palindrome_radii[index]] == expanded[index + palindrome_radii[index]]):
            palindrome_radii[index] += 1
        if index + palindrome_radii[index] > right_boundary:
            right_boundary = index + palindrome_radii[index]
            center = index
        if palindrome_radii[index] > best_length:
            best_index = index
            best_length = palindrome_radii[index]
    start = (best_index - best_length + 1) // 2
    return text[start:start + best_length - 1]

def _lcs(word1: str, word2: str, length1: int, length2: int) -> int:
    if length1 == 0 or length2 == 0:
        return 0
    if word1[length1 - 1] == word2[length2 - 1]:
        return 1 + _lcs(word1, word2, length1 - 1, length2 - 1)
    return max(_lcs(word1, word2, length1 - 1, length2), _lcs(word1, word2, length1, length2 - 1))

def min_distance_dp(word1: str, word2: str) -> int:
    (rows, cols) = (len(word1) + 1, len(word2) + 1)
    table = [[0 for _ in range(cols)] for _ in range(rows)]
    if rows == cols:
        for index in range(1, rows):
            (table[index][0], table[0][index]) = (index, index)
    else:
        for index in range(rows):
            table[index][0] = index
        for index in range(cols):
            table[0][index] = index
    for row in range(1, rows):
        for col in range(1, cols):
            if word1[row - 1] == word2[col - 1]:
                table[row][col] = table[row - 1][col - 1]
            else:
                table[row][col] = min(table[row - 1][col], table[row][col - 1]) + 1
    return table[len(word1)][len(word2)]

def reverse_vowel(text: str) -> str:
    vowels = 'AEIOUaeiou'
    (left, right) = (0, len(text) - 1)
    characters = list(text)
    while left < right:
        while left < right and characters[left] not in vowels:
            left += 1
        while left < right and characters[right] not in vowels:
            right -= 1
        (characters[left], characters[right]) = (characters[right], characters[left])
        (left, right) = (left + 1, right - 1)
    return ''.join(characters)

def remove_min(stack: list[int]) -> list[int]:
    storage_stack: list[int] = []
    if len(stack) == 0:
        return stack
    minimum = stack.pop()
    stack.append(minimum)
    for _ in range(len(stack)):
        val = stack.pop()
        if val <= minimum:
            minimum = val
        storage_stack.append(val)
    for _ in range(len(storage_stack)):
        val = storage_stack.pop()
        if val != minimum:
            stack.append(val)
    return stack

def first_switch_pairs(stack: list[int]) -> list[int]:
