    for _ in range(len(stack)):
        storage_stack.append(stack.pop())
    for _ in range((len(storage_stack) + 1) // 2):
        first = storage_stack.pop()
        if len(storage_stack) == 0:
            stack.append(first)
            break
        second = storage_stack.pop()
        stack.append(second)
        stack.append(first)
    return stack

