    for _ in range(len(queue)):
        stack.append(queue.pop())
    for _ in range(len(stack)):
        queue.append(stack.pop())
    for _ in range(len(queue)):
        if len(queue) == 0:
            break
        first = queue.pop()
        if len(queue) == 0:
            stack.append(first)
            break
        second = queue.pop()
        stack.append(second)
        stack.append(first)
    return stack

