def simplify_path(path: str) -> str:
    skip = {'..', '.', ''}
    stack: list[str] = []
    tokens = path.split('/')
    for token in tokens:
        if token == '..':
            if stack:
                stack.pop()
        elif token not in skip:
            stack.append(token)
    return '/' + '/'.join(stack)

