def search_in_a_sorted_matrix(mat: list[list[int]], rows: int, cols: int, key: int) -> bool:
    (i, j) = (rows - 1, 0)
    while i >= 0 and j < cols:
        if key == mat[i][j]:
            return True
        if key < mat[i][j]:
            i -= 1
        else:
            j += 1
    return False

def count_paths(rows: int, cols: int) -> int:
    if rows < 1 or cols < 1:
        return -1
    count = [[None for _ in range(cols)] for _ in range(rows)]
    for i in range(cols):
        count[0][i] = 1
    for j in range(rows):
        count[j][0] = 1
    for i in range(1, rows):
        for j in range(1, cols):
            count[i][j] = count[i - 1][j] + count[i][j - 1]
    return count[rows - 1][cols - 1]

def cholesky_decomposition(matrix: list[list[float]]) -> list[list[float]] | None:
    size = len(matrix)
    for row in matrix:
        if len(row) != size:
            return None
    result = [[0.0] * size for _ in range(size)]
    for j in range(size):
        diagonal_sum = sum((result[j][k] ** 2 for k in range(j)))
        diagonal_sum = matrix[j][j] - diagonal_sum
        if diagonal_sum <= 0:
            return None
        result[j][j] = math.sqrt(diagonal_sum)
        for i in range(j + 1, size):
            off_diagonal_sum = sum((result[i][k] * result[j][k] for k in range(j)))
            result[i][j] = (matrix[i][j] - off_diagonal_sum) / result[j][j]
    return result

def multiply(multiplicand: list[list[int]], multiplier: list[list[int]]) -> list[list[int]]:
    (multiplicand_rows, multiplicand_cols) = (len(multiplicand), len(multiplicand[0]))
    (multiplier_rows, multiplier_cols) = (len(multiplier), len(multiplier[0]))
    if multiplicand_cols != multiplier_rows:
        raise Exception('Multiplicand matrix not compatible with Multiplier matrix.')
    result = [[0] * multiplier_cols for _ in range(multiplicand_rows)]
    for i in range(multiplicand_rows):
        for j in range(multiplier_cols):
            for k in range(len(multiplier)):
                result[i][j] += multiplicand[i][k] * multiplier[k][j]
    return result

def sparse_multiply(mat_a: list[list[int]], mat_b: list[list[int]]) -> list[list[int]] | None:
    if mat_a is None or mat_b is None:
        return None
    (rows_a, cols_a) = (len(mat_a), len(mat_a[0]))
    cols_b = len(mat_b[0])
    if len(mat_b) != cols_a:
        raise Exception("A's column number must be equal to B's row number.")
    result = [[0] * cols_b for _ in range(rows_a)]
    for (i, row) in enumerate(mat_a):
        for (k, elem_a) in enumerate(row):
            if elem_a:
                for (j, elem_b) in enumerate(mat_b[k]):
                    if elem_b:
                        result[i][j] += elem_a * elem_b
    return result

def multiply(mat_a: list[list[int]], mat_b: list[list[int]]) -> list[list[int]]:
    size = len(mat_a)
    result = [[0] * size for _ in range(size)]
    for i in range(size):
        for j in range(size):
            for k in range(size):
                result[i][j] += mat_a[i][k] * mat_b[k][j]
    return result

def identity(size: int) -> list[list[int]]:
    result = [[0] * size for _ in range(size)]
    for i in range(size):
        result[i][i] = 1
    return result

def matrix_exponentiation(mat: list[list[int]], power: int) -> list[list[int]]:
    if power == 0:
        return identity(len(mat))
    elif power % 2 == 1:
        return multiply(matrix_exponentiation(mat, power - 1), mat)
    else:
        half = matrix_exponentiation(mat, power // 2)
        return multiply(half, half)

def sum_sub_squares(matrix: list[list[int]], k: int) -> list[list[int]] | None:
    size = len(matrix)
    if k > size:
        return None
    result_size = size - k + 1
    result = [[0] * result_size for _ in range(result_size)]
    for i in range(result_size):
        for j in range(result_size):
            total = 0
            for p in range(i, k + i):
                for q in range(j, k + j):
                    total += matrix[p][q]
            result[i][j] = total
    return result

def invert_matrix(matrix: list[list[int | float]]) -> list[list[int | float | fractions.Fraction]]:
    if not _array_is_matrix(matrix):
        return [[-1]]
    elif len(matrix) != len(matrix[0]):
        return [[-2]]
    elif len(matrix) < 2:
        return [[-3]]
    elif get_determinant(matrix) == 0:
        return [[-4]]
    elif len(matrix) == 2:
        multiplier = 1 / get_determinant(matrix)
        inverted = [[multiplier] * len(matrix) for _ in range(len(matrix))]
        inverted[0][1] = inverted[0][1] * -1 * matrix[0][1]
        inverted[1][0] = inverted[1][0] * -1 * matrix[1][0]
        inverted[0][0] = multiplier * matrix[1][1]
        inverted[1][1] = multiplier * matrix[0][0]
        return inverted
    else:
        matrix_of_minors = _get_matrix_of_minors(matrix)
        multiplier = fractions.Fraction(1, get_determinant(matrix))
        inverted = _transpose_and_multiply(matrix_of_minors, multiplier)
        return inverted

def get_determinant(matrix: list[list[int | float]]) -> int | float:
    if len(matrix) == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    sign = 1
    det = 0
    for i in range(len(matrix)):
        det += sign * matrix[0][i] * get_determinant(_get_minor(matrix, 0, i))
        sign *= -1
    return det

def _get_matrix_of_minors(matrix: list[list[int | float]]) -> list[list[int | float]]:
    size = len(matrix)
    result = [[0] * size for _ in range(size)]
    for row in range(size):
        for col in range(len(matrix[0])):
            sign = 1 if (row + col) % 2 == 0 else -1
            result[row][col] = sign * get_determinant(_get_minor(matrix, row, col))
    return result

def _get_minor(matrix: list[list[int | float]], row: int, col: int) -> list[list[int | float]]:
    minors = []
    for i in range(len(matrix)):
        if i != row:
            new_row = matrix[i][:col]
            new_row.extend(matrix[i][col + 1:])
            minors.append(new_row)
    return minors

def _transpose_and_multiply(matrix: list[list[int | float]], multiplier: int | float | fractions.Fraction=1) -> list[list[int | float | fractions.Fraction]]:
    for row in range(len(matrix)):
        for col in range(row + 1):
            temp = matrix[row][col] * multiplier
            matrix[row][col] = matrix[col][row] * multiplier
            matrix[col][row] = temp
    return matrix

def _array_is_matrix(matrix: list[list]) -> bool:
    if len(matrix) == 0:
        return False
    first_col = len(matrix[0])
    return all((len(row) == first_col for row in matrix))

def rotate(mat: list[list[int]]) -> list[list[int]]:
    if not mat:
        return mat
    mat.reverse()
    for i in range(len(mat)):
        for j in range(i):
            (mat[i][j], mat[j][i]) = (mat[j][i], mat[i][j])
    return mat

def spiral_traversal(matrix: list[list[int]]) -> list[int]:
    result: list[int] = []
    if len(matrix) == 0:
        return result
    row_begin = 0
    row_end = len(matrix) - 1
    col_begin = 0
    col_end = len(matrix[0]) - 1
    while row_begin <= row_end and col_begin <= col_end:
        for i in range(col_begin, col_end + 1):
            result.append(matrix[row_begin][i])
        row_begin += 1
        for i in range(row_begin, row_end + 1):
            result.append(matrix[i][col_end])
        col_end -= 1
        if row_begin <= row_end:
            for i in range(col_end, col_begin - 1, -1):
                result.append(matrix[row_end][i])
        row_end -= 1
        if col_begin <= col_end:
            for i in range(row_end, row_begin - 1, -1):
                result.append(matrix[i][col_begin])
        col_begin += 1
    return result

def max_killed_enemies(grid: list[list[str]]) -> int:
    if not grid:
        return 0
    (rows, cols) = (len(grid), len(grid[0]))
    max_killed = 0
    (row_enemies, col_enemies) = (0, [0] * cols)
    for i in range(rows):
        for j in range(cols):
            if j == 0 or grid[i][j - 1] == 'W':
                row_enemies = _row_kills(grid, i, j)
            if i == 0 or grid[i - 1][j] == 'W':
                col_enemies[j] = _col_kills(grid, i, j)
            if grid[i][j] == '0':
                max_killed = max(max_killed, row_enemies + col_enemies[j])
    return max_killed

def _row_kills(grid: list[list[str]], row: int, col: int) -> int:
    count = 0
    num_cols = len(grid[0])
    while col < num_cols and grid[row][col] != 'W':
        if grid[row][col] == 'E':
            count += 1
        col += 1
    return count

def _col_kills(grid: list[list[str]], row: int, col: int) -> int:
    count = 0
    num_rows = len(grid)
    while row < num_rows and grid[row][col] != 'W':
        if grid[row][col] == 'E':
            count += 1
        row += 1
    return count

def dot_product(iv_list1: list[tuple[int, float]], iv_list2: list[tuple[int, float]]) -> float:
    product = 0
    p1 = len(iv_list1) - 1
    p2 = len(iv_list2) - 1
    while p1 >= 0 and p2 >= 0:
        (i1, v1) = iv_list1[p1]
        (i2, v2) = iv_list2[p2]
        if i1 < i2:
            p1 -= 1
        elif i2 < i1:
            p2 -= 1
        else:
            product += v1 * v2
            p1 -= 1
            p2 -= 1
    return product

def crout_matrix_decomposition(matrix: list[list[float]]) -> tuple[list[list[float]], list[list[float]]]:
    size = len(matrix)
    lower = [[0.0] * size for _ in range(size)]
    upper = [[0.0] * size for _ in range(size)]
    for j in range(size):
        upper[j][j] = 1.0
        for i in range(j, size):
            alpha = float(matrix[i][j])
            for k in range(j):
                alpha -= lower[i][k] * upper[k][j]
            lower[i][j] = float(alpha)
        for i in range(j + 1, size):
            temp = float(matrix[j][i])
            for k in range(j):
                temp -= float(lower[j][k] * upper[k][i])
            if int(lower[j][j]) == 0:
                lower[j][j] = float(0.1 ** 40)
            upper[j][i] = float(temp / lower[j][j])
    return (lower, upper)

