def _abs_timedelta(delta):
    if delta.days < 0:
        now = _now()
        return now - (now + delta)
    return delta

def _date_and_delta(value, *, now=None):
    if not now:
        now = _now()
    if isinstance(value, dt.datetime):
        date = value
        delta = now - value
    elif isinstance(value, dt.timedelta):
        date = now - value
        delta = value
    else:
        try:
            value = int(value)
            delta = dt.timedelta(seconds=value)
            date = now - delta
        except (ValueError, TypeError):
            return (None, value)
    return (date, _abs_timedelta(delta))

def naturaldelta(value, months=True, minimum_unit='seconds') -> str:
    tmp = Unit[minimum_unit.upper()]
    if tmp not in (Unit.SECONDS, Unit.MILLISECONDS, Unit.MICROSECONDS):
        raise ValueError(f"Minimum unit '{minimum_unit}' not supported")
    minimum_unit = tmp
    if isinstance(value, dt.timedelta):
        delta = value
    else:
        try:
            value = int(value)
            delta = dt.timedelta(seconds=value)
        except (ValueError, TypeError):
            return value
    use_months = months
    seconds = abs(delta.seconds)
    days = abs(delta.days)
    years = days // 365
    days = days % 365
    months = int(days // 30.5)
    if not years and days < 1:
        if seconds == 0:
            if minimum_unit == Unit.MICROSECONDS and delta.microseconds < 1000:
                return _ngettext('%d microsecond', '%d microseconds', delta.microseconds) % delta.microseconds
            elif minimum_unit == Unit.MILLISECONDS or (minimum_unit == Unit.MICROSECONDS and 1000 <= delta.microseconds < 1000000):
                milliseconds = delta.microseconds / 1000
                return _ngettext('%d millisecond', '%d milliseconds', milliseconds) % milliseconds
            return _('a moment')
        elif seconds == 1:
            return _('a second')
        elif seconds < 60:
            return _ngettext('%d second', '%d seconds', seconds) % seconds
        elif 60 <= seconds < 120:
            return _('a minute')
        elif 120 <= seconds < 3600:
            minutes = seconds // 60
            return _ngettext('%d minute', '%d minutes', minutes) % minutes
        elif 3600 <= seconds < 3600 * 2:
            return _('an hour')
        elif 3600 < seconds:
            hours = seconds // 3600
            return _ngettext('%d hour', '%d hours', hours) % hours
    elif years == 0:
        if days == 1:
            return _('a day')
        if not use_months:
            return _ngettext('%d day', '%d days', days) % days
        elif not months:
            return _ngettext('%d day', '%d days', days) % days
        elif months == 1:
            return _('a month')
        else:
            return _ngettext('%d month', '%d months', months) % months
    elif years == 1:
        if not months and (not days):
            return _('a year')
        elif not months:
            return _ngettext('1 year, %d day', '1 year, %d days', days) % days
        elif use_months:
            if months == 1:
                return _('1 year, 1 month')
            else:
                return _ngettext('1 year, %d month', '1 year, %d months', months) % months
        else:
            return _ngettext('1 year, %d day', '1 year, %d days', days) % days
    else:
        return _ngettext('%s year', '%s years', years) % intcomma(years)

def naturaltime(value, future=False, months=True, minimum_unit='seconds', when=None) -> str:
    now = when or _now()
    (date, delta) = _date_and_delta(value, now=now)
    if date is None:
        return value
    if isinstance(value, (dt.datetime, dt.timedelta)):
        future = date > now
    ago = _('%s from now') if future else _('%s ago')
    delta = naturaldelta(delta, months, minimum_unit)
    if delta == _('a moment'):
        return _('now')
    return ago % delta

def naturalday(value, format='%b %d') -> str:
    try:
        value = dt.date(value.year, value.month, value.day)
    except AttributeError:
        return value
    except (OverflowError, ValueError):
        return value
    delta = value - dt.date.today()
    if delta.days == 0:
        return _('today')
    elif delta.days == 1:
        return _('tomorrow')
    elif delta.days == -1:
        return _('yesterday')
    return value.strftime(format)

def naturaldate(value) -> str:
    try:
        value = dt.date(value.year, value.month, value.day)
    except AttributeError:
        return value
    except (OverflowError, ValueError):
        return value
    delta = _abs_timedelta(value - dt.date.today())
    if delta.days >= 5 * 365 / 12:
        return naturalday(value, '%b %d %Y')
    return naturalday(value)

def _quotient_and_remainder(value, divisor, unit, minimum_unit, suppress):
    if unit == minimum_unit:
        return (value / divisor, 0)
    elif unit in suppress:
        return (0, value)
    else:
        return divmod(value, divisor)

def _carry(value1, value2, ratio, unit, min_unit, suppress):
    if unit == min_unit:
        return (value1 + value2 / ratio, 0)
    elif unit in suppress:
        return (0, value2 + value1 * ratio)
    else:
        return (value1, value2)

def _suitable_minimum_unit(min_unit, suppress):
    if min_unit in suppress:
        for unit in Unit:
            if unit > min_unit and unit not in suppress:
                return unit
        raise ValueError('Minimum unit is suppressed and no suitable replacement was found')
    return min_unit

def _suppress_lower_units(min_unit, suppress):
    suppress = set(suppress)
    for u in Unit:
        if u == min_unit:
            break
        suppress.add(u)
    return suppress

def ordinal(value, gender='male'):
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value
    if gender == 'male':
        t = (P_('0 (male)', 'th'), P_('1 (male)', 'st'), P_('2 (male)', 'nd'), P_('3 (male)', 'rd'), P_('4 (male)', 'th'), P_('5 (male)', 'th'), P_('6 (male)', 'th'), P_('7 (male)', 'th'), P_('8 (male)', 'th'), P_('9 (male)', 'th'))
    else:
        t = (P_('0 (female)', 'th'), P_('1 (female)', 'st'), P_('2 (female)', 'nd'), P_('3 (female)', 'rd'), P_('4 (female)', 'th'), P_('5 (female)', 'th'), P_('6 (female)', 'th'), P_('7 (female)', 'th'), P_('8 (female)', 'th'), P_('9 (female)', 'th'))
    if value % 100 in (11, 12, 13):
        return f'{value}{t[0]}'
    return f'{value}{t[value % 10]}'

def intcomma(value, ndigits=None):
    sep = thousands_separator()
    try:
        if isinstance(value, str):
            float(value.replace(sep, ''))
        else:
            float(value)
    except (TypeError, ValueError):
        return value
    if ndigits:
        orig = '{0:.{1}f}'.format(value, ndigits)
    else:
        orig = str(value)
    new = re.sub('^(-?\\d+)(\\d{3})', f'\\g<1>{sep}\\g<2>', orig)
    if orig == new:
        return new
    else:
        return intcomma(new)

def intword(value, format='%.1f'):
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value
    if value < powers[0]:
        return str(value)
    for (ordinal, power) in enumerate(powers[1:], 1):
        if value < power:
            chopped = value / float(powers[ordinal - 1])
            if float(format % chopped) == float(10 ** 3):
                chopped = value / float(powers[ordinal])
                (singular, plural) = human_powers[ordinal]
                return ' '.join([format, _ngettext(singular, plural, math.ceil(chopped))]) % chopped
            else:
                (singular, plural) = human_powers[ordinal - 1]
                return ' '.join([format, _ngettext(singular, plural, math.ceil(chopped))]) % chopped
    return str(value)

def apnumber(value):
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value
    if not 0 <= value < 10:
        return str(value)
    return (_('zero'), _('one'), _('two'), _('three'), _('four'), _('five'), _('six'), _('seven'), _('eight'), _('nine'))[value]

def fractional(value):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return value
    whole_number = int(number)
    frac = Fraction(number - whole_number).limit_denominator(1000)
    numerator = frac._numerator
    denominator = frac._denominator
    if whole_number and (not numerator) and (denominator == 1):
        return f'{whole_number:.0f}'
    elif not whole_number:
        return f'{numerator:.0f}/{denominator:.0f}'
    else:
        return f'{whole_number:.0f} {numerator:.0f}/{denominator:.0f}'

def scientific(value, precision=2):
    exponents = {'0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴', '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹', '+': '⁺', '-': '⁻'}
    negative = False
    try:
        if '-' in str(value):
            value = str(value).replace('-', '')
            negative = True
        if isinstance(value, str):
            value = float(value)
        fmt = '{:.%se}' % str(int(precision))
        n = fmt.format(value)
    except (ValueError, TypeError):
        return value
    (part1, part2) = n.split('e')
    if '-0' in part2:
        part2 = part2.replace('-0', '-')
    if '+0' in part2:
        part2 = part2.replace('+0', '')
    new_part2 = []
    if negative:
        new_part2.append(exponents['-'])
    for char in part2:
        new_part2.append(exponents[char])
    final_str = part1 + ' x 10' + ''.join(new_part2)
    return final_str

def clamp(value, format='{:}', floor=None, ceil=None, floor_token='<', ceil_token='>'):
    if value is None:
        return None
    if floor is not None and value < floor:
        value = floor
        token = floor_token
    elif ceil is not None and value > ceil:
        value = ceil
        token = ceil_token
    else:
        token = ''
    if isinstance(format, str):
        return token + format.format(value)
    elif callable(format):
        return token + format(value)
    else:
        raise ValueError('Invalid format. Must be either a valid formatting string, or a function that accepts value and returns a string.')

def naturalsize(value, binary=False, gnu=False, format='%.1f'):
    if gnu:
        suffix = suffixes['gnu']
    elif binary:
        suffix = suffixes['binary']
    else:
        suffix = suffixes['decimal']
    base = 1024 if gnu or binary else 1000
    bytes = float(value)
    abs_bytes = abs(bytes)
    if abs_bytes == 1 and (not gnu):
        return '%d Byte' % bytes
    elif abs_bytes < base and (not gnu):
        return '%d Bytes' % bytes
    elif abs_bytes < base and gnu:
        return '%dB' % bytes
    for (i, s) in enumerate(suffix):
        unit = base ** (i + 2)
        if abs_bytes < unit and (not gnu):
            return (format + ' %s') % (base * bytes / unit, s)
        elif abs_bytes < unit and gnu:
            return (format + '%s') % (base * bytes / unit, s)
    if gnu:
        return (format + '%s') % (base * bytes / unit, s)
    return (format + ' %s') % (base * bytes / unit, s)

def _get_default_locale_path():
    try:
        if __file__ is None:
            return None
        return os.path.join(os.path.dirname(__file__), 'locale')
    except NameError:
        return None

def get_translation():
    try:
        return _TRANSLATIONS[_CURRENT.locale]
    except (AttributeError, KeyError):
        return _TRANSLATIONS[None]

def activate(locale, path=None):
    if path is None:
        path = _get_default_locale_path()
    if path is None:
        raise Exception("Humanize cannot determinate the default location of the 'locale' folder. You need to pass the path explicitly.")
    if locale not in _TRANSLATIONS:
        translation = gettext_module.translation('humanize', path, [locale])
        _TRANSLATIONS[locale] = translation
    _CURRENT.locale = locale
    return _TRANSLATIONS[locale]

def _pgettext(msgctxt, message):
    try:
        return get_translation().pgettext(msgctxt, message)
    except AttributeError:
        key = msgctxt + '\x04' + message
        translation = get_translation().gettext(key)
        return message if translation == key else translation

def thousands_separator() -> str:
    try:
        sep = _THOUSANDS_SEPARATOR[_CURRENT.locale]
    except (AttributeError, KeyError):
        sep = ','
    return sep
